/* ── キャラクター・信頼度・パーティ・酒場・アイテム授受・セーブ・旅行・配達クエスト ── */

// ══════════════════════════════════════════
// TRUST SYSTEM（町ごとの信頼度 0〜100）
// ══════════════════════════════════════════

// 信頼度の初期化（キャラ生成時に呼ぶ）
function initTrust(startTownId){
 PC.trust = {};
 Object.keys(TOWNS).forEach(id => { PC.trust[id] = 0; });
 if(startTownId) PC.trust[startTownId] = 10;
}

// 信頼度取得
// 信頼度データが正しいオブジェクトかチェックし、壊れていれば再初期化する
// （後継時にNPCの忠誠度(数値のtrust)がPC.trust（町別オブジェクト）を上書きしてしまう不具合の自己修復）
function _ensureTrustObject(){
 if(!PC.trust || typeof PC.trust !== 'object' || Array.isArray(PC.trust)){
  initTrust(PC._startTown);
 }
}

function getTrust(townId){ _ensureTrustObject(); return (PC.trust||{})[townId] || 0; }

// 信頼度変動
// type='delivery' の場合は上限49
function changeTrust(townId, delta, type){
 _ensureTrustObject();
 const cur = PC.trust[townId] || 0;
 // 宅配・護衛は信頼度49上限（ただし既に50以上なら変更しない）
 if(type==='delivery' && cur >= 50) return;
 const cap = type==='delivery' ? 49 : 100;
 const next = Math.min(cap, Math.max(0, cur + delta));
 PC.trust[townId] = next;

 // 初めて信頼度100に達したとき → 英雄イベント
 if(next === 100 && cur < 100){
  if(!PC._heroTowns) PC._heroTowns = {};
  if(!PC._heroTowns[townId]){
   PC._heroTowns[townId] = true;
   const townName = (TOWNS[townId]||{}).name || townId;
   const heroMsgs = [
    `街の人々が広場に集まり、${PC.name}の名を呼んだ。誰かが「英雄だ」と叫び、その声はやがて大合唱になった。`,
    `${townName}の長老が${PC.name}の前に進み出た。「あなたはもうよそ者ではない。この街の誇りだ」`,
    `市場の露店が次々と幕を閉じ、街全体が祝祭の空気に包まれた。${PC.name}の武勲がこの街に根付いた日だった。`,
    `子どもたちが${PC.name}の周りに駆け寄り、手を引いて広場へ連れて行った。そこには街の人々が待っていた。`,
   ];
   const msg = heroMsgs[Math.floor(Math.random() * heroMsgs.length)];
   addLifeEvent('', `${townName}で英雄として祝福された。${msg}`);
 changeAlignment(8, 5); // 英雄クエスト：善+8/秩序+5
   PC._pendingHeroMsg = { townName, msg };

   // ── 地方英雄チェック ──
   checkRegionHero();
  }
 }
}

// ══════════════════════════════════════════
// 手配度システム（町ごとに独立。能動的な犯罪行為でのみ上昇）
// ══════════════════════════════════════════
const WANTED_MID_THRESHOLD = 40;  // これ以上で「中」：酒場の依頼を受けられない・3割で衛兵遭遇
const WANTED_HIGH_THRESHOLD = 70; // これ以上で「高」：賞金首扱い。町に入ると必ず衛兵遭遇、旅中は賞金稼ぎに襲われる
const WANTED_DECAY_PER_DAY = 0.1; // 風化速度（「高」の間は風化しない）

function _ensureWantedObject(){
 if(!PC.wanted || typeof PC.wanted !== 'object' || Array.isArray(PC.wanted)){
  PC.wanted = {};
 }
}

function getWanted(townId){
 _ensureWantedObject();
 return PC.wanted[townId] || 0;
}

function changeWanted(townId, delta){
 _ensureWantedObject();
 const cur = PC.wanted[townId] || 0;
 const next = Math.max(0, Math.min(100, cur + delta));
 PC.wanted[townId] = next;

 // 初めて手配度100に達したとき → 極悪人の噂イベント
 if(next === 100 && cur < 100){
  if(!PC._infamyTowns) PC._infamyTowns = {};
  if(!PC._infamyTowns[townId]){
   PC._infamyTowns[townId] = true;
   const townName = (TOWNS[townId]||{}).name || townId;
   const infamyMsgs = [
    `酒場の隅で誰かが声を潜めて言った。「${PC.name}……この街で知らぬ者はいない極悪人だそうだ」`,
    `市場を歩くと、人々が視線を逸らしながら囁き合った。「あれが${PC.name}か……近づかない方がいい」`,
    `子どもたちが物陰から${PC.name}を指差し、慌てて母親に引っ張られていった。もはやこの街で名を隠すことはできない。`,
    `衛兵詰所に${PC.name}の似顔絵が貼り出されていた。「${townName}の極悪人」と大書されている。`,
   ];
   const msg = infamyMsgs[Math.floor(Math.random() * infamyMsgs.length)];
   addLifeEvent('', `${townName}で極悪人として知れ渡った。${msg}`);
   changeAlignment(-8, -3); // 極悪人：悪+8/やや混沌+3
   PC._pendingInfamyMsg = { townName, msg };

   // ── 地方最悪の極悪人チェック ──
   checkRegionInfamy();
  }
 }

 return next;
}

function wantedTier(townId){
 const w = getWanted(townId);
 if(w >= WANTED_HIGH_THRESHOLD) return 'high';
 if(w >= WANTED_MID_THRESHOLD) return 'mid';
 return 'low';
}

// 訪問時にまとめて経過分の風化を適用（「高」の間は風化しない）
function tickWantedDecay(townId){
 _ensureWantedObject();
 if(!PC._wantedLastTick) PC._wantedLastTick = {};
 const lastDay = PC._wantedLastTick[townId] ?? GAME_TIME.totalDays;
 const days = GAME_TIME.totalDays - lastDay;
 if(days > 0){
  const cur = PC.wanted[townId] || 0;
  if(cur < WANTED_HIGH_THRESHOLD){
   PC.wanted[townId] = Math.max(0, cur - days*WANTED_DECAY_PER_DAY);
  }
 }
 PC._wantedLastTick[townId] = GAME_TIME.totalDays;
}

// ── 衛兵に見つかった後の「町封鎖」システム ──
// 一度衛兵に見つかると（逃走成功／戦闘勝利いずれでも）、賄賂・ハッタリ・実力行使のいずれかで
// 解決するまでその町を出られなくなる。1ヶ月（30日）経過で自動解除。
const GUARD_LOCKOUT_DAYS = 30;

function setGuardLockout(townId){
 if(!PC._guardLockout) PC._guardLockout = {};
 PC._guardLockout[townId] = { sinceDay: GAME_TIME.totalDays };
}

function isGuardLockedOut(townId){
 if(!PC._guardLockout || !PC._guardLockout[townId]) return false;
 const daysSince = GAME_TIME.totalDays - PC._guardLockout[townId].sinceDay;
 if(daysSince >= GUARD_LOCKOUT_DAYS){
  delete PC._guardLockout[townId];
  return false;
 }
 return true;
}

function clearGuardLockout(townId){
 if(PC._guardLockout) delete PC._guardLockout[townId];
}

// 町を出ようとした際、衛兵封鎖中なら解決手段を提示する
function showGuardLockoutMenu(townId, toId, method){
 const townName = (TOWNS[townId]||{}).name || townId;
 const tier = wantedTier(townId);
 const highTier = tier === 'high';
 const story = document.getElementById('story');
 if(story) story.innerHTML = ` <span style="color:#e0d0d0">${townName}</span><br><br>`
  + `<b> 門番に呼び止められた</b><br><br>`
  + `以前この町で衛兵に見つかった一件が尾を引いている。「お前、見覚えがあるな」と門番が眉をひそめた。このままでは町を出られそうにない。`
  + (highTier ? `<br><br><span style="color:#c8a0a0">手配度が高いせいか、金や口先ではとても誤魔化せそうにない。</span>` : '');
 // 解決後の遷移先：もともと選んでいた旅先があればその旅を再開し、無ければ町メニューへ戻る
 const proceed = ()=>{
  renderChoices([]);
  if(toId && method) travelTo(toId, method);
  else go('TOWN_'+townId.toUpperCase());
 };
 const choices = [];
 if(!highTier){
  choices.push({label:' 賄賂を渡す（20〜30GP）', fn:()=>{
   const amount = 20 + Math.floor(Math.random()*11);
   if((PC.gold||0) < amount){
    const s=document.getElementById('story');
    if(s) s.innerHTML += `<br><br><span style="color:#c8a0a0">持ち合わせが足りない……（${amount}GP必要）</span>`;
    renderChoices([{label:'← 戻る', fn:()=>showGuardLockoutMenu(townId, toId, method)}]);
    return;
   }
   PC.gold -= amount; updateHUD();
   clearGuardLockout(townId);
   const s=document.getElementById('story');
   if(s) s.innerHTML = ` <span style="color:#e0d0d0">${townName}</span><br><br><span style="color:#e8e4d8">門番の手に金を握らせると、目つきが和らいだ。「……何も見なかったことにしよう」（-${amount}GP）</span>`;
   renderChoices([{label:'▶ OK', fn:proceed}]);
  }});
  choices.push({label:' ハッタリで騙す（魅力 Lv2 能力値テスト）', fn:()=>{
   setupSavingRoll({attr:'chr', level:2,
    onSuccess:()=>{
     clearGuardLockout(townId);
     const s=document.getElementById('story');
     if(s) s.innerHTML = ` <span style="color:#e0d0d0">${townName}</span><br><br><span style="color:#e8e4d8">堂々と別人のふりをして押し通ると、門番は疑わしそうにしながらも道を空けた。</span>`;
     renderChoices([{label:'▶ OK', fn:proceed}]);
    },
    onFail:()=>{
     const s=document.getElementById('story');
     if(s) s.innerHTML += `<br><br><span style="color:#c8a0a0">「……いや、お前で間違いない」ハッタリは見破られた。</span>`;
     renderChoices([{label:'← 戻る', fn:()=>showGuardLockoutMenu(townId, toId, method)}]);
    },
   });
  }});
 }
 choices.push({label:' 力づくで突破する', fn:()=>{
  renderChoices([]);
  const level = Math.max(2, Math.min(10, (PC.level||1) + (highTier?1:0)));
  const guardCount = highTier ? (3 + Math.floor(Math.random()*2)) : (2 + Math.floor(Math.random()*2));
  const enemies = Array(guardCount).fill(0).map(()=>{
   const n = generateNPC(level);
   n.name = '衛兵'; n.bountyTitle = '衛兵';
   return {...n, curCon:n.con};
  });
  window._wantedArrestContext = { townId, tier };
  startCombatNPC({
   enemies, canFlee:false, win:'__noop__', lose:'WANTED_ARREST_NODE', skipLuckSave:true,
   onWin:()=>{
    document.getElementById('cbt-area').classList.add('hidden');
    document.getElementById('scroll-area').classList.remove('in-combat');
    document.getElementById('text-win').style.display = '';
    cbtState = null;
    clearGuardLockout(townId);
    updateHUD();
    const s = document.getElementById('story');
    if(s) s.innerHTML = ` <span style="color:#e0d0d0">${townName}</span><br><br><span style="color:#e8e4d8">門番の衛兵たちを叩きのめし、力づくで町を後にした。</span>`;
    renderChoices([{label:'▶ OK', fn:proceed}]);
   },
  });
 }});
 choices.push({label:'← 町に留まる', go:'TOWN_'+townId.toUpperCase()});
 renderChoices(choices);
}

// 手配度に応じたバッジHTML（信頼度バッジと並べて表示する用）
function renderWantedBadge(townId){
 tickWantedDecay(townId);
 const tier = wantedTier(townId);
 if(tier === 'low') return '';
 const w = Math.round(getWanted(townId));
 const label = tier === 'high' ? '賞金首' : '手配中';
 const color = tier === 'high' ? '#e07050' : '#e0c060';
 return ` <span style="font-size:calc(var(--font-sm) - 2px);color:${color};border:1px solid ${color};border-radius:3px;padding:1px 5px;margin-left:6px"> ${label}（手配度${w}）</span>`;
}

// 町に入る際の衛兵遭遇チェック。強制戦闘に入った場合はtrueを返す
function checkWantedAmbush(townId){
 tickWantedDecay(townId);
 const tier = wantedTier(townId);
 if(tier === 'low') return false;
 const chance = tier === 'high' ? 1 : 0.3;
 if(Math.random() >= chance) return false;
 startWantedGuardAmbush(townId, tier);
 return true;
}

// 信頼度75（地元の英雄扱い）以上の町に入った際、低確率でPCに憧れたLv1の若者が仲間入りを志願する
function checkAdmirerEvent(townId){
 if((PC.party||[]).length >= 3) return false;
 if(getTrust(townId) < 75) return false;
 if(Math.random() >= 0.05) return false;
 startAdmirerEvent(townId);
 return true;
}

function startAdmirerEvent(townId){
 const townName = (TOWNS[townId]||{}).name || townId;
 const npc = generateNPC(1);
 npc.background = {
  family: `${PC.name}が${townName}で成し遂げた武勲を目にして、いても立ってもいられなくなった。`,
  motive: `あんな風になりたい——それだけを胸に、旅支度もそこそこに飛び出してきた。`,
 };
 const story = document.getElementById('story');
 if(story){
  story.innerHTML = `<span style="color:#e0d8c8">${townName}</span><br><br>`
   +`<b> 憧れの若者</b><br><br>`
   +`人混みの中から、息を切らした若者が駆け寄ってきた。<br><br>`
   +`「${PC.name}さん、ですよね……！ ずっとお噂を聞いていました。お願いします、鞄持ちでいいので……どうか連れて行ってもらえませんか」`;
 }
 renderChoices([
  {label:' 一緒に連れて行く', fn:()=>{
   PC.party = PC.party || [];
   if(PC.party.length >= 3){
    const s = document.getElementById('story');
    if(s) s.innerHTML += `<br><br><span style="color:#c05040">パーティが満員（上限3人）のため、これ以上連れて行けない。</span>`;
    renderChoices([{label:'▶ OK', fn:()=>{ renderChoices([]); go('TOWN_'+townId.toUpperCase()); }}]);
    return;
   }
   PC.party.push({...npc, trust:100, joinDay:GAME_TIME.totalDays});
   addLifeEvent('', `${npc.name}がパーティに加わった（${({warrior:'戦士',rogue:'盗賊',wizard:'魔法使い'})[npc.type]||npc.type}・${npc.race}）。`);
   renderChoices([]);
   const s = document.getElementById('story');
   if(s) s.innerHTML = `<span style="color:#e0d8c8">${townName}</span><br><br><span style="color:#e8e4d8"> ${npc.name}が仲間に加わった！　目を輝かせながら、あなたの後についてきた。</span>`;
   updateHUD();
   renderChoices([{label:'▶ OK', fn:()=>{ renderChoices([]); go('TOWN_'+townId.toUpperCase()); }}]);
  }},
  {label:' 断る', fn:()=>{
   changeAlignment(-4, -3);
   renderChoices([]);
   const s = document.getElementById('story');
   if(s) s.innerHTML = `<span style="color:#e0d8c8">${townName}</span><br><br><span style="color:#c8b8a0">「……そうですか」若者は肩を落とし、人混みの中へ消えていった。</span>`;
   renderChoices([{label:'▶ OK', fn:()=>{ renderChoices([]); go('TOWN_'+townId.toUpperCase()); }}]);
  }},
 ]);
}

function startWantedGuardAmbush(townId, tier){
 const townName = (TOWNS[townId]||{}).name || townId;
 const level = Math.max(2, Math.min(10, (PC.level||1) + (tier==='high'?1:0)));
 const guardCount = tier === 'high' ? (3 + Math.floor(Math.random()*2)) : (2 + Math.floor(Math.random()*2));
 const enemies = Array(guardCount).fill(0).map(()=>{
  const n = generateNPC(level);
  n.name = '衛兵';
  n.bountyTitle = '衛兵';
  return {...n, curCon:n.con};
 });
 const story = document.getElementById('story');
 if(story){
  story.innerHTML = `<span style="color:#e0d0d0">${townName}</span><br><br>`
   +`<b>${tier==='high' ? ' 賞金首を発見！' : ' 衛兵に見咎められた！'}</b><br><br>`
   +(tier==='high'
    ? `門をくぐった瞬間、衛兵があなたの人相書きに気づいた。「賞金首だ！取り押さえろ！」`
    : `門番があなたの顔をじっと見て、囁き合っている。「……あいつじゃないか」`);
 }
 const afterEvade = (msg)=>{
  setGuardLockout(townId);
  updateHUD();
  const s = document.getElementById('story');
  if(s) s.innerHTML = `<span style="color:#e0d0d0">${townName}</span><br><br><span style="color:#e8e4d8">${msg}</span>`;
  renderChoices([{label:'▶ OK', fn:()=>{ renderChoices([]); go('TOWN_'+townId.toUpperCase()); }}]);
 };
 renderChoices([
  {label:' 逃げる（素早さ Lv2 能力値テスト）', fn:()=>{
   setupSavingRoll({attr:'spd', level:2,
    onSuccess:()=>{
     afterEvade('人混みに紛れて衛兵の目を盗み、逃げ切った！ただし顔を見られた以上、正面から町を出るのは難しそうだ。');
    },
    onFail:()=>{
     const s = document.getElementById('story');
     if(s) s.innerHTML += `<br><br><span style="color:#c8a0a0">逃げきれず、腕を掴まれてしまった！</span>`;
     renderChoices([]);
     window._wantedArrestContext = { townId, tier };
     startCombatNPC({
      enemies, canFlee:false, win:'__noop__', lose:'WANTED_ARREST_NODE', skipLuckSave:true,
      onWin:()=>{
       document.getElementById('cbt-area').classList.add('hidden');
       document.getElementById('scroll-area').classList.remove('in-combat');
       document.getElementById('text-win').style.display = '';
       cbtState = null;
       afterEvade('衛兵を振り切った！ただし顔を見られた以上、正面から町を出るのは難しそうだ。');
      },
     });
    },
   });
  }},
  {label:' 戦う', fn:()=>{
   renderChoices([]);
   window._wantedArrestContext = { townId, tier };
   startCombatNPC({
    enemies,
    canFlee: false,
    win:'__noop__',
    lose:'WANTED_ARREST_NODE',
    skipLuckSave: true,
    onWin:()=>{
     document.getElementById('cbt-area').classList.add('hidden');
     document.getElementById('scroll-area').classList.remove('in-combat');
     document.getElementById('text-win').style.display = '';
     cbtState = null;
     afterEvade('衛兵を振り切った！ただし顔を見られた以上、正面から町を出るのは難しそうだ。');
    },
   });
  }},
 ]);
 return;
}

// 盗みを働く（能動的な犯罪コマンド）。対象によって手口・リスク・手配度上昇が異なる
// 宝物の基準値：PCのレベルに応じた「典型的な戦闘」のtotalMR相当。ここに各手口の倍率をかけてgenerateTreasureに渡す
function _theftBaseMR(){ return 20 + (PC.level||1)*10; }

function showTheftMenu(townId){
 const townName = (TOWNS[townId]||{}).name || townId;
 const story = document.getElementById('story');
 if(story) story.innerHTML = ` <span style="color:#e0d8c8">${townName}</span><br><br><span style="color:#c0b098">何を狙いますか？</span>`;
 renderChoices([
  {label:' すり（器用さテスト・軽犯罪）', fn:()=>startPickpocket(townId)},
  {label:' 民家に忍び込む（運テスト・中犯罪）', fn:()=>startBurglary(townId)},
  {label:' 商店を襲う（戦闘・重犯罪）', fn:()=>startShopRobbery(townId)},
  {label:'← やめておく', go:'TOWN_'+townId.toUpperCase()},
 ]);
}

// ① すり：DEXテストLv1。成功で宝物表の1/3、手配度+1。失敗で体力-3、手配度+3
function startPickpocket(townId){
 const townName = (TOWNS[townId]||{}).name || townId;
 const story = document.getElementById('story');
 if(story) story.innerHTML = `<span style="color:#e0d8c8">${townName}</span><br><br><span style="color:#c0b098">雑踏に紛れ、すれ違いざまに懐を狙う……</span>`;
 setupSavingRoll({
  attr:'dex', level:1,
  onSuccess:()=>{
   const lootHtml = generateTreasure(Math.max(1,Math.floor(_theftBaseMR()/3)));
   changeWanted(townId, 1);
   const s = document.getElementById('story');
   if(s) s.innerHTML = `<span style="color:#e0d8c8">${townName}</span><br><br><span style="color:#e8e4d8">まんまと掏り取った。${lootHtml}</span>`;
   renderChoices([{label:'← 町に戻る', go:'TOWN_'+townId.toUpperCase()}]);
  },
  onFail:()=>{
   const dmg = 1 + Math.floor(Math.random()*6);
   PC.con=Math.max(0,PC.con-dmg); changeWanted(townId, 3); updateHUD();
   const s = document.getElementById('story');
   if(s) s.innerHTML = `<span style="color:#e0d8c8">${townName}</span><br><br><span style="color:#e8e4d8">気づかれて殴られた！　体力-${dmg}。</span>`;
   if(PC.con<=0){ renderChoices([{label:'…（力尽きた）', go:'DEAD'}]); return; }
   renderChoices([{label:'← 町に戻る', go:'TOWN_'+townId.toUpperCase()}]);
  },
 });
 renderChoices([]);
 scrollToTop();
}

// ② 民家に忍び込む：LKテストLv2。成功で宝物表の1/2、手配度+3。失敗で家主と戦闘、手配度+5
function startBurglary(townId){
 const townName = (TOWNS[townId]||{}).name || townId;
 const story = document.getElementById('story');
 if(story) story.innerHTML = `<span style="color:#e0d8c8">${townName}</span><br><br><span style="color:#c0b098">人気のない民家に忍び込む……</span>`;
 setupSavingRoll({
  attr:'lk', level:2,
  onSuccess:()=>{
   const lootHtml = generateTreasure(Math.max(1,Math.floor(_theftBaseMR()/2)));
   changeWanted(townId, 3);
   const s = document.getElementById('story');
   if(s) s.innerHTML = `<span style="color:#e0d8c8">${townName}</span><br><br><span style="color:#e8e4d8">家探しして金目のものを見つけた。${lootHtml}</span>`;
   renderChoices([{label:'← 町に戻る', go:'TOWN_'+townId.toUpperCase()}]);
  },
  onFail:()=>{
   changeWanted(townId, 5);
   const npcCount = 1 + Math.floor(Math.random()*3); // 1〜3
   const lvl = Math.max(1, Math.min(10, PC.level||1));
   const enemies = Array(npcCount).fill(0).map(()=>{ const n=generateNPC(lvl); return {...n, curCon:n.con}; });
   const s = document.getElementById('story');
   if(s) s.innerHTML = `<span style="color:#e0d0d0">${townName}</span><br><br><span style="color:#e8e4d8">物音に気づいた家主が戻ってきた！「泥棒！」</span>`;
   renderChoices([{label:' 戦う', fn:()=>{
    renderChoices([]);
    startCombatNPC({
     enemies, canFlee:true, win:'__noop__', lose:'DEAD',
     onWin:()=>{
      document.getElementById('cbt-area').classList.add('hidden');
      document.getElementById('scroll-area').classList.remove('in-combat');
      document.getElementById('text-win').style.display='';
      cbtState=null; updateHUD();
      const s2=document.getElementById('story');
      if(s2) s2.innerHTML = `<span style="color:#e0d0d0">${townName}</span><br><br><span style="color:#e8e4d8">家主を退け、その隙に逃げ出した。</span>`;
      renderChoices([{label:'▶ OK', fn:()=>{ renderChoices([]); go('TOWN_'+townId.toUpperCase()); }}]);
     },
    });
   }}]);
  },
 });
 renderChoices([]);
 scrollToTop();
}

// ③ 商店を襲う：判定なし、即戦闘（衛兵1〜5人）。勝利で宝物表の2倍、手配度+10。敗北は逮捕（衛兵の遭遇と同じ扱い）
function startShopRobbery(townId){
 const townName = (TOWNS[townId]||{}).name || townId;
 const npcCount = 1 + Math.floor(Math.random()*5); // 1〜5
 const lvl = Math.max(1, Math.min(10, PC.level||1));
 const enemies = Array(npcCount).fill(0).map(()=>{ const n=generateNPC(lvl); n.name='衛兵'; return {...n, curCon:n.con}; });
 const story = document.getElementById('story');
 if(story) story.innerHTML = `<span style="color:#e0d8c8">${townName}</span><br><br><span style="color:#c0b098">白昼堂々、商店に押し入った。すぐさま衛兵が駆けつける。</span>`;
 window._wantedArrestContext = { townId, tier: wantedTier(townId) };
 renderChoices([{label:' 戦う', fn:()=>{
  renderChoices([]);
  startCombatNPC({
   enemies, canFlee:false, win:'__noop__', lose:'WANTED_ARREST_NODE', skipLuckSave:true,
   onWin:()=>{
    document.getElementById('cbt-area').classList.add('hidden');
    document.getElementById('scroll-area').classList.remove('in-combat');
    document.getElementById('text-win').style.display='';
    cbtState=null;
    const lootHtml = generateTreasure(_theftBaseMR()*2);
    changeWanted(townId, 10);
    updateHUD();
    const s = document.getElementById('story');
    if(s) s.innerHTML = `<span style="color:#e0d0d0">${townName}</span><br><br><span style="color:#e8e4d8">衛兵を退け、店の金目の物を奪った。${lootHtml}</span>`;
    renderChoices([{label:'▶ OK', fn:()=>{ renderChoices([]); go('TOWN_'+townId.toUpperCase()); }}]);
   },
  });
 }}]);
}

