// 英雄依頼の発生チェック（酒場ノードのtxt()から呼ぶ）
// ══════════════════════════════════════════════════════
// 特命依頼：砂漠の砦掃討作戦（アル・ラシード限定）
// ══════════════════════════════════════════════════════

function checkSpecialMission(townId){
 if(townId !== 'al_rashid') return false;
 if(!PC._specialMissionCooldown) PC._specialMissionCooldown = 0;
 if(GAME_TIME.totalDays < PC._specialMissionCooldown) return false;
 if((PC.quests||[]).some(q=>q.type==='special_mission' && q.status==='active')) return false;
 return true;
}

function renderSpecialMissionBoard(){
 if(!checkSpecialMission('al_rashid')) return '';
 return `<div style="background:#0c0800;border:2px solid #884400;border-radius:4px;padding:12px;margin-bottom:10px">
  <div style="color:#e0d8c8;font-size:calc(var(--font-sm) - 1px);margin-bottom:6px"> 特命依頼</div>
  <div style="color:#f0ece0;font-size:var(--font-sm);margin-bottom:6px"> 砂漠の砦　掃討作戦</div>
  <div style="color:#e0d8c8;font-size:calc(var(--font-sm) - 1px);line-height:1.8;margin-bottom:10px">「砂漠の奥地、カシュール砦が混沌の勢力に汚染された。正規軍は増援として遊撃兵を募っている。生き残れる保証はない」</div>
  <button onclick="acceptSpecialMission()" style="width:100%;background:#1a0800;border:1px solid #484848;color:#e0d8c8;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 1px);padding:9px;cursor:pointer;border-radius:3px"> 作戦に参加する</button>
 </div>`;
}

function acceptSpecialMission(){
 if(!PC.quests) PC.quests=[];
 const q = {
  id: Date.now()+Math.random(),
  type:'special_mission',
  status:'active',
  fromTownId:'al_rashid',
  title:'砂漠の砦　掃討作戦',
  issuedDay: GAME_TIME.totalDays,
 };
 PC.quests.push(q);
 showSaveToast(' 特命依頼を引き受けた：砂漠の砦　掃討作戦');
 _refreshTavernBoard('al_rashid');
}

function startSpecialMission(){
 const q = (PC.quests||[]).find(q=>q.type==='special_mission' && q.status==='active');
 if(!q) return;
 _runSpecialMissionNode(q, 0);
}

// カオスSR：DEX/LK/IQからランダムに判定
function _chaosSR(level){
 const attrs = ['dex','lk','iq'];
 return attrs[Math.floor(Math.random()*attrs.length)];
}

