const _SM_KEYS = ['march','breach','inside','panic','boss'];

const _SPECIAL_NODES = [
 // ノード0：進軍（フレーバーのみ）
 {
  flavorKey:'march', title:' カシュール砦への進軍',
  sr: null,
 },
 // ノード1：突入（能力値テスト失敗でダメージ→MR型戦闘）
 {
  flavorKey:'breach', title:' 砦への突入',
  sr: { level:2, failDmg:3, failAttr:'con', failTxt:'混乱した状況で適切な行動が取れず、敵の攻撃をまともに受けた。' },
  combat: { mr_min:100, mr_max:200, name:'剥離した徴用兵（先遣隊）' },
 },
 // ノード2：砦内（フレーバーのみ）
 {
  flavorKey:'inside', title:' 砦内部の光景',
  sr: null,
 },
 // ノード3：因果の歪みパニック（能力値テスト失敗でダメージ→MR型戦闘）
 {
  flavorKey:'panic', title:' 因果の歪み',
  sr: { level:3, failDmg:4, failAttr:'con', failTxt:'命令の混濁に翻弄され、陣形から離れた瞬間を狙われた。' },
  combat: { mr_min:100, mr_max:200, name:'剥離した徴用兵（精鋭）' },
 },
 // ノード4：ボス戦（NPC型、カオスSR必須）
 {
  flavorKey:'boss', title:' 多重存在の指揮官',
  isBoss: true,
 },
];

function _runSpecialMissionNode(q, nodeIdx){
 const node = _SPECIAL_NODES[nodeIdx];
 const story = document.getElementById('story');
 const isBoss = node.isBoss;
 const border = isBoss ? '#884400' : '#553300';
 const bg = isBoss ? '#0c0600' : '#0a0600';
 const flavors = _SPECIAL_FLAVOR[node.flavorKey] || [];
 const bodyHtml = flavors[Math.floor(Math.random()*flavors.length)] || '';
 story.innerHTML = `<div style="border:1px solid ${border};border-radius:4px;padding:12px;background:${bg}">
  <div style="color:#e0d8c8;font-size:var(--font-sm);margin-bottom:8px">${node.title}</div>
  ${bodyHtml}
 </div>`;

 if(node.isBoss){
  // ボス戦（カオスSR必須NPC型）
  renderChoices([{label:' 指揮官に立ち向かう', fn:()=>_startSpecialMissionBoss(q)}]);
  return;
 }

 if(node.sr){
  const sr = node.sr;
  const attr = _chaosSR(sr.level);
  const attrNames = {dex:'器用さ',lk:'運',iq:'知力'};
  story.innerHTML += `<div style="color:#d8d0c0;font-size:calc(var(--font-sm) - 1px);margin-top:10px;padding:8px;background:#080600;border-left:2px solid #553300;line-height:1.9">時間の歪みに対応するための判定が必要だ。<br><span style="color:#e0d8c8"> ${attrNames[attr]} Lv${sr.level} 能力値テスト</span></div>`;
  renderChoices([{label:` ダイスを振る（${attrNames[attr]} Lv${sr.level} 能力値テスト）`, fn:()=>{
   document.getElementById('dice-area').classList.remove('hidden');
   setupSavingRoll({
    attr, level:sr.level, label:'特命依頼',
    onSuccess(){
     document.getElementById('dice-area').classList.add('hidden');
     story.innerHTML += `<div style="color:#f0ece0;font-size:calc(var(--font-sm) - 1px);margin-top:8px;padding:8px;background:var(--ink);border-left:2px solid var(--nature-border);line-height:1.9"> 歪みを読んだ。体が正しく動いた。</div>`;
     _startSpecialMissionCombat(q, node, nodeIdx, false);
    },
    onFail(){
     document.getElementById('dice-area').classList.add('hidden');
     PC[sr.failAttr] = Math.max(0, (PC[sr.failAttr]||0) - sr.failDmg);
     updateHUD();
     story.innerHTML += `<div style="color:#e0d0d0;font-size:calc(var(--font-sm) - 1px);margin-top:8px;padding:8px;background:#120800;border-left:2px solid #663322;line-height:1.9"> ${sr.failTxt}（${sr.failAttr.toUpperCase()} -${sr.failDmg}）</div>`;
     if(PC.con <= 0){ setTimeout(()=>go('DEAD'), 1000); return; }
     _startSpecialMissionCombat(q, node, nodeIdx, true);
    },
   });
  }}]);
  return;
 }

 // フレーバーのみ
 const isLast = nodeIdx >= _SPECIAL_NODES.length - 1;
 renderChoices([{label:'▶ 進む', fn:()=>_runSpecialMissionNode(q, nodeIdx+1)}]);
}

function _startSpecialMissionCombat(q, node, nodeIdx, srFailed){
 const mr = node.combat.mr_min + Math.floor(Math.random()*(node.combat.mr_max - node.combat.mr_min + 1));
 renderChoices([]);
 drawScene('combat');
 document.getElementById('dice-area').classList.add('hidden');
 startCombat({
  name: node.combat.name,
  mr, armor: Math.floor(mr/25),
  canFlee: false,
  win:'__noop__', lose:'DEAD',
  onWin(){
   document.getElementById('cbt-area').classList.add('hidden');
   document.getElementById('scroll-area').classList.remove('in-combat');
   document.getElementById('text-win').style.display = '';
   cbtState = null;
   _runSpecialMissionNode(q, nodeIdx+1);
  },
 });
}

function _startSpecialMissionBoss(q){
 renderChoices([]);
 drawScene('combat');
 document.getElementById('dice-area').classList.add('hidden');
 document.getElementById('text-win').style.display='none';

 // ボス生成（混沌根城と同等）
 const baseLv = 5 + Math.floor(Math.random()*4);
 const bossLv = Math.round(baseLv * 1.5);
 const boss = generateNPC(bossLv);
 boss.name = '多重存在の指揮官';
 boss.curCon = boss.con;

 const MINION_TYPES = ['warrior','warrior','rogue'];
 const minions = [0,1].map(()=>{
  const m = generateNPC(bossLv);
  m.type = MINION_TYPES[Math.floor(Math.random()*MINION_TYPES.length)];
  m.name = '剥離した護衛';
  m.curCon = m.con;
  return m;
 });

 const onWin = ()=>{
  document.getElementById('cbt-area').classList.add('hidden');
  document.getElementById('scroll-area').classList.remove('in-combat');
  document.getElementById('text-win').style.display='';
  cbtState = null;
  PC.quests = (PC.quests||[]).filter(qq=>qq.id!==q.id);
  // 報酬：英雄依頼の1.5倍相当（bossLv×75〜112GP）
  const reward = Math.floor(bossLv * (75 + Math.floor(Math.random()*38)));
  gainGPAll(reward);
  changeTrust('al_rashid', 10);
  PC._specialMissionCooldown = GAME_TIME.totalDays + (720 + Math.floor(Math.random()*361));
  updateHUD();
  changeAlignment(10, 10); // 砦掃討：善+10/秩序+10
 addLifeEvent('', '砂漠の砦掃討作戦を生き延びた。');
  _checkSpecialMissionCount();
  showSaveToast(` 特命依頼完了！ +${reward}GP`);
  const story = document.getElementById('story');
  story.innerHTML = `<div style="border:1px solid #505050;border-radius:4px;padding:12px;background:var(--ink)">
   <div style="color:#f0ece0;font-size:var(--font-sm);margin-bottom:8px"> 作戦完了</div>
   <div style="color:#e0d8c8;font-size:calc(var(--font-sm) - 1px);line-height:1.9">指揮官が崩れ落ちると、砦に充満していた歪みが急速に薄れた。<br><br>
正規軍の隊長が近づき、敬礼した。「よくやってくれた。この件は——公式には記録されない」<br><br>
砂漠の風が砦の中を吹き抜けた。</div>
   <div style="color:#f0ece0;font-size:calc(var(--font-sm) - 1px);margin-top:8px">報酬: ${reward}GP　信頼度+10</div>
  </div>`;
  renderChoices([{label:'← アル・ラシードへ戻る', go:'TOWN_AL_RASHID'}]);
 };

 // カオスSR必須戦闘システムを注入
 startCombatNPC({
  enemies: [boss, ...minions],
  canFlee: false,
  win:'__noop__', lose:'DEAD',
  chaosMode: true,  // カオスSRフラグ
  onWin,
 });
}

function checkSpecialMissionBoard(){
 const q = (PC.quests||[]).find(q=>q.type==='special_mission' && q.status==='active');
 if(q) return renderSpecialMissionActive(q);
 if(checkSpecialMission('al_rashid')) return renderSpecialMissionBoard();
 return '';
}

function renderSpecialMissionActive(q){
 const isVald  = q.fromTownId === 'valdheim';
 const isNeria = q.fromTownId === 'neria';
 const bg      = isVald ? 'var(--info-bg)' : '#0c0800';
 const border  = isVald ? 'var(--info-border)' : '#884400';
 const color   = isVald ? 'var(--info2)' : '#e0d8c8';
 const startFn = isVald ? 'startSpecialMissionValdheim()' : isNeria ? 'startSpecialMissionMarea()' : 'startSpecialMission()';
 return `<div style="background:${bg};border:1px solid ${border};border-radius:3px;padding:8px;margin:5px 0;font-size:var(--font-sm)">
  <span style="color:${color}"> 特命依頼</span>　${q.title}<br>
  <button onclick="${startFn}" style="margin-top:5px;width:100%;background:${bg};border:1px solid ${border};color:${color};font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 2px);padding:7px;cursor:pointer;border-radius:3px"> 出発する</button>
 </div>`;
}

// ══════════════════════════════════════════════════════
// 特命依頼：氷原の砦掃討作戦（ヴァルドヘイム限定）
// ══════════════════════════════════════════════════════

function checkSpecialMissionValdheim(townId){
 if(townId !== 'valdheim') return false;
 if(!PC._specialMissionVCooldown) PC._specialMissionVCooldown = 0;
 if(GAME_TIME.totalDays < PC._specialMissionVCooldown) return false;
 if((PC.quests||[]).some(q=>q.type==='special_mission' && q.status==='active')) return false;
 return true;
}

function renderSpecialMissionValdheimBoard(){
 if(!checkSpecialMissionValdheim('valdheim')) return '';
 return `<div style="background:var(--info-bg);border:2px solid #484848;border-radius:4px;padding:12px;margin-bottom:10px">
  <div style="color:#e0d8c8;font-size:calc(var(--font-sm) - 1px);margin-bottom:6px"> 特命依頼</div>
  <div style="color:var(--white);font-size:var(--font-sm);margin-bottom:6px"> 氷原の砦　掃討作戦</div>
  <div style="color:#e0d8c8;font-size:calc(var(--font-sm) - 1px);line-height:1.8;margin-bottom:10px">「極北の氷原にあるヴィルガル砦が混沌の勢力に汚染された。正規軍は増援を募っている。凍死より恐ろしいものがあることを、覚悟して行け」</div>
  <button onclick="acceptSpecialMissionValdheim()" style="width:100%;background:var(--info-bg);border:1px solid #484848;color:#e0d8c8;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 1px);padding:9px;cursor:pointer;border-radius:3px"> 作戦に参加する</button>
 </div>`;
}

function acceptSpecialMissionValdheim(){
 if(!PC.quests) PC.quests=[];
 const q = {
  id: Date.now()+Math.random(),
  type:'special_mission',
  status:'active',
  fromTownId:'valdheim',
  title:'氷原の砦　掃討作戦',
  issuedDay: GAME_TIME.totalDays,
 };
 PC.quests.push(q);
 showSaveToast(' 特命依頼を引き受けた：氷原の砦　掃討作戦');
 _refreshTavernBoard('valdheim');
}

function startSpecialMissionValdheim(){
 const q = (PC.quests||[]).find(q=>q.type==='special_mission' && q.status==='active' && q.fromTownId==='valdheim');
 if(!q) return;
 _runSpecialMissionVNode(q, 0);
}

