// ── 闘技場の殿堂（石碑）──
// 闘技場らしい称号に、NPC_EPITHETSの全カテゴリ（ふざけた系含む）を加えたプール
const ARENA_HOF_EPITHETS_BASE = [
 '剛腕の', '疾風の', '無敗の', '不屈の', '鉄壁の', '一撃の',
 '常勝の', '猛虎の', '嵐の', '氷刃の', '獅子心の', '不動の',
 '百戦の', '孤高の', '雷光の', '不倒の',
];
// NPC_EPITHETSは後方で定義されるため、実際に使う際にまとめて結合する
function arenaHofEpithetPool(){
 return [...ARENA_HOF_EPITHETS_BASE, ...Object.values(NPC_EPITHETS).flat()];
}

// 殿堂10名分をランダム生成（初回のみ）。年は50年〜現在の年まで
function arenaGenerateHallOfFame(){
 const nowYear = getCurrentDate().year;
 const maxYear = Math.max(51, nowYear - 1); // 現在より前の年から選ぶ
 const entries = [];
 const usedNames = new Set();
 const pool = arenaHofEpithetPool();
 for(let i=0;i<10;i++){
  let name;
  let guard = 0;
  do { name = NPC_NAMES[Math.floor(Math.random()*NPC_NAMES.length)]; guard++; }
  while(usedNames.has(name) && guard<50);
  usedNames.add(name);
  const epithet = pool[Math.floor(Math.random()*pool.length)];
  const year = 50 + Math.floor(Math.random()*(maxYear-50+1));
  const month = 1 + Math.floor(Math.random()*12);
  const day = 1 + Math.floor(Math.random()*28);
  entries.push({epithet, name, year, month, day});
 }
 entries.sort((a,b)=> a.year-b.year || a.month-b.month || a.day-b.day);
 return entries;
}

// 闘技場ごとの殿堂リストを取得（初回アクセス時に生成し、以後は保持）
function arenaGetHallOfFame(townId){
 PC._arenaHallOfFame = PC._arenaHallOfFame || {};
 if(!PC._arenaHallOfFame[townId]){
  PC._arenaHallOfFame[townId] = arenaGenerateHallOfFame();
 }
 return PC._arenaHallOfFame[townId];
}

// PCをその闘技場の殿堂入りさせる（一度だけ）
function arenaInductPCIfEligible(townId){
 PC._arenaInducted = PC._arenaInducted || {};
 if(PC._arenaInducted[townId]) return false;
 const list = arenaGetHallOfFame(townId);
 const pool2 = arenaHofEpithetPool();
 const epithet = pool2[Math.floor(Math.random()*pool2.length)];
 const d = getCurrentDate();
 list.push({epithet, name:PC.name, year:d.year, month:d.month, day:d.day, isPC:true});
 PC._arenaInducted[townId] = true;
 return true;
}

// ══════════════════════════════════════════════════════════
// 闘技場 観戦モード（PC不参加、NPCパーティ同士の自動戦闘）
// ══════════════════════════════════════════════════════════
let _arenaWatch = null;

// 同格同士の対戦カードを組んで観戦を開始する
// 両陣営の大まかな強さを見積もる（賭けのオッズ算出用。ダイスロールには依存しない静的な指標）
function _arenaComputePower(side){
 return side.reduce((s,n)=> s + (n.st||0) + (n.dex||0) + (n.con||0) + (n.level||1)*5, 0);
}
function _arenaComputeOdds(sideEast, sideWest){
 const pe = _arenaComputePower(sideEast);
 const pw = _arenaComputePower(sideWest);
 const total = Math.max(1, pe+pw);
 const probEast = pe/total;
 const probWest = pw/total;
 const houseEdge = 0.85; // 胴元の取り分
 const clamp = v => Math.round(Math.max(1.05, Math.min(1.5, v))*100)/100;
 return {
  oddsEast: clamp((1/Math.max(0.3,probEast))*houseEdge),
  oddsWest: clamp((1/Math.max(0.3,probWest))*houseEdge),
 };
}

// 下馬評の語り口バリエーション（sizeTxt, oddsEast, oddsWestを受け取り、フレーバー文を返す）
const ARENA_ODDS_FLAVOR_LINES = [
 (size,oe,ow)=>`${size}の一戦。客の一人が下馬評を語っている。<br><br>「東軍が勝てば配当は<b>${oe}倍</b>、西軍が勝てば<b>${ow}倍</b>ってところだろうな」`,
 (size,oe,ow)=>`${size}の一戦。元締めらしき男が声を張り上げている。<br><br>「さあさあ張った張った！東軍は<b>${oe}倍</b>、西軍は<b>${ow}倍</b>だ！」`,
 (size,oe,ow)=>`${size}の一戦。老いた占い師が水晶玉を覗き込んでいる。<br><br>「東軍の勝利で<b>${oe}倍</b>、西軍の勝利で<b>${ow}倍</b>……星がそう告げておる」`,
 (size,oe,ow)=>`${size}の一戦。隣に座った客がこっそり耳打ちしてきた。<br><br>「東軍なら<b>${oe}倍</b>、西軍なら<b>${ow}倍</b>らしいぜ」`,
 (size,oe,ow)=>`${size}の一戦。壁の古びた札に、配当が書き殴られている。<br><br>「東軍　<b>${oe}倍</b>／西軍　<b>${ow}倍</b>」`,
 (size,oe,ow)=>`${size}の一戦。賭け屋の少年が声を張り上げて客を集めている。<br><br>「東軍<b>${oe}倍</b>！西軍<b>${ow}倍</b>！さあどっちに賭ける！」`,
 (size,oe,ow)=>`${size}の一戦。常連らしき老人がぶつぶつ呟いている。<br><br>「今日は東軍<b>${oe}倍</b>、西軍<b>${ow}倍</b>か……悩ましいところだ」`,
 (size,oe,ow)=>`${size}の一戦。場内アナウンスが響く。<br><br>「本日の配当、東軍<b>${oe}倍</b>、西軍<b>${ow}倍</b>。ご検討ください」`,
];

function arenaStartWatch(rankKey, townId, returnNodeId, arenaTitle, scene){
 const rank = ARENA_RANKS[rankKey];
 const lvl = rank.minLv + Math.floor(Math.random()*(rank.maxLv-rank.minLv+1));
 const count = 2 + Math.floor(Math.random()*3); // 2〜4人ずつ
 const makeSide = ()=> Array.from({length:count}, ()=>{
  const n = generateNPC(lvl);
  n.curCon = n.con;
  return n;
 });
 const sideEast = makeSide(), sideWest = makeSide();
 const odds = _arenaComputeOdds(sideEast, sideWest);
 _arenaWatch = {
  sideEast, sideWest,
  round: 0,
  rankKey, townId, returnNodeId, arenaTitle, scene: scene||'town_desert_village',
  log: [' 両陣営が入場し、対峙する。'],
  detail: '',
  finished: false,
  odds, bet: null,
  oddsFlavorIdx: Math.floor(Math.random()*ARENA_ODDS_FLAVOR_LINES.length),
 };
 go('ARENA_BET_SELECT');
}

// 賭けを確定する（GPは即座に徴収し、決着時に清算する）
function arenaPlaceBet(side, amount){
 if(!_arenaWatch) return;
 if((PC.gold||0) < amount) return;
 PC.gold -= amount;
 _arenaWatch.bet = { side, amount };
 updateHUD();
}

function _arenaWatchAlive(side){ return side.filter(n=>n.curCon>0); }

// 押し込み度合いに応じて実況を変える（既存の_combatNarrativeのしきい値を踏襲）
function _arenaWatchNarrative(diff, totalRoll, winnerSide){
 const bigHit = diff >= Math.max(8, Math.floor(totalRoll * 0.3));
 const big = [
  `${winnerSide}軍が圧倒的な猛攻を叩き込んだ！`,
  `${winnerSide}軍が相手陣営を完全に崩した！`,
  `${winnerSide}軍の一撃が次々と決まる！`,
  `${winnerSide}軍が大きく攻め込んだ！`,
  `${winnerSide}軍の猛攻に、相手は防戦一方だ！`,
  `${winnerSide}軍が一気に流れを掴んだ！`,
 ];
 const small = [
  `${winnerSide}軍がわずかに押し込んだ。`,
  `${winnerSide}軍が優勢に立ったが、決定打には欠ける。`,
  `${winnerSide}軍が僅差でリードした。`,
  `${winnerSide}軍がやや有利に進めている。`,
  `${winnerSide}軍が押し気味だが、まだ拮抗している。`,
  `${winnerSide}軍がわずかに上回った。`,
 ];
 const pick = arr=>arr[Math.floor(Math.random()*arr.length)];
 return pick(bigHit ? big : small);
}

// 対象の回避判定（ダイス内訳も返す）。{success, roll, target}
function _arenaWatchDodgeRoll(casterLevel, target){
 const targetVal = casterLevel*5 + 15;
 const diceA = d6(), diceB = d6();
 const grand = diceA+diceB+(target.lk||0);
 return { success: grand >= targetVal, diceA, diceB, grand, targetVal };
}

// 1ラウンド分（魔法フェーズ→遠距離フェーズ[初回のみ]→近接フェーズ）を自動解決する
function arenaWatchResolveRound(){
 const w = _arenaWatch;
 w.round++;
 let log = `<b>── ラウンド${w.round} ──</b> <span onclick="var d=document.getElementById('arena-watch-detail');if(d){d.style.display=d.style.display==='none'?'':'none';}" style="cursor:pointer;font-size:var(--font-sm);color:#d0c8b8;border:1px solid #c0b098;border-radius:2px;padding:1px 4px;margin-left:4px">詳細</span><br>`;
 let detail = '';
 let sideBonusEast = 0, sideBonusWest = 0; // Detonate/Ice Bind/Atomizationの近接判定への上乗せ分

 // ── 魔法フェーズ：両陣営のwizard型を素早さ順にまとめて処理（使える攻撃魔法からランダム）──
 const casters = [
  ..._arenaWatchAlive(w.sideEast).filter(n=>n.type==='wizard').map(n=>({n, side:'東'})),
  ..._arenaWatchAlive(w.sideWest).filter(n=>n.type==='wizard').map(n=>({n, side:'西'})),
 ].sort((a,b)=>(b.n.spd||0)-(a.n.spd||0));

 const spDisplayNames = {ttyf:'Magic Bolt', blastingPower:'Detonate', freezePleeze:'Ice Bind', turnToStone:'Turn to Stone', atomization:'Atomization'};

 casters.forEach(({n, side})=>{
  if(n.curCon<=0) return;
  const npcLv = n.level||1;
  const picked = (typeof _npcPickAttackSpell==='function') ? _npcPickAttackSpell(n, (typeof NPC_ATTACK_SPELL_FNS_VS_ENEMY!=='undefined')?NPC_ATTACK_SPELL_FNS_VS_ENEMY:['ttyf']) : null;
  if(!picked) return;
  n.st -= picked.cost;
  const targets = _arenaWatchAlive(side==='東' ? w.sideWest : w.sideEast);
  if(targets.length===0) return;
  const target = targets[Math.floor(Math.random()*targets.length)];
  const spName = spDisplayNames[picked.fn] || picked.name;

  if(picked.fn === 'ttyf'){
   const dmg = (n.iq||0)*npcLv;
   const dr = _arenaWatchDodgeRoll(npcLv, target);
   detail += `　<span style="color:#c8b8a0">[魔法:${spName}] ${n.name}（${side}）→${target.name}：IQ${n.iq||0}×Lv${npcLv}=${dmg}／回避判定[${dr.diceA},${dr.diceB}]+運(${target.lk||0})=${dr.grand} vs ${dr.targetVal} → ${dr.success?'回避成功':'被弾'}</span><br>`;
   if(dr.success){
    log += `<span style="color:#c8b8a0">${n.name}の${spName}を${target.name}が回避！</span><br>`;
   } else {
    target.curCon = Math.max(0, target.curCon - dmg);
    log += `<span style="color:#e0a070">${n.name}の${spName}が${target.name}に直撃！（-${dmg}）</span><br>`;
   }
  } else if(picked.fn === 'blastingPower' || picked.fn === 'freezePleeze'){
   const dmg = Nd6(npcLv);
   if(side==='東') sideBonusEast += dmg; else sideBonusWest += dmg;
   detail += `　<span style="color:#c8b8a0">[魔法:${spName}] ${n.name}（${side}）：${npcLv}D6=${dmg}を近接判定に上乗せ</span><br>`;
   log += `<span style="color:#e0a070">${n.name}が${spName}を詠唱！（${side}軍の近接判定に${dmg}上乗せ）</span><br>`;
  } else if(picked.fn === 'turnToStone'){
   const dr = _arenaWatchDodgeRoll(6, target);
   detail += `　<span style="color:#c8b8a0">[魔法:${spName}] ${n.name}（${side}）→${target.name}：回避判定[${dr.diceA},${dr.diceB}]+運(${target.lk||0})=${dr.grand} vs ${dr.targetVal} → ${dr.success?'回避成功':'石化'}</span><br>`;
   if(dr.success){
    log += `<span style="color:#c8b8a0">${target.name}は咄嗟に身をこわばらせ、${n.name}の${spName}を逃れた！</span><br>`;
   } else {
    target.curCon = 0;
    log += `<span style="color:#e0a070">${n.name}の${spName}で${target.name}が石と化した！戦闘から除外される。</span><br>`;
   }
  } else if(picked.fn === 'atomization'){
   const dr = _arenaWatchDodgeRoll(7, target);
   const heatDmg = Nd6(npcLv);
   if(side==='東') sideBonusEast += heatDmg; else sideBonusWest += heatDmg;
   detail += `　<span style="color:#c8b8a0">[魔法:${spName}] ${n.name}（${side}）→${target.name}：回避判定[${dr.diceA},${dr.diceB}]+運(${target.lk||0})=${dr.grand} vs ${dr.targetVal} → ${dr.success?'回避成功（熱のみ残る）':'消滅'}／熱で近接に${heatDmg}上乗せ</span><br>`;
   if(dr.success){
    log += `<span style="color:#e0a070">${target.name}は間一髪で${n.name}の${spName}を逃れた！しかしその空間にあったものは分解され、${side}軍の近接判定に${heatDmg}上乗せ！</span><br>`;
   } else {
    target.curCon = 0;
    log += `<span style="color:#e0a070">${n.name}の${spName}で${target.name}が消滅した！発生した熱で${side}軍の近接判定に${heatDmg}上乗せ！</span><br>`;
   }
  }
 });

 // ── 遠距離フェーズ：最初のラウンドのみ、両陣営の遠距離武器持ちを素早さ順に処理 ──
 if(w.round===1){
  const shooters = [
   ..._arenaWatchAlive(w.sideEast).filter(n=>isRangedWeapon(n.equippedRanged)).map(n=>({n, side:'東'})),
   ..._arenaWatchAlive(w.sideWest).filter(n=>isRangedWeapon(n.equippedRanged)).map(n=>({n, side:'西'})),
  ].sort((a,b)=>(b.n.spd||0)-(a.n.spd||0));

  shooters.forEach(({n, side})=>{
   if(n.curCon<=0) return;
   const wpn = n.equippedRanged;
   const sr = savingRoll('dex', 2, n);
   detail += `　<span style="color:#c8b8a0">[遠距離] ${n.name}（${side}）の命中判定：[${sr.rolled}]+DEX(${n.dex||0})=${sr.total} vs ${sr.target} → ${sr.success?'命中コース':'外れ'}</span><br>`;
   if(!sr.success){ log += `<span style="color:#c8b8a0">${n.name}の${wpn.name}は狙いが外れた。</span><br>`; return; }
   const targets = _arenaWatchAlive(side==='東' ? w.sideWest : w.sideEast);
   if(targets.length===0) return;
   const target = targets[Math.floor(Math.random()*targets.length)];
   const diceRoll = Nd6(wpn.dice);
   const dexAdd = n.dex>12?(n.dex-12)*2:(n.dex<9?(n.dex-9)*2:0);
   const stAdd  = n.st>12?n.st-12:(n.st<9?n.st-9:0);
   const lkAdd  = n.lk>12?n.lk-12:(n.lk<9?n.lk-9:0);
   const hit = diceRoll + (wpn.adds||0) + stAdd + lkAdd + dexAdd;
   const armor = calcNPCArmor(target);
   const dmg = Math.max(0, hit-armor);
   const dr = _arenaWatchDodgeRoll(n.level||1, target);
   detail += `　<span style="color:#c8b8a0">${wpn.name} ${wpn.dice}D=${diceRoll} adds=${stAdd+lkAdd+dexAdd} hit=${hit}（防護-${armor}）→ダメージ${dmg}／回避判定[${dr.diceA},${dr.diceB}]+運(${target.lk||0})=${dr.grand} vs ${dr.targetVal} → ${dr.success?'回避成功':'被弾'}</span><br>`;
   if(dr.success){
    log += `<span style="color:#c8b8a0">${n.name}の${wpn.name}を${target.name}が回避！</span><br>`;
   } else {
    target.curCon = Math.max(0, target.curCon-dmg);
    log += `<span style="color:#e0a070">${n.name}の${wpn.name}が${target.name}に命中！（-${dmg}）</span><br>`;
   }
  });
 }

 // ── 近接フェーズ：生存者の合計ロールを比較し、負けた側に差分ダメージを分配 ──
 const meleeEast = _arenaWatchAlive(w.sideEast);
 const meleeWest = _arenaWatchAlive(w.sideWest);
 if(meleeEast.length>0 && meleeWest.length>0){
  const rollsEast = meleeEast.map(n=>({n, rv:calcNPCRoll(n)}));
  const rollsWest = meleeWest.map(n=>({n, rv:calcNPCRoll(n)}));
  const rollEast = rollsEast.reduce((s,r)=>s+r.rv.total, 0) + sideBonusEast;
  const rollWest = rollsWest.reduce((s,r)=>s+r.rv.total, 0) + sideBonusWest;
  detail += `　<span style="color:#c8b8a0">[近接] 東：${rollsEast.map(r=>`${r.n.name}[${r.rv.dice.join(',')}]=${r.rv.total}`).join('、')}${sideBonusEast>0?`　魔法上乗せ+${sideBonusEast}`:''}</span><br>`;
  detail += `　<span style="color:#c8b8a0">[近接] 西：${rollsWest.map(r=>`${r.n.name}[${r.rv.dice.join(',')}]=${r.rv.total}`).join('、')}${sideBonusWest>0?`　魔法上乗せ+${sideBonusWest}`:''}</span><br>`;
  log += `<span style="color:#c0b098">近接：東 ${rollEast} vs 西 ${rollWest}</span><br>`;
  if(rollEast > rollWest){
   const dmg = rollEast - rollWest;
   const per = Math.floor(dmg/meleeWest.length), rem = dmg%meleeWest.length;
   meleeWest.forEach((n,i)=>{
    const d = Math.max(1, (per+(i===0?rem:0)) - calcNPCArmor(n));
    n.curCon = Math.max(0, n.curCon-d);
   });
   log += `<span style="color:#e8e4d8">${_arenaWatchNarrative(dmg, rollEast+rollWest, '東')}</span><br>`;
  } else if(rollWest > rollEast){
   const dmg = rollWest - rollEast;
   const per = Math.floor(dmg/meleeEast.length), rem = dmg%meleeEast.length;
   meleeEast.forEach((n,i)=>{
    const d = Math.max(1, (per+(i===0?rem:0)) - calcNPCArmor(n));
    n.curCon = Math.max(0, n.curCon-d);
   });
   log += `<span style="color:#e8e4d8">${_arenaWatchNarrative(dmg, rollEast+rollWest, '西')}</span><br>`;
  } else {
   log += `<span style="color:#c8b8a0">互角のまま、両者譲らず。</span><br>`;
  }
 }

 log += `<div id="arena-watch-detail" style="display:none;font-size:calc(var(--font-sm) - 2px);color:#b8a890;margin:2px 0 4px 8px;line-height:1.8">${detail}</div>`;
 w.log = [log];
 const aliveEast = _arenaWatchAlive(w.sideEast).length;
 const aliveWest = _arenaWatchAlive(w.sideWest).length;
 if(aliveEast===0 || aliveWest===0){
  w.finished = true;
  w.winner = aliveEast>0 ? '東' : (aliveWest>0 ? '西' : '引き分け');
  // 賭けの清算（1回だけ）
  if(w.bet && !w.betSettled){
   w.betSettled = true;
   const betSideJa = w.bet.side==='east' ? '東' : '西';
   if(w.winner === betSideJa){
    const odds = w.bet.side==='east' ? w.odds.oddsEast : w.odds.oddsWest;
    const payout = Math.floor(w.bet.amount * odds);
    gainGP(payout, PC);
    updateHUD();
    w.betResultTxt = `<span style="color:#ffe0a0">賭けが的中！${betSideJa}軍に${w.bet.amount}GP賭け、配当${payout}GPを受け取った。</span>`;
   } else {
    w.betResultTxt = `<span style="color:#c8a0a0">賭けは外れた。${betSideJa}軍に賭けた${w.bet.amount}GPは戻ってこない。</span>`;
   }
  }
 }
}

// 指定ランクに挑戦する（参加費徴収→対戦相手生成→NPC型戦闘開始）
function arenaChallengeRank(rankKey, returnNodeId, arenaTitle, townId){
 const cooldown = arenaCooldownRemaining();
 if(cooldown > 0){
  showSaveToast(`闘技場はまだ準備中です（あと${cooldown}日）`);
  return;
 }
 const rank = ARENA_RANKS[rankKey];
 const count = arenaPartySize();
 const fee = rank.feePerPerson * count;
 if((PC.gold||0) < fee){
  showSaveToast('参加費が足りません');
  return;
 }
 PC.gold -= fee;
 PC._arenaLastFightDay = GAME_TIME.totalDays;
 updateHUD();
 const lvl = rank.minLv + Math.floor(Math.random()*(rank.maxLv-rank.minLv+1));
 const enemies = Array.from({length:count}, ()=>generateNPC(lvl));
 drawScene('combat');
 startCombatNPC({
  enemies, canFlee:true, win:'__noop__', lose:'__noop__', skipLuckSave:true, arenaMode:true,
  onWin:()=>{
   const prize = rank.prizeBase * count;
   gainGP(prize);
   updateHUD();
   document.getElementById('cbt-area').classList.add('hidden');
   document.getElementById('scroll-area').classList.remove('in-combat');
   document.getElementById('text-win').style.display = '';
   cbtState = null;
   const streak = arenaGetStreak(townId, rankKey) + 1;
   arenaSetStreak(townId, rankKey, streak);
   let extraMsg = '';
   const isHighest = rankKey === arenaHighestRank(townId);
   if(isHighest && streak===10){
    const inducted = arenaInductPCIfEligible(townId);
    if(inducted){
     extraMsg = `<br><br><span style="color:#ffe0a0"> 割れんばかりの歓声が沸き起こる。「殿堂入りだ！」——闘技場の石碑に、あなたの名が刻まれることになった。</span>`;
    }
   } else if(isHighest && streak>0 && streak%5===0){
    // 小規模闘技場（地方都市）では、その地方の中心都市の闘技場へ誘導する。
    // 中規模闘技場（地方の中心都市そのもの）は、それ以上「地方の中心都市」を辿っても自分自身になってしまうため、
    // 代わりに大規模闘技場があるカザーヌへ誘導する。大規模（カザーヌ）ではこれ以上誘導先がないため何も起きない。
    const scale = ARENA_TOWN_SCALE[townId] || 'small';
    if(scale === 'small'){
     const capitalName = getRegionCapitalName(townId);
     const capitalId = getRegionCapitalId(townId);
     if(capitalName && capitalId){
      if(!PC._arenaRecommended) PC._arenaRecommended = {};
      PC._arenaRecommended[capitalId] = true;
      extraMsg = `<br><br><span style="color:#e0d8c8">観客の一人が声をかけてきた。「これだけ連勝するとはな……お前は、${capitalName}の闘技場に行くべきだ」</span>`;
     }
    } else if(scale === 'medium'){
     if(!PC._arenaRecommended) PC._arenaRecommended = {};
     PC._arenaRecommended.khazan = true;
     extraMsg = `<br><br><span style="color:#e0d8c8">観客の一人が声をかけてきた。「これだけ連勝するとはな……お前は、カザーヌの闘技場に行くべきだ」</span>`;
    }
   }
   const s = document.getElementById('story');
   if(s) s.innerHTML = `<span style="color:#f0ece0">${arenaTitle}</span><br><br><span style="color:#ffcc88">勝利！観客の歓声を浴びながら、賞金${prize}GPを受け取った。</span>${extraMsg}`;
   renderChoices([{label:'▶ OK', go:returnNodeId}]);
  },
  onLose:()=>{
   // 闘技場での敗北は安全な敗退（死亡扱いにしない）
   PC.con = Math.max(PC.con, 1);
   (PC.party||[]).forEach(n=>{ if(n.con<=0) n.con = Math.max(n.con, 1); });
   arenaSetStreak(townId, rankKey, 0);
   updateHUD();
   document.getElementById('cbt-area').classList.add('hidden');
   document.getElementById('scroll-area').classList.remove('in-combat');
   document.getElementById('text-win').style.display = '';
   cbtState = null;
   const s = document.getElementById('story');
   if(s) s.innerHTML = `<span style="color:#f0ece0">${arenaTitle}</span><br><br><span style="color:#e0d0d0">力及ばず、審判の合図で戦いは止められた。命に別状はなく、参加費を失っただけで済んだようだ。</span>`;
   renderChoices([{label:'▶ OK', go:returnNodeId}]);
  }
 });
}


const HERO_REGIONS = {
 khazan_region:   { name:'カザーヌ地方',       towns:['khazan','port_argon','stonehiem'] },
 elmaria_region:  { name:'エルマリア地方',      towns:['elsia','verda','rimholm','marakai'] },
 zahara_region:   { name:'ザハラ地方',          towns:['al_rashid','oasis_fort','saroon','duna'] },
 draklim_region:  { name:'ドラクリム地方',      towns:['yeldun','frostpeak','ashveil'] },
 valdheim_region: { name:'ヴァルドヘイム地方',  towns:['valdheim','nifurvik','iskald'] },
 marea_region:    { name:'マレア地方',          towns:['neria','dorua','sarpe','nebra'] },
};

// ── 封地免状（自分の領地を築く第一歩）：各地方の中心都市の庁舎・宮殿でのみ授与される ──
// 店売りではなく、その地方で「地元の英雄」になっている町の数に応じて金額が決まる特別な下賜品
const REGION_CAPITAL_TOWNS = ['khazan','elsia','al_rashid','yeldun','valdheim','neria'];
const FIEF_CHARTER_BASE_PRICE = 10000;
const FIEF_CHARTER_DISCOUNT_PER_HERO_TOWN = 0.10; // 英雄になっている町1つにつき10%引き
const FIEF_CHARTER_MIN_PRICE_RATIO = 0.25; // 基準価格の25%を下限とする

// 指定した地方で、PCが英雄になっている町の数を数える
function countHeroTownsInRegion(regionKey){
 const region = HERO_REGIONS[regionKey];
 if(!region) return 0;
 return region.towns.filter(t => PC._heroTowns && PC._heroTowns[t]).length;
}

// 指定した地方の「英雄」情報を返す。PCが現に地方英雄ならPC自身（yearsSinceDeath:-1＝存命）、
// そうでなければ歴代の伝説（PC._regionLegends）から死後経過年数を算出して返す。記録が無ければnull
function getRegionLegendHero(regionKey){
 if(PC._heroRegions && PC._heroRegions[regionKey]){
  return { name: PC.name, yearsSinceDeath: -1 };
 }
 const legend = PC._regionLegends && PC._regionLegends[regionKey];
 if(!legend) return null;
 const yearsSinceDeath = Math.max(0, Math.floor((GAME_TIME.totalDays - legend.deathDay) / 365));
 return { name: legend.name, yearsSinceDeath };
}

// 封地免状の価格を計算（10GP単位に丸める）
function calcFiefCharterPrice(regionKey){
 const heroCount = countHeroTownsInRegion(regionKey);
 const ratio = Math.max(FIEF_CHARTER_MIN_PRICE_RATIO, 1 - heroCount*FIEF_CHARTER_DISCOUNT_PER_HERO_TOWN);
 return Math.round(FIEF_CHARTER_BASE_PRICE * ratio / 10) * 10;
}

// 中心都市の庁舎・宮殿
// 領地の領民：3ヶ月ごとにランダムなイベントを判定して増減を反映し、年に1度だけ既存の増加率も適用する
// （拠点訪問時、経過四半期数分をまとめて処理する）
// 1-100人:+25%/年 101-200:+20% 201-300:+15% 301-400:+10% 401-500:+5% 501以上:+1〜5%（年1回・複利ではなく単純加算）
// 上限は200家族＝1000人・下限5人
function _fiefPopGrowthRate(pop){
 if(pop <= 100) return 0.25;
 if(pop <= 200) return 0.20;
 if(pop <= 300) return 0.15;
 if(pop <= 400) return 0.10;
 if(pop <= 500) return 0.05;
 return 0.01 + Math.random()*0.04;
}

// 3ヶ月に1度、ランダムに判定される領地の出来事（人口への影響は乗算・%）
const FIEF_QUARTERLY_EVENTS = [
 { name:'何もなかった',       pct:40.0, impact:0.0,   log:false },
 { name:'嵐',                 pct:12.0, impact:0.0,   log:true,
  flavor:'嵐が領地を襲った。' },
 { name:'激しい突風',         pct:10.0, impact:-0.1,  log:true,
  flavor:'激しい突風が吹き荒れ、屋根や柵が飛ばされた。' },
 { name:'火災、小規模',       pct:10.0, impact:-0.1,  log:true,
  flavor:'小規模な火災が発生し、家屋の一部が焼けた。' },
 { name:'竜巻',                pct:8.0,  impact:-0.5,  log:true,
  flavor:'竜巻が発生し、建物が半壊するなどの被害が出た。' },
 { name:'地震',                pct:5.0,  impact:-1.0,  log:true,
  flavor:'地震が発生した。' },
 { name:'洪水',                pct:4.0,  impact:-1.5,  log:true,
  flavor:'洪水が発生し、広い範囲が浸水した。' },
 { name:'ハリケーン',          pct:3.0,  impact:-2.0,  log:true,
  flavor:'ハリケーンが直撃し、広域にわたって建造物が破壊された。' },
 { name:'火災、大規模',       pct:2.5,  impact:-3.0,  log:true,
  flavor:'大規模な火災が発生し、市街地の一部が焼け落ちた。' },
 { name:'流星群',              pct:2.0,  impact:0.0,   log:true,
  flavor:'夜空に流星群が現れた。' },
 { name:'疫病',                pct:1.5,  impact:-5.0,  log:true,
  flavor:'疫病が流行し、多くの領民が命を落とした。' },
 { name:'爆発',                pct:1.0,  impact:-0.8,  log:true,
  flavor:'原因不明の爆発事故が発生した。' },
 { name:'陥没穴',              pct:0.8,  impact:-0.2,  log:true,
  flavor:'突如として地面が陥没し、建物が呑み込まれた。' },
 { name:'彗星',                pct:0.1,  impact:0.0,   log:true,
  flavor:'空に彗星が現れた。領民たちは吉兆か凶兆かと噂しあっている。' },
 { name:'隕石衝突',            pct:0.1,  impact:-25.0, log:true,
  flavor:'隕石が領地に直撃し、壊滅的な被害をもたらした。' },
];
function _rollFiefQuarterlyEvent(){
 const r = Math.random()*100;
 let cum = 0;
 for(const e of FIEF_QUARTERLY_EVENTS){
  cum += e.pct;
  if(r < cum) return e;
 }
 return FIEF_QUARTERLY_EVENTS[FIEF_QUARTERLY_EVENTS.length-1];
}
// 四半期キー（年×4＋四半期インデックス0〜3）を返す
function _fiefQuarterKey(totalDays){
 const d = daysToDate(totalDays);
 return d.year*4 + Math.floor((d.month-1)/3);
}

function _applyFiefYearlyPopulation(prop){
 if(prop.population == null) return null;
 const nowQKey = _fiefQuarterKey(GAME_TIME.totalDays);
 if(prop.lastPopQuarterKey == null){
  // 旧セーブ移行：lastPopCheckYearがあれば年初のQ0として引き継ぐ。なければ現在の四半期から開始する
  prop.lastPopQuarterKey = prop.lastPopCheckYear != null ? prop.lastPopCheckYear*4 : nowQKey;
  return null;
 }
 const quarters = nowQKey - prop.lastPopQuarterKey;
 if(quarters <= 0) return null;

 const before = prop.population;
 prop.ledger = prop.ledger||[];
 let eventLines = [];
 const QUARTER_MONTH = [2, 5, 8, 11]; // 各四半期を代表する月（表示用）
 for(let i=0; i<quarters; i++){
  const qKey = prop.lastPopQuarterKey + i + 1;
  const y = Math.floor(qKey/4);
  const qIdx = qKey % 4; // 0〜3（何四半期目か）
  const qMonth = QUARTER_MONTH[qIdx];

  // その四半期のランダムイベントを判定し、乗算で反映する
  const ev = _rollFiefQuarterlyEvent();
  const popBeforeEvent = prop.population;
  if(ev.impact !== 0){
   prop.population = Math.max(5, Math.min(1000, Math.round(prop.population * (1 + ev.impact/100))));
  }
  if(ev.log){
   prop.ledger.unshift({ type:'fief_event', year:y, quarter:qIdx+1, month:qMonth, eventName:ev.name, flavor:ev.flavor, impact:ev.impact, populationBefore:popBeforeEvent, populationAfter:prop.population });
   eventLines.push(`${y}年Q${qIdx+1}：${ev.name}${ev.impact!==0?`（${ev.impact}%）`:''}`);
  }

  // 4四半期（1年）ごとに、既存の年次増加率を適用する
  if(qIdx === 3){
   const pop = prop.population;
   if(pop > 0){
    const rate = _fiefPopGrowthRate(pop);
    const growth = Math.round(pop * rate);
    prop.population = Math.max(5, Math.min(1000, pop + growth));
   }
  }
 }
 prop.lastPopQuarterKey = nowQKey;
 if(prop.ledger.length > 200) prop.ledger.length = 200;

 const diff = prop.population - before;
 const diffText = diff > 0 ? `+${diff}人` : `${diff}人`;
 let resultHtml = `<div style="border:1px solid var(--border2);border-radius:4px;padding:8px;margin-top:8px">
  <span style="color:#c8b8a0">${quarters}四半期の間に、領地の人口は${before}人から${prop.population}人へ変化した（${diffText}）。</span>`;
 if(eventLines.length){
  const shown = eventLines.slice(0, 5);
  resultHtml += `<br><span style="color:#a89878;font-size:calc(var(--font-sm) - 1px)">${shown.join('、')}${eventLines.length>5?` 他${eventLines.length-5}件`:''}</span>`;
 }
 resultHtml += `</div>`;
 const titleHtml = _updateNobilityTitle();
 if(titleHtml) resultHtml += titleHtml;
 return resultHtml;
}

// ── 貴族の称号 ──
// 地方ごとに「領民800人を超えた領地の数」を数え、1つ目=男爵／2つ目=子爵／3つ目=伯爵／4つ目以上=侯爵。
// 表示する二つ名は、最も多く該当領地を持つ地方の称号を使う（同数なら先に見つかった地方を優先）
const NOBILITY_TITLES = ['男爵', '子爵', '伯爵', '侯爵'];

// 現在の所有状況から、表示すべき称号（地方・段階）を算出する
function _computeNobilityTitle(){
 const regionCounts = {};
 (PC._fiefCharters||[]).forEach(c=>{
  const p = PC.properties?.[c.fiefId];
  if((p?.population||0) > 800){
   regionCounts[c.regionKey] = (regionCounts[c.regionKey]||0) + 1;
  }
 });
 let bestRegion = null, bestCount = 0;
 for(const [regionKey, count] of Object.entries(regionCounts)){
  if(count > bestCount){ bestCount = count; bestRegion = regionKey; }
 }
 if(bestCount <= 0) return null;
 const tierIdx = Math.min(bestCount, NOBILITY_TITLES.length) - 1;
 return { title: NOBILITY_TITLES[tierIdx], regionKey: bestRegion, count: bestCount };
}

// 称号を再計算し、以前より格が上がっていればその旨のフレーバーHTMLを返す（変化がなければnull）
function _updateNobilityTitle(){
 const result = _computeNobilityTitle();
 const newTitle = result?.title || null;
 const prevTitle = PC._nobilityTitle || null;
 const prevIdx = prevTitle ? NOBILITY_TITLES.indexOf(prevTitle) : -1;
 const newIdx = newTitle ? NOBILITY_TITLES.indexOf(newTitle) : -1;
 if(newIdx <= prevIdx) return null; // 一度得た称号は格下げしない。現在以下の格ならそのまま据え置く
 PC._nobilityTitle = newTitle;
 const region = HERO_REGIONS[result.regionKey];
 addLifeEvent('', `${region?region.name:'その地方'}にて領地${result.count}つが領民800人を超える繁栄を成し遂げ、${newTitle}として認められた。`);
 return `<div style="border:2px solid var(--gold);border-radius:4px;padding:10px;margin-top:8px;background:#1a1408">
  <div style="color:#ffe0a0;font-size:var(--font-sm)"> 領地の繁栄が王国に認められ、あなたは「${newTitle}」の称号を授かった。</div>
 </div>`;
}

// ── 領民の信頼度 ──
// 信頼度 = ((領主の魅力+運+知力) + 設備ポイント合計 + ランダム0〜100) / 4
// 毎年初めに再計算するが、税収への適用は毎月その時点の値を参照する（年内のイベント変動にも対応するため）
function _fiefFacilityPoints(prop){
 return (prop.facilities||[]).reduce((s,id)=>{
  const f = FIEF_FACILITIES.find(x=>x.id===id);
  return s + (f?.trustPoints||0);
 }, 0);
}
function _fiefTrustRank(trust){
 if(trust >= 80) return { label:'理想郷',       taxMult:1.2, unrest:false };
 if(trust >= 60) return { label:'順調・繁栄',   taxMult:1.1, unrest:false };
 if(trust >= 40) return { label:'平均・不安定', taxMult:1.0, unrest:false };
 if(trust >= 20) return { label:'反抗的・挑戦的', taxMult:0.5, unrest:false };
 return             { label:'動乱・不穏',       taxMult:0,   unrest:true };
}
function _applyFiefYearlyTrust(prop){
 const nowYear = daysToDate(GAME_TIME.totalDays).year;
 if(prop.lastTrustCheckYear == null){
  prop.lastTrustCheckYear = nowYear;
  if(prop.trust == null){
   const facilityPts = _fiefFacilityPoints(prop);
   const base = (PC.chr||0) + (PC.lk||0) + (PC.iq||0);
   const rnd = Math.random()*101; // 0〜100
   prop.trust = Math.round((base + facilityPts + rnd) / 4);
  }
  return null;
 }
 const years = nowYear - prop.lastTrustCheckYear;
 if(years <= 0) return null;
 const before = prop.trust;
 const facilityPts = _fiefFacilityPoints(prop);
 const base = (PC.chr||0) + (PC.lk||0) + (PC.iq||0);
 const rnd = Math.random()*101;
 prop.trust = Math.round((base + facilityPts + rnd) / 4);
 prop.lastTrustCheckYear = nowYear;
 const rank = _fiefTrustRank(prop.trust);
 prop.ledger = prop.ledger||[];
 prop.ledger.unshift({ type:'trust', year:nowYear, before, after:prop.trust, rankLabel:rank.label });
 if(prop.ledger.length > 200) prop.ledger.length = 200;
 return `<div style="border:1px solid var(--border2);border-radius:4px;padding:8px;margin-top:8px">
  <span style="color:#c8b8a0">領民の信頼度が見直された：${before} → ${prop.trust}（${rank.label}）</span>
 </div>`;
}

// 領地の税収：領民1人あたり月1GP。50%は設備維持費、45%は地方の公爵への上納金として自動的に消え、
// 残り5%だけが拠点の保管庫に加わる（信頼度による倍率を乗せた上で）。拠点訪問時、経過月数分をまとめて処理する
function _fiefMonthKey(totalDays){
 const d = daysToDate(totalDays);
 return d.year*12 + d.month;
}
function _applyFiefMonthlyTax(prop){
 if(prop.population == null) return null;
 const nowKey = _fiefMonthKey(GAME_TIME.totalDays);
 if(prop.lastTaxMonthKey == null){ prop.lastTaxMonthKey = nowKey; return null; }
 const monthsElapsed = nowKey - prop.lastTaxMonthKey;
 if(monthsElapsed <= 0) return null;

 prop.ledger = prop.ledger||[];
 prop.storage = prop.storage||{ gold:0, sp:0, cp:0, weapons:[], armors:[], jewels:[], torches:0 };
 let totalGain = 0, totalUpkeep = 0, totalTribute = 0, totalUnrestLoss = 0;
 for(let i=0; i<monthsElapsed; i++){
  const monthKey = prop.lastTaxMonthKey + i + 1;
  const y = Math.floor((monthKey-1)/12);
  const m = ((monthKey-1)%12)+1;
  const pop = prop.population||0;
  const trust = prop.trust ?? 50;
  const rank = _fiefTrustRank(trust);

  if(rank.unrest){
   // 動乱・不穏：税収は完全に途絶し、通常の2〜3倍のペースで人口が減る
   const monthlyBase = 1 + Math.floor(Math.random()*4); // 通常ペースの月割り目安（1〜4人）
   const mult = 2 + Math.random(); // 2〜3倍
   const loss = Math.round(monthlyBase * mult);
   prop.population = Math.max(5, pop - loss);
   totalUnrestLoss += loss;
   prop.ledger.unshift({ type:'tax', year:y, month:m, population:pop, tax:0, upkeep:0, tribute:0, gain:0, unrest:true, unrestLoss:loss });
   continue;
  }

  const taxBase = pop * 1;
  const tax = Math.round(taxBase * rank.taxMult);
  const upkeep = Math.round(tax*0.50);
  const tribute = Math.round(tax*0.45);
  const gain = Math.max(0, tax - upkeep - tribute); // 残り5%相当（丸め誤差はここで吸収）
  prop.storage.gold = (prop.storage.gold||0) + gain;
  totalGain += gain; totalUpkeep += upkeep; totalTribute += tribute;
  prop.ledger.unshift({ type:'tax', year:y, month:m, population:pop, tax, upkeep, tribute, gain });
 }
 if(prop.ledger.length > 200) prop.ledger.length = 200;
 prop.lastTaxMonthKey = nowKey;
 const titleHtml = _updateNobilityTitle();
 if(totalGain+totalUpkeep+totalTribute+totalUnrestLoss <= 0) return titleHtml;
 let msg = `${monthsElapsed}ヶ月分の税収を処理した。`;
 if(totalGain+totalUpkeep+totalTribute > 0) msg += `維持費${totalUpkeep}GP・上納金${totalTribute}GPを差し引き、保管庫に${totalGain}GPが加わった。`;
 if(totalUnrestLoss > 0) msg += `<br><span style="color:#c05040">動乱により、領民${totalUnrestLoss}人が離散した。</span>`;
 return `<div style="border:1px solid var(--border2);border-radius:4px;padding:8px;margin-top:8px">
  <span style="color:#c8b8a0">${msg}</span>
 </div>` + (titleHtml || '');
}

// 領地のイベント台帳を表示する
function showFiefLedger(townId){
 const prop = PC.properties?.[townId];
 const ledger = prop?.ledger||[];
 const story = document.getElementById('story');

 // 直近1ヶ月分の税収・支出記録（動乱時も含め、最新のtaxタイプを1件だけ探す）
 const latestTax = ledger.find(l=>l.type==='tax');
 const taxHtml = latestTax
  ? (latestTax.unrest
    ? `<div style="border:1px solid #6a3030;border-radius:4px;padding:8px;margin-top:6px">
       <span style="color:#c8a8a0;font-size:calc(var(--font-sm) - 1px)">${latestTax.year}年${latestTax.month}月</span>　<span style="color:#e08070">動乱・不穏</span><br>
       <span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">税収は完全に途絶。領民${latestTax.unrestLoss}人が離散した（${latestTax.population}人 → ${Math.max(0,latestTax.population-latestTax.unrestLoss)}人）</span>
      </div>`
    : `<div style="border:1px solid var(--border2);border-radius:4px;padding:8px;margin-top:6px">
       <span style="color:#c8a8a0;font-size:calc(var(--font-sm) - 1px)">${latestTax.year}年${latestTax.month}月</span>　<span style="color:#e0d8c8">税収</span><br>
       <span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">領民${latestTax.population}人＝${latestTax.tax}GP　（維持費${latestTax.upkeep}GP／上納金${latestTax.tribute}GP／保管庫+${latestTax.gain}GP）</span>
      </div>`)
  : '<span style="color:#b0a080">まだ税収の記録はない。</span>';

 // それ以外（人口変動・地方イベント・信頼度）は引き続き時系列で並べる
 const eventsHtml = ledger.filter(l=>l.type!=='tax').map(l=>{
    if(l.type==='population'){
     const diffText = l.diff > 0 ? `+${l.diff}人` : `${l.diff}人`;
     return `<div style="border:1px solid var(--border2);border-radius:4px;padding:8px;margin-top:6px">
      <span style="color:#c8a8a0;font-size:calc(var(--font-sm) - 1px)">${l.year}年</span>　<span style="color:#e0d8c8">人口変動</span><br>
      <span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">${l.before}人 → ${l.after}人（${diffText}）</span>
     </div>`;
    }
    if(l.type==='fief_event'){
     const isBad = l.impact < 0;
     const dateLabel = l.month ? `${l.year}年${l.month}月` : `${l.year}年 第${l.quarter}四半期`;
     const flavor = l.flavor || '';
     const popLine = l.impact!==0
      ? `${isBad?'領地に被害が発生し':'恩恵があったのか'}人口が${l.populationAfter}人になった。`
      : '';
     return `<div style="border:1px solid ${isBad?'#6a4030':'var(--border2)'};border-radius:4px;padding:8px;margin-top:6px">
      <span style="color:#c8a8a0;font-size:calc(var(--font-sm) - 1px)">${dateLabel}</span>　<span style="color:${isBad?'#e0a070':'#e0d8c8'}">${l.eventName}が発生した。</span><br>
      <span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">${flavor}${popLine?(flavor?'<br>':'')+popLine:''}</span>
     </div>`;
    }
    if(l.type==='trust'){
     return `<div style="border:1px solid var(--border2);border-radius:4px;padding:8px;margin-top:6px">
      <span style="color:#c8a8a0;font-size:calc(var(--font-sm) - 1px)">${l.year}年</span>　<span style="color:#e0d8c8">信頼度の見直し</span><br>
      <span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">${l.before} → ${l.after}（${l.rankLabel}）</span>
     </div>`;
    }
    return '';
   }).join('');

 story.innerHTML = ` <span style="color:#f0ece0">領地のイベント台帳</span><br><br>`
  + `<b style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">今月の税収</b>`
  + taxHtml
  + `<hr style="border:none;border-top:1px solid var(--border2);margin:14px 0">`
  + (eventsHtml || '<span style="color:#b0a080">まだ記録はない。</span>');
 renderChoices([
  {label:'← 拠点に戻る', fn:()=>_showPropertyMain(townId)},
 ]);
}

// 領地の名前をいつでも変更できるようにする
function renameFief(townId){
 const prop = PC.properties?.[townId];
 if(!prop) return;
 const current = prop.fiefName || '無名の領地';
 const input = prompt('領地の新しい名前を入力してください。', current);
 if(input == null) return; // キャンセル
 const newName = input.trim();
 if(!newName){
  showSaveToast('名前が入力されなかったため、変更しなかった');
  return;
 }
 const oldName = prop.fiefName;
 prop.fiefName = newName;
 addLifeEvent('', oldName ? `領地の名前を「${oldName}」から「${newName}」に改めた。` : `領地に「${newName}」と名付けた。`);
 showSaveToast(`領地の名前を「${newName}」に変更した`);
 _showPropertyMain(townId);
}

// ── 複数領地対応のためのヘルパー群 ──
// 領地の拠点キー（PC.properties用）は 'fief_' + 基点となった町のIDで一意に決まる。
// これにより「町・村1つにつき紐づく領地は1つ」という制約が自然に守られる
function fiefIdForAnchor(anchorTownId){ return 'fief_' + anchorTownId; }
function isFiefId(id){ return typeof id === 'string' && id.startsWith('fief_'); }
function getFiefCharter(fiefId){ return (PC._fiefCharters||[]).find(c=>c.fiefId===fiefId); }
function getFiefCharterByAnchor(anchorTownId){ return (PC._fiefCharters||[]).find(c=>c.anchorTownId===anchorTownId); }

// 旧形式（PC._fiefCharter単数・PC.properties.fief）のデータが残っていれば新形式に変換する。
// セーブ読み込み時だけでなく、更新をまたいでリロードせずに遊び続けているセッションでも
// 主要な領地画面に入るたびに呼び、その場で自己修復できるようにする
function _migrateFiefDataIfNeeded(){
 if(PC._fiefCharter && !PC._fiefCharters){
  const oldCharter = PC._fiefCharter;
  const fiefId = fiefIdForAnchor(oldCharter.anchorTownId);
  PC._fiefCharters = [{ ...oldCharter, fiefId }];
  delete PC._fiefCharter;
  if(PC.properties && PC.properties.fief){
   PC.properties[fiefId] = PC.properties.fief;
   delete PC.properties.fief;
  }
 }
}

// 旧形式（motiveTag等が無い）の背景データに、動機タグ・固有データを逆引きして補完する。
// PC.background.motive（文字列）がBG_MOTIVE内のいずれかの文面と一致すれば、そのタグ等を復元する。
function _migrateBackgroundMotiveIfNeeded(){
 if(!PC.background || PC.background.motiveTag !== undefined) return;
 const allMotives = [...BG_MOTIVE.warrior, ...BG_MOTIVE.wizard];
 const match = allMotives.find(m => m.text === PC.background.motive);
 if(match){
  PC.background.motiveTag = match.tag || null;
  PC.background.motiveClue = match.clue || null;
  PC.background.motiveTarget = match.target || null;
  PC.background.motiveSubject = match.subject || null;
  PC.background.motiveWrongdoing = match.wrongdoing || null;
  PC.background.motiveWhoJudges = match.whoJudges || null;
  PC.background.motiveIsDebt = match.isDebt || false;
  _initMotiveExtras(PC.background, match);
 } else {
  PC.background.motiveTag = null;
 }
}

function showRegionalPalace(townId){
 _migrateFiefDataIfNeeded();
 const town = TOWNS[townId];
 const regionKey = getRegionKey(townId);
 const region = HERO_REGIONS[regionKey];
 const story = document.getElementById('story');
 const heroCount = countHeroTownsInRegion(regionKey);
 PC._fiefCharters = PC._fiefCharters||[];

 // 既に持っている領地のうち、領民800人を超えたものの数だけ、次の免状を取得できる
 const qualifyingCount = PC._fiefCharters.filter(c=>{
  const p = PC.properties?.[c.fiefId];
  return (p?.population||0) > 800;
 }).length;
 const maxAllowed = 1 + qualifyingCount;
 const atCap = PC._fiefCharters.length >= maxAllowed;
 const ownedListText = PC._fiefCharters.map(c=>{
  const p = PC.properties?.[c.fiefId];
  const ownedRegion = HERO_REGIONS[c.regionKey];
  const anchorName = (TOWNS[c.anchorTownId]||{name:c.anchorTownId}).name;
  const popText = p?.population != null ? `・領民${p.population}人` : '';
  return `${p?.fiefName||'名もなき領地'}（${ownedRegion?ownedRegion.name:'ある地方'}／${anchorName}より${c.anchorDays}日${popText}）`;
 }).join('、');

 let body;
 if(PC._fiefCharters.length > 0 && atCap){
  body = `<span style="color:#c8b8a0">あなたは既に${ownedListText}を治めている。次の領地を賜るには、いずれかの領地で領民が800人を超える繁栄を成し遂げる必要がある。</span>`;
 } else if(heroCount === 0){
  body = `<span style="color:#c8b8a0">受付の役人は${PC.name}の名を聞いて丁重に頭を下げたが、こう告げた。「領地の話は、まだこの地方でお名前が知れ渡ってからということで……」</span>`;
 } else {
  const price = calcFiefCharterPrice(regionKey);
  const introText = PC._fiefCharters.length > 0
   ? `<span style="color:#c8b8a0">既に${ownedListText}を治めるあなたの繁栄は、王国中の知るところとなっている。</span><br><br>`
   : '';
  body = introText
   + `<span style="color:#e8e0d0">${region.name}の${heroCount}つの町であなたの武名は既に轟いている。役人が恭しく巻物を捧げ持ち、告げた。</span><br><br>`
   +`<span style="color:#c8b8a0">「${region.name}にて領地を賜りたいとの由、承知いたしました。しかるべき手続きを経れば、この封地免状をお渡しできます」</span><br><br>`
   +`<span style="color:#ffcc88">封地免状：${price}GP（英雄となっている町：${heroCount}／${region.towns.length}）</span>`;
 }

 story.innerHTML = ` <span style="color:#e0d8c8">${town?.name || townId} 庁舎・宮殿</span><br><br>${body}`;

 const choices = [];
 if(!atCap && heroCount > 0){
  const price = calcFiefCharterPrice(regionKey);
  choices.push({label:` 封地免状を授かる（${price}GP）`, fn:()=>showFiefLocationSelect(townId, regionKey, price)});
 }
 choices.push({label:'← 広場に戻る', fn:()=>smallTownHub(townId)});
 renderChoices(choices);
}

// 領地の位置を選ぶ：地方内のどこかの町・集落から15〜20日の地点となる
function showFiefLocationSelect(townId, regionKey, price){
 const region = HERO_REGIONS[regionKey];
 const story = document.getElementById('story');
 story.innerHTML = ` <span style="color:#e0d8c8">${(TOWNS[townId]||{}).name || townId} 庁舎・宮殿</span><br><br>`
  +`<b> 領地の位置を選ぶ</b><br><br>`
  +`<span style="color:#c8b8a0">領地は${region.name}のいずれかの町・集落から15〜20日ほど離れた地に定められる。基点となる町・集落を選んでください。</span>`;
 renderChoices([
  ...region.towns.map(t=>({
   label:`${(TOWNS[t]||{name:t}).name}から`,
   fn:()=>showFiefLocationConfirm(townId, regionKey, price, t),
  })),
  {label:'← 戻る', fn:()=>showRegionalPalace(townId)},
 ]);
}

// 距離を確定し、最終確認を行う
function showFiefLocationConfirm(townId, regionKey, price, anchorTownId){
 const region = HERO_REGIONS[regionKey];
 const days = 15 + Math.floor(Math.random()*6); // 15〜20日
 const anchorName = (TOWNS[anchorTownId]||{name:anchorTownId}).name;
 const story = document.getElementById('story');
 story.innerHTML = ` <span style="color:#e0d8c8">${(TOWNS[townId]||{}).name || townId} 庁舎・宮殿</span><br><br>`
  +`<span style="color:#e8e0d0">役人が地図を広げ、${anchorName}から${days}日ほど離れた地点に印をつけた。</span><br><br>`
  +`<span style="color:#ffcc88">領地の位置：${anchorName}より${days}日</span><br>`
  +`<span style="color:#ffcc88">封地免状：${price}GP</span>`;
 renderChoices([
  {label:` この位置で封地免状を授かる（${price}GP）`, fn:()=>{
   if((PC.gold||0) < price){
    showSaveToast('所持金が足りない');
    return;
   }
   PC.gold -= price;
   PC._fiefCharters = PC._fiefCharters||[];
   PC._fiefCharters.push({
    fiefId: fiefIdForAnchor(anchorTownId),
    regionKey, townId,
    anchorTownId, anchorDays: days,
    obtainedDay: GAME_TIME.totalDays,
   });
   updateHUD();
   addLifeEvent('', `${region.name}・${anchorName}より${days}日の地に封地免状を授かった。`);
   showSaveToast(`封地免状を授かった（${price}GP）`);
   showRegionalPalace(townId);
  }},
  {label:'← 基点を選び直す', fn:()=>showFiefLocationSelect(townId, regionKey, price)},
 ]);
}

function checkRegionHero(){
 if(!PC._heroTowns) return;
 if(!PC._heroRegions) PC._heroRegions = {};

 for(const [regionKey, region] of Object.entries(HERO_REGIONS)){
  if(PC._heroRegions[regionKey]) continue; // 既に達成済み

  // その地方の全町で英雄になっているか
  const allHero = region.towns.every(t => PC._heroTowns[t]);
  if(!allHero) continue;

  // 地方英雄達成！
  PC._heroRegions[regionKey] = true;
  const regionMsgs = [
   `${region.name}の各地から使者が集まり、${PC.name}を「地方の英雄」として認めた。`,
   `${region.name}全土に${PC.name}の名が轟いた。旅人も商人も、その名を知らぬ者はいない。`,
   `${region.name}の長老会議が開かれ、${PC.name}に地方英雄の称号が授けられた。`,
   `${region.name}の民が一堂に集い、${PC.name}の功績を称える祭りが三日三晩続いた。`,
  ];
  const regionMsg = regionMsgs[Math.floor(Math.random() * regionMsgs.length)];
  addLifeEvent('', `【地方英雄】${region.name}の英雄として認められた。${regionMsg}`);
  PC._pendingRegionHeroMsg = { regionName: region.name, msg: regionMsg };
 }
}

// 地方の全ての町で極悪人になったかチェック（地方英雄と同じ地方区分を流用）
// ── 地方ごとの依頼傾向・評価 ──────────────────────────────
const QUEST_TYPE_WEIGHT = {
 delivery_local: 1, delivery_cross: 2, purchase: 2, escort: 2, contraband: 1,
 hunt: 4, bounty: 3, kidnapping: 2, assassination: 3,
};
const QUEST_TYPE_LABEL = {
 delivery_local:'配達人', delivery_cross:'配達人', purchase:'配達人', escort:'用心棒', contraband:'密輸人',
 hunt:'討伐屋', bounty:'賞金稼ぎ', kidnapping:'誘拐屋', assassination:'暗殺者',
};
// 酒場の噂で「〇〇の仕事なら△△に任せろ」と話す際の、評価ラベルごとの仕事内容の言い回し
const QUEST_LABEL_TASK_PHRASE = {
 '配達人':'届け物', '用心棒':'護衛の仕事', '密輸人':'ちょっとした裏の仕事',
 '討伐屋':'モンスター退治', '賞金稼ぎ':'賞金首の始末', '誘拐屋':'厄介な頼まれごと', '暗殺者':'表沙汰にできない頼まれごと',
};

// 依頼達成を地方ごとに記録する
function recordRegionQuest(townId, qtype){
 const regionKey = getRegionKey(townId);
 if(!regionKey || !QUEST_TYPE_WEIGHT[qtype]) return;
 // 地方状態システムへの反映（§6の点数表。地方内配達・護衛・討伐・賞金首のみ対象）
 applyRegionConditionQuestDelta(townId, qtype);
 if(!PC._regionQuestStats) PC._regionQuestStats = {};
 if(!PC._regionQuestStats[regionKey]) PC._regionQuestStats[regionKey] = {};
 const stats = PC._regionQuestStats[regionKey];
 if(!stats[qtype]) stats[qtype] = { count:0, firstDay: GAME_TIME.totalDays };
 stats[qtype].count += 1;

 // 評価ラベルが変わったかチェック
 if(!PC._regionEvalLabel) PC._regionEvalLabel = {};
 const prevLabel = PC._regionEvalLabel[regionKey] || null;
 const top = getRegionTopQuestType(regionKey);
 const newLabel = top ? top.label : null;
 if(newLabel && newLabel !== prevLabel){
  PC._regionEvalLabel[regionKey] = newLabel;
  const regionName = (HERO_REGIONS[regionKey]||{}).name || regionKey;
  PC._pendingRegionEvalMsg = { regionName, label: newLabel, prevLabel };
 }
}

// ある地方で最も点数の高い依頼種別（評価ラベル）を求める
// 同点なら重みが重い方、重みも同じなら先に達成した方（firstDayが早い方）を優先
function getRegionTopQuestType(regionKey){
 const stats = (PC._regionQuestStats||{})[regionKey];
 if(!stats) return null;
 // 同じ評価ラベルを持つ種別（例：地方内宅配・地方またぎ宅配・買い付け→配達人）は合算して扱う
 const labelGroups = {};
 for(const [qtype, data] of Object.entries(stats)){
  if(!data.count) continue;
  const label = QUEST_TYPE_LABEL[qtype];
  if(!label) continue;
  const weight = QUEST_TYPE_WEIGHT[qtype] || 0;
  if(!labelGroups[label]) labelGroups[label] = { score:0, count:0, weight:0, firstDay: data.firstDay };
  const g = labelGroups[label];
  g.score += weight * data.count;
  g.count += data.count;
  g.weight = Math.max(g.weight, weight);
  g.firstDay = Math.min(g.firstDay, data.firstDay);
 }
 let best = null;
 for(const [label, g] of Object.entries(labelGroups)){
  if(g.count <= 30) continue; // 足切り：30件を超えていない種別はそもそも候補にしない
  const cand = { label, score:g.score, weight:g.weight, firstDay:g.firstDay, count:g.count };
  if(!best
     || cand.score > best.score
     || (cand.score === best.score && cand.weight > best.weight)
     || (cand.score === best.score && cand.weight === best.weight && cand.firstDay < best.firstDay)){
   best = cand;
  }
 }
 if(!best) return null;
 return { label: best.label, score: best.score, count: best.count };
}

function checkRegionInfamy(){
 if(!PC._infamyTowns) return;
 if(!PC._infamyRegions) PC._infamyRegions = {};

 for(const [regionKey, region] of Object.entries(HERO_REGIONS)){
  if(PC._infamyRegions[regionKey]) continue; // 既に達成済み

  // その地方の全町で極悪人になっているか
  const allInfamous = region.towns.every(t => PC._infamyTowns[t]);
  if(!allInfamous) continue;

  // 地方最悪の極悪人達成！
  PC._infamyRegions[regionKey] = true;
  const regionMsgs = [
   `${region.name}のどの町に行っても、${PC.name}の名を知らぬ者はいなくなった。恐れと嫌悪の視線が、行く先々でついて回る。`,
   `${region.name}全土の衛兵詰所に、${PC.name}の似顔絵入りの手配書が貼り出された。「地方最悪の極悪人」と記されている。`,
   `${region.name}の各町の長が密かに集まり、${PC.name}への対応を協議したという噂が流れた。`,
   `${region.name}を旅する商人たちの間で、${PC.name}に関わるなという警告が合言葉のように広まっている。`,
  ];
  const regionMsg = regionMsgs[Math.floor(Math.random() * regionMsgs.length)];
  addLifeEvent('', `【地方最悪の極悪人】${region.name}のどこでも極悪人として知られるようになった。${regionMsg}`);
  PC._pendingRegionInfamyMsg = { regionName: region.name, msg: regionMsg };
 }
}

// 信頼度ランク
function trustRank(townId){
 const t = getTrust(townId);
 if(t >= 75) return {label:'地元の英雄', color:'#f0ece0', disc:0.8};
 if(t >= 50) return {label:'常連',       color:'#e0d8c8', disc:0.9};
 if(t >= 25) return {label:'顔見知り',   color:'#c8b8a0', disc:1.0};
 return             {label:'よそ者',     color:'#b0a898', disc:null}; // 購入不可（SR必要）
}

