 const prop = PC.properties[townId];
 const story = document.getElementById('story');
 const otherProps = Object.keys(PC.properties||{}).filter(t=>t!==townId);

 // 転居できる人物リスト（留守番＋子ども全員）
 const members = [
  ...(prop.caretakers||[]).map(n=>({...n, _isChild:false})),
  ...(prop.children||[]).map(c=>({...c, _isChild:true})),
 ];

 story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
