function propertyTransferDest(fromTownId, member, destTownIds){
 const fromDef = PROPERTY_DEFS[fromTownId];
 const story = document.getElementById('story');

 // 護送費計算：徒歩日数×2GP（最低10GP）、ルートなしは一律100GP
 const calcCost = (destId)=>{
  const route = getRoute(fromTownId, destId);
  if(!route) return 100;
  const days = route.days.walk || route.days.coach || 30;
  return Math.max(10, days * 10);
 };

 story.innerHTML = ` <span style="color:#f0ece0">${fromDef.name}</span><br><br>`
  +`<b> 転居先を選ぶ</b><br><br>`
  +`<span style="color:#c0b098">${member.name}をどの拠点へ転居させますか？</span><br>`
  +`<span class="dim" style="font-size:calc(var(--font-sm) - 1px)">護送費：徒歩日数×2GP（最低10GP）</span>`;

 renderChoices([
  ...destTownIds.map(destId=>{
   const destDef = PROPERTY_DEFS[destId];
   const cost = calcCost(destId);
   const canAfford = (PC.gold||0) >= cost;
   // 転居先の保管金チェック（30日分の生活費を目安に警告）
   const destPropData = PC.properties[destId];
   const destStorGP = (destPropData?.storage?.gold)||0;
   const destCurrentMembers = (destPropData?.caretakers||[]).length + (destPropData?.children||[]).length;
   const newMemberCount = destCurrentMembers + 1;
   const warnDays = 30;
   const needed = newMemberCount * warnDays * foodPrice(1);
   const lowFunds = destStorGP < needed;
   const warnLabel = lowFunds ? ` ⚠ 生活費不足の恐れあり（保管:${destStorGP}GP / 目安${needed}GP）` : '';
   return {label:` ${destDef.name}へ（護送費 ${cost}GP）${canAfford?'':'　［所持金不足］'}${warnLabel}`, fn:()=>{
    if(!canAfford){ showSaveToast('所持金が足りない'); return; }
    const fromProp = PC.properties[fromTownId];
    const destProp = PC.properties[destId];
    destProp.caretakers = destProp.caretakers||[];
    destProp.children = destProp.children||[];    console.log('移送メンバー:', member.name, 'isChild:', member._isChild, '_npcId:', member._npcId);

    if(member._isChild){
     const idx = (fromProp.children||[]).findIndex(c=>c.bornDay===member.bornDay&&c.name===member.name);
     console.log('子どもidx:', idx);
     if(idx>=0){
      const [child] = fromProp.children.splice(idx,1);
      destProp.children.push(child);
     }
    } else {
     const idx = (fromProp.caretakers||[]).findIndex(n=>n._npcId===member._npcId);
     console.log('留守番idx:', idx, 'from caretakers:', JSON.stringify((fromProp.caretakers||[]).map(n=>({name:n.name,id:n._npcId}))));
     if(idx>=0){
      const [npc] = fromProp.caretakers.splice(idx,1);
      destProp.caretakers.push(npc);     }
    }

    payPrice(cost);
    addLifeEvent('', `${member.name}を${fromDef.name}から${destDef.name}へ転居させた。（護送費${cost}GP）`);
    updateHUD();
    showSaveToast(` ${member.name}を${destDef.name}へ転居させた（${cost}GP）`);
    propertyManageCaretakers(fromTownId);
   }};
  }),
  {label:'← 戻る', fn:()=>propertyTransfer(fromTownId)},
 ]);
}

// ══════════════════════════════════════════════════
// ── 留守番パーティの自主遠征 ──
// 拠点の留守番NPCだけでパーティを組み、PC抜きで1〜6日の遠征に送り出す。
// 結果は拠点訪問時に自動解決（プレイヤーは操作しない）。報酬・戦利品は拠点の保管庫へ。
// ══════════════════════════════════════════════════
// 拠点1つあたり、同時に送り出せる遠征パーティの上限
const EXPEDITION_MAX_PARTIES = 4;

const EXPEDITION_TYPES = [
 { id:'hunt',    label:'討伐遠征',     risk:'高',   desc:'地方の脅威となるモンスターを狩りに行く。危険は大きいが実入りも良い。' },
 { id:'explore', label:'探索遠征',     risk:'中',   desc:'近隣の遺跡や洞窟の未踏エリアを探索する。罠による負傷が中心。' },
 { id:'escort',  label:'護衛任務',     risk:'低〜中', desc:'商隊や旅人を他の町まで送り届ける。町の信頼度も上がる。' },
 { id:'forage',  label:'採取・薬草集め', risk:'低',   desc:'安全な範囲で薬草や素材を集める。実入りは少ないがほぼ無傷。' },
 { id:'trade',   label:'交易随行',     risk:'低',   desc:'隊商に同行して荷運びを手伝う。安定した稼ぎと経験が得られる。' },
];

// 留守番パーティを送り出すメンバーを選ぶ画面
function propertyExpeditionSelectMembers(townId, selected){
 selected = selected || [];
 const def = isFiefId(townId) ? PROPERTY_DEFS.fief : PROPERTY_DEFS[townId];
 const prop = PC.properties[townId];
 const caretakers = prop.caretakers||[];
 const story = document.getElementById('story');

 story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
  +`<b> 遠征メンバーを選ぶ</b><br><br>`
  +`<span style="color:#c0b098">誰を遠征に送りますか？（1人から可）</span><br>`
  +(selected.length ? `<span style="color:#ffcc88">選択中：${selected.map(n=>n.name).join('、')}</span><br>` : '')
  +(selected.length >= caretakers.length ? `<span style="color:#c05040">⚠ 全員を送ると拠点の留守番が不在になり、盗難のリスクが生じます</span><br>` : '');

 const remaining = caretakers.filter(n=>!selected.includes(n));
 renderChoices([
  ...remaining.map(n=>({
   label:` ${n.name}を加える（${({warrior:'戦士',rogue:'盗賊',wizard:'魔法使い'})[n.type]||n.type}・Lv${n.level||1}）`,
   fn:()=>propertyExpeditionSelectMembers(townId, [...selected, n]),
  })),
  ...(selected.length ? [{label:' このメンバーで進む', fn:()=>propertyExpeditionSelectType(townId, selected)}] : []),
  {label:'← 拠点に戻る', fn:()=>_showPropertyMain(townId)},
 ]);
}

// 遠征先の候補地名（探索遠征用のフレーバー）
const EXPEDITION_EXPLORE_SITES = [
 '旧坑道', '崩れた聖堂の地下', '忘れられた地下墓所', '砂に埋もれた廃墟',
 '森の奥の遺跡', '打ち捨てられた砦', '古い盗賊のアジト跡', '干上がった水路の奥',
];

// townIdの地方から、townId以外のランダムな町を1つ選ぶ（護衛・交易の目的地用）
// 近隣2〜3町を旅程日数順に洗い出し、その中からランダムに1つ選ぶ（本当に近い町の中で毎回変化を持たせる）。
// ルートが1つも見つからない場合のみ、同地方内からランダムに選ぶフォールバックを使う。
// 戻り値：{ name: 町名, days: 片道所要日数（フォールバック時はnull） }
function _pickExpeditionDestTown(townId){
 const candidates = Object.keys(TOWNS).filter(t=>t!==townId);
 const withDays = candidates.map(destId=>{
  const route = getRoute(townId, destId);
  if(!route) return null;
  // 留守番NPCは馬車・船を使わず徒歩で移動する想定。徒歩ルートがなければ次点として馬車→船の順で使う
  const days = route.days.walk ?? route.days.coach ?? route.days.ship ?? Infinity;
  return isFinite(days) ? {destId, days} : null;
 }).filter(Boolean).sort((a,b)=>a.days-b.days);

 if(withDays.length){
  const nearest = withDays.slice(0, Math.min(3, withDays.length));
  const pick = nearest[Math.floor(Math.random()*nearest.length)];
  return { name:(TOWNS[pick.destId]||{name:pick.destId}).name, days:pick.days };
 }
 const region = getRegionKey(townId);
 const pool = (region && REGIONS[region]) ? REGIONS[region].filter(t=>t!==townId) : candidates;
 const best = (pool.length ? pool : candidates)[Math.floor(Math.random()*(pool.length?pool.length:candidates.length))];
 return { name:(TOWNS[best]||{name:best}).name, days:null };
}

// 5種の遠征内容を具体的に確定させる（討伐相手・探索先・護衛先などをこの時点で決めて記憶する）
// 種類を1つ指定して、その内容だけを新しく確定させる（連続遠征の再出発時に使う）
function _generateSingleExpeditionOffer(townId, typeId){
 // 拠点が領地の場合、地方・目的地の判定は免状の基点となった町を基準にする
 const isFief = isFiefId(townId);
 const fiefCharter = isFief ? getFiefCharter(townId) : null;
 const regionRefTownId = isFief ? (fiefCharter?.anchorTownId || townId) : townId;

 if(typeId === 'hunt'){
  const region = getRegionKey(regionRefTownId) || 'khazan_region';
  const table = HUNT_MONSTER_TABLE[region] || HUNT_MONSTER_TABLE.khazan_region;
  const totalWeight = table.reduce((s,e)=>s+(e.weight!=null?e.weight:1), 0);
  let r = Math.random()*totalWeight, mEntry = table[table.length-1];
  for(const e of table){ const w=e.weight!=null?e.weight:1; if(r<w){ mEntry=e; break; } r-=w; }
  const count = mEntry.minApp + Math.floor(Math.random()*(mEntry.maxApp-mEntry.minApp+1));
  return { typeId:'hunt', label:` 討伐遠征：${mEntry.name}${count>1?`（${count}体）`:''}の討伐`, target:{mEntry, count} };
 }
 if(typeId === 'explore'){
  const site = EXPEDITION_EXPLORE_SITES[Math.floor(Math.random()*EXPEDITION_EXPLORE_SITES.length)];
  const depth = 1 + Math.floor(Math.random()*5);
  return { typeId:'explore', label:` 探索遠征：${site}を探る`, target:{site, depth} };
 }
 if(typeId === 'escort'){
  // 領地からの護衛は、免状の基点となった町（＝実際に旅で行き来している唯一の町）のみを対象にする
  const dest = isFief
   ? { name:(TOWNS[regionRefTownId]||{name:regionRefTownId}).name, days:fiefCharter?.anchorDays }
   : _pickExpeditionDestTown(townId);
  return { typeId:'escort', label:` 護衛任務：${dest.name}への隊商護衛（片道${dest.days??'?'}日）`, target:{destName:dest.name, destDays:dest.days} };
 }
 if(typeId === 'forage'){
  return { typeId:'forage', label:' 採取・薬草集め：郊外での採取', target:{} };
 }
 if(typeId === 'trade'){
  // 領地からの交易随行も同様に、基点の町のみを対象にする
  const dest = isFief
   ? { name:(TOWNS[regionRefTownId]||{name:regionRefTownId}).name, days:fiefCharter?.anchorDays }
   : _pickExpeditionDestTown(townId);
  return { typeId:'trade', label:` 交易随行：${dest.name}への隊商随行（片道${dest.days??'?'}日）`, target:{destName:dest.name, destDays:dest.days} };
 }
 return null;
}

function _generateExpeditionOffers(townId){
 return {
  hunt:    _generateSingleExpeditionOffer(townId, 'hunt'),
  explore: _generateSingleExpeditionOffer(townId, 'explore'),
  escort:  _generateSingleExpeditionOffer(townId, 'escort'),
  forage:  _generateSingleExpeditionOffer(townId, 'forage'),
  trade:   _generateSingleExpeditionOffer(townId, 'trade'),
 };
}

// 遠征の種類を選ぶ画面
function propertyExpeditionSelectType(townId, members){
 const story = document.getElementById('story');
 const offers = _generateExpeditionOffers(townId);

 story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
  +`<b> 遠征の内容を選ぶ</b><br><br>`
  +`<span style="color:#c0b098">メンバー：${members.map(n=>n.name).join('、')}</span><br><br>`
  +EXPEDITION_TYPES.map(t=>{
   const offer = offers[t.id];
   return `<div style="border:1px solid var(--border2);border-radius:4px;padding:6px 8px;margin-top:6px">
   <span style="color:#e0d8c8">${offer.label}</span>　<span style="color:#c8a8a0;font-size:calc(var(--font-sm) - 1px)">リスク：${t.risk}</span><br>
   <span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">${t.desc}</span></div>`;
  }).join('');

 renderChoices([
  ...EXPEDITION_TYPES.map(t=>({label:`${offers[t.id].label}に出発させる`, fn:()=>propertyExpeditionConfirmRepeat(townId, members, offers[t.id])})),
  {label:'← メンバー選択に戻る', fn:()=>propertyExpeditionSelectMembers(townId)},
 ]);
}

// 出発前に「1回だけ」か「停止するまで繰り返す」かを選ばせる
function propertyExpeditionConfirmRepeat(townId, members, offer){
 const story = document.getElementById('story');
 story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
  +`<b> ${offer.label.trim()}</b><br><br>`
  +`<span style="color:#c0b098">メンバー：${members.map(n=>n.name).join('、')}</span><br><br>`
  +`<span style="color:#c8b8a0">この内容を1回だけ行わせますか？　それとも、あなたが止めるまで同じ内容を繰り返させますか？</span>`;
 renderChoices([
  {label:' 1回だけ行かせる', fn:()=>propertyExpeditionDepart(townId, members, offer, false)},
  {label:' 停止するまで繰り返させる', fn:()=>propertyExpeditionDepart(townId, members, offer, true)},
  {label:'← 内容選択に戻る', fn:()=>propertyExpeditionSelectType(townId, members)},
 ]);
}

// 出発確定
function propertyExpeditionDepart(townId, members, offer, repeat){
 const prop = PC.properties[townId];
 prop.expeditions = prop.expeditions||[];
 if(prop.expeditions.length >= EXPEDITION_MAX_PARTIES){
  showSaveToast(`これ以上は同時に遠征に出せない（上限${EXPEDITION_MAX_PARTIES}隊）`);
  _showPropertyMain(townId);
  return;
 }
 // 護衛・交易随行は実際の目的地への片道日数×2（往復分）。それ以外は1〜6日のランダム
 const destDays = offer.target && offer.target.destDays;
 const days = (destDays != null) ? destDays * 2 : (1 + Math.floor(Math.random()*6));
 // 遠征に出るメンバーは、不在の間は留守番として数えない（泥棒リスク判定を正しく機能させるため、
 // caretakersから一時的に取り除いて遠征データ側で保持する）
 const memberIds = members.map(n=>n._npcId);
 prop.caretakers = (prop.caretakers||[]).filter(n=>!memberIds.includes(n._npcId));
 prop.expeditions.push({
  id: Date.now()+Math.random(),
  members,
  typeId: offer.typeId,
  offerLabel: offer.label,
  target: offer.target,
  departDay: GAME_TIME.totalDays,
  returnDay: GAME_TIME.totalDays + days,
  repeat: !!repeat,
  stopRequested: false,
 });
 const tDef = EXPEDITION_TYPES.find(t=>t.id===offer.typeId);
 const repeatNote = repeat ? '（停止するまで繰り返す）' : '';
 // 出発の記録は拠点の遠征記録（台帳）にのみ残す（ライフイベントには記録しない）
 prop.expeditionLog = prop.expeditionLog||[];
 prop.expeditionLog.unshift({
  type: 'depart',
  day: GAME_TIME.totalDays,
  label: offer.label.trim(),
  memberNames: members.map(n=>n.name).join('、'),
  repeat: !!repeat,
 });
 if(prop.expeditionLog.length > 20) prop.expeditionLog.length = 20;
 showSaveToast(`${members.map(n=>n.name).join('、')}が${offer.label.trim()}に出発した（${days}日の予定）${repeatNote}`);
 _showPropertyMain(townId);
}

// 拠点訪問時：帰還予定日を過ぎていれば結果を解決する。戻り値：解決していれば結果HTML、なければnull
function _checkExpeditionReturn(townId){
 const prop = PC.properties[townId];
 if(!prop || !(prop.expeditions||[]).length) return null;

 const due = prop.expeditions.filter(exp=>GAME_TIME.totalDays >= exp.returnDay);
 if(!due.length) return null;
 // 帰還したものだけ配列から取り除き、残り（まだ帰還日を迎えていないもの）は維持する
 prop.expeditions = prop.expeditions.filter(exp=>GAME_TIME.totalDays < exp.returnDay);

 const MAX_CYCLES_PER_VISIT = 200; // 1回の訪問で追いつかせる周回数の上限（極端な長期放置での処理落ち防止）
 let combinedHtml = '';

 due.forEach(exp=>{
  let currentExp = exp;
  let cycles = 0;
  let lastHtml = '';
  let cappedOut = false;

  // 「停止するまで繰り返す」設定の場合、帰還予定日を迎えるたびに自動で再抽選・再出発させ、
  // 現在の日付に追いつくまでこのまま連鎖させる（PCが訪問していなくても裏で進み続けたことにする）
  while(currentExp && GAME_TIME.totalDays >= currentExp.returnDay){
   const members = currentExp.members||[];
   if(!members.length){
    combinedHtml += `<div style="color:#c8a890"> 遠征に出た者たちの消息は分からないままだ……</div>`;
    currentExp = null;
    break;
   }
   const wasRepeat = currentExp.repeat && !currentExp.stopRequested;
   const { html, survivors } = _resolveExpedition(townId, prop, members, currentExp.typeId, currentExp.target||{}, currentExp.offerLabel, currentExp.returnDay);
   cycles++;
   lastHtml = html;

   if(wasRepeat && survivors.length){
    if(cycles >= MAX_CYCLES_PER_VISIT){ cappedOut = true; break; } // 続きは次回訪問時に持ち越す
    const newOffer = _generateSingleExpeditionOffer(townId, currentExp.typeId);
    if(!newOffer){ currentExp = null; break; }
    const memberIds = survivors.map(n=>n._npcId);
    prop.caretakers = (prop.caretakers||[]).filter(n=>!memberIds.includes(n._npcId));
    const destDays = newOffer.target && newOffer.target.destDays;
    const days = (destDays != null) ? destDays * 2 : (1 + Math.floor(Math.random()*6));
    // 帰還予定日は「前回の帰還予定日」からの積み上げにする（現在日からの計算だと周回数がズレるため）
    currentExp = {
     id: Date.now()+Math.random(),
     members: survivors,
     typeId: newOffer.typeId,
     offerLabel: newOffer.label,
     target: newOffer.target,
     departDay: currentExp.returnDay,
     returnDay: currentExp.returnDay + days,
     repeat: true,
     stopRequested: false,
    };
   } else {
    currentExp = null; // 停止指定・全滅・繰り返し設定なしのいずれかで打ち切り
   }
  }

  if(cycles > 1){
   combinedHtml += `<div style="border:1px solid var(--border2);border-radius:4px;padding:10px;margin-top:8px">
    <div style="color:#f0ece0;font-size:var(--font-sm);margin-bottom:6px"> 留守中に${cycles}回の遠征が繰り返された（直近の結果）</div>
    ${lastHtml}
   </div>`;
  } else if(cycles === 1){
   combinedHtml += lastHtml;
  }
  if(cappedOut){
   combinedHtml += `<div style="color:#a89878;font-size:calc(var(--font-sm) - 1px);margin-top:4px">（あまりに長期間留守にしていたため、続きは次に訪れた時に持ち越された）</div>`;
  }
  // まだ帰還日を迎えていない（あるいは上限で打ち切られた）遠征は、次回訪問時のためにそのまま積み直す
  if(currentExp) prop.expeditions.push(currentExp);
 });
 return combinedHtml;
}

// 遠征結果の解決本体（targetは出発時に確定済みの対象データ：討伐相手・探索先・護衛先など）
function _resolveExpedition(townId, prop, members, typeId, target, offerLabel, resolveDay){
 resolveDay = resolveDay != null ? resolveDay : GAME_TIME.totalDays; // 記録に使う日付（追いつき処理では実際の帰還予定日を渡す）
 prop.storage = prop.storage || { gold:0, sp:0, cp:0, weapons:[], armors:[], jewels:[], torches:0 };
 const tDef = EXPEDITION_TYPES.find(t=>t.id===typeId);
 const names = members.map(n=>n.name).join('、');
 let deathNames = []; // 遠征中に死亡したメンバー名（末尾でcaretakersへの復帰から除外する）
 let goldGained = 0;  // 記録用：この遠征で保管庫に入ったGP
 let apGained = 0;    // 記録用：メンバー1人あたりの獲得経験値
 let eventDesc = '';  // 記録用：道中で何があったか（山賊遭遇・罠発動等）の一言説明
 let html = `<div style="border:1px solid var(--border2);border-radius:4px;padding:10px;margin-top:8px">
  <div style="color:#f0ece0;font-size:var(--font-sm);margin-bottom:6px"> ${names}が${(offerLabel||tDef.label).trim()}から帰還した</div>`;

 if(typeId === 'hunt'){
  const mEntry = target.mEntry;
  const count = target.count||1;
  let monsterMR = mEntry.mr * count;
  const monsterArmor = mEntry.armor||0;
  const startCON = members.reduce((s,n)=>s+n.con,0);
  let partyCON = startCON;
  const partyArmor = members.reduce((s,n)=>s+calcNPCArmor(n),0) / members.length; // 平均防具値

  let rounds = 0;
  while(monsterMR > 0 && partyCON > 0 && rounds < 10){
   rounds++;
   const partyRoll = members.reduce((s,n)=>s+calcNPCRoll(n).total,0);
   const monsterRoll = monsterCombatRoll(monsterMR).total;
   const dmgToMonster = Math.max(0, partyRoll - monsterArmor);
   const dmgToParty = Math.max(0, monsterRoll - partyArmor*members.length);
   monsterMR -= dmgToMonster;
   partyCON -= dmgToParty;
  }

  if(partyCON <= 0){
   // 大敗：メンバーごとに死亡判定（負担割合に応じて）
   eventDesc = `${mEntry.name}の群れに大敗した`;
   html += `<div style="color:#c05040">大敗した。${mEntry.name}の群れに歯が立たなかった。</div>`;
   const deaths = [];
   members.forEach(n=>{
    const dieChance = 0.15 + Math.random()*0.25; // 15〜40%
    if(Math.random() < dieChance){
     deaths.push(n.name);
     addLifeEvent('', `${n.name}が${tDef.label}中に命を落とした。`);
    } else {
     n.con = Math.max(1, Math.floor(n.con*0.3));
    }
   });
   if(deaths.length){
    deathNames = deaths;
    prop.graves = prop.graves||[];
    deaths.forEach(name=>prop.graves.push({name, diedDay:resolveDay, cause:tDef.label}));
    html += `<div style="color:#c05040"> 訃報：${deaths.join('、')}が帰らぬ人となった。</div>`;
   }
  } else {
   const lostRatio = 1 - (partyCON/startCON);
   const mr0 = mEntry.mr*count;
   const gp = Math.floor(mr0 * (0.8+Math.random()*0.4));
   apGained = Math.floor(mr0 / members.length);
   if(lostRatio < 0.2){
    eventDesc = `${mEntry.name}を軽傷で討伐した（大成功）`;
    html += `<div style="color:#f0ece0">大成功。${mEntry.name}を軽傷で退けた。</div>`;
    goldGained = gp;
    prop.storage.gold = (prop.storage.gold||0) + gp;
   } else if(lostRatio < 0.6){
    eventDesc = `${mEntry.name}を討伐したが手傷を負った`;
    html += `<div style="color:#e0d8c8">${mEntry.name}を討伐したが、それなりの手傷を負った。</div>`;
    goldGained = gp;
    prop.storage.gold = (prop.storage.gold||0) + gp;
   } else {
    apGained = Math.floor(apGained*0.5);
    eventDesc = `${mEntry.name}に苦戦し撤退した`;
    html += `<div style="color:#c8a890">苦戦の末に撤退した。得るものは少なかった。</div>`;
    goldGained = Math.floor(gp*0.3);
    prop.storage.gold = (prop.storage.gold||0) + goldGained;
   }
   html += `<div style="color:#ffcc88"> 報酬：${goldGained}GP　経験値+${apGained}</div>`;
   members.forEach(n=>{ n.con = Math.max(1, Math.round(n.con * (partyCON/startCON))); gainAPFor(n, apGained); });
  }

 } else if(typeId === 'explore'){
  const depth = target.depth || (1 + Math.floor(Math.random()*5));
  const trapLv = ydRollTrapLevel(depth);
  const avgDex = members.reduce((s,n)=>s+(n.dex||10),0)/members.length;
  const avgLk  = members.reduce((s,n)=>s+(n.lk||10),0)/members.length;
  const roll = roll2D6explode().total + avgDex + avgLk;
  const srTarget = trapLv*5 + 15;
  if(roll >= srTarget){
   eventDesc = `${target.site||'未踏エリア'}の探索に成功した`;
   html += `<div style="color:#f0ece0">${target.site||'未踏エリア'}の探索に成功した。</div>`;
   goldGained = 10 + Math.floor(Math.random()*trapLv*10);
   apGained = trapLv * 5;
   prop.storage.gold = (prop.storage.gold||0) + goldGained;
   html += `<div style="color:#ffcc88"> 報酬：${goldGained}GP　経験値+${apGained}</div>`;
   members.forEach(n=>gainAPFor(n, apGained));
  } else {
   const dmg = trapLv + Math.floor(Math.random()*trapLv*2+1);
   const hurt = members[Math.floor(Math.random()*members.length)];
   hurt.con = Math.max(1, hurt.con-dmg);
   apGained = Math.floor(trapLv * 2);
   eventDesc = `${target.site||'未踏エリア'}で罠にかかった（${hurt.name}が負傷）`;
   html += `<div style="color:#c8a890">${target.site||'未踏エリア'}で罠にかかり、${hurt.name}が負傷した（体力-${dmg}）。収穫は無かったが、経験値+${apGained}は得た。</div>`;
   members.forEach(n=>gainAPFor(n, apGained));
  }

 } else if(typeId === 'escort'){
  const destName = target.destName || 'その町';
  const ambushed = Math.random() < 0.3;
  if(ambushed){
   const partyRoll = members.reduce((s,n)=>s+calcNPCRoll(n).total,0);
   const banditMR = 15 * members.length;
   if(partyRoll > monsterCombatRoll(banditMR).total){
    eventDesc = '道中で山賊に襲われたが、撃退した';
    html += `<div style="color:#f0ece0">${destName}への道中で山賊に襲われたが、撃退して無事に送り届けた。</div>`;
    goldGained = 8 + Math.floor(Math.random()*11); // 8〜18GP
    apGained = 15;
    prop.storage.gold = (prop.storage.gold||0) + goldGained;
    html += `<div style="color:#ffcc88"> 報酬：${goldGained}GP　経験値+${apGained}</div>`;
    changeTrust(townId, 2);
    members.forEach(n=>gainAPFor(n, apGained));
   } else {
    const hurt = members[Math.floor(Math.random()*members.length)];
    hurt.con = Math.max(1, Math.floor(hurt.con*0.6));
    apGained = 5;
    eventDesc = `道中で山賊に襲われ、苦戦した（${hurt.name}が負傷）`;
    html += `<div style="color:#c8a890">${destName}への道中で山賊に苦戦し、${hurt.name}が負傷した。護衛は不首尾に終わったが、経験値+${apGained}は得た。</div>`;
    members.forEach(n=>gainAPFor(n, apGained));
   }
  } else {
   eventDesc = '道中は平穏だった';
   html += `<div style="color:#f0ece0">${destName}までの道中は平穏で、無事に送り届けた。</div>`;
   goldGained = 5 + Math.floor(Math.random()*8); // 5〜12GP
   apGained = 8;
   prop.storage.gold = (prop.storage.gold||0) + goldGained;
   html += `<div style="color:#ffcc88"> 報酬：${goldGained}GP　経験値+${apGained}</div>`;
   changeTrust(townId, 1);
   members.forEach(n=>gainAPFor(n, apGained));
  }

 } else if(typeId === 'forage'){
  const avgLk = members.reduce((s,n)=>s+(n.lk||10),0)/members.length;
  const roll = roll2D6explode().total + avgLk;
  if(roll >= 20){
   eventDesc = '上質な薬草がよく採れた';
   goldGained = 5 + Math.floor(Math.random()*8);
   apGained = 4;
   prop.storage.gold = (prop.storage.gold||0) + goldGained;
   html += `<div style="color:#f0ece0">上質な薬草がよく採れた。</div><div style="color:#ffcc88"> 収穫：${goldGained}GP　経験値+${apGained}</div>`;
  } else {
   eventDesc = 'それなりの量を採ってきた';
   goldGained = 2 + Math.floor(Math.random()*4);
   apGained = 2;
   prop.storage.gold = (prop.storage.gold||0) + goldGained;
   html += `<div style="color:#c8b8a0">それなりの量を採ってきた。</div><div style="color:#ffcc88"> 収穫：${goldGained}GP　経験値+${apGained}</div>`;
  }
  members.forEach(n=>gainAPFor(n, apGained));

 } else if(typeId === 'trade'){
  const destName = target.destName || 'その町';
  const avgChr = members.reduce((s,n)=>s+(n.chr||10),0)/members.length;
  const roll = roll2D6explode().total + avgChr;
  goldGained = roll >= 20 ? (10+Math.floor(Math.random()*8)) : (5+Math.floor(Math.random()*6));
  apGained = 10;
  eventDesc = `${destName}への隊商随行を無事に終えた`;
  prop.storage.gold = (prop.storage.gold||0) + goldGained;
  html += `<div style="color:#f0ece0">${destName}への隊商随行を無事に終えた。</div><div style="color:#ffcc88"> 報酬：${goldGained}GP　経験値+${apGained}</div>`;
  members.forEach(n=>gainAPFor(n, apGained));
 }

 html += `</div>`;
 // 生存者は留守番として拠点に復帰させる（死亡者は除く）
 const survivors = members.filter(n=>!deathNames.includes(n.name));
 prop.caretakers = [...(prop.caretakers||[]), ...survivors];

 // 遠征の記録を保存（新しいものを先頭に、最大20件まで保持）
 prop.expeditionLog = prop.expeditionLog||[];
 prop.expeditionLog.unshift({
  type: 'result',
  day: resolveDay,
  label: (offerLabel||tDef.label).trim(),
  memberNames: names,
  deathNames: [...deathNames],
  goldGained,
  apGained,
  eventDesc,
  html,
 });
 if(prop.expeditionLog.length > 20) prop.expeditionLog.length = 20;

 return { html, survivors };
}

// 「拠点を管理する」メニューから、繰り返し遠征の停止を予約する
function _fiefStopExpedition(townId, expId){
 const prop = PC.properties[townId];
 const exp = (prop?.expeditions||[]).find(e=>e.id===expId);
 if(exp){
  exp.stopRequested = true;
  showSaveToast('次に帰還した時点で、遠征の繰り返しを取りやめます');
 }
 _showPropertyMain(townId);
}

// 遠征の記録一覧を表示
function propertyExpeditionLog(townId){
 const prop = PC.properties[townId];
 const log = prop.expeditionLog||[];
 const story = document.getElementById('story');
 story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
  +`<b> 遠征の記録</b><br><br>`
  +(log.length ? log.map(l=>{
    if(l.type === 'depart'){
     return `<div style="border:1px solid var(--border2);border-radius:4px;padding:8px;margin-top:6px">
      <span style="color:#c8a8a0;font-size:calc(var(--font-sm) - 1px)">${formatDate(daysToDate(l.day))}</span>　<span style="color:#e0d8c8">${l.label}</span><br>
      <span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">メンバー：${l.memberNames}</span><br>
      <span style="color:#a89878;font-size:calc(var(--font-sm) - 1px)">出発した${l.repeat?'（停止するまで繰り返す）':''}</span>
     </div>`;
    }
    return `<div style="border:1px solid var(--border2);border-radius:4px;padding:8px;margin-top:6px">
    <span style="color:#c8a8a0;font-size:calc(var(--font-sm) - 1px)">${formatDate(daysToDate(l.day))}</span>　<span style="color:#e0d8c8">${l.label}</span><br>
    <span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">メンバー：${l.memberNames}</span><br>
    ${l.eventDesc ? `<span style="color:#b8a888;font-size:calc(var(--font-sm) - 1px)">道中：${l.eventDesc}</span><br>` : ''}
    <span style="color:#ffcc88;font-size:calc(var(--font-sm) - 1px)">報酬：${l.goldGained||0}GP　経験値：+${l.apGained||0}</span>
    ${(l.deathNames||[]).length ? `<br><span style="color:#c05040;font-size:calc(var(--font-sm) - 1px)">戦死：${l.deathNames.join('、')}</span>` : ''}
   </div>`;
   }).join('') : '<span style="color:#b0a080">まだ遠征の記録はない。</span>');
 renderChoices([
  {label:'← 拠点に戻る', fn:()=>_showPropertyMain(townId)},
 ]);
}

// ── 留守番を置く ──
function propertySetCaretaker(townId){
 const def = isFiefId(townId) ? PROPERTY_DEFS.fief : PROPERTY_DEFS[townId];
 const prop = PC.properties[townId];
 prop.caretakers = prop.caretakers || [];
 const story = document.getElementById('story');
 const available = (PC.party||[]).filter(n=>n.con>0);

 if(!available.length){
  showSaveToast('パーティに誰もいない');
  goPropertyNode(townId);
  return;
 }

 story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
  +`<b> 留守番を置く</b><br><br>`
  +`<span style="color:#c0b098">選んだNPCはパーティから外れ、拠点に残る。生活費は1GP／日かかる。</span><br><br>`
  +`<span style="color:#c0b098">現在の留守番：${prop.caretakers.length>0?prop.caretakers.map(n=>n.name).join('、'):'なし'}</span>`;

 renderChoices([
  ...available.filter(n=>!prop.caretakers.some(c=>c===n||c._npcId===n._npcId)).map((n,i)=>({
   label:`${n.name}（信頼度 ${n.trust??0}）を留守番に置く`,
   fn:()=>{
    // 既に留守番にいれば追加しない
    if(prop.caretakers.some(c=>c===n||c._npcId===n._npcId)) return;
    // 上限チェック
    if(prop.caretakers.length >= propCaretakerLimit(townId)){ showSaveToast(`留守番は${propCaretakerLimit(townId)}名までです`); return; }
    const idx = PC.party.indexOf(n);
    if(idx !== -1) PC.party.splice(idx,1);
    n._joinedPropertyDay = GAME_TIME.totalDays;
    prop.caretakers.push(n);
    prop._lastVisitDay = GAME_TIME.totalDays;
    addLifeEvent('', `${n.name}を${propName(townId)||'拠点'}の留守番に置いた。`);
    updateHUD(); renderPartyTab();
    showSaveToast(` ${n.name}を留守番に置いた`);
    propertySetCaretaker(townId);
   },
  })),
  {label:'← 留守番管理に戻る', fn:()=>propertyManageCaretakers(townId)},
 ]);
}

// ── 留守番を引き取る ──
function propertyPickupCaretaker(townId){
 const def = isFiefId(townId) ? PROPERTY_DEFS.fief : PROPERTY_DEFS[townId];
 const prop = PC.properties[townId];
 prop.caretakers = prop.caretakers || [];
 const story = document.getElementById('story');

 if(!prop.caretakers.length){
  showSaveToast('留守番がいない');
  goPropertyNode(townId);
  return;
 }

 story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
  +`<b> 留守番を引き取る</b><br><br>`
  +`<span style="color:#c0b098">引き取ったNPCはパーティに戻る。</span>`;

 renderChoices([
  ...prop.caretakers.map((n)=>({
   label:`${n.name}を引き取る`,
   fn:()=>{
    PC.party = PC.party||[];
    if(PC.party.length >= 3 && !PC.party.some(p=>p===n||p._npcId===n._npcId)){
     showSaveToast('パーティが満員（上限3人）で引き取れない');
     return;
    }
    const idx = prop.caretakers.indexOf(n);
    if(idx !== -1) prop.caretakers.splice(idx,1);
    // 既にパーティにいなければ追加
    if(!PC.party.some(p=>p===n||p._npcId===n._npcId)){
     PC.party.push(n);
     addLifeEvent('', `${n.name}がパーティに戻った（${({warrior:'戦士',rogue:'盗賊',wizard:'魔法使い'})[n.type]||n.type}・${n.race}）。`);
    }
    updateHUD(); renderPartyTab();
    showSaveToast(` ${n.name}をパーティに戻した`);
    propertyPickupCaretaker(townId);
   },
  })),
  {label:'← 留守番管理に戻る', fn:()=>propertyManageCaretakers(townId)},
 ]);
}

// ── 拠点での結婚申し込み ──
function propertyPropose(townId){
 const def = isFiefId(townId) ? PROPERTY_DEFS.fief : PROPERTY_DEFS[townId];
 const story = document.getElementById('story');
 const targets = (PC.party||[]).filter(n=>n.con>0 && !n.married);

 if(!targets.length){
  story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
   +`<span style="color:#c0b098">今は申し込める相手がいない。</span>`;
  renderChoices([{label:'← 戻る', fn:()=>goPropertyNode(townId)}]);
  return;
 }

 // 1日1回制限チェック
 const prop = PC.properties[townId];
 if(prop._lastProposeDay === GAME_TIME.totalDays){
  story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
   +`<span style="color:#c0b098">あまりしつこくすると嫌われる。今日はやめよう。</span>`;
  renderChoices([{label:'← 戻る', fn:()=>goPropertyNode(townId)}]);
  return;
 }

 // 対象が複数いれば選択、1人なら直接
 const showPropose = (npc)=>{
  if(!npc.marriagePref) Object.assign(npc, _rollMarriagePref()); // 実装前に生成されたNPCには求婚時に割り付ける
  const trust = npc.trust??0;
  const trustLabel = trust>=90?'篤い信頼':'まだ信頼が足りない';
  const canPropose = trust >= 90;
  const typeJa = {warrior:'戦士',rogue:'盗賊',wizard:'魔法使い'}[npc.type]||npc.type;
  const prefBonus = calcMarriagePrefBonus(npc, townId);
  const prefHint = prefBonus > 5 ? `<br><span style="color:#e8d8b0">${npc.name}は、あなたのことを気に入っているようだ。</span>`
   : prefBonus < -5 ? `<br><span style="color:#c8a0a0">${npc.name}は、どこか物足りなさを感じているようだ。</span>`
   : '';

  story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
   +`<b> ${npc.name}への求婚</b><br><br>`
   +`<span style="color:#c0b098">${typeJa}　信頼度：<span style="color:${canPropose?'#f0ece0':'#c8c0c0'}">${trust}/100（${trustLabel}）</span></span><br><br>`
   +(canPropose
    ? `<span style="color:#c0b098">拠点の一室で、二人きりの時間が流れている。<br>魅力 Lv3 能力値テストに成功すれば、${npc.name}は申し込みを受け入れてくれるだろう。${prefHint}</span>`
    : `<span style="color:#e0d0d0">信頼度が90以上のときに申し込むことができる。</span>`
   );

  if(!canPropose){
   renderChoices([{label:'← 戻る', fn:()=>goPropertyNode(townId)}]);
   return;
  }

  setupSavingRoll({
   attr:'chr', level:3, targetAdjust: prefBonus,
   onSuccess:()=>{
    prop._lastProposeDay = GAME_TIME.totalDays;
    npc.married = true;
    if(!PC.spouse) PC.spouse = [];
    PC.spouse.push({name:npc.name, townId, marriedDay:GAME_TIME.totalDays});
    addLifeEvent('', `${npc.name}と結婚した。`);
    updateHUD();
    const responses = [
     `${npc.name}はしばらく黙っていたが、やがて静かに頷いた。「……はい。」`,
     `${npc.name}の目に光が宿った。「ずっと待っていた言葉だ。」`,
     `${npc.name}は驚いた表情を見せたが、すぐに柔らかな笑みを浮かべた。「もちろん。」`,
     `${npc.name}は少し照れたように笑った。「こんな場所で言うとは思わなかったが……ああ、受け入れよう。」`,
    ];
    const txt = responses[Math.floor(Math.random()*responses.length)]
     +`<br><br><span style="color:#f0ece0"> ${npc.name}と結ばれた。</span>`;
    const s = document.getElementById('story');
    if(s) s.innerHTML = `<div style="padding:8px 0">${txt}</div>`;
    renderChoices([{label:'← 戻る', fn:()=>goPropertyNode(townId)}]);
    scrollToTop();
   },
   onFail:()=>{
    prop._lastProposeDay = GAME_TIME.totalDays;
    const responses = [
     `${npc.name}は視線を逸らした。「……今はまだ、その答えを出せない。」`,
     `${npc.name}は静かに首を振った。「気持ちは嬉しい。でも今は答えられない。」`,
     `${npc.name}はしばらく沈黙した後、立ち上がった。「もう少し時間をくれ。」`,
    ];
    const txt = responses[Math.floor(Math.random()*responses.length)];
    const s = document.getElementById('story');
    if(s) s.innerHTML = `<div style="padding:8px 0">${txt}</div>`;
    renderChoices([{label:'← 戻る', fn:()=>goPropertyNode(townId)}]);
    scrollToTop();
   },
  });
 };

 if(targets.length === 1){
  showPropose(targets[0]);
 } else {
  story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
   +`<b> 誰に申し込みますか？</b>`;
  renderChoices([
   ...targets.map(n=>({
    label:`${n.name}（信頼度 ${n.trust??0}/100）`,
    fn:()=>showPropose(n),
   })),
   {label:'← 戻る', fn:()=>goPropertyNode(townId)},
  ]);
 }
}

// ── 拠点での休養 ──
// ── 子どもイベント ──────────────────────────────
function _checkPropertyBabyEvent(townId, callback){
 const prop = PC.properties[townId];
 prop.caretakers = prop.caretakers||[];
 prop.children = prop.children||[];

 // 配偶者を探す（拠点留守番 or パーティにいる状態でもOK）
 const spouseInfo = (PC.spouse||[])[0];
 if(!spouseInfo){ callback(); return; }
 const spouse = prop.caretakers.find(n=>n.married && n.name===spouseInfo.name)
              || (PC.party||[]).find(n=>n.married && n.name===spouseInfo.name);
 if(!spouse){ callback(); return; }

 // 年齢に基づく確率計算
 const race = PC.race||'human';
 const lifespan = (AGING_PARAMS[race]||AGING_PARAMS.human).lifespan;
 const age = PC.age||20;
 const ratio = age / lifespan;
 const chance = ratio<=0.25 ? 0.5 : ratio<=0.5 ? 0.3 : ratio<=0.75 ? 0.1 : 0.01;

 if(Math.random() >= chance){ callback(); return; }

 // 子どもが生まれる！
 const story = document.getElementById('story');
 story.innerHTML = `<span style="color:#f0ece0"> ${propName(townId)}</span><br><br>`
  +`<div style="border:2px solid var(--nature2);border-radius:4px;padding:14px;background:#060e06;margin:8px 0">`
  +`<div style="color:var(--white);font-size:calc(var(--font-sm) + 1px);margin-bottom:8px"> 新しい命の誕生</div>`
  +`<div style="color:#f0ece0">${spouse.name}との間に子どもが生まれた！</div><br>`
  +`<div style="color:#f0ece0">名前を付けてあげよう。</div></div>`;

 // 両親の種族からランダム選択
 const parentRaces = [race, spouse.race||race];
 const childRace = parentRaces[Math.floor(Math.random()*parentRaces.length)];
 // タイプは完全ランダム
 const childType = NPC_TYPES[Math.floor(Math.random()*NPC_TYPES.length)];

 // 命名UI
 // 命名UIをHTMLボタンで直接実装（renderChoicesを経由しない）
 const inputId = 'baby-name-input-'+Date.now();
 const btnId   = 'baby-name-btn-'+Date.now();
 story.innerHTML +=
  `<div style="margin-top:12px">` +
  `<input id="${inputId}" type="text" placeholder="名前を入力..." ` +
  `style="background:#1a1200;border:1px solid #484848;color:#f0ece0;` +
  `font-family:system-ui,sans-serif;font-size:var(--font-sm);padding:8px;` +
  `width:100%;border-radius:3px;box-sizing:border-box">` +
  `</div>` +
  `<div style="margin-top:10px">` +
  `<button id="${btnId}" class="choice-btn" style="width:100%"> この名前にする</button>` +
  `</div>` +
  `<div id="baby-dbg-${inputId}" style="font-size:calc(var(--font-sm) - 3px);color:#f0ddd8;margin-top:6px"></div>`;

 // ボタンにイベントを直接設定
 setTimeout(()=>{
  const btn = document.getElementById(btnId);
  const dbg = document.getElementById('baby-dbg-'+inputId);
  if(!btn){ if(dbg) dbg.textContent='ERR:btn not found'; return; }
  btn.onclick = ()=>{
   try{
    const nameEl = document.getElementById(inputId);
    if(dbg) dbg.textContent = 'btn clicked, nameEl='+(nameEl?'OK':'NULL');
    const childName = (nameEl&&nameEl.value.trim()) || pickNPC();
    const child = {
     _childId: Date.now()+Math.random(),
     name: childName,
     race: childRace,
     type: childType,
     isChild: true,
     bornDay: GAME_TIME.totalDays,
     parents: {pc:PC.name, spouse:spouse.name},
     _statsRevealed: false,
    };
    prop.children.push(child);
    if(typeof addLifeEvent === 'function') addLifeEvent('', `${spouse.name}との間に${childName}が生まれた。`);
    showSaveToast(` ${childName}が生まれた！`);
    story.innerHTML = `<span style="color:#f0ece0"> ${propName(townId)}</span><br><br>`
     +`<span style="color:var(--white)"> <b>${childName}</b>が生まれた。<br><br>`
     +`${childName}は拠点で大切に育てられる。<br>`
     +`15歳になったらパーティに加えることができる。</span>`;
    renderChoices([{label:'← 拠点に戻る', fn:callback, go:'__travel__'}]);
   }catch(e){
    const dbg2 = document.getElementById('baby-dbg-'+inputId);
    if(dbg2) dbg2.textContent = 'ERR:'+e.message;
    else alert('ERR:'+e.message);
   }
  };
 }, 50);
}

// ── 子どもを引き取る（15歳以上） ──
function propertyPickupChild(townId){
 const def = isFiefId(townId) ? PROPERTY_DEFS.fief : PROPERTY_DEFS[townId];
 const prop = PC.properties[townId];
 prop.children = prop.children||[];
 const story = document.getElementById('story');

 // 年齢計算（1年=365日）
 const grown = prop.children.filter(c=>{
  const ageYears = (GAME_TIME.totalDays - c.bornDay) / 365;
  return ageYears >= 15;
 });

 if(!grown.length){
  showSaveToast('まだ15歳になった子がいない');
  propertyManageCaretakers(townId); return;
 }

 story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
  +`<b> 子どもを引き取る</b><br><br>`
  +`<span style="color:#c0b098">15歳以上の子どもをパーティに加えることができます。</span>`;

 renderChoices([
  ...grown.map((child,i)=>{
   const ageYears = Math.floor((GAME_TIME.totalDays - child.bornDay) / 365);
   return {
    label:`${child.name}（${ageYears}歳）を引き取る`,
    fn:()=>{
     if(!child._statsRevealed){
      // まず能力値を確定してからタイプ選択
      _revealChildStats(child, prop);
     }
     // タイプ選択画面を表示
     if(!child._typeChosen){
      const iq = child.iq||0, dex = child.dex||0;
      const canWizard = iq>=10 && dex>=8;
      story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
       +`<b> ${child.name}の職業を選ぶ</b><br><br>`
       +`<span style="color:#c0b098">ST:${child.st} IQ:${child.iq} LK:${child.lk} CON:${child.con} DEX:${child.dex} CHR:${child.chr} SPD:${child.spd}</span><br><br>`
       +`<span style="color:#c0b098">${child.name}はどの道を歩むのか。今こそ決める時だ。</span>`
       +(!canWizard?`<br><span style="color:#e0d0d0;font-size:calc(var(--font-sm) - 2px)">※ 魔法使いには知力10・器用さ8以上が必要</span>`:'');
      const typeChoices = [
       {label:' 戦士（Warrior）', fn:()=>{ child.type='warrior'; child._typeChosen=true; _recruitChild(child,prop,townId); }},
       ...(canWizard?[{label:' 魔法使い（Wizard）', fn:()=>{ child.type='wizard'; child._typeChosen=true; _recruitChild(child,prop,townId); }}]:[]),
       {label:' 筊賊（Rogue）', fn:()=>{ child.type='rogue'; child._typeChosen=true; _recruitChild(child,prop,townId); }},
       {label:'← 戻る', fn:()=>propertyPickupChild(townId)},
      ];
      renderChoices(typeChoices);
     } else {
      _recruitChild(child, prop, townId);
     }
    },
   };
  }),
  {label:'← 留守番管理に戻る', fn:()=>propertyManageCaretakers(townId)},
 ]);
}

function _revealChildStats(child, prop){
 // 能力値のみ確定（タイプ選択は別途）
 const spouseData = prop.caretakers.find(n=>n.name===child.parents?.spouse)
                 || (PC.party||[]).find(n=>n.name===child.parents?.spouse);
 const attrs = ['st','iq','lk','con','dex','chr','spd'];
 const base = {};
 attrs.forEach(a=>{
  const pcVal = PC[a]||8;
  const spVal = spouseData?.[a]||8;
  const avg = Math.floor((pcVal+spVal)/2);
  base[a] = Math.min(18, Math.max(3, avg + Math.floor(Math.random()*7)-3));
 });
 const applied = applyRace(base, child.race);
 Object.assign(child, applied);
 child.maxCon = applied.con; child.maxSt = applied.st;
 child.level = 1; child.ap = 0; child.gold=0; child.sp=0; child.cp=0;
 child._statsRevealed = true;
 child.trust = 80;
 child._npcId = child._npcId || Date.now()+Math.random();
}

function _recruitChild(child, prop, townId){
 PC.party = PC.party||[];
 if(PC.party.length >= 3){
  showSaveToast('パーティが満員（上限3人）で迎え入れられない');
  propertyPickupChild(townId);
  return;
 }
 const def = isFiefId(townId) ? PROPERTY_DEFS.fief : PROPERTY_DEFS[townId];
 // タイプに応じた装備を設定
 const t = child.type||'warrior';
 child.equippedWeapons = t==='wizard'?[]:[{name:'ショートソード',dice:3,adds:0,twoHand:false,weight:30,stReq:7,dexReq:3}];
 child.equippedArmors = [{name:'布製の鎧',hits:3,stReq:1,isShield:false,weight:100}];
 child.invWeapons = t!=='wizard'?[]:[{name:'ショートソード',dice:3,adds:0,twoHand:false,weight:30,stReq:7,dexReq:3}];
 child.invArmors = [];
 child.spells = t==='wizard'?[{...SPELLS_L1[2]}]:[];
 // bornDayをbirthDayとして引き継ぎ、個体寿命を設定
 if(!child.birthDay) child.birthDay = child.bornDay;
 if(!child.lifespan){
  const ranges = { human:[60,100], elf:[600,1000], dwarf:[150,250], halfling:[80,120], fairy:[150,250], leprechaun:[250,350], troll:[270,330], ogre:[135,165], orc:[54,66], goblin:[36,44] };
  const [min,max] = ranges[child.race||'human'] || ranges.human;
  child.lifespan = min + Math.floor(Math.random()*(max-min+1));
 }
 // 仲間入りのタイミングで身長・体重を決定
 if(child.height==null || child.weight==null) Object.assign(child, rollBodySize(child.race));
 const idx = prop.children.indexOf(child);
 prop.children.splice(idx,1);
 PC.party = PC.party||[];
 PC.party.push(child);
 addLifeEvent('', `${child.name}がパーティに加わった（${({warrior:'戦士',rogue:'盗賊',wizard:'魔法使い'})[child.type]||child.type}・${child.race}）。`);
 updateHUD(); renderPartyTab();
 const typeJa = {warrior:'戦士',rogue:'盗賊',wizard:'魔法使い'}[child.type]||child.type;
 const story = document.getElementById('story');
 story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
  +`<span style="color:#f0ece0"> <b>${child.name}</b>がパーティに加わった！</span><br><br>`
  +`<span style="color:#c0b098">種族：${child.race}　タイプ：${typeJa}</span><br>`
  +`<span style="color:#c0b098">ST:${child.st} IQ:${child.iq} LK:${child.lk} CON:${child.con} DEX:${child.dex} CHR:${child.chr} SPD:${child.spd}</span>`;
 renderChoices([{label:'← 拠点に戻る', fn:()=>goPropertyNode(townId)}]);
}

function propertyRest(townId){
 const def = isFiefId(townId) ? PROPERTY_DEFS.fief : PROPERTY_DEFS[townId];
 const story = document.getElementById('story');

 const showUI = (msg='')=>{
  const costPerDay = foodPrice(1); // 食料代 1GP/日（収穫判定で変動）
  const maxAfford = Math.floor(PC.gold||0);
  const priceLabel = costPerDay > 1
   ? `<span style="color:#e0d0d0">${costPerDay}GP／日</span>`
   : `${costPerDay}GP／日`;
  story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}で休養</span><br><br>`
   +`<span style="color:#c0b098">生活費：${priceLabel}</span><br>`
   +`<span style="color:#c0b098">所持金：${PC.gold||0}GP　現在CON：${PC.con}/${PC.maxCon}</span>`
   +(msg?`<br><br>${msg}`:'');

  const choices = [];
  const days = [1,3,7,14,30,365];
  days.forEach(d=>{
   const cost = d * costPerDay;
   const canAfford = (PC.gold||0) >= cost;
   const label = d===365 ? `1年間休養する（生活費 ${cost}GP）${canAfford?'':'　［所持金不足］'}` : `${d}日間休養する（生活費 ${cost}GP）${canAfford?'':'　［所持金不足］'}`;
   choices.push({
    label,
    fn: canAfford ? ()=>doPropertyRest(townId, d, costPerDay) : null,
   });
  });
  choices.push({label:'← 戻る', fn:()=>goPropertyNode(townId)});
  renderChoices(choices);
 };
 showUI();
}

function doPropertyRest(townId, days, costPerDay){
 const cost = days * costPerDay;
 if((PC.gold||0) < cost){ showSaveToast('所持金が足りない'); return; }

 // 生活費を支払い
 PC.gold = (PC.gold||0) - cost;
 // 拠点で休むと村の時刻を朝にリセット（ヴェルダ裏路地の時刻連動用）
 GAME_TIME.hour = 6;

 // 回復処理（innRestをベースに、日数に応じて回復量を変える）
 const conHeal = Math.min(PC.maxCon - PC.con, Math.floor(PC.maxCon * Math.min(1.0, days * 0.15)));
 PC.con = Math.min(PC.maxCon, PC.con + conHeal);
 PC.st  = PC.maxSt;
 const msgs = [];
 msgs.push(`体力+${conHeal}`);

 // 毒治癒（3日以上）
 if(days >= 3 && PC._poisoned){
  PC._poisoned = false;
  msgs.push('毒が癒えた');
 }
 // 飢え回復
 if(PC._hungerDmg > 0){
  PC.st  = Math.min(PC._stBase||PC.maxSt,  PC.st  + PC._hungerDmg);
  PC.con = Math.min(PC._conBase||PC.maxCon, PC.con + PC._hungerDmg);
  PC.dex = Math.min(PC._dexBase||PC.dex+PC._hungerDmg, PC.dex + PC._hungerDmg);
  msgs.push(`飢えが回復（ST/CON/DEX +${PC._hungerDmg}）`);
  PC._hungerDmg = 0; PC._stBase = PC._conBase = PC._dexBase = null;
 }
 // パーティ回復
 const aliveParty = (PC.party||[]).filter(n=>n.con>0);
 if(aliveParty.length){
  aliveParty.forEach(n=>{
   n.con = Math.min(n.maxCon, n.con + Math.floor(n.maxCon * Math.min(1.0, days * 0.15)));
  });
  msgs.push(`仲間も回復（${aliveParty.map(n=>n.name).join('、')}）`);
 }

 updateHUD();
 showSaveToast(` ${days}日間休養（生活費 ${cost}GP）　${msgs.join('、')}`);

 startPropertyRestTick(townId, days, ()=>{
  const _back = ()=>propertyRest(townId);
  // 休養のあと、訪ねてきた元仲間と出会うことがある（出会いがなければそのまま休養画面に戻る）
  const _next = ()=>{ if(!fcVisitEncounter(_back, { letters:true, place:propName(townId) })) _back(); };
  // 1年間休養かつ結婚済みかつ配偶者が拠点に留守番している場合の子どもイベント
  if(days >= 365){
   _checkPropertyBabyEvent(townId, _next);
  } else {
   _next();
  }
 });
}

// 休養を1日ずつ進める（旅の約3倍速）。低確率で功名目当ての襲撃者に中断される
let restTickState = null;
function restLog(html){
 let evEl = document.getElementById('rest-events');
 if(!evEl){
  const storyEl = document.getElementById('story');
  if(!storyEl) return;
  storyEl.innerHTML += `<div id="rest-log-wrap" style="border-top:1px solid var(--panel2);margin-top:8px;padding-top:8px;font-size:var(--font-base)"><div id="rest-events"></div></div>`;
  evEl = document.getElementById('rest-events');
  if(!evEl) return;
 }
 const d = document.createElement('div');
 d.innerHTML = html;
 evEl.prepend(d);
 Array.from(evEl.children).slice(1).forEach(ch=>{ ch.style.opacity = '0.45'; });
}

function startPropertyRestTick(townId, days, onDone){
 renderChoices([]);
 const townName = (TOWNS[townId]||{}).name || propName(townId);
 restTickState = { townId, totalDays: days, daysDone: 0, onDone, interval: 333 };
 const tpw = document.getElementById('travel-progress-wrap');
 if(tpw){
  tpw.style.display = '';
  document.getElementById('travel-progress-bar').style.width = '0%';
  document.getElementById('travel-progress-dot').style.left = '0%';
  document.getElementById('travel-latest').textContent = '';
  document.getElementById('travel-progress-label').innerHTML =
   ` 休養中　<span style="color:#f0ece0">${townName}</span>　<span id="travel-day-count" style="color:#e0d8c8">0/${days}日</span>`;
 }
 setTimeout(_restTick, restTickState.interval);
}

function _restTick(){
 const rs = restTickState;
 if(!rs) return;
 if(rs.daysDone >= rs.totalDays){
  const tpw = document.getElementById('travel-progress-wrap');
  if(tpw) tpw.style.display = 'none';
  restLog(`<span style="color:#ece8e0">⏳ ${rs.totalDays}日の休養を終えた。</span> ${dateStr()}`);
  const onDone = rs.onDone;
  restTickState = null;
  renderChoices([{label:'▶ OK', fn:()=>{ renderChoices([]); onDone(); }}]);
  return;
 }
 rs.daysDone++;
 const aged = advanceDays(1);
 if(aged){
  if(aged.event === 'death'){
   const tpw = document.getElementById('travel-progress-wrap');
   if(tpw) tpw.style.display = 'none';
   restLog(`<span class="red"> 老衰により死亡…享年${aged.age}歳。</span>`);
   restTickState = null;
   setTimeout(()=>go('DEAD_OLDAGE'), 1500);
   return;
  }
  if(aged.event === 'aging'){
   restLog(`<span style="color:var(--ora)"> 加齢：強さ・知力・運・魅力・器用さ・素早さ・体力 が各-1</span>`);
  }
  if(aged.event === 'birthday'){
   restLog(`<span style="color:#f0ece0"> 誕生日！ ${aged.age}歳になった。</span>`);
  }
 }

 // プログレスバーを毎ターン更新
 if(rs.totalDays > 0){
  const pct = Math.min(100, rs.daysDone / rs.totalDays * 100);
  const bar = document.getElementById('travel-progress-bar');
  const dot = document.getElementById('travel-progress-dot');
  if(bar) bar.style.width = pct + '%';
  if(dot) dot.style.left = pct + '%';
  const dayCount = document.getElementById('travel-day-count');
  if(dayCount) dayCount.textContent = `${rs.daysDone}/${rs.totalDays}日`;
 }

 // 割り込みイベント：功名目当ての襲撃者
 if(checkRestInterruptEvent(rs.townId)) return;
 // 訪ねてきた元仲間が到着していたら、休養を中断して出会う（話が済んだら休養を再開する）
 if(fcVisitRestInterrupt(rs.townId)) return;

 setTimeout(_restTick, rs.interval);
}

// 休養中、低確率で功名目当ての冒険者・暗殺者が襲撃してくる（地元の英雄扱い以上の町限定）
const REST_EVENT_RATE_PER_DAY = 0.01; // 拠点の休養中にイベントが起きる確率（1日あたり）
function checkRestInterruptEvent(townId){
 if(getTrust(townId) < 75) return false;
 if(Math.random() >= REST_EVENT_RATE_PER_DAY) return false; // 休養中のイベント全体の発生率（現状は襲撃のみ）
 startRestInterruptCombat(townId);
 return true;
}

function startRestInterruptCombat(townId){
 const level = Math.max(3, Math.min(10, PC.level||1));
 const attacker = generateNPC(level);
 attacker.bountyTitle = '功名目当ての賊';
 const story = document.getElementById('story');
 if(story){
  story.innerHTML += `<div style="margin-top:10px;padding:8px;background:#150808;border:1px solid #5a3030;border-radius:4px">
   <b> 休養を破る足音</b><br><br>
   休んでいるところに、剣を構えた者が押し入ってきた。「${PC.name}を倒して名を上げてやる！」殺気立った目でこちらを見据えている。
  </div>`;
 }
 renderChoices([{label:' 迎え撃つ', fn:()=>{
  renderChoices([]);
  startCombatNPC({
   enemies:[{...attacker, curCon:attacker.con}],
   canFlee:false,
   win:'__noop__',
   lose:'DEAD',
   onWin:()=>{
    document.getElementById('cbt-area').classList.add('hidden');
    document.getElementById('scroll-area').classList.remove('in-combat');
    document.getElementById('text-win').style.display='';
    cbtState=null;
    updateHUD();
    const s = document.getElementById('story');
    if(s) s.innerHTML += `<div style="margin-top:8px;color:#e8e4d8"> 賊を退けた。落ち着きを取り戻し、休養を続ける。</div>`;
    restLog(`<span style="color:#e0a060"> 功名目当ての賊に襲撃されたが、撃退した。</span>`);
    renderChoices([{label:'▶ 休養を続ける', fn:()=>{
     renderChoices([]);
     if(restTickState) setTimeout(_restTick, restTickState.interval);
    }}]);
   },
  });
 }}]);
}

// ── アイテム保管サブメニュー ──
// ── 拠点の店（メイン画面） ──────────────────────────────────
function propertyShop(townId){
 _calcShopSales(townId); // 経過日数ぶんの販売を清算
 const shop = _propShop(townId);
 if(!shop) return;
 const story = document.getElementById('story');
 const keeper = _shopKeeperInfo(townId);
 const kindLabel = {weapon:'武器', armor:'防具', jewel:'宝飾品', specialty:'特産品'};

 story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
  +`<b> 店番</b><br><br>`
  +`<span style="color:#c0b098">店番：${keeper?`${keeper.name}（魅力${keeper.chr}）`:'未設定（誰もいないと売れません）'}</span><br>`
  +`<span style="color:#c0b098">棚の商品：${shop.shelf.length}点</span><br>`
  +`<span style="color:#c0b098">未回収の売上：<b style="color:#f0ece0">${shop.earnings||0}GP</b></span>`
  +(shop.shelf.length ? `<br><br><span style="font-size:calc(var(--font-sm) - 1px);color:#a89880">── 棚の中身 ──</span><br>`
    + shop.shelf.map(e=>`<span style="color:#c8b8a0">${kindLabel[e.kind]}：${e.item.name}　${e.price}GP</span>`).join('<br>') : '');

 renderChoices([
  {label:' 店番を選ぶ／変える', fn:()=>propertyShopSetKeeper(townId)},
  {label:' 商品を棚に並べる', fn:()=>propertyShopAddItem(townId)},
  ...(shop.shelf.length ? [{label:' 棚から商品を下げる', fn:()=>propertyShopRemoveItem(townId)}] : []),
  ...((shop.earnings||0) > 0 ? [{label:` 売上を回収する（${shop.earnings}GP）`, fn:()=>{
   PC.gold = (PC.gold||0) + shop.earnings;
   showSaveToast(`${shop.earnings}GPを回収した`);
   shop.earnings = 0;
   updateHUD();
   propertyShop(townId);
  }}] : []),
  {label:'← 拠点に戻る', fn:()=>goPropertyNode(townId)},
 ]);
}

// ── 店番を選ぶ ──
function propertyShopSetKeeper(townId){
 const shop = _propShop(townId);
 const prop = PC.properties[townId];
 const story = document.getElementById('story');
 const candidates = [
  { id:'PC', name:PC.name, chr:PC.chr||0, lk:PC.lk||0 },
  ...(prop.caretakers||[]).map(n=>({ id:n._npcId, name:n.name, chr:n.chr||0, lk:n.lk||0 })),
  ...(prop.residents||[]).filter(_residentIsAlive).map(r=>({ id:'resident:'+r.name, name:`${r.name}（引退）`, chr:r.chr??10, lk:r.lk??10 })),
 ];
 story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
  +`<b> 店番を選ぶ</b><br><br>`
  +`<span style="color:#c0b098">魅力が高いほど売れやすくなります。</span>`;
 renderChoices([
  ...candidates.map(c=>({
   label:`${c.name}（魅力${c.chr}）${shop.keeperId===c.id?'　※現在の店番':''}`,
   fn:()=>{ shop.keeperId = c.id; showSaveToast(`${c.name}を店番にした`); propertyShop(townId); }
  })),
  {label:'← 戻る', fn:()=>propertyShop(townId)},
 ]);
}

// ── 商品を棚に並べる ──
function propertyShopAddItem(townId){
 const shop = _propShop(townId);
 const stor = _propStor(townId);
 const story = document.getElementById('story');
 story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
  +`<b> 商品を選ぶ</b><br><br>`
  +`<span style="color:#c0b098">所持品・保管品のどちらからでも並べられます。</span>`;
 renderChoices([
  {label:' 武器を選ぶ', fn:()=>propertyShopAddPick(townId,'weapon')},
  {label:' 防具を選ぶ', fn:()=>propertyShopAddPick(townId,'armor')},
  {label:' 宝飾品を選ぶ', fn:()=>propertyShopAddPick(townId,'jewel')},
  {label:' 特産品を選ぶ', fn:()=>propertyShopAddPick(townId,'specialty')},
  {label:'← 戻る', fn:()=>propertyShop(townId)},
 ]);
}

function propertyShopAddPick(townId, kind){
 const stor = _propStor(townId);
 const story = document.getElementById('story');
 const srcMap = {
  weapon:    { inv: PC.invWeapons||[],    stor: stor.weapons },
  armor:     { inv: PC.invArmors||[],     stor: stor.armors },
  jewel:     { inv: PC.invJewels||[],     stor: stor.jewels },
  specialty: { inv: PC.invSpecialties||[],stor: stor.specialties },
 };
 const src = srcMap[kind];
 const kindLabel = {weapon:'武器', armor:'防具', jewel:'宝飾品', specialty:'特産品'}[kind];
 const eq = kind==='weapon' ? (PC.equippedWeapons||[]) : kind==='armor' ? (PC.equippedArmors||[]) : [];
 const invAvail = src.inv.filter(it=>!eq.includes(it));

 story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
  +`<b> ${kindLabel}を選ぶ</b><br><br>`
  +`<span style="color:#c0b098">同名の商品が複数あれば、価格を一括で設定できます。</span>`;

 // 同名アイテムをまとめてグループ化
 const groupByName = (list)=>{
  const groups = [];
  list.forEach(it=>{
   let g = groups.find(g=>g.name===it.name);
   if(!g){ g = {name:it.name, items:[]}; groups.push(g); }
   g.items.push(it);
  });
  return groups;
 };

 const choices = [];
 groupByName(invAvail).forEach(g=>{
  const base = _shopBasePrice(kind, g.items[0], townId);
  const countTxt = g.items.length > 1 ? ` ×${g.items.length}` : '';
  choices.push({label:`[所持] ${g.name}${countTxt}（定価目安 ${base}GP）`, fn:()=>propertyShopSetPrice(townId, kind, g.items, ()=>{
   g.items.forEach(it=>{ const idx = src.inv.indexOf(it); if(idx>=0) src.inv.splice(idx,1); });
  })});
 });
 groupByName(src.stor).forEach(g=>{
  const base = _shopBasePrice(kind, g.items[0], townId);
  const countTxt = g.items.length > 1 ? ` ×${g.items.length}` : '';
  choices.push({label:`[保管] ${g.name}${countTxt}（定価目安 ${base}GP）`, fn:()=>propertyShopSetPrice(townId, kind, g.items, ()=>{
   g.items.forEach(it=>{ const idx = src.stor.indexOf(it); if(idx>=0) src.stor.splice(idx,1); });
  })});
 });
 choices.push({label:'← 戻る', fn:()=>propertyShopAddItem(townId)});
 renderChoices(choices);
}

function propertyShopSetPrice(townId, kind, items, removeFromSource){
 const base = _shopBasePrice(kind, items[0], townId) || 10;
 const countTxt = items.length > 1 ? `　※${items.length}点まとめて同じ価格になります` : '';
 const input = prompt(`「${items[0].name}」の販売価格を入力してください（定価目安：${base}GP）${countTxt}`, String(base));
 if(input === null) return;
 const price = parseInt(input, 10);
 if(!price || price <= 0){ showSaveToast('正しい価格を入力してください'); return; }
 const shop = _propShop(townId);
 removeFromSource();
 items.forEach(item=>{ shop.shelf.push({ kind, item, price }); });
 showSaveToast(`${items[0].name}を${items.length>1?`${items.length}点、`:''}${price}GPで棚に並べた`);
 propertyShop(townId);
}

// ── 棚から商品を下げる（保管に戻す） ──
function propertyShopRemoveItem(townId){
 const shop = _propShop(townId);
 const stor = _propStor(townId);
 const story = document.getElementById('story');
 const kindLabel = {weapon:'武器', armor:'防具', jewel:'宝飾品', specialty:'特産品'};
 const storMap = { weapon:stor.weapons, armor:stor.armors, jewel:stor.jewels, specialty:stor.specialties };
 story.innerHTML = ` <span style="color:#f0ece0">${propName(townId)}</span><br><br>`
  +`<b> 棚から下げる</b><br><br>`
  +`<span style="color:#c0b098">下げた商品は拠点の保管に戻ります。</span>`;
 renderChoices([
  ...shop.shelf.map((e,i)=>({
   label:`${kindLabel[e.kind]}：${e.item.name}（${e.price}GP）を下げる`,
   fn:()=>{
    storMap[e.kind].push(e.item);
    shop.shelf.splice(i,1);
    showSaveToast(`${e.item.name}を棚から下げた`);
    propertyShop(townId);
   }
  })),
  {label:'← 戻る', fn:()=>propertyShop(townId)},
 ]);
}


