// ── 所持金の預け入れ・引き出し ──
function propertyStorageMoney(townId){
 const stor = _propStor(townId);
 if(!stor) return;
 const story = document.getElementById('story');

 const depositGP = (amt)=>{
  const actual = Math.min(amt, PC.gold||0);
  if(!actual){ showSaveToast('GPが足りない'); return; }
  stor.gold=(stor.gold||0)+actual; PC.gold=(PC.gold||0)-actual; updateHUD(); showSaveToast(`${actual}GPを預けた`); showDeposit();
 };
 const withdrawGP = (amt)=>{
  const actual = Math.min(amt, stor.gold||0);
  if(!actual){ showSaveToast('保管中のGPがない'); return; }
  PC.gold=(PC.gold||0)+actual; stor.gold=(stor.gold||0)-actual; updateHUD(); showSaveToast(`${actual}GPを引き出した`); showWithdraw();
 };

 const statusHtml = ()=>{
  const storGP=stor.gold||0, storSP=stor.sp||0, storCP=stor.cp||0;
  return ` <span style="color:#f0ece0">所持金の保管</span><br><br>`
   +`<span style="color:#c0b098">保管中：${storGP}GP ${storSP}SP ${storCP}CP</span><br>`
   +`<span style="color:#c0b098">所持中：${PC.gold||0}GP ${PC.sp||0}SP ${PC.cp||0}CP</span>`;
 };

 // トップメニュー
 const showUI = ()=>{
  story.innerHTML = statusHtml();
  renderChoices([
   {label:' 所持金を保管する', fn:()=>showDeposit()},
   {label:' 保管金を持ち出す', fn:()=>showWithdraw()},
   {label:'← 戻る', fn:()=>propertyStorageMenu(townId)},
  ]);
 };

 // 預け入れ画面
 const showDeposit = ()=>{
  story.innerHTML = statusHtml();
  const amounts = [10,50,100,500,1000].filter(n=>n<=(PC.gold||0));
  renderChoices([
   ...amounts.map(n=>({label:`${n}GP 預ける`, fn:()=>depositGP(n)})),
   {label:`所持GPをすべて預ける（${PC.gold||0}GP）`, fn:()=>depositGP(PC.gold||0)},
   {label:`所持金を全て預ける（GP/SP/CP）`, fn:()=>{
    stor.gold=(stor.gold||0)+(PC.gold||0); stor.sp=(stor.sp||0)+(PC.sp||0); stor.cp=(stor.cp||0)+(PC.cp||0);
    PC.gold=0; PC.sp=0; PC.cp=0; updateHUD(); showSaveToast('全額を預けた'); showDeposit();
   }},
   {label:'← 戻る', fn:()=>showUI()},
  ]);
 };

 // 引き出し画面
 const showWithdraw = ()=>{
  const storGP=stor.gold||0;
  story.innerHTML = statusHtml();
  const amounts = [10,50,100,500,1000].filter(n=>n<=storGP);
  renderChoices([
   ...amounts.map(n=>({label:`${n}GP 引き出す`, fn:()=>withdrawGP(n)})),
   {label:`保管GPをすべて引き出す（${storGP}GP）`, fn:()=>withdrawGP(storGP)},
   {label:`保管金を全て引き出す（GP/SP/CP）`, fn:()=>{
    PC.gold=(PC.gold||0)+(stor.gold||0); PC.sp=(PC.sp||0)+(stor.sp||0); PC.cp=(PC.cp||0)+(stor.cp||0);
    stor.gold=0; stor.sp=0; stor.cp=0; updateHUD(); showSaveToast('全額を引き出した'); showWithdraw();
   }},
   {label:'← 戻る', fn:()=>showUI()},
  ]);
 };

 showUI();
}

