// ── 松明の預け入れ・引き出し ──
function propertyStorageTorches(townId){
 const stor = _propStor(townId);
 if(!stor) return;
 const story = document.getElementById('story');
 const showUI = ()=>{
  const held = PC._torchStock||0;
  const stored = stor.torches||0;
  story.innerHTML = ` <span style="color:#f0ece0">松明の保管</span><br><br>`
   +`<span style="color:#c0b098">保管中：${stored}本　所持中：${held}本</span>`;
  renderChoices([
   {label:`▼ 全て預ける（${held}本）`, fn:()=>{
    if(!held){ showSaveToast('松明を持っていない'); return; }
    stor.torches=(stor.torches||0)+held; PC._torchStock=0; PC._torchTurns=0; updateHUD(); showSaveToast(`松明${held}本を預けた`); showUI();
   }},
   {label:`▼ 1本預ける`, fn:()=>{
    if(!held){ showSaveToast('松明を持っていない'); return; }
    stor.torches=(stor.torches||0)+1; PC._torchStock=Math.max(0,held-1); if(!PC._torchStock) PC._torchTurns=0; updateHUD(); showSaveToast('松明1本を預けた'); showUI();
   }},
   {label:`▲ 全て引き出す（${stored}本）`, fn:()=>{
    if(!stored){ showSaveToast('保管中の松明はない'); return; }
    PC._torchStock=(PC._torchStock||0)+stored; stor.torches=0; updateHUD(); showSaveToast(`松明${stored}本を引き出した`); showUI();
   }},
   {label:`▲ 1本引き出す`, fn:()=>{
    if(!stored){ showSaveToast('保管中の松明はない'); return; }
    PC._torchStock=(PC._torchStock||0)+1; stor.torches=Math.max(0,stored-1); updateHUD(); showSaveToast('松明1本を引き出した'); showUI();
   }},
   {label:'← アイテム保管に戻る', fn:()=>propertyStorageItems(townId)},
  ]);
 };
 showUI();
}

// ── その他の行動サブメニュー ──────────────────────────
function goOtherActions(townId){
 const def = PROPERTY_TOWNS.includes(townId) ? PROPERTY_DEFS[townId] : null;
 const hasProp = hasProperty(townId);
 const story = document.getElementById('story');
 if(story) story.innerHTML = ` <span style="color:#e0d8c8">その他の行動</span><br><br><span style="color:#c0b098">何をしますか？</span>`;
 const choices = [];
 // 散策（大都市のみ）
 const exploreCities = [];
 if(exploreCities.includes(townId)){
  choices.push({label:' 街を散策する（1日）', fn:()=>exploreCity(townId,'TOWN_'+townId.toUpperCase()), go:'__travel__'});
 }
 // 村・裏路地散策（実験導入中：VILLAGE_BACKALLEY_CONFIGSに設定のある村のみ）
 if(typeof VILLAGE_BACKALLEY_CONFIGS !== 'undefined' && VILLAGE_BACKALLEY_CONFIGS[townId]){
  const cfg = VILLAGE_BACKALLEY_CONFIGS[townId];
  const ph = villagePhase(getGameHour());
  choices.push({label:` 裏路地を散策する（${cfg.label}・現在：${ph.label}）`, fn:()=>enterVillageBackAlley(townId)});
 }
 // 小規模拠点：中央広場（行政地区／旧市街地区）散策（実験導入中：SMALL_TOWN_DISTRICTSに設定のある拠点のみ）
 if(typeof SMALL_TOWN_DISTRICTS !== 'undefined' && SMALL_TOWN_DISTRICTS[townId]){
  const ph = villagePhase(getGameHour());
  choices.push({label:` 街を散策する（中央広場・現在：${ph.label}）`, fn:()=>smallTownHub(townId)});
 }
 // 両替所（金庫サービス）：散策都市＋ヴァルドヘイム
 const bankTowns = ['khazan','al_rashid','elsia','yeldun','valdheim'];
 if(bankTowns.includes(townId)){
  choices.push({label:' 両替所（金庫サービス）', fn:()=>goExchangeBank(townId)});
 }
 // アルバイト（対応する仕事データがある町のみ。カルヴォ砦のような軍事拠点には無い）
 if(PARTTIME_JOBS[townId]){
  choices.push({label:' アルバイト（1週間・3GP）', fn:()=>doPartTimeJob(townId), go:'__travel__'});
 }
 // 物件
 if(def){
  const owned = hasProp;
  choices.push({label: owned ? ' 拠点を確認する' : ' 物件を見る', fn:()=>goPropertyNode(townId)});
 }
 const rogueGuildCities = ['khazan','elsia','al_rashid','yeldun','valdheim'];
 const hasPartyRogue = (PC.party||[]).some(m=>m.type==='rogue'&&m.con>0);
 if(rogueGuildCities.includes(townId) && (PC.type==='rogue' || hasPartyRogue)){
  choices.push({label:' 盗賊ギルド', fn:()=>{ PC.town=townId; enterGuild('rogue'); }});
 }
 const wizardGuildCities = ['khazan','elsia','al_rashid','yeldun','valdheim','neria'];
 const hasPartyWizard = (PC.party||[]).some(m=>m.type==='wizard'&&m.con>0);
 if(wizardGuildCities.includes(townId) && (PC.type==='wizard' || hasPartyWizard)){
  choices.push({label:' ウィザードズギルド', fn:()=>{ PC.town=townId; enterGuild('wizard'); }});
 }
 // 賞金首を探す：ボタンでの即時発見は廃止。街区・裏路地探索中の確率遭遇でのみ発見できる。
 // 暗殺対象を追う（targetTownIdがここの町であれば表示）
 {
  const aq = (PC.quests||[]).find(q=>q.type==='assassination' && q.status==='active'
   && (q.targetTownId===townId || (!q.targetTownId && q.fromTownId===townId)));
  if(aq) choices.push({label:` 暗殺対象を追う（${aq.targetName}）`, fn:()=>searchAssassinationTarget(townId)});
 }
 // 誘拐対象を追う（targetTownIdがここの町であれば表示）
 {
  const kq = (PC.quests||[]).find(q=>q.type==='kidnapping' && q.status==='active'
   && (q.targetTownId===townId || (!q.targetTownId && q.fromTownId===townId)));
  if(kq) choices.push({label:` 誘拐対象を追う（${kq.targetName}）`, fn:()=>searchKidnappingTarget(townId)});
 }
 // 闘技場（ARENA_TOWN_NODEに設定のある町のみ）
 if(typeof ARENA_TOWN_NODE !== 'undefined' && ARENA_TOWN_NODE[townId]){
  choices.push({label:' 闘技場', go:ARENA_TOWN_NODE[townId]});
 }

 // 盗みを働く（能動的な犯罪行為。手配度が上がる）
 choices.push({label:' 盗みを働く', fn:()=>showTheftMenu(townId), go:'__travel__'});

 // 混沌の根城（この町に根城がある場合）
 {
  if(!PC._chaosNest) initChaosNest();
  const nest = PC._chaosNest;
  if(nest.nestTownId === townId && !nest.defeatedByNPC && !nest.cleared){
   const townName = (TOWNS[townId]||{}).name || townId;
   choices.push({label:` 混沌の根城へ（${nest.wizardTitle} ${nest.wizardName}）`, fn:()=>enterChaosNest(townId)});
  }
 }


 // ダンジョン（街ごとに対応するものを表示）
 const dungeonMap = {
  khazan:    {label:' 王城地下牢へ',           go:'CRYPT_ENTRANCE'},
  stonehiem: {label:' 郊外の古代遺跡へ',       go:'RUIN_ENTRANCE'},
  rimholm:   {label:' 郊外の封じられた神殿へ', go:'SHRINE_ENTRANCE'},
  al_rashid: {label:' 東方の地下迷宮へ',       go:'AL_DNG_ENTRANCE'},
  frostpeak: {label:' 山麓の迷宮へ',           go:'FP_ENTRANCE'},
  iskald:    {label:' 古代遺跡の地下へ',       go:'ISKALD_ENTRANCE'},
 };
 if(dungeonMap[townId]){
  const d = dungeonMap[townId];
  choices.push({label:d.label, go:d.go});
 }
 if(townId === 'valdheim'){
  choices.push({label:' 北の大迷宮へ', fn:()=>enterValdheimGrandDungeon()});
 }
 if(townId === 'port_argon'){
  choices.push({label:' 打ち捨てられた坑道へ向かう（3日）', fn:()=>startLairJourney()});
  if(isPortArgonIslandUp()){
   choices.push({label:' 沖合に隆起した島へ向かう（船で3日）', fn:()=>startPortArgonIslandJourney()});
  }
 }
 if(townId === 'verda'){
  choices.push({label:` ${LAIR2_NAME}へ向かう（4日）`, fn:()=>startLair2Journey()});
 }
 if(townId === 'ashveil'){
  choices.push({label:` ${LAIR3_NAME}へ向かう（6日）`, fn:()=>startLair3Journey()});
 }
 if(townId === 'saroon'){
  choices.push({label:` ${LAIR4_NAME}へ向かう（2日）`, fn:()=>startLair4Journey()});
 }
 if(townId === 'marakai'){
  choices.push({label:` ${LAIR5_NAME}へ向かう（船で5日）`, fn:()=>startLair5Journey()});
 }
 if(townId === 'nifurvik'){
  choices.push({label:` ${NIFLAIR_NAME}へ向かう（徒歩5日）`, fn:()=>startNiflairJourney()});
 }
 if(townId === 'elsia'){
  choices.push({label:` ${LAIR6_NAME}へ向かう（徒歩4日）`, fn:()=>startLair6Journey()});
 }
 if(townId === 'duna'){
  choices.push({label:` ${LAIR7_NAME}へ向かう（徒歩2日）`, fn:()=>startLair7Journey()});
 }
 if(townId === 'stonehiem'){
  choices.push({label:` ${OUTPOST_NAME}へ向かう（徒歩2日）`, fn:()=>startOutpostJourney()});
 }
 // 定住したかつての仲間を訪ねる（settledTownがこの町のNPC全員分、ボタンを分けて表示）
 (PC._formerCompanions||[]).filter(n=>!n._dead && n.settledTown===townId).forEach(npc=>{
  choices.push({label:` ${npc.name}の家を訪ねる`, fn:()=>visitSettledCompanion(townId, npc._npcId)});
 });
 // 放浪中の者：酒場で居場所を聞いた町では、その人を探しに行ける（期限が過ぎていれば、行ってみて初めて「もう発った」と分かる）
 (PC._formerCompanions||[]).filter(n=>!n._dead && n._lastSeen && n._lastSeen.town===townId).forEach(npc=>{
  choices.push({label:` ${npc.name}を探す（酒場へ）`, fn:()=>visitRoamingCompanion(townId, npc._npcId)});
 });

 // 「冒険に出た理由」の決着系イベント：出発した町でのみ扱う
 if(townId === PC._startTown && PC.background){
  const bg = PC.background;
  // wealthタグ・借金持ちのみ：総資産が一定額に達したら返済できる
  if(bg.motiveTag === 'wealth' && bg.motiveIsDebt && !bg.wealthResolved && calcTotalWealth() >= 10000){
   choices.push({label:' 借金を返す', fn:()=>repayDebtAtStartTown(townId)});
  }
  // familyタグ：母が存命の間、いつでも生活費を渡せる
  if(bg.motiveTag === 'family' && bg.familyMotherAlive){
   choices.push({label:' 実家に生活費を渡す', fn:()=>giveFamilyMoney(townId)});
  }
 }

 // 旅芸人の一座が滞在中なら、ここから一座のメニューへ
 troupeTownChoices(townId).forEach(c=>choices.push(c));

 choices.push({label:'← 戻る', go:'TOWN_'+townId.toUpperCase()});
 renderChoices(choices);
}

// 総資産（所持金＋両替所の全口座＋拠点・領地の保管庫）を合算する
function calcTotalWealth(){
 let total = PC.gold || 0;
 Object.values(PC.bankAccounts||{}).forEach(acc=>{ total += acc.gold||0; });
 Object.values(PC.properties||{}).forEach(prop=>{ total += prop.storage?.gold||0; });
 return total;
}

// 借金を返す（wealthタグ・isDebtのみ）：固定5000GPを所持金→両替所→拠点保管庫の順に取り崩す
function repayDebtAtStartTown(townId){
 let remaining = 5000;
 const take = (getAmt, setAmt)=>{
  if(remaining<=0) return;
  const have = getAmt();
  const used = Math.min(have, remaining);
  setAmt(have-used);
  remaining -= used;
 };
 take(()=>PC.gold||0, v=>{ PC.gold=v; });
 Object.keys(PC.bankAccounts||{}).forEach(t=>{
  if(remaining<=0) return;
  take(()=>PC.bankAccounts[t].gold||0, v=>{ PC.bankAccounts[t].gold=v; });
 });
 Object.keys(PC.properties||{}).forEach(t=>{
  if(remaining<=0) return;
  const prop = PC.properties[t];
  if(!prop.storage) return;
  take(()=>prop.storage.gold||0, v=>{ prop.storage.gold=v; });
 });
 PC.background.wealthResolved = true;
 addLifeEvent('', '長年の借金を完済した。肩の荷が下りた。');
 changeTrust(PC._startTown, 10, 'debt_repaid');
 updateHUD();
 const story = document.getElementById('story');
 if(story) story.innerHTML = ` <span style="color:#e0d8c8">借金を返す</span><br><br>`
  +`<span style="color:#c0b098">長年の借金を、ついに完済した。肩の荷が下りたようだ。5000GPを支払った。</span><br>`
  +`<span style="color:#c8b8a0">この町での信頼度が上がった。</span>`;
 renderChoices([{label:'← 戻る', fn:()=>goOtherActions(townId)}]);
}

// 実家に生活費を渡す（familyタグのみ）
function giveFamilyMoney(townId){
 const bg = PC.background;
 const story = document.getElementById('story');

 // 帰郷のたびに、未報告の節目（妹の結婚・母の死去）をまず確認する
 const years = Math.floor(GAME_TIME.totalDays / 365);
 if(!bg.familySisterMarried && years >= bg.familySisterMarryYear){
  bg.familySisterMarried = true;
  addLifeEvent('', '故郷に帰り、妹が地元の相手に嫁いだと知った。');
  story.innerHTML = ` <span style="color:#e0d8c8">実家</span><br><br><span style="color:#c0b098">妹が、地元の相手に嫁いだという。もう子どもではないのだと、しみじみと実感した。</span>`;
  renderChoices([{label:'▶ 続ける', fn:()=>giveFamilyMoney(townId)}]);
  return;
 }
 if(bg.familyMotherAlive && years >= bg.familyMotherDeathYear){
  bg.familyMotherAlive = false;
  const earnedEpithet = bg.familyTotalSent >= 10000;
  if(earnedEpithet) PC.epithet = '孝行者の';
  addLifeEvent('', `故郷の母が息を引き取った。${earnedEpithet?'長年の仕送りが認められ、二つ名「孝行者の」を得た。':''}`);
  story.innerHTML = ` <span style="color:#e0d8c8">実家</span><br><br><span style="color:#c0b098">母が、静かに息を引き取ったと知らされた。長年支えてくれた人だった。</span>`
   + (earnedEpithet ? `<br><br><span style="color:#ffcc88">これまでの仕送りが認められ、二つ名「孝行者の」を得た。</span>` : '');
  updateHUD();
  renderChoices([{label:'← 戻る', fn:()=>goOtherActions(townId)}]);
  return;
 }

 const amounts = [100,500,1000].filter(n=>n<=(PC.gold||0));
 story.innerHTML = ` <span style="color:#e0d8c8">実家に生活費を渡す</span><br><br>`
  +`<span style="color:#c0b098">${bg.familySisterMarried?'母':'母と妹'}の暮らしの足しにと、いくらか渡すことにした。</span><br>`
  +`<span style="color:#c8b8a0">所持金：${PC.gold||0}GP　これまでの総額：${bg.familyTotalSent}GP</span>`;
 const doGive = (amount)=>{
  PC.gold -= amount;
  bg.familyTotalSent += amount;
  changeAlignment(Math.floor(amount/100), 0);
  updateHUD();
  story.innerHTML = ` <span style="color:#e0d8c8">実家に生活費を渡す</span><br><br>`
   +`<span style="color:#c0b098">${amount}GPを渡した。感謝された。</span>`;
  renderChoices([{label:'← 戻る', fn:()=>goOtherActions(townId)}]);
 };
 renderChoices([
  ...amounts.map(n=>({label:`${n}GP渡す`, fn:()=>doGive(n)})),
  ...((PC.gold||0)>0 ? [{label:`所持金全額渡す（${PC.gold||0}GP）`, fn:()=>doGive(PC.gold||0)}] : []),
  {label:'← 戻る', fn:()=>goOtherActions(townId)},
 ]);
}

// 定住したかつての仲間の家を訪ね、近況を聞く
function visitSettledCompanion(townId, npcId){
 const npc = (PC._formerCompanions||[]).find(n=>n._npcId===npcId);
 const story = document.getElementById('story');
 if(!npc || npc._dead){
  if(story) story.innerHTML = ` <span style="color:#e0d8c8">その他の行動</span><br><br><span style="color:#c0b098">訪ねてみたが、家は既に空き家になっていた……</span>`;
  renderChoices([{label:'← 戻る', fn:()=>goOtherActions(townId)}]);
  return;
 }
 ensureFormerChildReady(npc);
 catchUpFormerCompanion(npc);
 const townName = (TOWNS[townId]||{}).name || townId;
 // 行き先を告げて別れた仲間のうち、レベル5未満の者は、初めて訪ねたときに一定確率で「実は家を持たず冒険を続けていた」と分かる
 // （結婚して去った者は家庭を持っているため対象外。酒場で居場所を突き止めた者は決定済みなので再判定しない）
 if(!npc._roamChecked){
  npc._roamChecked = true;
  if(!fcIsMarriedLeaver(npc) && fcLevel(npc) < FC_SETTLE_LEVEL && Math.random() < FC_ITINERANT_RATE_TOLD){
   npc._itinerant = true;
   npc._whereInit = true;
   npc._hiddenTown = pickDepartureSettleTown();
   delete npc.settledTown;
   addLifeEvent('', `${npc.name}を訪ねたが、家を空けて冒険に出ているらしい。`);
   if(story) story.innerHTML = ` <span style="color:#e0d8c8">${npc.name}の家（${townName}）</span><br><br>`
    + `<span style="color:#c0b098">訪ねてみたが、${npc.name}は家を空けて冒険に出ているらしい。近所の者は「しばらく帰ってきていないよ」と言う。</span><br><br>`
    + `<span style="color:#a8a090;font-size:var(--font-sm)">居場所が分からなくなってしまった。酒場の主人に尋ねてみよう。</span>`;
   renderChoices([{label:'← 戻る', fn:()=>goOtherActions(townId)}]);
   return;
  }
 }
 let html = ` <span style="color:#e0d8c8">${npc.name}の家（${townName}）</span><br><br>`
  + `<span style="color:#c0b098">${_formerCompanionHouseLabel(npc)}を訪ねると、${npc.name}が出迎えてくれた。</span><br><br>`
  + `<span style="color:#c0b098">${formerCompanionVisitLine(npc)}</span>`;

 const finish = (html, blocked)=>{
  // 子どもが15歳以上・まだ仲間に加わっていない場合、一定確率で「自分のように連れて行ってくれないか」と持ちかけられる
  // ただしパーティが満員の間は、そもそも打診自体が起きない
  const childAge = formerCompanionChildAge(npc);
  const partyFull = (PC.party||[]).length >= 3;
  const childGrown = childAge!=null && childAge>=15 && !npc._childRecruited;
  const offerChild = childGrown && !partyFull && !blocked && Math.random()<0.4;
  if(offerChild){
   html += `<br><br><span style="color:#c0b098">「${PC.name}、実は折り入って頼みがあるんだ。うちの${npc._childName}ももう${childAge}歳でね……自分のように、あなたのパーティに連れて行ってくれないか。この町にいるだけじゃ、もったいない器だと思うんだ」</span>`;
  } else if(childGrown && partyFull && !blocked){
   html += `<br><br><span style="color:#c0b098">「${PC.name}、うちの${npc._childName}ももう${childAge}歳でね……いつかパーティに、と思っているんだが、今は連れが多いようだから、また今度にしよう」</span>`;
  }
  if(story) story.innerHTML = html;

  const choices = [];
  if(offerChild){
   choices.push({label:` ${npc._childName}を仲間に加える`, fn:()=>{
    const child = _revealFormerCompanionChildStats(npc); // 能力値と職業をここで確定する
    npc._childPendingStats = child; // 実際の加入処理でも同じ能力値・職業を使い回す
    const typeJa = {warrior:'戦士',rogue:'盗賊',wizard:'魔法使い'}[child.type]||child.type;
    story.innerHTML = ` <span style="color:#e0d8c8">${npc._childName}</span><br><br>`
     +`<span style="color:#c0b098">ST:${child.st} IQ:${child.iq} LK:${child.lk} CON:${child.con} DEX:${child.dex} CHR:${child.chr} SPD:${child.spd}</span><br><br>`
     +`<span style="color:#c0b098">${npc._childName}は、これまで培ってきた力を見込まれ、${typeJa}としての道を歩むことになりそうだ。</span>`;
    renderChoices([
     {label:` 迎え入れる`, fn:()=>_recruitFormerCompanionChild(npc, townId)},
     {label:'← 断る', fn:()=>visitSettledCompanion(townId, npcId)},
    ]);
   }});
   choices.push({label:' 今回は見送る', fn:()=>goOtherActions(townId)});
  } else {
   choices.push({label:'← 戻る', fn:()=>goOtherActions(townId)});
  }
  renderChoices(choices);
 };
 // こちらから訪ねた場合も、相手が質問を投げかけてくる（同じ人とは30日に1回まで）
 const now = GAME_TIME.totalDays;
 if(npc._talkedDay != null && now - npc._talkedDay < FC_CALL_TALK_INTERVAL_DAYS){ finish(html, false); return; }
 npc._talkedDay = now;
 fcRunQuestion(npc, fcCallKind(npc), html, true, (h, flag)=>{
  if(flag === 'e'){
   if(story) story.innerHTML = h;
   renderChoices([{label:'← 戻る', fn:()=>goOtherActions(townId)}]);
   return;
  }
  finish(h, flag === 'n');
 });
}



// ══ 両替所（金庫サービス） ══════════════════════════════════════

// 都市の両替所名
const EXCHANGE_BANK_NAMES = {
 khazan:    'カザーヌ両替商ギルド',
 al_rashid: 'アル＝ラシード砂漠金融組合',
 elsia:     'エルシア王立両替所',
 yeldun:    'イェルドゥン山岳交易銀行',
 valdheim:  'ヴァルドヘイム氷原交易所',
};

// PC.bankAccounts[townId] = { gold:0, sp:0, cp:0 }
function _getBank(townId){
 if(!PC.bankAccounts) PC.bankAccounts={};
 if(!PC.bankAccounts[townId]) PC.bankAccounts[townId]={gold:0,sp:0,cp:0};
 return PC.bankAccounts[townId];
}

// 仲間専用の口座：npc.bankAccounts[townId] = { gold:0, sp:0, cp:0 }
function _getNPCBank(npc, townId){
 if(!npc.bankAccounts) npc.bankAccounts={};
 if(!npc.bankAccounts[townId]) npc.bankAccounts[townId]={gold:0,sp:0,cp:0};
 return npc.bankAccounts[townId];
}

// 両替所のある街に到着した際、同行中の仲間が自分の判断で所持金を預け入れる
// GP：手元には「強さ×50」だけ残し、それを超える分だけを預け入れる
// SP・CP：手元に残さず全額預け入れる（いずれも手数料25%）
function autoDepositNPCAssets(townId){
 const logs = [];
 (PC.party||[]).forEach(npc=>{
  if(!npc || (npc.con||0)<=0) return; // 死亡・離脱中の仲間は対象外
  const keep = (npc.st||0) * 50;
  const gold = npc.gold||0;
  const goldAmount = Math.max(0, gold - keep);
  const spAmount = npc.sp||0;
  const cpAmount = npc.cp||0;
  if(goldAmount<=0 && spAmount<=0 && cpAmount<=0) return;
  const acc = _getNPCBank(npc, townId);
  const parts = [];

  if(goldAmount>0){
   const fee = Math.floor(goldAmount*0.25);
   const net = goldAmount - fee;
   npc.gold = gold - goldAmount;
   acc.gold = (acc.gold||0) + net;
   parts.push(`${goldAmount}GP（手数料${fee}GP、保管${net}GP）`);
  }
  if(spAmount>0){
   const fee = Math.floor(spAmount*0.25);
   const net = spAmount - fee;
   npc.sp = 0;
   acc.sp = (acc.sp||0) + net;
   parts.push(`${spAmount}SP（手数料${fee}SP、保管${net}SP）`);
  }
  if(cpAmount>0){
   const fee = Math.floor(cpAmount*0.25);
   const net = cpAmount - fee;
   npc.cp = 0;
   acc.cp = (acc.cp||0) + net;
   parts.push(`${cpAmount}CP（手数料${fee}CP、保管${net}CP）`);
  }
  logs.push(`${npc.name}が${parts.join('、')}を${EXCHANGE_BANK_NAMES[townId]||'両替所'}に預けた`);
 });
 return logs;
}

function goExchangeBank(townId){
 const bankName = EXCHANGE_BANK_NAMES[townId] || '両替所';
 const acc = _getBank(townId);
 const story = document.getElementById('story');

 const statusHtml = ()=>{
  // 他の口座があれば残高一覧も表示
  const otherBalances = Object.entries(PC.bankAccounts||{})
   .filter(([t,a])=>t!==townId && (a.gold||a.sp||a.cp))
   .map(([t,a])=>`${EXCHANGE_BANK_NAMES[t]||t}：${a.gold||0}GP ${a.sp||0}SP ${a.cp||0}CP`)
   .join('<br>');
  return ` <span style="color:#f0ece0">${bankName}</span><br><br>`
   +`<span style="color:#c0b098">預け入れ手数料：25%（100GPを預けると75GPが保管されます）</span><br><br>`
   +`<span style="color:#f0ece0">口座残高：${acc.gold||0}GP ${acc.sp||0}SP ${acc.cp||0}CP</span><br>`
   +`<span style="color:#c0b098">所持中：${PC.gold||0}GP ${PC.sp||0}SP ${PC.cp||0}CP</span>`
   +(otherBalances?`<br><br><span style="color:#e8e0d0;font-size:calc(var(--font-sm) - 2px)">他口座（出金不可）：<br>${otherBalances}</span>`:'');
 };

 // トップ
 const showUI = ()=>{
  story.innerHTML = statusHtml();
  renderChoices([
   {label:' 所持金を預け入れる', fn:()=>showDeposit()},
   {label:' 預け入れ金を引き出す', fn:()=>showWithdraw()},
   {label:'← 戻る', fn:()=>goOtherActions(townId)},
  ]);
 };

 // 預け入れ（25%手数料）
 const showDeposit = ()=>{
  story.innerHTML = statusHtml()
   +`<br><span style="color:#e0d8c8"> 預け入れ額の25%が手数料として差し引かれます</span>`;
  const amounts = [10,50,100,500,1000].filter(n=>n<=(PC.gold||0));
  renderChoices([
   ...amounts.map(n=>{
    const fee = Math.floor(n*0.25);
    const net = n - fee;
    return {label:`${n}GP 預ける → 保管${net}GP（手数料${fee}GP）`, fn:()=>depositBank(townId,n,showDeposit)};
   }),
   {label:`所持GPをすべて預ける（${PC.gold||0}GP → 保管${Math.floor((PC.gold||0)*0.75)}GP）`,
    fn:()=>depositBank(townId, PC.gold||0, showDeposit)},
   {label:'← 戻る', fn:()=>showUI()},
  ]);
 };

 // 引き出し（手数料なし）
 const showWithdraw = ()=>{
  const accGP = acc.gold||0;
  story.innerHTML = statusHtml();
  if(!accGP && !(acc.sp) && !(acc.cp)){
   story.innerHTML += `<br><span style="color:#c0b098">この口座に預け入れはありません。</span>`;
   renderChoices([{label:'← 戻る', fn:()=>showUI()}]);
   return;
  }
  const amounts = [10,50,100,500,1000].filter(n=>n<=accGP);
  renderChoices([
   ...amounts.map(n=>({label:`${n}GP 引き出す`, fn:()=>withdrawBank(townId,n,showWithdraw)})),
   {label:`残高をすべて引き出す（${accGP}GP）`, fn:()=>withdrawBank(townId,accGP,showWithdraw)},
   {label:'← 戻る', fn:()=>showUI()},
  ]);
 };

 showUI();
}

function depositBank(townId, amount, callback){
 if(!amount||amount<=0){ showSaveToast('金額が不正'); return; }
 const actual = Math.min(amount, PC.gold||0);
 if(!actual){ showSaveToast('GPが足りない'); return; }
 const fee = Math.floor(actual*0.25);
 const net  = actual - fee;
 PC.gold = (PC.gold||0) - actual;
 const acc = _getBank(townId);
 acc.gold = (acc.gold||0) + net;
 updateHUD();
 showSaveToast(`${actual}GP預け入れ（手数料${fee}GP）→ 保管${net}GP`);
 if(callback) callback();
}

function withdrawBank(townId, amount, callback){
 if(!amount||amount<=0){ showSaveToast('金額が不正'); return; }
 const acc = _getBank(townId);
 const actual = Math.min(amount, acc.gold||0);
 if(!actual){ showSaveToast('残高が足りない'); return; }
 acc.gold = (acc.gold||0) - actual;
 PC.gold  = (PC.gold||0)  + actual;
 updateHUD();
 showSaveToast(`${actual}GP引き出した`);
 if(callback) callback();
}

