// ── TREASURE GENERATOR ──────────────────────
const TREASURE_GEMS = [
 {f:1,s:[1,2],name:'水晶',    base:1},
 {f:1,s:[3,4],name:'七宝',    base:2},
 {f:1,s:[5,6],name:'トパーズ',     base:3},
 {f:2,s:[1,2],name:'ガーネット',    base:4},
 {f:2,s:[3,4],name:'トルコ石', base:5},
 {f:2,s:[5,6],name:'アメジスト',  base:6},
 {f:3,s:[1,2],name:'象牙',     base:7},
 {f:3,s:[3,4],name:'紅玉髄', base:8},
 {f:3,s:[5,6],name:'オパール',      base:9},
 {f:4,s:[1,2],name:'炎のオパール', base:10},
 {f:4,s:[3,4],name:'アクアマリン',base:11},
 {f:4,s:[5,6],name:'翡翠',      base:12},
 {f:5,s:[1,2],name:'蛇紋石',base:13},
 {f:5,s:[3,4],name:'真珠',     base:14},
 {f:5,s:[5,6],name:'ルビー',      base:15},
 {f:6,s:[1,2],name:'サファイア',  base:16},
 {f:6,s:[3,4],name:'ダイヤモンド',   base:17},
 {f:6,s:[5,6],name:'エメラルド',   base:18},
];
const TREASURE_ITEM_TYPES = ['首飾り','頭飾り','腕輪','指輪','装飾帯','武器'];
const TREASURE_SETTINGS   = ['革製','銅製','青銅製','鉄製','銀製','金製'];

function generateTreasure(totalMR){
 const roll2 = d6()+d6();
 const parts = [];
 if(roll2 === 2){
  parts.push(generateJewel());
 } else if(roll2 === 12){
  parts.push(...collectCoins(rollTreasureCoins(totalMR)));
  parts.push(generateJewel());
 } else {
  parts.push(...collectCoins(rollTreasureCoins(totalMR)));
 }
 return parts.join('  ');
}

function rollTreasureCoins(totalMR){
 return Math.max(1, Math.floor(Nd6(3) * 10 * (totalMR / 30)));
}

function collectCoins(baseAmt){
 // baseAmtはコインの枚数。パーティ全員に等分配
 const members = [PC, ...(PC.party||[]).filter(n=>n.con>0)];
 const count = members.length;
 // 討伐同行者募集ダンジョン内なら、PC自身の取り分は頭数分配のさらに半分にする
 const _companionHalf = (typeof _isCompanionHuntCombat === 'function') && _isCompanionHuntCombat();
 const coinRoll = d6();
 if(coinRoll === 1){
  const share = Math.floor(baseAmt / count);
  const rem = baseAmt - share * count;
  members.forEach(m => gainCP(share, m));
  if(rem > 0) gainCP(rem, PC);
  if(_companionHalf) gainCP(-Math.floor(share / 2), PC);
  return ['\u{1F4B0} '+baseAmt+'CP（'+count+'人分配→各'+share+'CP'+(_companionHalf?'、あなたはさらに半分':'')+'）'];
 } else if(coinRoll <= 4){
  const share = Math.floor(baseAmt / count);
  const rem = baseAmt - share * count;
  members.forEach(m => gainSP(share, m));
  if(rem > 0) gainSP(rem, PC);
  if(_companionHalf) gainSP(-Math.floor(share / 2), PC);
  return ['\u{1F4B0} '+baseAmt+'SP（'+count+'人分配→各'+share+'SP'+(_companionHalf?'、あなたはさらに半分':'')+'）'];
 } else {
  const share = Math.floor(baseAmt / count);
  const rem = baseAmt - share * count;
  members.forEach(m => gainGP(share, m));
  if(rem > 0) gainGP(rem, PC);
  if(_companionHalf) gainGP(-Math.floor(share / 2), PC);
  return ['\u{1F4B0} '+baseAmt+'GP（'+count+'人分配→各'+share+'GP'+(_companionHalf?'、あなたはさらに半分':'')+'）'];
 }
}

function generateJewel(){
 const f = d6();
 const s = d6();
 const gem = TREASURE_GEMS.find(g => g.f===f && g.s.includes(s)) || TREASURE_GEMS[0];
 let sizeRoll = d6();
 PC.invJewels = PC.invJewels || [];
 if(sizeRoll === 6){
  const itemType = TREASURE_ITEM_TYPES[d6()-1];
  let setting = TREASURE_SETTINGS[d6()-1];
  if(itemType==='武器' && setting==='革製') setting='Steel';
  let sr2 = d6(); if(sr2===6) sr2=d6();
  const gemCount = sr2<=1?5 : sr2<=2?4 : sr2<=3?3 : sr2<=4?2 : 1;
  const priceGP = gem.base * 10 * gemCount;

  if(itemType === '武器'){
   // カザーヌ装備屋のテーブルからランダムに武器を選ぶ
   const baseWeapon = WEAPONS_TABLE_KHAZAN[Math.floor(Math.random()*WEAPONS_TABLE_KHAZAN.length)];
   // 売値の1/10を攻撃修整として加算（切り捨て）
   const magicBonus = Math.floor(priceGP / 10);
   const newAdds = baseWeapon.adds + magicBonus;
   const magicName = gem.name+'x'+gemCount+' '+setting+' '+baseWeapon.name;
   const magicWeapon = {
    name: magicName,
    dice: baseWeapon.dice,
    adds: newAdds,
    twoHand: baseWeapon.twoHand,
    stReq: baseWeapon.stReq,
    dexReq: baseWeapon.dexReq || 0,
    weight: baseWeapon.weight || 0,
    cost: Math.floor(priceGP * 0.5),
    _isMagic: true,
    _priceGP: priceGP,
    ...(baseWeapon.isRanged  ? { isRanged:  true, range: baseWeapon.range||50 } : {}),
    ...(baseWeapon.rangedOk  ? { rangedOk:  true } : {}),
   };
   PC.invWeapons = PC.invWeapons || [];
   PC.invWeapons.push(magicWeapon);
   const desc = `${magicName}（${baseWeapon.dice}D${newAdds>=0?'+':''}${newAdds}）`;
   return `⚔ ${desc}（売値${Math.floor(priceGP*0.5)}GP）`;
  }

  const name = gem.name+'x'+gemCount+' '+setting+' '+itemType;
  PC.invJewels.push({name, priceGP});
  return '\u{1F48E} '+name+'(売値'+Math.floor(priceGP*0.5)+'GP)';
 }
 const sizes = [
  {name:'小',mult:5},{name:'並',mult:10},{name:'大',mult:20},
  {name:'特大',mult:50},{name:'巨大',mult:100}
 ];
 const sz = sizes[sizeRoll-1];
 const priceGP = gem.base * sz.mult;
 const name = sz.name+' '+gem.name;
 PC.invJewels.push({name, priceGP});
 return '\u{1F48E} '+name+'(売値'+Math.floor(priceGP*0.5)+'GP)';
}
// ── END TREASURE GENERATOR ─────────────────────────────────────

// 表示用文字列（0の単位は省略）
function formatMoney(pc=PC){
 const parts=[];
 if(pc.gold) parts.push(`<span style="color:#f0ece0">${pc.gold}GP</span>`);
 if(pc.sp) parts.push(`<span style="color:#f0ece0">${pc.sp}SP</span>`);
 if(pc.cp) parts.push(`<span style="color:#e0d8cc">${pc.cp}CP</span>`);
 return parts.length ? parts.join(' ') : '<span style="color:#c0b098">0CP</span>';
}

// アイテムのcost（GP単位小数）を表示文字列に変換
// 例: 1→"1GP" / 0.1→"1SP" / 0.01→"1CP"
function formatItemCost(costGP){
 const cp = Math.round(costGP * 100);
 if(cp === 0) return '0CP';
 if(cp % 100 === 0) return `${cp/100}GP`;
 if(cp % 10 === 0) return `${cp/10}SP`;
 return `${cp}CP`;
}

// 通貨の重量（枚数合計）
function coinWeight(pc=PC){ return (pc.gold||0)+(pc.sp||0)+(pc.cp||0); }

