//  PARTY / NPC SYSTEM
// ══════════════════════════════════════════

const NPC_RACES = ['human','human','human','elf','dwarf','halfling','fairy','leprechaun'];
// PCが選べるモンスター種族。旅・酒場等の一般NPCにも、ごく低確率で紛れ込む
const NPC_MONSTER_RACES = ['troll','ogre','orc','goblin'];
const NPC_TYPES = ['warrior','warrior','rogue','wizard'];

// NPCの結婚観：1人につき1つだけランダムに割り当てる
const MARRIAGE_PREF_TYPES = ['wealth','strength','alignment','intelligence','charm','age','trust','danger','profession','race'];
function _rollMarriagePref(){
 const pref = MARRIAGE_PREF_TYPES[Math.floor(Math.random()*MARRIAGE_PREF_TYPES.length)];
 const result = { marriagePref: pref };
 if(pref === 'profession') result.marriagePrefProfession = NPC_TYPES[Math.floor(Math.random()*NPC_TYPES.length)];
 if(pref === 'race') result.marriagePrefRace = NPC_RACES[Math.floor(Math.random()*NPC_RACES.length)];
 return result;
}

// NPCの結婚観に基づき、求婚時の能力値テストの目標値修正を計算する（プラスなら易しくなる）
function calcMarriagePrefBonus(npc, townId){
 const pref = npc.marriagePref;
 if(!pref) return 0;
 switch(pref){
  case 'wealth': {
   const gold = PC.gold||0;
   if(gold <= 5000) return -5;
   if(gold < 15000) return 0;
   return 5 + Math.floor((gold-15000)/5000)*5;
  }
  case 'strength':
   return PC.st>15 ? (PC.st-15) : -(15-PC.st);
  case 'intelligence':
   return PC.iq>15 ? (PC.iq-15) : -(15-PC.iq);
  case 'charm':
   return PC.chr>15 ? (PC.chr-15) : -(15-PC.chr);
  case 'alignment': {
   const dE = Math.abs((PC.alignment_ethics||0) - (npc.alignment_ethics||0));
   const dO = Math.abs((PC.alignment_order||0) - (npc.alignment_order||0));
   return Math.max(-15, 15 - (dE + dO));
  }
  case 'age': {
   const pcAge = PC.age || 0;
   const npcAge = npc.age != null ? npc.age : Math.floor((GAME_TIME.totalDays - (npc.birthDay||0)) / 365);
   const diff = Math.abs(pcAge - npcAge);
   if(diff === 0) return 15;
   if(diff <= 3) return Math.round(15 - 12*(diff/3));
   if(diff <= 5) return Math.round(3 - 3*((diff-3)/2));
   return -diff;
  }
  case 'trust': {
   const t = getTrust(townId);
   if(t>=100) return 15;
   if(t>=80) return 10;
   if(t>=60) return 5;
   return 0;
  }
  case 'danger': {
   const w = getWanted(townId);
   if(w>=100) return 15;
   if(w>=80) return 10;
   if(w>=60) return 5;
   return 0;
  }
  case 'profession':
   return PC.type === npc.marriagePrefProfession ? 15 : 0;
  case 'race':
   return PC.race === npc.marriagePrefRace ? 15 : 0;
 }
 return 0;
}

// ── 仲間の自発的離脱システム ──────────────────────────
// 婚期：declineStart（老化開始年齢）の2/3を目安とする
function marriageAge(race){
 const p = AGING_PARAMS[race] || AGING_PARAMS.human;
 return Math.round(p.declineStart * 2/3);
}
function npcAgeOf(npc){
 return npc.age != null ? npc.age : Math.floor((GAME_TIME.totalDays - (npc.birthDay||0)) / 365);
}

// NPC同士の結婚観の相性（PC向けcalcMarriagePrefBonusのNPC間版・簡易）
function calcNPCPairPrefScore(npc, other){
 const pref = npc.marriagePref;
 if(!pref) return 0;
 switch(pref){
  case 'strength': return other.st>15 ? (other.st-15) : -(15-other.st);
  case 'intelligence': return other.iq>15 ? (other.iq-15) : -(15-other.iq);
  case 'charm': return other.chr>15 ? (other.chr-15) : -(15-other.chr);
  case 'alignment': {
   const dE = Math.abs((other.alignment_ethics||0)-(npc.alignment_ethics||0));
   const dO = Math.abs((other.alignment_order||0)-(npc.alignment_order||0));
   return Math.max(-15, 15-(dE+dO));
  }
  case 'age': {
   const diff = Math.abs(npcAgeOf(npc) - npcAgeOf(other));
   if(diff===0) return 15;
   if(diff<=3) return Math.round(15-12*(diff/3));
   if(diff<=5) return Math.round(3-3*((diff-3)/2));
   return -diff;
  }
  case 'profession': return other.type===npc.marriagePrefProfession ? 15 : 0;
  case 'race': return other.race===npc.marriagePrefRace ? 15 : 0;
  default: return 0; // wealth/trust/dangerはNPC同士では判定不能
 }
}
function npcPairCompatible(npc, other){
 return calcNPCPairPrefScore(npc, other) >= 10 && calcNPCPairPrefScore(other, npc) >= 10;
}

// あるNPCについて、今この瞬間に該当しうる離脱理由を全て返す（複数該当することもある）
function evalDepartureReasons(npc){
 const reasons = [];
 // 不満系：結婚観に照らした現在のPCとの相性が著しく低い
 if(npc.marriagePref){
  const bonus = calcMarriagePrefBonus(npc, PC.town);
  if(bonus <= -10) reasons.push({ type:'dissatisfaction', pref:npc.marriagePref });
 }
 // 独立志向：レベル5以上
 if((npc.level||1) >= 5) reasons.push({ type:'independence' });
 // 婚期：未婚かつ種族ごとの適齢期に達している
 if(!npc.married && npcAgeOf(npc) >= marriageAge(npc.race)){
  reasons.push({ type:'marriage_age' });
 }
 // パーティ内結婚：相思相愛の相手がパーティ内にいる
 const partner = (PC.party||[]).find(o=>o!==npc && o.con>0 && !o.married && npcPairCompatible(npc, o));
 if(partner) reasons.push({ type:'party_marriage', partnerId:partner._npcId, partnerName:partner.name });
 // 理想の伴侶探し：race/profession型の結婚観を持つ
 if(npc.marriagePref==='race' || npc.marriagePref==='profession'){
  reasons.push({ type:'ideal_partner' });
 }
 // 師事・弟子入り：profession型の結婚観＋レベル3以上
 if(npc.marriagePref==='profession' && (npc.level||1) >= 3){
  reasons.push({ type:'apprenticeship' });
 }
 return reasons;
}

// PCの配偶者となったNPCかどうか（将来的にPCの子の父・母となる存在のため、離脱対象から除外する）
function isNpcPcSpouse(npc){
 return !!(npc.married && (PC.spouse||[]).some(s=>s.name===npc.name));
}

// パーティ全体を見て、今離脱を打ち明けてきてもおかしくないNPCを1人（と理由）選ぶ。いなければnull
function checkPartyDepartureCandidate(){
 const candidates = [];
 (PC.party||[]).forEach(npc=>{
  if(npc.con<=0) return;
  if(npc._isTemporaryCompanion) return; // 同行者募集・同行配達の一時的な同行者は独立希望を出さない
  if(isNpcPcSpouse(npc)) return; // 配偶者・PCの子の父/母となるNPCは離脱しない
  if(npc._departureCooldownUntil && npc._departureCooldownUntil > GAME_TIME.totalDays) return;
  evalDepartureReasons(npc).forEach(reason=>candidates.push({npc, reason}));
 });
 if(!candidates.length) return null;
 return candidates[Math.floor(Math.random()*candidates.length)];
}

// 離脱後の定住先をランダムに選ぶ（マレア地方を除く）
function pickDepartureSettleTown(){
 const towns = Object.keys(TOWNS).filter(t=>getRegionKey(t) !== 'marea_region');
 if(!towns.length) return PC.town;
 return towns[Math.floor(Math.random()*towns.length)];
}

// ── 離脱したNPCの「不在中の成長」処理 ──
// 再会（道中の再会・定住先訪問）のたびに一度だけ呼び、前回チェック以降に経過した年数分をまとめて処理する。
// 1年ごとに2D6し、現在のレベルを上回ったらレベルが1つ上がる（PCのレベルアップと同じ選択肢からランダムに1つ適用）。
// レベル9に達すると、定住先の町で英雄として認められたことにする。
// また、離脱から1年以上経っていれば、まだ判定していない場合に一度だけ「子どもができたかどうか」を抽選する。
function _applyRandomLevelUpStat(npc){
 const lv = npc.level;
 const half = Math.floor(lv/2);
 const opts = [
  ()=>{ npc.st=(npc.st||0)+lv; npc.maxSt=(npc.maxSt||npc.st)+lv; },
  ()=>{ gainIQ(half, npc); },
  ()=>{ npc.lk=(npc.lk||0)+lv*2; },
  ()=>{ npc.con=(npc.con||0)+lv; npc.maxCon=(npc.maxCon||npc.con)+lv; },
  ()=>{ npc.dex=(npc.dex||0)+half; },
  ()=>{ npc.chr=(npc.chr||0)+half; },
  ()=>{ npc.st=(npc.st||0)+half; npc.maxSt=(npc.maxSt||npc.st)+half; npc.con=(npc.con||0)+half; npc.maxCon=(npc.maxCon||npc.con)+half; },
 ];
 opts[Math.floor(Math.random()*opts.length)]();
}
function catchUpFormerCompanion(npc){
 if(npc._dead) return; // 故人は成長も子どもの抽選もしない
 const now = GAME_TIME.totalDays;
 const leftDay = npc._leftPartyDay ?? now;
 const lastCheck = npc._lastGrowthCheckDay ?? leftDay;
 const yearsToProcess = Math.floor((now - lastCheck) / 365);
 if(yearsToProcess > 0){
  for(let i=0; i<yearsToProcess; i++){
   npc.level = npc.level || 1;
   const roll = Nd6(2);
   if(roll > npc.level){
    npc.level += 1;
    _applyRandomLevelUpStat(npc);
   }
  }
  npc._lastGrowthCheckDay = lastCheck + yearsToProcess*365;
  if(npc.level >= 9 && !npc._isHero) npc._isHero = true;
 }
 // 離脱1年以上経過していれば、まだ判定していない場合のみ「子どもができたか」を一度だけ抽選する
 const totalYears = Math.floor((now - leftDay) / 365);
 if(totalYears >= 1 && npc._hasChild == null){
  npc._hasChild = Math.random() < 0.4;
  if(npc._hasChild){
   // 誕生日は離脱後のどこかのタイミング（現在までの間）にランダムで設定する
   npc._childBornDay = leftDay + Math.floor(Math.random()*(now-leftDay));
   npc._childName = pickNPC();
   npc._childRace = npc.race;
  }
 }
}

// かつての仲間の子どもの年齢（歳）を返す。子どもがいなければnull
function formerCompanionChildAge(npc){
 if(!npc._hasChild || npc._childBornDay == null) return null;
 return Math.floor((GAME_TIME.totalDays - npc._childBornDay) / 365);
}

// レベルに応じた家の規模の描写（訪問時の描写に使う）
function _formerCompanionHouseLabel(npc){
 const lv = npc.level || 1;
 if(lv >= 10) return '豪邸';
 if(lv >= 7) return '大きな家';
 if(lv >= 5) return '普通の家';
 return 'こぢんまりとした家';
}

// 定住先を訪ねた際の近況（離脱理由×経過年数で内容を変える）
function formerCompanionVisitLine(npc, opts){
 const years = Math.floor((GAME_TIME.totalDays - (npc._leftPartyDay||GAME_TIME.totalDays)) / 365);
 const early = years < 2;
 const n = PC.name;
 let lines;
 switch(npc.leaveReason){
  case 'marriage_age':
  case 'party_marriage':
   lines = early ? [
    `「${n}か！　いや、まだ新しい暮らしに慣れてきたところでね。落ち着いたらまた顔を出してくれ」`,
    `「${n}、久しぶりだな。二人での暮らしにはまだ手探りなところもあるが、悪くないもんだよ」`,
    `「よく来たな。所帯を持つというのは、思っていた以上に忙しいものだと今実感しているところさ」`,
    `「${n}か！　まだこの家にも慣れていなくてね、色々と落ち着かないんだ」`,
   ] : [
    `「${n}、久しいな！　実はこの前、子どもが生まれてね。今は親としての毎日で忙しくしているよ」`,
    `「${n}か！　見てくれ、うちの子だ。もうすっかり親の顔になっただろう？」`,
    `「久しぶりだな、${n}。子育ては大変だが、こんなに満たされる日々があるとは思わなかったよ」`,
    `「${n}、よく来た。子どもが生まれてからというもの、毎日があっという間に過ぎていくんだ」`,
   ];
   break;
  case 'independence':
   lines = early ? [
    `「${n}か。まだ思うようにはいかなくてね、仲間集めに苦労している」`,
    `「久しぶりだな。リーダーというのは思っていたより難しいものだと、痛感しているところさ」`,
    `「${n}か！　仲間はまだ二、三人しかいないが、少しずつ形になってきてはいる」`,
    `「よく来たな。まだ駆け出しのパーティだが、いつか大きくしてみせるさ」`,
   ] : [
    `「よく来たな、${n}！　実はこの前、ちょっとした武勇伝を打ち立ててね……」と、少し得意げに語ってくれた。`,
    `「${n}か！　うちのパーティも、ようやく名が知られるようになってきたよ」`,
    `「久しぶりだな。あの時飛び出して正解だった——今はそう思えるようになったよ」`,
    `「${n}、よく来た。今では立派に部下を率いる身になったんだ。感慨深いものがあるな」`,
   ];
   break;
  case 'apprenticeship':
   lines = early ? [
    `「${n}か。まだ師匠に扱かれる毎日でね、半人前もいいところさ」`,
    `「久しぶりだな。修行はまだまだ厳しくて、音を上げそうになる日もあるよ」`,
    `「${n}か！　覚えることが多くてね、まだ全然追いついていないんだ」`,
    `「よく来たな。師匠は厳しいが、学ぶことは多い。今はそれだけで精一杯さ」`,
   ] : [
    `「${n}、久しぶりだな。今では立派な一人前と認められてね、自分が弟子を取る立場になったんだ」`,
    `「${n}か！　ようやく師匠から独り立ちを許されてね。感慨深いものがあるよ」`,
    `「久しぶりだな。あの頃の苦労が、ようやく実を結んだ気がしている」`,
    `「${n}、よく来た。今では弟子を数人抱える身になったんだ、時の流れは早いものだな」`,
   ];
   break;
  case 'ideal_partner':
   lines = early ? [
    `「${n}、まだ探し続けているところだ。焦らずやっているよ」`,
    `「久しぶりだな。噂を頼りにあちこち回っているが、まだこれといった出会いはないよ」`,
    `「${n}か。理想を追うというのは、思っていたより時間がかかるものらしい」`,
    `「よく来たな。すぐには見つからないものだと分かってはいるが、諦めてはいないよ」`,
   ] : [
    `「${n}、聞いてくれ！　ついに理想の相手を見つけたんだ」と、嬉しそうに話してくれた。`,
    `「${n}か！　長い旅だったが、ようやく探し求めていた相手に出会えたよ」`,
    `「久しぶりだな。今の暮らしは、あの頃思い描いていた通りのものになっている」`,
    `「${n}、よく来た。探していた相手と、今は一緒に暮らしているんだ」`,
   ];
   break;
  case 'dissatisfaction':
   lines = early ? [
    `「……${n}か。少し距離を置けて、正直清々している」`,
    `「久しぶりだな。まだ、あの頃のことを思い出すと複雑な気持ちになるよ」`,
    `「${n}か。悪くは思っていないが、正直まだ整理がついていないところもある」`,
    `「よく来たな。あの決断が正しかったのか、今もたまに考えることがあるよ」`,
   ] : [
    `「${n}、久しぶりだな。今はもう吹っ切れて、穏やかに暮らしているよ」`,
    `「${n}か！　あの時のことは、もうすっかり過去の話さ。今は穏やかなものだよ」`,
    `「久しぶりだな。時間が経って、ようやくあの頃のことも笑って話せるようになった」`,
    `「${n}、よく来た。今の暮らしの方が、自分には合っていたと思っているよ」`,
   ];
   break;
  default:
   lines = [
    `「${n}、久しぶりだな。元気そうで何よりだ」`,
    `「よく来たな、${n}。変わらず元気にしているよ」`,
    `「${n}か！　こんなところまで訪ねてきてくれるとはな」`,
   ];
 }
 let line = pick(lines);
 // 結婚関連の理由以外で子どもができていた場合、追加で触れる
 if(npc._hasChild && npc.leaveReason!=='marriage_age' && npc.leaveReason!=='party_marriage' && !(opts && opts.noChild)){
  line += '<br>' + pick([
   `${npc.name}の傍らには、小さな子どもがちょこんと座っていた。「実はこっちも所帯を持ってね」と少し照れ臭そうに笑った。`,
   `奥から小さな足音がして、${npc.name}の子どもが顔をのぞかせた。「うちの子だ。可愛いもんだろう」と目を細めた。`,
   `${npc.name}の後ろで子どもが人見知りしながらこちらを窺っていた。「実は、こっちも家族が増えてね」`,
  ]);
 }
 if(npc._isHero){
  line += '<br>' + pick([
   `この町では、${npc.name}の武勲を知らぬ者はいないという。すっかり町の英雄だ。`,
   `道中、何度も${npc.name}の噂を耳にした。今やこの町を代表する顔になっているらしい。`,
   `町の子どもたちが、${npc.name}の武勇伝を真似て遊んでいるのを見かけた。すっかり伝説の存在だ。`,
  ]);
 }
 return line;
}

// かつての仲間の子ども（15歳以上）の能力値を確定する
function _revealFormerCompanionChildStats(npc){
 const attrs = ['st','iq','lk','con','dex','chr','spd'];
 const base = {};
 attrs.forEach(a=>{
  const parentVal = npc[a]||8;
  base[a] = Math.min(18, Math.max(3, parentVal + Math.floor(Math.random()*7)-3));
 });
 const child = applyRace(base, npc._childRace||npc.race);
 child.name = npc._childName || pickNPC();
 child.race = npc._childRace||npc.race;
 child.maxCon = child.con; child.maxSt = child.st;
 child.level = 1; child.ap = 0; child.gold=0; child.sp=0; child.cp=0;
 child.trust = 80;
 child._npcId = Date.now()+Math.random();
 child.type = _decideChildProfession(child); // 能力値に見合った職業をあらかじめ決めておく
 return child;
}

// 能力値の傾向から、その子にふさわしい職業を決める
// （知力・器用さが揃っていれば魔法使い、それ以外は器用さと強さの高い方で盗賊/戦士を決める）
function _decideChildProfession(child){
 const iq = child.iq||0, dex = child.dex||0, st = child.st||0;
 if(iq>=10 && dex>=8 && iq>=st) return 'wizard';
 return dex > st ? 'rogue' : 'warrior';
}

// かつての仲間の子どもをパーティに迎え入れる
function _recruitFormerCompanionChild(npc, townId){
 PC.party = PC.party||[];
 if(PC.party.length >= 3){
  showSaveToast('パーティが満員（上限3人）で迎え入れられない');
  visitSettledCompanion(townId, npc._npcId);
  return;
 }
 // 能力値・職業ともに確定済みならそのまま使う（なければこの場で確定する）
 const child = npc._childPendingStats || _revealFormerCompanionChildStats(npc);
 delete npc._childPendingStats;
 const t = child.type;
 child.equippedWeapons = t==='wizard'?[]:[{name:'ショートソード',dice:3,adds:0,twoHand:false,weight:30,stReq:7,dexReq:3}];
 child.equippedArmors = [{name:'布製の鎧',hits:3,stReq:1,isShield:false,weight:100}];
 child.invWeapons = t!=='wizard'?[]:[{name:'ショートソード',dice:3,adds:0,twoHand:false,weight:30,stReq:7,dexReq:3}];
 child.invArmors = [];
 child.spells = t==='wizard'?[{...SPELLS_L1[2]}]:[];
 const ranges = { human:[60,100], elf:[600,1000], dwarf:[150,250], halfling:[80,120], fairy:[150,250], leprechaun:[250,350], troll:[270,330], ogre:[135,165], orc:[54,66], goblin:[36,44] };
 const [min,max] = ranges[child.race||'human'] || ranges.human;
 child.lifespan = min + Math.floor(Math.random()*(max-min+1));
 child.birthDay = npc._childBornDay;
 Object.assign(child, rollBodySize(child.race));
 npc._childRecruited = true;
 PC.party.push(child);
 addLifeEvent('', `${npc.name}の子・${child.name}がパーティに加わった（${({warrior:'戦士',rogue:'盗賊',wizard:'魔法使い'})[t]||t}・${child.race}）。`);
 updateHUD(); renderPartyTab();
 const typeJa = {warrior:'戦士',rogue:'盗賊',wizard:'魔法使い'}[t]||t;
 const story = document.getElementById('story');
 if(story) story.innerHTML = ` <span style="color:#f0ece0">${npc.name}の家</span><br><br>`
  +`<span style="color:#f0ece0"> <b>${child.name}</b>がパーティに加わった！</span><br><br>`
  +`<span style="color:#c0b098">種族：${child.race}　タイプ：${typeJa}</span><br>`
  +`<span style="color:#c0b098">ST:${child.st} IQ:${child.iq} LK:${child.lk} CON:${child.con} DEX:${child.dex} CHR:${child.chr} SPD:${child.spd}</span>`;
 renderChoices([{label:'← 戻る', fn:()=>goOtherActions(townId)}]);
}

function rollNPCStat(base=8){ return base + Nd6(2) - 2; }

// レベル2以上のNPC wizardは、自身のレベル÷2（切り捨て）までの呪文レベルを全てマスターしている
function _npcSpellsForLevel(level){
 const maxSpellLv = Math.floor((level||1) / 2);
 let spells = SPELLS_L1.map(s=>({...s}));
 for(let lv=2; lv<=Math.min(maxSpellLv, 7); lv++){
  const table = SPELL_LEVEL_TABLES[lv];
  if(table) spells = spells.concat(table.map(s=>({...s})));
 }
 return spells;
}

function generateNPC(level=1){
 // 通常はNPC_RACESから、ごく低確率（0.5%）でモンスター種族が紛れ込む
 const race = (Math.random() < 0.005)
  ? NPC_MONSTER_RACES[Math.floor(Math.random()*NPC_MONSTER_RACES.length)]
  : NPC_RACES[Math.floor(Math.random()*NPC_RACES.length)];
 const type = NPC_TYPES[Math.floor(Math.random()*NPC_TYPES.length)];
 const name = NPC_NAMES[Math.floor(Math.random()*NPC_NAMES.length)];

 // ベース値をロール
 const base = {
 st: rollNPCStat(8 + (level-1)*2),
 iq: rollNPCStat(8 + (level-1)*2),
 lk: rollNPCStat(8),
 con: rollNPCStat(8 + (level-1)*2),
 dex: rollNPCStat(8 + (level-1)*2),
 chr: rollNPCStat(8),
 spd: rollNPCStat(8),
 };

 // 種族係数を適用
 const applied = applyRace(base, race);
 const { st, iq, lk, con, dex, chr, spd } = applied;

 // 装備（レベルに応じて強化）
 const weapons =
  level>=5 ? [{name:'グレートソード',dice:6,adds:0,twoHand:true,weight:170,stReq:21,dexReq:18}] :
  level>=4 ? [{name:'ブロードソード',dice:3,adds:4,twoHand:false,weight:120,stReq:15,dexReq:10},{name:'短剣',dice:2,adds:1,twoHand:false,weight:16,stReq:1,dexReq:4}] :
  level>=3 ? [{name:'ブロードソード',dice:3,adds:4,twoHand:false,weight:120,stReq:15,dexReq:10}] :
  level>=2 ? [{name:'ショートソード',dice:3,adds:0,twoHand:false,weight:30,stReq:7,dexReq:3}] :
             [{name:'ショートソード',dice:3,adds:0,twoHand:false,weight:30,stReq:7,dexReq:3}];
 const armors =
  level>=5 ? [{name:'革製の鎧',hits:6,stReq:2,isShield:false,weight:200},{name:'バックラー',hits:3,stReq:1,isShield:true,weight:75}] :
  level>=4 ? [{name:'革製の鎧',hits:6,stReq:2,isShield:false,weight:200}] :
  level>=3 ? [{name:'布製の鎧',hits:3,stReq:1,isShield:false,weight:100},{name:'バックラー',hits:3,stReq:1,isShield:true,weight:75}] :
  level>=2 ? [{name:'布製の鎧',hits:3,stReq:1,isShield:false,weight:100}] :
             [{name:'布製の鎧',hits:3,stReq:1,isShield:false,weight:100}];

 // 一定確率（30%）で遠距離武器（弓）を装備。ステータスで使える範囲からランダムに選ぶ
 let equippedRanged = null, npcArrows = 0;
 if(type !== 'wizard' && Math.random() < 0.3){
  const bows = [
   {name:'軽弓',   dice:3,adds:0,stReq:12,dexReq:15,weight:40,twoHand:true,isRanged:true,range:65},
   {name:'戦弓',   dice:5,adds:0,stReq:20,dexReq:16,weight:60,twoHand:true,isRanged:true,range:80},
   {name:'重戦弓', dice:6,adds:0,stReq:25,dexReq:17,weight:70,twoHand:true,isRanged:true,range:90},
  ];
  const usable = bows.filter(b => st>=b.stReq && dex>=b.dexReq);
  if(usable.length>0){
   equippedRanged = usable[Math.floor(Math.random()*usable.length)];
   npcArrows = 10;
  }
 }

 // level2以上のNPCはAPをそのレベルに到達している分だけ持つ
 const npcAp = LEVEL_THRESHOLDS[level-1] || 0;

 // 所持金（レベルに応じたランダム）
 const npcGold = Nd6(2) * level * 5;
 const npcSP   = d6() * level;
 const npcCP   = d6();

 const epithet = generateEpithet();
 return {
 name, race, type, level,
 epithet,
 ap: npcAp,
 st, iq, lk, con, dex, chr, spd,
 maxCon: con,
 maxSt: st,
 ...rollBodySize(race),
 gold: npcGold, sp: npcSP, cp: npcCP,
 equippedWeapons: type==='wizard' ? [] : weapons,
 equippedArmors: armors,
 equippedBoots: false,
 equippedClothing: false,
 equippedRanged: equippedRanged,
 arrows: npcArrows,
 invWeapons: type!=='wizard' ? [] : weapons,
 invArmors: [],
 spells: type==='wizard' ? _npcSpellsForLevel(level) : [],
 ...(_rollMarriagePref()),
 _npcId: Date.now() + Math.random(),
 birthDay: GAME_TIME.totalDays - Math.floor((18 + Math.floor(Math.random()*30)) * 365), // 18〜47歳でスポーン
 lifespan: (()=>{
  const ranges = {
   human:      [60, 100],
   elf:        [600, 1000],
   dwarf:      [150, 250],
   halfling:   [80,  120],
   fairy:      [150, 250],
   leprechaun: [250, 350],
   troll:      [270, 330],
   ogre:       [135, 165],
   orc:        [54,  66],
   goblin:     [36,  44],
  };
  const [min, max] = ranges[race] || ranges.human;
  return min + Math.floor(Math.random() * (max - min + 1));
 })(),
 };
}

// 種族を確実にゴブリンに固定してNPCを生成する（通行料イベント等、特定種族の敵役を作りたい場合に使用）
function generateGoblinGuard(level){
 const npc = generateNPC(level);
 const base = {
  st: rollNPCStat(8 + (level-1)*2),
  iq: rollNPCStat(8 + (level-1)*2),
  lk: rollNPCStat(8),
  con: rollNPCStat(8 + (level-1)*2),
  dex: rollNPCStat(8 + (level-1)*2),
  chr: rollNPCStat(8),
  spd: rollNPCStat(8),
 };
 Object.assign(npc, applyRace(base, 'goblin'));
 npc.maxCon = npc.con;
 npc.maxSt = npc.st;
 npc.race = 'goblin';
 npc.type = 'warrior';
 npc.name = 'ゴブリンの守衛';
 return npc;
}

