const LAIR_RACE_JA = {human:'人間',elf:'エルフ',dwarf:'ドワーフ',halfling:'ハーフリング',fairy:'フェアリー',leprechaun:'レプラコーン',troll:'トロール',ogre:'オーガ',orc:'オーク',goblin:'ゴブリン'};

// ── ゴブリンの巣窟用 ──
function generateLairGoblin(rank){ // rank: 'guard'|'veteran'|'leader'
 const level = rank==='leader'?3:rank==='veteran'?2:1;
 const npc = generateGoblinGuard(level);
 npc.name = rank==='leader' ? 'ゴブリンのリーダー' : rank==='veteran' ? 'ベテランゴブリン' : 'ゴブリンガード';
 // リーダーは一定確率で魔法使いを兼ねており、その場合Lv1の魔法を使う
 if(rank==='leader' && Math.random()<0.3){
  npc.type = 'wizard';
  npc.spells = SPELLS_L1.map(s=>({...s}));
 }
 return npc;
}

// ── オークの巣窟用 ──
function generateLairOrc(rank){ // rank: 'guard'|'veteran'|'captain'
 const level = rank==='captain'?3:rank==='veteran'?2:1;
 const npc = generateOrcWarrior(level);
 npc.name = rank==='captain' ? 'オークキャプテン' : rank==='veteran' ? 'ベテランオーク' : 'オークガード';
 // キャプテンは一定確率で魔法使いを兼ねており、その場合Lv1の魔法を使う
 if(rank==='captain' && Math.random()<0.3){
  npc.type = 'wizard';
  npc.spells = SPELLS_L1.map(s=>({...s}));
 }
 return npc;
}

// エリア4〜6用：指定レベルまでの攻撃魔法を全て使えるようにする（_npcSpellsForLevelと異なり、
// 「レベル÷2」ではなくキャラクターレベルそのものを呪文レベル上限として明示指定できる版）
function _spellsUpToLevel(maxLv){
 let spells = SPELLS_L1.map(s=>({...s}));
 for(let lv=2; lv<=Math.min(maxLv,7); lv++){
  const table = SPELL_LEVEL_TABLES[lv];
  if(table) spells = spells.concat(table.map(s=>({...s})));
 }
 return spells;
}

