// PC._lairDungeon の初期化・補完（新規キャラ／旧セーブ互換）
function initLairDungeon(){
 if(!PC._lairDungeon){
  PC._lairDungeon = { themeId:null, lastThemeId:null, spawnDay:null, clearedDay:null, nextRespawnDay:0, nodeState:{}, scenarioSorcererName:null, scenarioNames:null };
 }
 const lair = PC._lairDungeon;
 if(!lair.nodeState) lair.nodeState = {};
 Object.keys(LAIR_ROOM_AREAS).forEach(id=>{
  if(!lair.nodeState[id]) lair.nodeState[id] = { defeated:false, monsters:null };
 });
}

// ダンジョン入場時に呼ぶ：無人かつ再湧き予定日を過ぎていればテーマを抽選して住み着かせる（通常テーマ90%／シナリオ10%）
function checkLairRespawn(){
 _lairCheckRespawnGeneric('lair', initLairDungeon);
}

// ポートアルゴンから坑道までの旅程日数
const LAIR_TRAVEL_DAYS = 3;

// ダンジョン入口（外部からの入場ポイント）
function enterLairDungeon(){
 checkLairRespawn();
 initTorch();
 go('LAIR_ENTRANCE');
}

// 共通：旅の進捗UIを初期化して表示する
function _lairShowTravelUI(fromLabel, toLabel){
 drawScene('travel');
 showTravelImage('walk', 'port_argon', 'port_argon');
 const storyEl = document.getElementById('story');
 if(storyEl) storyEl.innerHTML = '';
 const tpw = document.getElementById('travel-progress-wrap');
 if(tpw){
  tpw.style.display = '';
  document.getElementById('travel-progress-bar').style.width = '0%';
  document.getElementById('travel-progress-dot').style.left = '0%';
  document.getElementById('travel-latest').textContent = '';
  document.getElementById('travel-progress-label').innerHTML =
   ` 徒歩　<span style="color:#f0ece0">${fromLabel}</span> → <span style="color:#f0ece0">${toLabel}</span>　<span id="travel-day-count" style="color:#e0d8c8">0/${LAIR_TRAVEL_DAYS}日</span>`;
 }
 renderChoices([]);
}

// ポートアルゴン → 坑道（往路）。道中エンカウントは通常の街道移動と同じ仕組みを流用する
function startLairJourney(){
 checkCompanionDeliveryAbandon();
 hideDungeonImage();
 _lairShowTravelUI('ポートアルゴン', '打ち捨てられた坑道');
 advanceDaysAnimated(LAIR_TRAVEL_DAYS, ()=>{
  checkLairRespawn();
  go('LAIR_FRONT');
 });
 if(travelState){ travelState.method = 'walk'; travelState.crossRegion = false; travelState.arriveLabel = ' 坑道に入る'; travelState.destLabel = '打ち捨てられた坑道'; }
 travelLog(`<span style="color:#b8a890"> 徒歩で <span style="color:#f0ece0">ポートアルゴン</span> → <span style="color:#f0ece0">打ち捨てられた坑道</span> へ出発。所要: ${LAIR_TRAVEL_DAYS}日</span>`);
}

