// 壁の調査（運または知力のLv1能力値テストをランダムに選んで実施）
// cfg: {returnNode, hasSecret, onFound}
// - hasSecretがtrueの場合、成功時にonFound()を呼ぶ（隠し扉の発見など）
// - hasSecretがfalse、または能力値テストに失敗した場合は「特に何もない」処理＋16%でエリア2のモンスターが現れる
function lair2SearchWall(cfg){
 const attr = Math.random() < 0.5 ? 'lk' : 'iq';
 setupSavingRoll({
  attr, level: 1,
  onSuccess(){
   if(cfg.hasSecret){ cfg.onFound(); return; }
   lair2WallNoResult(cfg.returnNode);
  },
  onFail(){
   lair2WallNoResult(cfg.returnNode);
  },
 });
}
function lair2WallNoResult(returnNode){
 const s = document.getElementById('story');
 if(s) s.innerHTML += `<br><span style="color:#c8b8a0">壁を調べてみたが、特に何も見つからなかった。</span>`;
 const wander = rollLair2Wandering(2);
 if(wander && wander.length){
  if(s) s.innerHTML += `<br><span style="color:#f0ddd8">物音に気づかれた！モンスターが現れた！</span>`;
  renderChoices([{label:' 迎え撃つ', fn:()=>startLair2WanderCombat(wander, returnNode)}]);
  return;
 }
 renderChoices([{label:'▶ OK', fn:()=>go(returnNode)}]);
}

// レバーを操作する（A/B/C）。3本すべて動かすと部屋1Jの落とし格子が開く
function lair2PullLever(id, returnNode){
 const flagKey = '_lair2Lever' + id;
 const s = document.getElementById('story');
 if(PC[flagKey]){
  if(s) s.innerHTML += `<br><span style="color:#c8b8a0">レバーはすでに動かしてある。</span>`;
 } else {
  PC[flagKey] = true;
  if(s) s.innerHTML += `<br><span style="color:#f0ece0">レバーを動かした。ギ、ギギ……と重い音が遠くから響いた。</span>`;
 }
 renderChoices([{label:'▶ OK', fn:()=>go(returnNode)}]);
}
function lair2PortcullisOpen(){
 return !!(PC._lair2LeverA && PC._lair2LeverB && PC._lair2LeverC);
}

