// ══════════════════════════════════════════
const LAIR4_NAME = '忘却の螺旋堂';
const LAIR4_TRAVEL_DAYS = 2;

function _lair4ShowTravelUI(fromLabel, toLabel){
 drawScene('travel');
 showTravelImage('walk', 'saroon', 'saroon');
 const storyEl = document.getElementById('story');
 if(storyEl) storyEl.innerHTML = '';
 const tpw = document.getElementById('travel-progress-wrap');
 if(tpw){
  tpw.style.display = '';
  document.getElementById('travel-progress-bar').style.width = '0%';
  document.getElementById('travel-progress-dot').style.left = '0%';
  document.getElementById('travel-latest').textContent = '';
  document.getElementById('travel-progress-label').innerHTML =
   ` 徒歩　<span style="color:#f0ece0">${fromLabel}</span> → <span style="color:#f0ece0">${toLabel}</span>　<span id="travel-day-count" style="color:#e0d8c8">0/${LAIR4_TRAVEL_DAYS}日</span>`;
 }
 renderChoices([]);
}
function startLair4Journey(){
 checkCompanionDeliveryAbandon();
 hideDungeonImage();
 _lair4ShowTravelUI('サルーン', LAIR4_NAME);
 advanceDaysAnimated(LAIR4_TRAVEL_DAYS, ()=>{
  checkLair4Respawn();
  go('LAIR4_FRONT');
 });
 if(travelState){ travelState.method = 'walk'; travelState.crossRegion = false; travelState.arriveLabel = ' 螺旋堂に入る'; travelState.destLabel = LAIR4_NAME; }
 travelLog(`<span style="color:#b8a890"> 徒歩で <span style="color:#f0ece0">サルーン</span> → <span style="color:#f0ece0">${LAIR4_NAME}</span> へ出発。所要: ${LAIR4_TRAVEL_DAYS}日</span>`);
}
function startLair4ReturnJourney(){
 hideDungeonImage();
 _lair4ShowTravelUI(LAIR4_NAME, 'サルーン');
 advanceDaysAnimated(LAIR4_TRAVEL_DAYS, ()=>{ go('TOWN_SAROON'); _lairPayRescueRewardGeneric('lair4'); });
 if(travelState){ travelState.method = 'walk'; travelState.crossRegion = false; travelState.destLabel = 'サルーン'; }
 travelLog(`<span style="color:#b8a890"> 徒歩で <span style="color:#f0ece0">${LAIR4_NAME}</span> → <span style="color:#f0ece0">サルーン</span> へ出発。所要: ${LAIR4_TRAVEL_DAYS}日</span>`);
}

// 部屋ノードID → エリア番号（1〜3）。部屋8は戦闘なし（特に何もない小部屋）
const LAIR4_ROOM_AREAS = {
 LAIR4_ROOM_7:3, LAIR4_ROOM_6:3,
 LAIR4_ROOM_1:2, LAIR4_ROOM_4:2, LAIR4_ROOM_3:2,
 LAIR4_ROOM_2:1, LAIR4_ROOM_5:1,
};

function initLair4Dungeon(){
 if(!PC._lair4Dungeon){
  PC._lair4Dungeon = { themeId:null, lastThemeId:null, spawnDay:null, clearedDay:null, nextRespawnDay:0, nodeState:{}, scenarioSorcererName:null, scenarioNames:null };
 }
 const lair = PC._lair4Dungeon;
 if(!lair.nodeState) lair.nodeState = {};
 Object.keys(LAIR4_ROOM_AREAS).forEach(id=>{
  if(!lair.nodeState[id]) lair.nodeState[id] = { defeated:false, monsters:null };
 });
}

// ダンジョン入場時に呼ぶ：無人かつ再湧き予定日を過ぎていればテーマを抽選して住み着かせる（通常テーマ90%／シナリオ10%）
function checkLair4Respawn(){
 _lairCheckRespawnGeneric('lair4', initLair4Dungeon);
}

// 部屋ノードの状態表示用テキストを返す（未生成なら初回訪問時にエンカウントをキャッシュ生成する。シナリオのkindにも対応）
function lair4RoomStatusText(nodeId){
 return _lairRoomStatusTextGeneric('lair4', nodeId);
}

// 部屋の戦闘・イベントを開始する（NPC型／MR型の戦闘を自動判別してディスパッチ。宝物系・捕虜の部屋は専用処理へ振り分ける）
function startLair4Encounter(nodeId){
 _lairStartEncounterGeneric('lair4', nodeId);
}

// 部屋を討伐済みにし、全部屋討伐済みなら一掃成立（半年後に再湧き）
function defeatLair4Room(nodeId){
 const lair = PC._lair4Dungeon;
 lair.nodeState[nodeId].defeated = true;
 const allDefeated = Object.keys(LAIR4_ROOM_AREAS).every(id=>lair.nodeState[id].defeated);
 if(allDefeated){
  lair.lastThemeId = lair.themeId;
  lair.clearedDay = GAME_TIME.totalDays;
  lair.nextRespawnDay = GAME_TIME.totalDays + 180;
  lair.themeId = null;
 }
}

// ワンダリングモンスター判定（16%）。テーマ不在（無人期間）なら常にnull。areaは呼び出し側が指定する
function rollLair4Wandering(area){
 const lair = PC._lair4Dungeon;
 if(!lair || !lair.themeId) return null;
 if(Math.random() >= 0.16) return null;
 const theme = _lairScenarioAwareTheme(lair.themeId);
 const table = (_lairAreaTableGeneric(theme, area)||[]).filter(e=>typeof e.spawn === 'function');
 if(!table.length) return null;
 const entry = table[Math.floor(Math.random()*table.length)];
 return entry.spawn();
}

// ワンダリングモンスターとの戦闘を開始し、勝利後は指定ノードへ戻る
function startLair4WanderCombat(monsters, returnNode){
 const isNPCType = monsters.length && monsters[0].st !== undefined;
 const common = {
  win:'__noop__', lose:'DEAD', canFlee:true,
  onWin: ()=>{
   document.getElementById('cbt-area').classList.add('hidden');
   document.getElementById('scroll-area').classList.remove('in-combat');
   document.getElementById('text-win').style.display = '';
   cbtState = null;
   go(returnNode);
  },
 };
 if(isNPCType) startCombatNPC({ enemies: monsters, autoTreasure:true, ...common });
 else startCombat({ enemies: monsters, ...common });
}

