function _niflairShowTravelUI(fromLabel, toLabel){
 drawScene('travel');
 showTravelImage('walk', 'nifurvik', 'nifurvik');
 const storyEl = document.getElementById('story');
 if(storyEl) storyEl.innerHTML = '';
 const tpw = document.getElementById('travel-progress-wrap');
 if(tpw){
  tpw.style.display = '';
  document.getElementById('travel-progress-bar').style.width = '0%';
  document.getElementById('travel-progress-dot').style.left = '0%';
  document.getElementById('travel-latest').textContent = '';
  document.getElementById('travel-progress-label').innerHTML =
   ` 徒歩　<span style="color:#f0ece0">${fromLabel}</span> → <span style="color:#f0ece0">${toLabel}</span>　<span id="travel-day-count" style="color:#e0d8c8">0/${NIFLAIR_TRAVEL_DAYS}日</span>`;
 }
 renderChoices([]);
}

// ニフルヴィク → 地中神殿の廃墟（往路）
function startNiflairJourney(){
 checkCompanionDeliveryAbandon();
 hideDungeonImage();
 _niflairShowTravelUI('ニフルヴィク', NIFLAIR_NAME);
 advanceDaysAnimated(NIFLAIR_TRAVEL_DAYS, ()=>{
  checkNiflairRespawn();
  go('NIFLAIR_FRONT');
 });
 if(travelState){ travelState.method = 'walk'; travelState.crossRegion = false; travelState.arriveLabel = ' 巣窟に入る'; travelState.destLabel = NIFLAIR_NAME; }
 travelLog(`<span style="color:#b8a890"> 徒歩で <span style="color:#f0ece0">ニフルヴィク</span> → <span style="color:#f0ece0">${NIFLAIR_NAME}</span> へ出発。所要: ${NIFLAIR_TRAVEL_DAYS}日</span>`);
}

// 地中神殿の廃墟 → ニフルヴィク（復路）
function startNiflairReturnJourney(){
 hideDungeonImage();
 _niflairShowTravelUI(NIFLAIR_NAME, 'ニフルヴィク');
 advanceDaysAnimated(NIFLAIR_TRAVEL_DAYS, ()=>{
  go('TOWN_NIFURVIK');
  _lairPayRescueRewardGeneric('niflair');
 });
 if(travelState){ travelState.method = 'walk'; travelState.crossRegion = false; travelState.destLabel = 'ニフルヴィク'; }
 travelLog(`<span style="color:#b8a890"> 徒歩で <span style="color:#f0ece0">${NIFLAIR_NAME}</span> → <span style="color:#f0ece0">ニフルヴィク</span> へ出発。所要: ${NIFLAIR_TRAVEL_DAYS}日</span>`);
}

// 部屋ノードID → エリア番号（1〜3）。持続討伐制（他5ダンジョンと同じ、テーマは全巣窟共通のLAIR_THEMESから抽選）
const NIFLAIR_ROOM_AREAS = {
 NIFLAIR_ROOM3:1, NIFLAIR_ROOM4:1, NIFLAIR_ROOM5:1,
 NIFLAIR_ROOM7:2, NIFLAIR_ROOM10:2,
 NIFLAIR_ROOM8:3, NIFLAIR_ROOM9:3,
};

// PC._niflairDungeon の初期化・補完
function initNiflairDungeon(){
 if(!PC._niflairDungeon){
  PC._niflairDungeon = { themeId:null, lastThemeId:null, spawnDay:null, clearedDay:null, nextRespawnDay:0, nodeState:{}, scenarioSorcererName:null, scenarioNames:null };
 }
 const lair = PC._niflairDungeon;
 if(!lair.nodeState) lair.nodeState = {};
 Object.keys(NIFLAIR_ROOM_AREAS).forEach(id=>{
  if(!lair.nodeState[id]) lair.nodeState[id] = { defeated:false, monsters:null };
 });
}

// ダンジョン入場時に呼ぶ：無人かつ再湧き予定日を過ぎていればテーマを抽選して住み着かせる（他5ダンジョンと共通ロジック）
function checkNiflairRespawn(){
 _lairCheckRespawnGeneric('niflair', initNiflairDungeon);
}

function enterNiflairDungeon(){
 checkNiflairRespawn();
 initTorch();
 go('NIFLAIR_ENTRANCE');
}

// 部屋を討伐済みにし、全部屋討伐済みなら一掃成立（半年後に再湧き）
function defeatNiflairRoom(nodeId){
 const lair = PC._niflairDungeon;
 lair.nodeState[nodeId].defeated = true;
 const allDefeated = Object.keys(NIFLAIR_ROOM_AREAS).every(id=>lair.nodeState[id].defeated);
 if(allDefeated){
  lair.lastThemeId = lair.themeId;
  lair.clearedDay = GAME_TIME.totalDays;
  lair.nextRespawnDay = GAME_TIME.totalDays + 180;
  lair.themeId = null;
 }
}

// ワンダリングモンスター判定（16%）。テーマ不在（無人期間）なら常にnull
function rollNiflairWandering(area){
 const lair = PC._niflairDungeon;
 if(!lair || !lair.themeId) return null;
 if(Math.random() >= 0.16) return null;
 const theme = _lairScenarioAwareTheme(lair.themeId);
 const table = (_lairAreaTableGeneric(theme, area||1)||[]).filter(e=>typeof e.spawn === 'function');
 if(!table.length) return null;
 const entry = table[Math.floor(Math.random()*table.length)];
 return entry.spawn();
}

// ワンダリングモンスターとの戦闘を開始し、勝利後は指定ノードへ戻る
function startNiflairWanderCombat(monsters, returnNode){
 const isNPCType = monsters.length && monsters[0].st !== undefined;
 const common = {
  win:'__noop__', lose:'DEAD', canFlee:true,
  onWin: ()=>{
   document.getElementById('cbt-area').classList.add('hidden');
   document.getElementById('scroll-area').classList.remove('in-combat');
   document.getElementById('text-win').style.display = '';
   cbtState = null;
   go(returnNode);
  },
 };
 if(isNPCType) startCombatNPC({ enemies: monsters, autoTreasure:true, ...common });
 else startCombat({ enemies: monsters, ...common });
}

// ノードID → 通路移動時のワンダリング判定に使うエリア番号（1 or 2）。未登録のノードは判定なし
const NIFLAIR_ENC_AREA = {
 NIFLAIR_PASSAGE2:1, NIFLAIR_PASSAGE3:1,
 NIFLAIR_HALL1:2, NIFLAIR_HALL2:2, NIFLAIR_HALL3:2, NIFLAIR_HALL4:2,
 NIFLAIR_TJUNC1:2, NIFLAIR_HALL5:2, NIFLAIR_HALL6:2, NIFLAIR_HALL7:2,
 NIFLAIR_HALL8:2, NIFLAIR_HALL9:2, NIFLAIR_PASSAGE4:2, NIFLAIR_PASSAGE5:2,
};

// 16%の確率でエリアNのワンダリングモンスターと遭遇しつつ移動する（他5ダンジョンのワンダリング判定と同じ仕組み）
function niflairMove(dest){
 const area = NIFLAIR_ENC_AREA[dest];
 if(area){
  const wander = rollNiflairWandering(area);
  if(wander && wander.length){
   const counts = {};
   wander.forEach(m=>{ counts[m.name] = (counts[m.name]||0)+1; });
   const desc = Object.entries(counts).map(([n,c])=> c>1 ? `${n}×${c}` : n).join('、');
   const s = document.getElementById('story');
   if(s) s.innerHTML += `<br><br><span style="color:#f0ddd8"> ${desc}が現れた！</span>`;
   renderChoices([]);
   drawScene('combat');
   startNiflairWanderCombat(wander, dest);
   return;
  }
 }
 go(dest);
}

// 部屋1・東の扉の罠：知力Lv1能力値テスト→（成功時は開けるか選択）→運Lv3能力値テストで落とし穴回避
function niflairRoom1EastDoor(){
 if(PC._niflairR1TrapDone){
  const s = document.getElementById('story');
  if(s) s.innerHTML += `<br><br><span style="color:#e0d8c8">東の扉の先は、落とし穴になっていた小さな空間だ。今はもう何もない。</span>`;
  renderChoices([{label:'▶ OK', fn:()=>go('NIFLAIR_ROOM1')}]);
  return;
 }
 setupSavingRoll({
  attr:'iq', level:1,
  onSuccess(){
   const s = document.getElementById('story');
   if(s) s.innerHTML += `<br><br><span style="color:#e0d8c8">床の継ぎ目に不自然な溝があるのに気づいた。この扉を開けるのは危険かもしれない。</span>`;
   renderChoices([
    {label:'→ それでも扉を開ける', fn:()=>_niflairR1PitTrap()},
    {label:'← 扉には触れずにおく', fn:()=>go('NIFLAIR_ROOM1')},
   ]);
  },
  onFail(){
   const s = document.getElementById('story');
   if(s) s.innerHTML += `<br><br><span style="color:#e0d8c8">特に気づくこともなく、そのまま扉を開けてしまった。</span>`;
   _niflairR1PitTrap();
  },
 });
}
function _niflairR1PitTrap(){
 setupSavingRoll({
  attr:'lk', level:3,
  onSuccess(){
   PC._niflairR1TrapDone = true;
   const s = document.getElementById('story');
   if(s) s.innerHTML += `<br><br><span style="color:#e0d8c8">とたんに床が開いたが、とっさに身体を跳ね除けて落とし穴に落ちずに済んだ。扉の先はただの落とし穴だったようだ。</span>`;
   renderChoices([{label:'▶ OK', fn:()=>go('NIFLAIR_ROOM1')}]);
  },
  onFail(){
   PC._niflairR1TrapDone = true;
   const dmg = d6();
   PC.con = Math.max(0, PC.con - dmg);
   updateHUD();
   const s = document.getElementById('story');
   if(s) s.innerHTML += `<br><br><span style="color:#e0d0d0">床が開き、そのまま落とし穴に真っ逆さまに落ちてしまった！　体力-${dmg}</span>`;
   if(PC.con<=0){ renderChoices([{label:'…（力尽きた）', go:'DEAD'}]); return; }
   renderChoices([{label:'▶ OK', fn:()=>go('NIFLAIR_ROOM1')}]);
  },
 });
}

