// themeIdからテーマ本体を取得（通常テーマ／シナリオ双方に対応）
function _lair5GetTheme(themeId){
 return _lairScenarioAwareTheme(themeId);
}
// _lair5GetThemeの中身を汎用化したもの（全5つの巣窟ダンジョンで共有）
function _lairScenarioAwareTheme(themeId){
 if(!themeId) return null;
 return LAIR5_SCENARIOS[themeId] || LAIR_THEMES[themeId] || null;
}

function initLair5Dungeon(){
 if(!PC._lair5Dungeon){
  PC._lair5Dungeon = { themeId:null, lastThemeId:null, spawnDay:null, clearedDay:null, nextRespawnDay:0, nodeState:{}, scenarioSorcererName:null, scenarioNames:null };
 }
 const lair = PC._lair5Dungeon;
 if(!lair.nodeState) lair.nodeState = {};
 Object.keys(LAIR5_ROOM_AREAS).forEach(id=>{
  if(!lair.nodeState[id]) lair.nodeState[id] = { defeated:false, monsters:null };
 });
}

// ダンジョン入場時に呼ぶ：無人かつ再湧き予定日を過ぎていればテーマを抽選して住み着かせる
// 通常テーマ90%／シナリオ10%の重み付けで抽選する
function checkLair5Respawn(){
 initLair5Dungeon();
 const lair = PC._lair5Dungeon;
 if(!lair.themeId && GAME_TIME.totalDays >= lair.nextRespawnDay){
  const scenarioIds = Object.keys(LAIR5_SCENARIOS);
  let pick;
  if(scenarioIds.length && Math.random() < 0.10){
   const pool = lair.lastThemeId ? scenarioIds.filter(t=>t!==lair.lastThemeId) : scenarioIds;
   const src = pool.length ? pool : scenarioIds;
   pick = src[Math.floor(Math.random()*src.length)];
  } else {
   const ids = Object.keys(LAIR_THEMES);
   const candidates = lair.lastThemeId ? ids.filter(t=>t!==lair.lastThemeId) : ids;
   pick = candidates[Math.floor(Math.random()*candidates.length)];
  }
  lair.themeId = pick;
  lair.spawnDay = GAME_TIME.totalDays;
  lair.clearedDay = null;
  if(LAIR5_SCENARIOS[pick]){
   const sd = LAIR5_SCENARIOS[pick];
   const cnt = sd.nameCount != null ? sd.nameCount : 1;
   const names = [];
   while(names.length < cnt){
    const cand = NPC_NAMES[Math.floor(Math.random()*NPC_NAMES.length)];
    if(!names.includes(cand)) names.push(cand);
   }
   lair.scenarioNames = names.length ? names : null;
   lair.scenarioSorcererName = names[0] || null; // 後方互換（旧デバッグ表示等が直接参照する場合用）
  } else {
   lair.scenarioNames = null;
   lair.scenarioSorcererName = null;
  }
  Object.keys(LAIR5_ROOM_AREAS).forEach(id=>{ lair.nodeState[id] = { defeated:false, monsters:null }; });
 }
}

// デバッグパネル用：指定シナリオを強制発生させる（本番のcheckLair5Respawnと同じ名前抽選ロジックを使う）
function _dbgForceLair5Scenario(themeId){
 initLair5Dungeon();
 const l = PC._lair5Dungeon;
 l.themeId = themeId;
 const sd = LAIR5_SCENARIOS[themeId];
 const cnt = sd ? (sd.nameCount != null ? sd.nameCount : 1) : 0;
 const names = [];
 while(names.length < cnt){
  const cand = NPC_NAMES[Math.floor(Math.random()*NPC_NAMES.length)];
  if(!names.includes(cand)) names.push(cand);
 }
 l.scenarioNames = names.length ? names : null;
 l.scenarioSorcererName = names[0] || null;
 l.spawnDay = GAME_TIME.totalDays;
 l.clearedDay = null;
 Object.keys(LAIR5_ROOM_AREAS).forEach(id=>{ l.nodeState[id] = { defeated:false, monsters:null }; });
 const sName = _lair5GetTheme(themeId).name;
 showSaveToast(names.length ? `シナリオ「${sName}（${names.join('・')}）」を強制発生` : `シナリオ「${sName}」を強制発生`);
}

// 指定エリアの表がまだ用意されていないテーマの場合、用意されている最も近い下位エリアの表にフォールバックする
// （エリア4以降は現状ゴブリン・オークの巣窟のみ用意されているため、他テーマでの参照エラーを防ぐ）
function _lair5AreaTable(theme, area){
 return _lairAreaTableGeneric(theme, area);
}
// _lair5AreaTableの中身を汎用化したもの（全5つの巣窟ダンジョンで共有）
function _lairAreaTableGeneric(theme, area){
 for(let a=area; a>=1; a--){
  if(theme['area'+a]) return theme['area'+a];
 }
 return theme.area1;
}

// 部屋の選択肢ラベルを種別に応じて返す（宝物庫は「宝箱を開ける」、革袋・施錠された木箱は「調べる」、捕虜は「近づく」、モンスターは「戦う」）
// 全5つの巣窟ダンジョンで共通。旧名の_lair5EncounterLabelは後方互換のためのエイリアス
function _lairEncounterLabel(ns){
 if(ns.kind === 'vault') return ' 宝箱を開ける';
 if(ns.kind === 'rescue') return ' 近づく';
 if(ns.kind === 'treasure' || ns.kind === 'lockbox') return ' 調べる';
 return ' 戦う';
}

