// 旅の途中でNPCと遭遇（travelEventから呼ぶ）
// ── 空虚な鎧 ヴェイン ──────────────────────────────
function startVaineEncounter(ts){
 travelState = ts;
 drawScene('travel');

 // 出現描写（ランダム）
 const VAINE_APPEARANCES = [
  `道の前方、陽炎のように揺れながら、それは現れた。\n人の形をしているが、人ではない。黒光りする全身鎧——傷ひとつない漆黒の甲冑が、ひとりでに立っている。兜の開口部の奥に目を凝らすと、そこには何もない。光さえ吸い込まれていく、深い虚無だけがある。\n鎧は音もなく${PC.name}の方を向いた。`,
  `影が濃くなったと思った次の瞬間、それは存在していた。\n完全な板金鎧。しかし着用者の重みがない——足跡が地面に刻まれず、草が踏みつぶされず、風が鎧の隙間を素通りしている。\nどこからともなく声が響いた。鎧の内側から、あるいは空気そのものから。`,
  `街道の脇に立つ古い石碑の影から、それは静かに歩み出てきた。\n黒鋼の全身鎧。装飾のない、禁欲的なほど無骨な造り。しかし兜の面頬の奥——そこに当然あるべき眼が、ない。顔が、ない。ただ暗闇が詰まっている。\n止まった。${PC.name}を見ている——何かで見ている。`,
  `${PC.name}が気づいた時、それはすでにそこにいた。\nいつから立っていたのか分からない。まるで最初からその場所の一部であったかのように、黒い鎧姿が街道の真ん中に佇んでいる。\n人間の体格に近いが、それ以上の何かを内包しているような圧迫感がある。兜の奥には何もない——あるとすれば、無限に続く暗闇だけだ。`,
  `気配もなく、それはただ「そこにあった」。まるで最初から風景の一部だったかのように。\n近づくにつれ、鎧の表面に無数の傷——いや、傷ではないと気づいた。無数の可能性が刻まれた、紋様のようなものだ。同じ模様は二つとない。`,
  `夜霧の中から、金属の擦れる音ひとつなく、それは滑るように現れた。\n月明かりを浴びても、鎧には影が落ちない。地面に、その存在を示すものは何一つない。`,
  `遠くに見えていた道標が、いつの間にか黒い甲冑へと姿を変えていた。\n錯覚だと思おうとしたが、それは確かに動き、確かに${PC.name}を見つめていた。`,
 ];

 // 台詞（多元宇宙・混沌の示唆）
 const VAINE_TALKS = [
  { line: `「……また会うな、${PC.name}」\n沈黙の後、訂正するように続けた。\n「いや。この位相では初めてか。私は無数の層を渡り歩く——どこかで会ったことが、こちらの記憶に残り続ける」`,
    sub:  '「お前が守ろうとしているものは、すでに別の位相では塵になっている。だからといって、ここでの営みが無意味だとは言わない。混沌はむしろ、その抵抗を愛している」' },
  { line: `「この世界の秩序は、薄い膜のようなものだ」\n鎧が一歩踏み出す。地面が、わずかに沈んだ。\n「私が渡ってきた位相の数だけ、その膜が破れた瞬間を見てきた。崩壊には一定のリズムがある。そしてこの世界は今、そのリズムに乗り始めている」`,
    sub:  '「我らが側にある、と言っておこう。時間は常に——そちらにいる」' },
  { line: `「英雄という概念は、興味深い」\n皮肉でも賞賛でもない、観察者の口調だった。\n「無数の位相で、無数の英雄を見た。あるものは秩序を守り、あるものは混沌に飲まれ、あるものは自らが混沌の器となった。結末の分布は——均等ではない」`,
    sub:  '「確率の話をしている。お前が勝つ可能性がないとは言わない。ただ、私が観測してきた限り——流れはひとつの方向を向いている」' },
  { line: `「混沌は破壊ではない」\n鎧の奥の暗闇が、深くなったような気がした。\n「秩序もまた、ひとつの暴力だ。形を強制し、変化を拒絶し、あるべき姿を決めつける。混沌はただ——全てのものがあるべき場所に還ることを望んでいる」`,
    sub:  '「私はその方向性を、美しいと思っている。個人的な感想だが」' },
  { line: `「お前は選択の重さを知らない」\n静かな、責めるでもない口調だった。\n「一つの選択が、無数の枝を生む。お前がここで交わす言葉ひとつが、既に別の位相を生み落としている。今この瞬間にも」`,
    sub:  '「だから私は、言葉を選ぶ。無意味に見えても、無意味ではない」' },
  { line: `「終わりは、始まりの別名に過ぎない」\n鎧が僅かに首——かつて首だった場所——を傾けた。\n「私が見てきた位相の多くは、崩壊した。だが崩壊の後には、必ず何かが芽吹いていた。混沌とは、その芽吹きの土壌だ」`,
    sub:  '「恐れる必要はない、とだけ言っておこう。もっとも、お前が信じるかどうかは別の話だが」' },
  { line: `「時に、私は自問する」\n珍しく、迷いを含んだ声だった。\n「これほど多くの位相を渡り歩いて、私は何を求めているのか、と。答えはまだ出ていない」`,
    sub:  '「お前に聞かれて初めて、その問いを口にした。奇妙な気分だ」' },
 ];

 const appear = VAINE_APPEARANCES[Math.floor(Math.random() * VAINE_APPEARANCES.length)];
 const talk   = VAINE_TALKS[Math.floor(Math.random() * VAINE_TALKS.length)];

 travelLog(`<div style="border:1px solid #443300;border-radius:4px;padding:12px;background:#0a0800;margin:4px 0">
  <div style="color:#d8d0c0;font-size:calc(var(--font-sm) - 1px);margin-bottom:10px"> ${ts.daysDone}日目　旅の途中</div>
  <div style="color:#d0c8b8;font-size:var(--font-sm);line-height:1.9;white-space:pre-wrap;margin-bottom:12px">${appear}</div>
  <div style="color:#f0ece0;font-size:calc(var(--font-sm) - 1px);margin-bottom:6px">── 空虚な鎧 ──</div>
  <div style="color:#d0c8b8;font-size:var(--font-sm);line-height:1.9;white-space:pre-wrap">${talk.line}</div>
  <div style="color:#c0b098;font-size:calc(var(--font-sm) - 1px);margin-top:10px;line-height:1.8;font-style:italic">${talk.sub}</div>
 </div>`);

 const choices = document.getElementById('choices');
 choices.innerHTML = '';

 // 返答選択肢（毎回7種類の中からランダムに3つ選ばれる）
 const allReplies = [
  { label:'「位相とは何だ」',
    res: `「位相」\n間を置いた。\n「お前たちの言語で近い概念は——世界、か。あるいは可能性、か。ひとつの選択が行われるたびに、別の選択をした世界が枝分かれして生まれる。私はその枝を渡り歩いてきた。何千、何万の枝を」\n「この世界は、その枝のひとつに過ぎない」` },
  { label:'「混沌に仕えるのか」',
    res: `「仕える、という言葉は正確ではない」\n鎧の奥の暗闘が、わずかに揺れた。\n「私は混沌の方向性を——正しいと判断した。それだけだ。主従関係ではない。ただ、この宇宙が向かうべき場所を、私は知っている。そしてその方向に立っている」\n「お前たちが秩序と呼ぶものは、流れに逆らうことだ」` },
  { label:'「なぜ私に話しかける」',
    res: `長い沈黙があった。\n「……それは私にも分からない」\n珍しいことのように、その声には微かな困惑があった。\n「無数の位相で、無数の者と会ってきた。だが、同じ者に何度も出会う位相というものが、存在する。お前は——その類の者かもしれない」\n「あるいは、ただの誤差かもしれない」` },
  { label:'「お前に名はあるのか」',
    res: `また間があった。\n「名——それは一つの位相に縛られた概念だ。だが、この位相でお前たちに呼ばれた名がある。ヴェイン、と」\n「気に入っているわけではないが、拒む理由もない」` },
  { label:'「私を殺すつもりか」',
    res: `「殺す？」\n奇妙な間があった。理解に苦しんでいるような、あるいは面白がっているような。\n「私はお前の生死に関心がない。介入もしない。私はただの——観測者だ。もっとも、観測者であることそのものが、既にひとつの介入なのかもしれないが」` },
  { label:'「その先に何があるのか教えてくれ」',
    res: `「先、か」\n鎧がわずかに${PC.name}へ向き直った。\n「教えたところで、お前はその通りに動かないだろう。位相を渡ってきた経験から言えば、それが最も興味深いところだ。予言は、聞いた者の行動によって容易く覆る」\n「だから教えない。それもまた、私の観測の一部だ」` },
  { label:'「お前は孤独ではないのか」',
    res: `初めて、鎧が沈黙した。長い沈黙だった。\n「……その問いに答えた位相を、私は知らない」\n声には、これまでになかった何かが滲んでいた。\n「渡り歩くということは、どこにも属さないということだ。孤独、という言葉が正しいかどうかは——お前たちに判断を委ねよう」` },
 ];
 // シャッフルして先頭3件を今回の選択肢にする
 const replies = [...allReplies].sort(()=>Math.random()-0.5).slice(0, 3);

 replies.forEach(r => {
  const b = document.createElement('button'); b.className = 'choice-btn';
  b.textContent = r.label;
  b.onclick = () => {
   travelLog(`<div style="color:#d0c8b8;font-size:var(--font-sm);line-height:1.9;white-space:pre-wrap;padding:10px;background:#0d0d0d;border-left:2px solid #443300;margin:2px 0">${r.res}</div>`);
   choices.innerHTML = '';
   _showVaineActionChoices(ts);
  };
  choices.appendChild(b);
 });

 _showVaineActionChoices(ts);
}

function _showVaineActionChoices(ts, initial=false){
 const choices = document.getElementById('choices');

 // 立ち去るボタン
 const leave = document.createElement('button'); leave.className = 'choice-btn';
 leave.textContent = '背を向けて立ち去る';
 leave.onclick = () => {
  choices.innerHTML = '';
  addLifeEvent('', '旅の途中で、名を明かさぬ空虚な鎧と出会った。');
  travelLog(`<span style="color:#d8d0c0"> ${ts.daysDone}日目：空虚な鎧と別れ、旅を続けた。</span>`);
  setTimeout(()=>travelTick(), ts.interval);
 };
 choices.appendChild(leave);
}

// デバッグ用：空虚な鎧ヴェインとの遭遇を強制発生させる（会話パターンの確認用）
function dbgForceVaineEncounter(){
 const ts = {
  totalDays: 999, daysDone: 1, destId: null,
  onDone: ()=>{ showSaveToast('デバッグ：ヴェイン遭遇テスト終了'); },
  events: [], interval: 1200, method: 'walk', crossRegion: false,
 };
 startVaineEncounter(ts);
}

function rollNPCEncounter(){
 if(Math.random()>((travelState && travelState._wildOff) ? 0.001 : 0.04)) return null; // 4%（元8%の半分）／荒野の街道外は0.1%
 // レベル1〜5をランダムに（低レベルが出やすい重み付け）
 const lv = [1,1,1,2,2,3,3,4,5][Math.floor(Math.random()*9)];
 return generateNPC(lv);
}


// Roll 2D6 with doubles-explode
function roll2D6explode(){
 let total=0, a=d6(), b=d6();
 total = a+b;
 while(a===b){ a=d6(); b=d6(); total+=a+b; }
 return total;
}

// ── PERSONAL ADDS ──────────────────────
// ST, LK, DEX: each point above 12 = +1, each point below 9 = -1
function calcAdds(pc=PC){
 let adds=0;
 ['st','lk','dex'].forEach(s=>{
 const v = pc[s];
 if(v>12) adds += v-12;
 else if(v<9) adds += v-9;
 });
 return adds;
}

// ── WEAPON COMBAT ROLL ─────────────────
function playerCombatRoll(weaponIdx=0){
 const adds = calcAdds();
 const equipped = PC.equippedWeapons || [];
 if(!equipped.length) return d6() + adds; // 素手
 const w = equipped[weaponIdx] || equipped[0];
 let roll = Nd6(w.dice);
 return roll + w.adds + adds;
}

// ── MONSTER CR COMBAT ROLL ─────────────
function monsterCombatRoll(mr){
 const dice = Math.floor(mr/10)+1;
 const adds = Math.ceil(mr/2);
 const rv = rollNd6(dice);
 return {total: rv.total + adds, dice: rv.dice};
}

// ── SAVING ROLL ────────────────────────
// target = level*5 + 15 (Lv1=20, Lv2=25, Lv3=30...)
// Roll 2D6 + attribute value. Doubles explode.
// Returns {success, rolled, total, target, ap}
function savingRoll(attr, level, pc=PC){
 const target = level*5 + 15;
 const attrVal = pc[attr] || 0;
 const rolled = roll2D6explode();
 const ap = rolled * level; // 成否・ファンブル問わず経験値加算
 if(rolled < 5){ return {success:false, rolled, total:rolled+attrVal, target, ap}; }
 const total = rolled + attrVal;
 const success = total >= target;
 return {success, rolled, total, target, ap};
}

// ── ARMOR VALUE ────────────────────────
// Warriors get double armor protection
function effectiveArmor(pc=PC){
 const base = (pc.equippedArmors||[]).reduce((s,a)=>s+a.hits,0);
 const warriorBase = pc.type==='warrior' ? base*2 : base;
 return (pc===PC && (PC._fortifyArmorTurns||0) > 0) ? warriorBase*3 : warriorBase;
}

// ── LEVEL & 経験値 ─────────────────────────
const LEVEL_THRESHOLDS = [0,1000,3000,7000,15000,25000,45000,70000,100000,140000,200000,280000,400000,550000,750000,1000000,2000000,4000000,8000000,16000000];
function checkLevel(pc=PC){
 let lv=1;
 for(let i=1;i<LEVEL_THRESHOLDS.length;i++){
 if(pc.ap >= LEVEL_THRESHOLDS[i]) lv=i+1; else break;
 }
 return lv;
}
// NPC（またはPC）に直接APを加算する
function gainAPFor(pc, amount){
 if(!pc || amount <= 0) return;
 pc.ap = (pc.ap||0) + amount;
 if(pc === PC){
  gainAP(0); // PCのレベルチェックのみ（gainAPAll重複呼び防止）
 } else {
  // NPC レベルアップチェック
  const newLv = calcLevelFromAP(pc.ap);
  if(newLv > (pc.level||1)){
   pc.level = newLv;
   _queueLevelUp(newLv, pc);
  }
 }
}

// APからレベルを計算（LEVEL_THRESHOLDSを使用・checkLevelと同ロジック）
function calcLevelFromAP(ap){
 let lv = 1;
 for(let i=1;i<LEVEL_THRESHOLDS.length;i++){
  if(ap >= LEVEL_THRESHOLDS[i]) lv = i+1; else break;
 }
 return lv;
}

// PCのみにAPを加算してレベルアップチェック
function gainAP(amount){
 PC.ap = (PC.ap||0) + amount;
 const newLv = checkLevel();
 if(newLv > PC.level){
  PC.level = newLv;
  _queueLevelUp(newLv, PC);
  return true;
 }
 if(newLv < PC.level){
  PC.ap = Math.max(PC.ap, LEVEL_THRESHOLDS[PC.level-1]||0);
 }
 return false;
}

// イベントAP：PCとパーティ全員に同額を配布
function gainAPAll(amount){
 if(amount <= 0) return;
 gainAP(amount);
 (PC.party||[]).forEach(n=>{ if(n.con>0) gainAPFor(n, amount); });
 // AP取得 → パーティNPCの信頼度+1
 if((PC.party||[]).filter(n=>n.con>0).length > 0) changeNPCTrust(+1);
}

// 戦闘AP：MR合計を頭数で割ってPC+パーティ全員に配布
function gainAPCombat(totalMR){
 if(totalMR <= 0) return 0;
 const members = 1 + (PC.party||[]).filter(n=>n.con>0).length;
 const share = Math.max(1, Math.floor(totalMR / members));
 gainAP(share);
 (PC.party||[]).forEach(n=>{ if(n.con>0) gainAPFor(n, share); });
 // 戦闘AP取得 → パーティNPCの信頼度+1
 if(members > 1) changeNPCTrust(+1);
 return share;
}

// ── LEVEL UP UI ────────────────────────
// PC・NPC共用のレベルアップキュー（同じタイミングで複数人が同時にレベルアップした場合、1人ずつ順番に処理する）
let _npcLevelUpQueue = [];
// 「現在レベルアップ表示中／表示予約済み」フラグ。
// パネルのDOMクラス（hidden）ではなくこのフラグで判定することで、
// setTimeoutの実行前に後続のgainAPFor()が呼ばれても正しく順番待ちに積めるようにする
let _levelUpActive = false;
// レベルアップ後に再開すべき戦闘継続関数（カオスSR中のNPCフェーズ再開用）
let _pendingCombatResume = null;

// PC・NPC共通：レベルアップ表示を予約する（表示中／予約中なら順番待ちキューに積む）
function _queueLevelUp(lv, pc){
 if(_levelUpActive){
  _npcLevelUpQueue.push({lv, pc});
 } else {
  _levelUpActive = true;
  setTimeout(()=>showLevelUpPanel(lv, pc), 100);
 }
}

function _processNpcLevelUpQueue(){
 if(_npcLevelUpQueue.length === 0){ _levelUpActive = false; return; }
 const {lv, pc} = _npcLevelUpQueue.shift();
 _levelUpActive = true;
 setTimeout(()=>showLevelUpPanel(lv, pc), 150);
}

// pc省略またはPC渡しでPC本人、NPC渡しでNPCのレベルアップ
function showLevelUpPanel(lv, pc){
 pc = pc || PC;
 const isPC = (pc === PC);
 const name = isPC ? 'あなた' : (pc.name || 'NPC');
 const panel = document.getElementById('levelup-panel');
 document.getElementById('lu-title').textContent = `⬆ ${name}　Lv${lv-1} → Lv${lv}`;
 const half = Math.floor(lv / 2);

 // 選択肢定義（対象pcに適用）
 const opts = [
  { label:`A. 強さ + ${lv}`,                       fn:()=>{ pc.st+=lv; pc.maxSt=(pc.maxSt||pc.st)+lv; } },
  { label:`B. 知力 + ${half}`,                     fn:()=>{ gainIQ(half, pc); } },
  { label:`C. 運 + ${lv*2}`,                       fn:()=>{ pc.lk+=lv*2; } },
  { label:`D. 体力 + ${lv}`,                       fn:()=>{ pc.con+=lv; pc.maxCon=(pc.maxCon||pc.con)+lv; } },
  { label:`E. 器用さ + ${half}`,                   fn:()=>{ pc.dex+=half; } },
  { label:`F. 魅力 + ${half}`,                     fn:()=>{ pc.chr+=half; } },
  { label:`G. 強さ + ${half} / 体力 + ${half}`,   fn:()=>{ pc.st+=half; pc.maxSt=(pc.maxSt||pc.st)+half; pc.con+=half; pc.maxCon=(pc.maxCon||pc.con)+half; } },
 ];

 const el = document.getElementById('lu-options');
 el.innerHTML = '';
 opts.forEach(opt=>{
  const btn = document.createElement('button');
  btn.className = 'choice-btn';
  btn.style.cssText = 'background:#2a1a08;border:1px solid var(--leather);color:#f0ece0;font-size:calc(var(--font-sm) - 1px);padding:10px;text-align:left';
  btn.textContent = opt.label;
  btn.onclick = ()=>{
   opt.fn();
   updateHUD();
   panel.classList.add('hidden');
   const story = document.getElementById('story');
   const notice = document.createElement('div');
   notice.style.cssText = 'border-top:1px solid var(--leather);margin-top:10px;padding-top:8px;color:#f0ece0;font-size:var(--font-sm)';
   notice.innerHTML = `⬆ <b>${name} Lv${lv} アップ！</b>　${opt.label.replace(/^[A-G]\.\s*/,'')}`;
   story.appendChild(notice);
   // キューに次のNPCが待機していれば処理
   _processNpcLevelUpQueue();
   // 戦闘継続関数があればそちらを優先（カオスSR中のNPCフェーズ再開）
   if(_npcLevelUpQueue.length === 0){
    if(_pendingCombatResume){
     const fn = _pendingCombatResume;
     _pendingCombatResume = null;
     setTimeout(fn, 50);
    } else if(cbtState){
     // OKボタンが既に表示中なら干渉しない
     const okArea = document.getElementById('cbt-ok-area');
     const hasOkBtn = okArea && okArea.style.display !== 'none' && okArea.innerHTML.trim() !== '';
     if(!hasOkBtn){
      if(cbtState.isNPC){ updateCombatUINPC(); _showPCActionChoices(); }
      else { updateCombatUI(); _showPCActionChoices(); }
     }
    }
   }
  };
  el.appendChild(btn);
 });

 panel.classList.remove('hidden');
 panel.scrollIntoView({behavior:'smooth', block:'nearest'});
}

// ── WEIGHT POSSIBLE ────────────────────
// 防寒着と荷物袋を装備していれば強さ×100、していなければその半分（強さ×50）までしか持てない
const weightPossible = (pc=PC) => pc.equippedClothing ? pc.st * 100 : pc.st * 50;

// 現在の総所持重量を計算（アイテム＋硬貨）
function calcTotalWeight(pc=PC){
 let w = 0;
 // 武器（インベントリ全て）
 (pc.invWeapons||[]).forEach(iw=>{
 w += iw.weight||0;
 });
 // 防具（インベントリ全て）
 (pc.invArmors||[]).forEach(ia=>{
 w += ia.weight||0;
 });
 // 靴（名前からEQUIP_TABLEを参照して正確な重量を取得）
 if(pc.invBootsName){
 const bootsDef = EQUIP_TABLE.find(t=>t.name===pc.invBootsName);
 if(bootsDef) w += bootsDef.weight;
 } else if(pc.invBoots){
 // 後方互換：旧セーブデータはBootsとして扱う
 w += 40;
 }
 // 衣服
 if(pc.invClothingName){
  const cDef = EQUIP_TABLE.find(t=>t.name===pc.invClothingName);
  if(cDef) w += cDef.weight;
 } else if(pc.invClothing){
  w += 10; // 後方互換
 }
 // 予備の靴
 FOOTWEAR_NAMES.forEach(n=>{
  const cnt = spareFootwearCount(n, pc);
  const d = cnt ? EQUIP_TABLE.find(t=>t.name===n) : null;
  if(d) w += d.weight * cnt;
 });
 // その他所持品
 (pc.invEquip||[]).forEach(name=>{
 const def = EQUIP_TABLE.find(t=>t.name===name);
 if(def) w += def.weight;
 });
 // 地方特産品
 (pc.invSpecialties||[]).forEach(sp=>{
 w += sp.weight||0;
 });
 // 松明（_torchStockで管理、1本あたりの重量はEQUIP_TABLEから取得）
 const torchDef = EQUIP_TABLE.find(t=>t.name==='松明');
 if(torchDef){
 const totalTorches = (pc._torchStock || 0) + (pc._torchTurns > 0 ? 1 : 0);
 w += totalTorches * torchDef.weight;
 }
 // 食料ポイント（1ポイント = 重量5）
 w += (pc._food || 0) * 5;
 // 硬貨（GP+SP+CP 各1wu）
 w += coinWeight(pc);
 return w;
}

// 重量オーバーチェック＆SPD半減を適用
// pc.spdBaseに素のSPDを保存し、過積載ならspd=floor(spdBase/2)
function checkWeightPenalty(pc=PC){
 if(pc.spdBase == null) pc.spdBase = pc.spd; // 初回セット
 const max = weightPossible(pc);
 const cur = calcTotalWeight(pc);
 const over = cur > max;
 if(over){
 pc.spd = Math.max(1, Math.floor(pc.spdBase / 2));
 } else {
 pc.spd = pc.spdBase;
 }
 return { cur, max, over };
}

// ══════════════════════════════════════════
// SAVE / LOAD SYSTEM
// ══════════════════════════════════════════
const SAVE_SLOT_COUNT = 3;
const SAVE_KEY_PREFIX = 'tt5_save_';
const AUTOSAVE_KEY = 'tt5_autosave';

function autoSave(){
 if(PC._autoSave === false) return;
 const data = {
  pc: JSON.parse(JSON.stringify(PC)),
  gameTime: JSON.parse(JSON.stringify(GAME_TIME)),
  nodeId: currentNodeId,
  savedAt: Date.now(),
  isAutoSave: true,
 };
 localStorage.setItem(AUTOSAVE_KEY, JSON.stringify(data));
 showSaveToast(' 自動セーブ完了');
}

function loadAutoSave(){
 const raw = localStorage.getItem(AUTOSAVE_KEY);
 if(!raw) return false;
 const data = JSON.parse(raw);
 // Object.assignは「上書きマージ」のため、ロード前のセッションに残っていたキーが
 // ロードするセーブデータに存在しない場合でもクリアされず残ってしまう。
 // 領地関連のフィールドはこれが原因で新旧データが混線しうるため、代入前に明示的にリセットする
 delete PC._fiefCharter;
 delete PC._fiefCharters;
 PC.properties = {}; // 拠点データもロード前のセッションの残留を防ぐため必ず空にリセットしてから代入する
 PC._tavernThanks = {}; // 酒場のお礼（受け取り待ち）も、ロード前のセッションの残留を防ぐためリセットしてから代入する
 PC._formerCompanions = []; // かつての仲間の名簿も、ロード前のセッションの残留を防ぐためリセットしてから代入する
 _fcVisitLastDay = null;     // 来訪判定の基準日も、ロード後の最初の判定で現在日に合わせ直す
 delete PC._wild; delete PC._wildMaps; delete PC._wildCamps; delete PC._wildCastles; delete PC._troupes; delete PC._troupeContract; delete PC._arcs; delete PC._arcLog; delete PC._arcEpilogues; delete PC._arcLastStart; delete PC._arcLastType; delete PC._arcSeeds; delete PC._arcLetters; delete PC._arcReunions; delete PC._arcTravelerDone; // 旅芸人の一座・護衛契約も、ロード前のセッションの残留を防ぐため消してから代入する
 Object.assign(PC, data.pc);
 Object.assign(GAME_TIME, data.gameTime);
 if(PC.invEquip){
  PC.invEquip = PC.invEquip.filter(name => {
   if(name === '松明'){ PC._torchStock = (PC._torchStock||0)+3; return false; }
   return true;
  });
 }
 if(PC._torchStock == null) PC._torchStock = 0;
 if(PC._torchTurns == null) PC._torchTurns = 0;
 // 旧データ移行：領地の複数所有対応リファクタリング以前のセーブデータを新形式に変換する
 _migrateFiefDataIfNeeded();
 // 旧データ移行：動機タグ導入以前のセーブデータに、タグ・固有データを逆引きで補完する
 _migrateBackgroundMotiveIfNeeded();
 // 装備参照の結び付け直し（セーブ/ロードで見た目上の複製が生まれる問題の修正）
 _reconcileEquipRefs(PC);
 (PC.party||[]).forEach(npc=>_reconcileEquipRefs(npc));
 ['title-screen','chargen','shop-area'].forEach(id=>{
  document.getElementById(id)?.classList.add('hidden');
 });
 // モバイルでステータスパネルが開いたまま残らないよう、ロード時に必ず閉じる
 if(window.innerWidth < 860) document.getElementById('inv-panel')?.classList.add('hidden');
 const g = document.getElementById('game');
 g.classList.remove('hidden'); g.style.display='flex';
 currentNodeId = data.nodeId || 'TOWN_KHAZAN';
 updateHUD(); updateTimebar();
 // 拠点画面・領地の広場は通常のノードシステムを経由しないため、専用のマーカーIDから復元する
 if(currentNodeId === 'FIEF_PLAZA' || (currentNodeId && currentNodeId.startsWith('FIEF_PLAZA_'))){
  // 'FIEF_PLAZA'（接尾辞なし）は複数領地対応前の旧マーカー。fiefIdが取れない場合は先頭の領地にフォールバックする
  const fiefId = currentNodeId.startsWith('FIEF_PLAZA_') ? currentNodeId.slice('FIEF_PLAZA_'.length).toLowerCase() : null;
  const charter = fiefId ? getFiefCharter(fiefId) : (PC._fiefCharters||[])[0];
  if(charter) showFiefPlaza(charter.anchorTownId);
  else go('TOWN_KHAZAN');
 } else if(currentNodeId && currentNodeId.startsWith('PROPERTY_')){
  let townId = currentNodeId.slice('PROPERTY_'.length).toLowerCase();
  // 'PROPERTY_FIEF'（複数領地対応前の旧マーカー）は先頭の領地のfiefIdに読み替える
  if(townId === 'fief'){
   const firstCharter = (PC._fiefCharters||[])[0];
   townId = firstCharter ? firstCharter.fiefId : null;
  }
  if(townId && isValidPropertyId(townId)) goPropertyNode(townId);
  else go('TOWN_KHAZAN');
 } else {
  go(currentNodeId);
 }
 return true;
}
const WORLD_KEY = 'tt5_world'; // 世界の継続状態（暦・過去仲間）
let currentSaveSlot = 1; // 現在使用中スロット（1〜3）
function getSaveKey(slot){ return SAVE_KEY_PREFIX + (slot||currentSaveSlot); }
let currentNodeId = 'TOWN_KHAZAN';
let _lastNodeId = null; // go()で移動する直前にいたノード（巣窟の逃走成功時など「1つ前のノードに戻る」用途に使用）

// ── WORLD STATE ─────────────────────────
// 引退・死亡をまたいで保存される世界状態
function loadWorldState(){
 try{
 const raw = localStorage.getItem(WORLD_KEY);
 const ws = raw ? JSON.parse(raw) : null;
 console.log('[WS] loadWorldState key=', WORLD_KEY, 'found=', !!ws, 'properties=', ws ? JSON.stringify(ws.properties)?.slice(0,200) : null);
 return ws;
 }catch(e){ console.error('[WS] loadWorldState error', e); return null; }
}
function saveWorldState(ws){
 console.log('[WS] saveWorldState key=', WORLD_KEY, 'properties=', JSON.stringify(ws.properties)?.slice(0,200), 'residents=', JSON.stringify(ws.properties ? Object.values(ws.properties).map(p=>p.residents) : null));
 localStorage.setItem(WORLD_KEY, JSON.stringify(ws));
}
function clearWorldState(){
 localStorage.removeItem(WORLD_KEY);
}

// 現在PCを引退・死亡させ、WORLD_STATEを更新
function mergeArray(wsArr, pcArr, key){
 // wsArrとpcArrをkeyで重複排除してマージ（pcArrを優先）
 const base = JSON.parse(JSON.stringify(wsArr||[]));
 const cur  = JSON.parse(JSON.stringify(pcArr||[]));
 cur.forEach(item=>{
  const idx = base.findIndex(b=>b[key]===item[key]);
  if(idx >= 0) base[idx] = item; else base.push(item);
 });
 return base;
}

function archiveCurrentPC(reason){
 const ws = loadWorldState() || { totalDays: 0, knownNPCs: [] };
 // 暦を保存
 ws.totalDays = GAME_TIME.totalDays;
 // 生存中の仲間＋過去仲間を蓄積（重複排除）
 const currentParty = (PC.party||[]).filter(n => n.con > 0);
 currentParty.forEach(npc => {
 if(!ws.knownNPCs.find(k => k._npcId === npc._npcId)){
 ws.knownNPCs.push(JSON.parse(JSON.stringify(npc)));
 } else {
 const idx = ws.knownNPCs.findIndex(k => k._npcId === npc._npcId);
 ws.knownNPCs[idx] = JSON.parse(JSON.stringify(npc));
 }
 });
 ws.lastPCName = PC.name;
 ws.lastReason = reason;
 ws.lastTown = PC.town; // 後継者の初期滞在町に使う（前のキャラクターが最後にいた町）

 // 混沌の状態を保存
 if(PC._chaosNest) ws.chaosNest = JSON.parse(JSON.stringify(PC._chaosNest));
 // 飢饉の記録を保存
 if(PC._famineYear) ws.famineYear = PC._famineYear;
 if(PC._famineHeroName) ws.famineHeroName = PC._famineHeroName;
 // 地方英雄・各町英雄フラグを保存（噂話用）
 if(PC._heroRegions) ws.heroRegions = JSON.parse(JSON.stringify(PC._heroRegions));
 if(PC._heroTowns) ws.heroTowns = JSON.parse(JSON.stringify(PC._heroTowns));
 // 地方伝説の英雄（歴代）を保存。既存の記録を引き継ぎつつ、今回死亡した代がその地方の英雄なら記録を更新する
 ws.regionLegends = Object.assign({}, PC._regionLegends || {});
 if(reason === 'dead' && PC._heroRegions){
  Object.keys(PC._heroRegions).forEach(regionKey=>{
   if(PC._heroRegions[regionKey]){
    ws.regionLegends[regionKey] = { name: PC.name, deathDay: GAME_TIME.totalDays };
   }
  });
 }
 // 農業の豊凶状況を保存
 if(PC._harvestYear) ws.harvestYear = PC._harvestYear;
 if(PC._harvestResult) ws.harvestResult = PC._harvestResult;
 if(PC._foodPriceMult) ws.foodPriceMult = PC._foodPriceMult;
 if(PC._harvestPriceApplied) ws.harvestPriceApplied = PC._harvestPriceApplied; // 'retire' | 'dead'
 // 地方状態システム（物流途絶度・治安悪化度・住民流出度）を保存
 if(PC._regionCondition) ws.regionCondition = JSON.parse(JSON.stringify(PC._regionCondition));
 if(PC._regionConditionAmbient) ws.regionConditionAmbient = JSON.parse(JSON.stringify(PC._regionConditionAmbient));
 // 2026年10月4日：巣窟ダンジョン（全箇所）の状態を保存。世代交代しても「空／稼働中」の状態や
 // 次回再湧き予定日が引き継がれるようにする（これまでは保存されず、新しい代の最初のチェックで
 // 強制的にリセット＝即座に再湧きしてしまっていた）
 ws.lairDungeons = {};
 Object.entries(LAIR_DUNGEON_REG).forEach(([key, def])=>{
  if(PC[def.stateProp]) ws.lairDungeons[key] = JSON.parse(JSON.stringify(PC[def.stateProp]));
 });
 // 危機的状況からのPC主導の回復の記録（世界に残る記録なので世代交代しても引き継ぐ）
 if(PC._regionWasCrisis) ws.regionWasCrisis = JSON.parse(JSON.stringify(PC._regionWasCrisis));
 if(PC._regionCrisisRecord) ws.regionCrisisRecord = JSON.parse(JSON.stringify(PC._regionCrisisRecord));

 // 拠点をワールドステートに保存（既存データとマージ）
 if(PC.properties && Object.keys(PC.properties).length > 0){
  ws.properties = ws.properties || {};
  // 各拠点をマージ：現PCのデータを基本としつつ、既存wsの graves/graveyard/residents を保持
  Object.keys(PC.properties).forEach(townId=>{
   const curProp = JSON.parse(JSON.stringify(PC.properties[townId]));
   const wsProp  = ws.properties[townId] || {};
   // 墓地・住人は既存wsのデータと現PCのデータを合算
   curProp.graves    = mergeArray(wsProp.graves,    curProp.graves,    'name');
   curProp.graveyard = mergeArray(wsProp.graveyard, curProp.graveyard, 'name');
   curProp.residents = mergeArray(wsProp.residents, curProp.residents, 'name');
   ws.properties[townId] = curProp;
  });

  // 「拠点に住んで引退」の場合のみ住人として登録
  if(reason === 'retire_to_property'){
   const townIds = Object.keys(PC.properties);
   const mainTown = townIds.sort((a,b)=>(PC.properties[b]?.tier||0)-(PC.properties[a]?.tier||0))[0];
   console.log('[WS] retire_to_property mainTown=', mainTown, 'ws.properties[mainTown]=', !!ws.properties?.[mainTown]);
   if(mainTown && ws.properties[mainTown]){
    const prop = ws.properties[mainTown];
    prop.residents = prop.residents || [];
    if(!prop.residents.find(r=>r.name===PC.name)){
     const birthTotalDays = ((PC.birthYear||0) - (GAME_TIME.startYear||400)) * 365 + ((PC.birthMonth||1)-1)*30 + ((PC.birthDay||1)-1);
     const typeJa = {warrior:'戦士',rogue:'盗賊',wizard:'魔法使い'}[PC.type]||PC.type;
     const lifespanYears = PC.lifespan || (AGING_PARAMS[PC.race]||AGING_PARAMS.human).lifespan;
     const resident = { name: PC.name, race: PC.race, type: PC.type, typeJa, birthTotalDays, lifespanYears, retiredAge: PC.age||0, movedInDay: GAME_TIME.totalDays, retiredDay: GAME_TIME.totalDays, chr: PC.chr||10, lk: PC.lk||10 };
     prop.residents.push(resident);
     console.log('[WS] resident added:', JSON.stringify(resident));
    } else {
     console.log('[WS] resident already exists:', PC.name);
    }
   }
  }
 }

 saveWorldState(ws);
}

