function saveGame(){
 // スロット選択UIを表示してからセーブ
 showSaveSlotUI('save');
}

function _doSaveToSlot(slot){
 const data = {
  pc: JSON.parse(JSON.stringify(PC)),
  gameTime: JSON.parse(JSON.stringify(GAME_TIME)),
  nodeId: currentNodeId,
  savedAt: Date.now(),
 };
 localStorage.setItem(getSaveKey(slot), JSON.stringify(data));
 currentSaveSlot = slot;
 showSaveToast(` スロット${slot}にセーブしました`);
}

// セーブ/ロードでequippedWeapons/Armorsとinv側の参照が分離してしまう問題の修正
// （JSON化で「同じオブジェクトを指す」という関係が失われ、見た目上の複製が生まれるため、名前で結び付け直す）
function _reconcileEquipRefs(actor){
 if(!actor) return;
 const usedWIdx = new Set();
 (actor.equippedWeapons||[]).forEach(eq=>{
  if((actor.invWeapons||[]).includes(eq)){ usedWIdx.add((actor.invWeapons||[]).indexOf(eq)); return; }
  const idx = (actor.invWeapons||[]).findIndex((w,i)=>w.name===eq.name && !usedWIdx.has(i));
  if(idx>=0){ actor.invWeapons[idx] = eq; usedWIdx.add(idx); }
 });
 const usedAIdx = new Set();
 (actor.equippedArmors||[]).forEach(eq=>{
  if((actor.invArmors||[]).includes(eq)){ usedAIdx.add((actor.invArmors||[]).indexOf(eq)); return; }
  const idx = (actor.invArmors||[]).findIndex((a,i)=>a.name===eq.name && !usedAIdx.has(i));
  if(idx>=0){ actor.invArmors[idx] = eq; usedAIdx.add(idx); }
 });
}

function loadGame(slot){
 slot = slot || currentSaveSlot;
 const raw = localStorage.getItem(getSaveKey(slot));
 if(!raw) return;
 const data = JSON.parse(raw);
 currentSaveSlot = slot;
 // Object.assignは「上書きマージ」のため、ロード前のセッションに残っていたキーが
 // ロードするセーブデータに存在しない場合でもクリアされず残ってしまう。
 // 領地関連のフィールドはこれが原因で新旧データが混線しうるため、代入前に明示的にリセットする
 delete PC._fiefCharter;
 delete PC._fiefCharters;
 PC.properties = {}; // 拠点データもロード前のセッションの残留を防ぐため必ず空にリセットしてから代入する
 PC._tavernThanks = {}; // 酒場のお礼（受け取り待ち）も、ロード前のセッションの残留を防ぐためリセットしてから代入する
 PC._formerCompanions = []; // かつての仲間の名簿も、ロード前のセッションの残留を防ぐためリセットしてから代入する
 _fcVisitLastDay = null;     // 来訪判定の基準日も、ロード後の最初の判定で現在日に合わせ直す
 delete PC._wild; delete PC._wildMaps; delete PC._wildCamps; delete PC._wildCastles; delete PC._troupes; delete PC._troupeContract; delete PC._arcs; delete PC._arcLog; delete PC._arcEpilogues; delete PC._arcLastStart; delete PC._arcLastType; delete PC._arcSeeds; delete PC._arcLetters; delete PC._arcReunions; delete PC._arcTravelerDone; // 旅芸人の一座・護衛契約も、ロード前のセッションの残留を防ぐため消してから代入する
 Object.assign(PC, data.pc);
 Object.assign(GAME_TIME, data.gameTime);

 // 旧形式移行：invEquip内の松明を_torchStockに変換
 if(PC.invEquip){
  PC.invEquip = PC.invEquip.filter(name => {
   if(name === '松明'){ PC._torchStock = (PC._torchStock||0)+3; return false; }
   return true;
  });
 }
 if(PC._torchStock == null) PC._torchStock = 0;
 if(PC._torchTurns == null) PC._torchTurns = 0;
 // 呪文名・説明を最新定義と同期（セーブデータの名称が古い場合に対応）
 const allSpellDefs = [...(SPELLS_L1||[]),...(SPELLS_L2||[]),...(SPELLS_L3||[]),...(SPELLS_L4||[]),...(SPELLS_L5||[]),...(SPELLS_L6||[]),...(SPELLS_L7||[])];
 (PC.spells||[]).forEach(s=>{
  const def = allSpellDefs.find(d=>d.fn===s.fn);
  if(def){ s.name = def.name; s.desc = def.desc; }
 });
 (PC.party||[]).forEach(npc=>{
  (npc.spells||[]).forEach(s=>{
   const def = allSpellDefs.find(d=>d.fn===s.fn);
   if(def){ s.name = def.name; s.desc = def.desc; }
  });
 });
 // 旧データ移行：alignmentがなければランダム初期値を付与（保存データで判定）
 if(!('alignment_ethics' in data.pc)) PC.alignment_ethics = Math.floor((Math.random()-0.5)*60);
 if(!('alignment_order'  in data.pc)) PC.alignment_order  = Math.floor((Math.random()-0.5)*60);
 // 旧データ移行：魔法使いのPCがLv1呪文を1つも持っていなければ補う
 // （キャラ作成時の不具合で全滅していたケースの救済。既にunlockKnockKnock等を個別に持っていても重複しないようマージする）
 if(PC.type==='wizard'){
  PC.spells = PC.spells || [];
  const known = new Set(PC.spells.map(s=>s.name));
  SPELLS_L1.forEach(sp=>{ if(!known.has(sp.name)) PC.spells.push({...sp}); });
 }
 // 旧データ移行：領地の複数所有対応リファクタリング以前のセーブデータを新形式に変換する
 // （PC._fiefCharter単数オブジェクト → PC._fiefCharters配列／PC.properties.fief → PC.properties[fiefId]）
 _migrateFiefDataIfNeeded();
 // 旧データ移行：動機タグ導入以前のセーブデータに、タグ・固有データを逆引きで補完する
 _migrateBackgroundMotiveIfNeeded();
 // 装備参照の結び付け直し（セーブ/ロードで見た目上の複製が生まれる問題の修正）
 _reconcileEquipRefs(PC);
 (PC.party||[]).forEach(npc=>_reconcileEquipRefs(npc));
 // パーティNPCの旧データ移行
 (PC.party||[]).forEach((npc,i)=>{
  const saved = data.pc?.party?.[i];
  if(!saved || !('alignment_ethics' in saved)) npc.alignment_ethics = Math.floor((Math.random()-0.5)*60);
  if(!saved || !('alignment_order'  in saved)) npc.alignment_order  = Math.floor((Math.random()-0.5)*60);
  // 身長・体重がなければこの機会に決めてしまう（既存の仲間NPC向け）
  if(npc.height==null || npc.weight==null) Object.assign(npc, rollBodySize(npc.race));
  // 魔法使いNPCがLv1呪文を全種持っていなければ補う（Magic Boltのみだった旧仕様の救済）
  if(npc.type==='wizard'){
   npc.spells = npc.spells || [];
   const npcKnown = new Set(npc.spells.map(s=>s.name));
   SPELLS_L1.forEach(sp=>{ if(!npcKnown.has(sp.name)) npc.spells.push({...sp}); });
  }
 });
 // 拠点留守番NPCの旧データ移行
 Object.entries(PC.properties||{}).forEach(([tid, prop])=>{
  (prop.caretakers||[]).forEach((npc,i)=>{
   const saved = data.pc?.properties?.[tid]?.caretakers?.[i];
   if(!saved || !('alignment_ethics' in saved)) npc.alignment_ethics = Math.floor((Math.random()-0.5)*60);
   if(!saved || !('alignment_order'  in saved)) npc.alignment_order  = Math.floor((Math.random()-0.5)*60);
   if(npc.height==null || npc.weight==null) Object.assign(npc, rollBodySize(npc.race));
  });
 });
 ['title-screen','chargen','shop-area'].forEach(id=>{
  document.getElementById(id)?.classList.add('hidden');
 });
 // モバイルでステータスパネルが開いたまま残らないよう、ロード時に必ず閉じる
 if(window.innerWidth < 860) document.getElementById('inv-panel')?.classList.add('hidden');
 const g = document.getElementById('game');
 g.classList.remove('hidden'); g.style.display='flex';
 currentNodeId = data.nodeId || 'TOWN_KHAZAN';
 updateHUD(); updateTimebar();
 // 拠点画面・領地の広場は通常のノードシステムを経由しないため、専用のマーカーIDから復元する
 if(currentNodeId === 'FIEF_PLAZA' || (currentNodeId && currentNodeId.startsWith('FIEF_PLAZA_'))){
  // 'FIEF_PLAZA'（接尾辞なし）は複数領地対応前の旧マーカー。fiefIdが取れない場合は先頭の領地にフォールバックする
  const fiefId = currentNodeId.startsWith('FIEF_PLAZA_') ? currentNodeId.slice('FIEF_PLAZA_'.length).toLowerCase() : null;
  const charter = fiefId ? getFiefCharter(fiefId) : (PC._fiefCharters||[])[0];
  if(charter) showFiefPlaza(charter.anchorTownId);
  else go('TOWN_KHAZAN');
 } else if(currentNodeId && currentNodeId.startsWith('PROPERTY_')){
  let townId = currentNodeId.slice('PROPERTY_'.length).toLowerCase();
  // 'PROPERTY_FIEF'（複数領地対応前の旧マーカー）は先頭の領地のfiefIdに読み替える
  if(townId === 'fief'){
   const firstCharter = (PC._fiefCharters||[])[0];
   townId = firstCharter ? firstCharter.fiefId : null;
  }
  if(townId && isValidPropertyId(townId)) goPropertyNode(townId);
  else go('TOWN_KHAZAN');
 } else {
  go(currentNodeId);
 }
}

function deleteSave(slot){
 slot = slot || currentSaveSlot;
 if(!confirm(`スロット${slot}のデータを削除しますか？`)) return;
 localStorage.removeItem(getSaveKey(slot));
 showSaveToast(' 削除しました');
 checkSaveOnTitle();
}

function getSlotInfo(slot){
 const raw = localStorage.getItem(getSaveKey(slot));
 if(!raw) return null;
 try{
  const d = JSON.parse(raw);
  const dt = new Date(d.savedAt);
  const ts = `${dt.getMonth()+1}/${dt.getDate()} ${dt.getHours()}:${String(dt.getMinutes()).padStart(2,'0')}`;
  return { name:d.pc.name, race:d.pc.race, type:d.pc.type, level:d.pc.level, age:d.pc.age, ts, nodeId:d.nodeId };
 }catch(e){ return null; }
}

// 旧API互換（getSaveInfo → スロット1参照）
function getSaveInfo(){ return getSlotInfo(1) ? '(スロットあり)' : null; }

// ゲーム中のスロット選択UI（セーブ用）
function showSaveSlotUI(mode){
 // 既存パネルを削除
 const existing = document.getElementById('save-slot-panel');
 if(existing){ existing.remove(); return; }

 const panel = document.createElement('div');
 panel.id = 'save-slot-panel';
 panel.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:var(--info-bg);border:2px solid #484848;border-radius:6px;padding:16px;z-index:9998;min-width:260px;box-shadow:0 0 30px #000a';
 panel.innerHTML = `<div style="color:#e8e0d8;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 3px);margin-bottom:10px;text-align:center"> セーブスロット選択</div>`;

 const raceMap={human:'人間',elf:'エルフ',dwarf:'ドワーフ',halfling:'ハーフリング',fairy:'フェアリー',leprechaun:'レプラコーン',troll:'トロール',ogre:'オーガ',orc:'オーク',goblin:'ゴブリン'};
 const typeMap={warrior:'戦士',rogue:'盗賊',wizard:'魔法使い'};

 for(let s=1; s<=SAVE_SLOT_COUNT; s++){
  const info = getSlotInfo(s);
  const row = document.createElement('div');
  row.style.cssText = 'border:1px solid #484848;border-radius:3px;padding:8px;margin:4px 0;display:flex;align-items:center;gap:8px;cursor:pointer;background:var(--info-bg);';

  const isCurrent = s === currentSaveSlot;
  let slotLabel = `<span style="color:${isCurrent?'var(--nature2)':'var(--steel)'};font-size:calc(var(--font-sm) - 4px)">SLOT ${s}${isCurrent?' ':''}</span>`;
  let slotDesc = info
   ? `<span style="color:#ccc;font-size:calc(var(--font-sm) - 3px)">${info.name}</span> <span style="color:#e0d8c8;font-size:calc(var(--font-sm) - 4px)">${raceMap[info.race]||info.race} Lv${info.level} [${info.ts}]</span>`
   : `<span style="color:#c0b098;font-size:calc(var(--font-sm) - 3px)">── 空き ──</span>`;

  row.innerHTML = `<div style="flex:1">${slotLabel}<br>${slotDesc}</div>`;
  row.onclick = ()=>{
   if(mode === 'load'){
    if(!info){ return; }
    if(!confirm(`スロット${s}（${info.name}）をロードしますか？`)) return;
    panel.remove(); loadGame(s);
   } else {
    if(info){
     const slotName = info.name !== PC.name ? `スロット${s}（${info.name}）` : `スロット${s}`;
     if(!confirm(`${slotName}のデータに上書きしますか？`)) return;
    }
    panel.remove();
    _doSaveToSlot(s);
   }
  };
  panel.appendChild(row);
 }

 // 自動セーブスロット（ロード時のみ表示）
 if(mode === 'load'){
  const asRaw = localStorage.getItem(AUTOSAVE_KEY);
  if(asRaw){
   try{
    const asData = JSON.parse(asRaw);
    const asDate = new Date(asData.savedAt).toLocaleString('ja-JP',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
    const asName = asData.pc?.name || '?';
    const asRow = document.createElement('div');
    asRow.style.cssText = 'border:1px solid #585858;border-radius:3px;padding:8px;margin:4px 0;display:flex;align-items:center;gap:8px;cursor:pointer;background:var(--ink);';
    asRow.innerHTML = `<div style="flex:1"><span style="color:#f0ece0;font-size:calc(var(--font-sm) - 4px)">AUTO </span><br><span style="color:#ccc;font-size:calc(var(--font-sm) - 3px)">${asName}</span> <span style="color:#e0d8c8;font-size:calc(var(--font-sm) - 4px)">[${asDate}]</span></div>`;
    asRow.onclick = ()=>{
     if(!confirm(`自動セーブデータをロードしますか？`)) return;
     panel.remove(); loadAutoSave();
    };
    panel.appendChild(asRow);
   }catch(e){}
  }
 }

 const cancelBtn = document.createElement('button');
 cancelBtn.textContent = ' キャンセル';
 cancelBtn.style.cssText = 'margin-top:8px;width:100%;background:none;border:1px solid #334;color:#c0b098;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 4px);padding:6px;cursor:pointer;border-radius:3px';
 cancelBtn.onclick = ()=>panel.remove();
 panel.appendChild(cancelBtn);

 document.body.appendChild(panel);
}

