function troupePickEvent(mode, winter){
 const c = PC._troupeContract; if(!c) return null;
 troupeSafetyInit(c);
 const key = winter ? 'winter' : mode;
 const ids = Object.keys(TROUPE_EVENTS).filter(id=>TROUPE_EVENTS[id].modes.includes(key));
 let pool = ids.filter(id=>!c.eventLog.includes(id));
 if(!pool.length) pool = ids;
 if(!pool.length) return null;
 const danger = c.safety < 20;
 const w = id=>{
  const e = TROUPE_EVENTS[id];
  return e.weight * (danger ? (e.bad ? 1.5 : 0.5) : 1);
 };
 let total = pool.reduce((s,id)=>s+w(id), 0);
 let r = Math.random() * total;
 for(const id of pool){ r -= w(id); if(r <= 0) return id; }
 return pool[pool.length-1];
}
function troupeRunEvent(id, ctx){
 const c = ctx.c;
 troupeSafetyInit(c);
 c.eventLog = (c.eventLog||[]).concat([id]).slice(-3);
 troupeSafetyTick();
 TROUPE_EVENTS[id].run(ctx);
}

// travelTick から呼ぶ：今日が移動中のイベント日なら、イベントを始めてtrue
function troupeTravelEventTick(ts){
 if(!ts || !ts._troupeLeg || !ts._troupeEvDays) return false;
 const i = ts._troupeEvDays.indexOf(ts.daysDone);
 if(i < 0) return false;
 ts._troupeEvDays.splice(i, 1);
 const c = PC._troupeContract;
 const t = c && PC._troupes && PC._troupes[c.region];
 if(!t) return false;
 const id = troupePickEvent('travel', false);
 if(!id) return false;
 troupeRunEvent(id, troupeEvCtx('travel', t, ts, false));
 return true;
}

// 町への到着時：自然回復・公演の成功ぶんの回復、そして滞在イベントの判定。イベントを始めたらtrue
function troupeArrivalEvent(t){
 const c = PC._troupeContract;
 if(!c || !t.contract) return false;
 troupeSafetyInit(c);
 troupeSafetyTick();
 if(!t.winter) c.safety = Math.min(100, c.safety + 3);
 if(Math.random() >= TROUPE_STAY_EV_RATE) return false;
 const id = troupePickEvent('stay', t.winter);
 if(!id) return false;
 troupeRunEvent(id, troupeEvCtx('stay', t, null, t.winter));
 return true;
}

// ── デバッグ ──
function troupeDebugStatus(){
 troupeEnsure();
 const now = GAME_TIME.totalDays;
 const rows = TROUPE_REGIONS.map(rk=>{
  const t = PC._troupes[rk]; troupeCatchUp(t);
  const pos = t.phase === 'stay'
   ? `${troupeTownName(t.townId)}に滞在（${troupeDateLabel(t.arriveDay)}着→${troupeDateLabel(t.departDay)}発${t.winter?'・冬営':''}${t.recruiting?'・護衛募集中':''}）`
   : `${troupeTownName(t.fromTownId)}→${troupeTownName(t.nextTownId)}へ移動中（${troupeDateLabel(t.arriveDay)}着）`;
  return `${fcRegionName(rk)}『${t.name}』座長${t.leader}：${pos}${t.contract?'【護衛契約中】':''}`;
 });
 const c = PC._troupeContract;
 alert(rows.join('\n') + (c ? `\n\n契約：残り${c.endDay-now}日／給金${c.paidMonths}か月分支払済み／無事度${c.safety==null?100:c.safety}` : '\n\n契約：なし'));
}
// 現在地の地方の一座を、現在の町に呼ぶ（募集中・夏扱いの通常滞在にする）
function troupeDebugSummon(){
 troupeEnsure();
 const rk = getRegionKey(PC.town);
 const t = PC._troupes[rk];
 if(!t){ showSaveToast('この地方に一座はいません（マレア地方など）'); return null; }
 if(t.contract){ showSaveToast('すでに契約中です'); return t; }
 t.townId = PC.town; t.phase = 'stay'; t.arriveDay = GAME_TIME.totalDays;
 troupeRollStay(t);
 t.recruiting = true;
 return t;
}
function troupeDebugSafety(delta){
 const c = PC._troupeContract;
 if(!c){ showSaveToast('契約中ではありません'); return; }
 troupeSafetyInit(c);
 c.safety = delta === 'zero' ? 0 : Math.max(0, Math.min(100, c.safety + delta));
 showSaveToast('無事度：' + c.safety);
 if(c.safety <= 0){
  const t = PC._troupes[c.region];
  document.getElementById('debug-panel').style.display = 'none';
  troupeContractFail(troupeEvCtx('stay', t, null, false), '（デバッグ：無事度を0にした）');
 }
}
function troupeDebugEvent(){
 const c = PC._troupeContract;
 const t = c && PC._troupes[c.region];
 if(!t){ showSaveToast('契約中ではありません'); return; }
 const ids = Object.keys(TROUPE_EVENTS).filter(id=>TROUPE_EVENTS[id].modes.some(m=>m !== 'travel'));
 const id = prompt('町で発生させるイベントID：\n' + ids.join(' / '), ids[0]);
 if(!id || !TROUPE_EVENTS[id] || !ids.includes(id)){ showSaveToast('イベントIDが正しくありません'); return; }
 document.getElementById('debug-panel').style.display = 'none';
 troupeRunEvent(id, troupeEvCtx('stay', t, null, TROUPE_EVENTS[id].modes.includes('winter') && !TROUPE_EVENTS[id].modes.includes('stay')));
}
function troupeDebugContract(){
 const t = troupeDebugSummon();
 if(!t || t.contract) return;
 t.winter = false; t.departDay = GAME_TIME.totalDays + 3;
 troupeSignContract(PC.town, t);
}

