// 次の日送りを予約する（予約中かどうかをtravelState._tickPendingで持ち、旅が作り直された後の古い予約は無効にする）
function _travelTickSched(){
 const st = travelState;
 if(st) st._tickPending = true;
 return ()=>{ if(travelState !== st) return; travelTick(); };
}

// ══════════════════════════════════════════
// 連続クエスト（アーク）— 試作A「消えた隊商」
// 仕様：プロジェクトの「連続クエスト生成_設計案」
// ・入口は酒場の噂（客に話しかけたときの10%、同時進行は3本まで、同じ地方では1本まで）
// ・段階：①発端（酒場の噂）→②手がかり（生き残りに会う）→③現場（対決）→④決着（報告）
// ・段階の間に日数の窓（ready〜by）を置く。byを過ぎると、PCのいない間に「別の結末」で決着する（地方状態に影響）
// ・具体的な要素（商会名・生き残り・積み荷・真相・場所）は発端の時点で決めて PC._arcs に保存する（乱数の再現は不要）
// ・敵のLvは3〜5
// ・場面は各町の酒場メニューにボタンとして現れる（arcTavernChoices。fcTavernAskChoices から呼ぶ）
// ══════════════════════════════════════════
const ARC_MAX_ACTIVE = 3;
const ARC_RUMOR_CHANCE = 0.10;       // 酒場で客に話しかけたとき、噂が出る確率
const ARC_RUMOR_GAP_DAYS = 20;       // 前回の発端から最低この日数は空ける
const ARC_ENEMY_LV = [3, 5];
const ARC_EPILOGUE_KEEP_DAYS = 240;  // 後日譚の噂を酒場で聞ける期間
const ARC_CARGO = ['塩','絹織物','香辛料','鉄のインゴット','葡萄酒','毛皮','薬草','陶器','穀物','染料'];
const ARC_WITNESS_ROLES = ['生き残った御者','隊商の護衛','荷運びの少年','隊商に同行していた行商人'];
// 獣（魔獣）はNPC型ではなくCR（MR）型で扱う。出現する獣のCR合計＝目安レベル×100（目安レベル＝NPCを出す場合のレベル）
const ARC_BEASTS = [
 {name:'人食い熊',       min:50,  max:100, armor:2},
 {name:'トロル',         min:50,  max:150, armor:3},
 {name:'ミニドラゴン',   min:110, max:110, armor:4},
 {name:'グリフォン',     min:100, max:200, armor:2},
 {name:'マンティコア',   min:75,  max:150, armor:3},
 {name:'ヒドラ',         min:200, max:400, armor:4},
 {name:'ドラゴン',       min:300, max:500, armor:6},
];
const ARC_BEAST_MAX_COUNT = 4;
const ARC_BEAST_TOLERANCE = 30;   // 固定CRの獣で、合計が目標からずれてよい幅
const ARC_TRUTH_WEIGHTS = [['bandits', 5], ['monster', 3], ['staged', 2]];
const ARC_CLUE_SR = [
 {attr:'chr', level:2, label:'話を聞き出す',     btn:' 酒を勧めて、じっくりと話を聞き出す（魅力 Lv2）'},
 {attr:'iq',  level:2, label:'証言の食い違い',   btn:' 証言の食い違いを突いて、記憶をたどらせる（知力 Lv2）'},
 {attr:'lk',  level:2, label:'水を向ける',       btn:' ふと思い出すきっかけを狙って、水を向ける（運 Lv2）'},
];
// 結末ごとの地方状態への影響（deedの時点で適用する）
const ARC_REGION_FX = {
 bandits: { cleared:{unrest:-3}, left:{unrest:1.5}, lapsed:{unrest:3, logi:2} },
 monster: { cleared:{unrest:-2}, left:{unrest:1},   lapsed:{unrest:2, logi:2} },
 staged:  { cleared:{logi:-2},   left:{},           lapsed:{logi:1}, bought:{} },
};

function arcList(){ if(!Array.isArray(PC._arcs)) PC._arcs = []; return PC._arcs; }
function arcActive(){ return arcList().filter(a=>a.state === 'active'); }
function arcTown(id){ return (TOWNS[id] || {}).name || id; }
function arcRand(a, b){ return a + Math.floor(Math.random() * (b - a + 1)); }
function arcPick(arr){ return arr[Math.floor(Math.random() * arr.length)]; }
function arcWeighted(pairs){
 const total = pairs.reduce((t, p)=>t + p[1], 0);
 let r = Math.random() * total;
 for(const [k, w] of pairs){ if((r -= w) < 0) return k; }
 return pairs[0][0];
}
function arcFindById(id){ return arcList().find(a=>a.id === id) || null; }
function arcStory(html, replace){
 const el = document.getElementById('story');
 if(!el) return;
 if(replace){ el.innerHTML = html; return; }
 // 結果を続けて表示するとき、直前の「さて、どう探るか。」などの問いかけは消す（答えが出たあとに残らないように）
 el.innerHTML = el.innerHTML.replace(/(<br\s*\/?>\s*)*<span[^>]*>さて、(?:どう探るか|どうするか)。<\/span>/g, '') + html;
}
function arcHideDice(){ const d = document.getElementById('dice-area'); if(d) d.classList.add('hidden'); }

// 地方状態への加減（0〜100にクランプ。対象外の地方は何もしない）
function arcRegionShift(regionKey, fx){
 if(!regionKey || !REGION_CONDITION_SCOPE.includes(regionKey) || !fx) return;
 ensureRegionCondition();
 const c = PC._regionCondition[regionKey];
 const clamp = v => Math.max(0, Math.min(100, v));
 if(fx.unrest) c.unrest = clamp(c.unrest + fx.unrest);
 if(fx.logi)   c.logi   = clamp(c.logi   + fx.logi);
 if(fx.exodus) c.exodus = clamp(c.exodus + fx.exodus);
}

// ── 後日譚（酒場で聞ける噂）──
function arcEpilogueText(a, kind){
 if(a.type === 'runaway') return arcEEpilogueText(a, kind);
 if(a.type === 'bodyguard') return arcEpilogueTextD(a, kind);
 if(a.type === 'false_request') return arcEpilogueTextB(a, kind);
 if(a.type === 'stolen_goods') return arcEpilogueTextC(a, kind);
 const m = a.merchant + '商会';
 const T = {
  bandits: {
   cleared:`「${m}の隊商を襲った野盗どもが、片づけられたらしい。やったのは${PC.name}とかいう冒険者だそうだ。街道もだいぶ静かになった」`,
   left:   `「${m}の隊商の件、野盗の根城が分かったのに誰も手を出さなかったらしい。あの辺りはまだ物騒だぞ」`,
   lapsed: `「${m}の隊商の件は、結局うやむやになっちまった。あの街道、野盗の被害がまた出ているらしい。気をつけな」`,
  },
  monster: {
   cleared:`「${m}の隊商を襲った化け物が、退治されたらしい。やったのは${PC.name}とかいう冒険者だそうだ。これで山道も通れる」`,
   left:   `「${m}の隊商の件、化け物の巣が分かったのに、誰も手を出さなかったらしい。山道はまだ通れたもんじゃない」`,
   lapsed: `「${m}の隊商の件は、化け物の仕業だったって噂だ。誰も確かめに行かないまま、山道は通る者がいなくなった」`,
  },
  staged: {
   cleared:`「${m}の隊商の件、消えたのは隊商主の狂言だったそうだ。${PC.name}とかいう冒険者が積み荷を取り戻したらしい」`,
   bought: `「${m}の隊商の件は、行方知れずのままだとさ。……積み荷はどこかで売られてるって噂だがね」`,
   lapsed: `「${m}の隊商の件は、行方知れずのままだとさ。隊商主もろとも消えた、なんて話もある。商会は傾きかけてるらしい」`,
   left:   `「${m}の隊商の件は、行方知れずのままだとさ」`,
  },
 };
 return (T[a.truth] && T[a.truth][kind]) || T.bandits.lapsed;
}
function arcFinish(a, kind){
 a.state = 'done'; a.outcome = kind;
 const idx = arcList().indexOf(a);
 if(idx >= 0) arcList().splice(idx, 1);
 if(!Array.isArray(PC._arcLog)) PC._arcLog = [];
 PC._arcLog.push({type:a.type, truth:a.truth, kind, region:a.region, day:GAME_TIME.totalDays, merchant:a.merchant, depth:(a.chain && a.chain.depth) || 1});
 if(PC._arcLog.length > 30) PC._arcLog.shift();
 if(!Array.isArray(PC._arcEpilogues)) PC._arcEpilogues = [];
 PC._arcEpilogues.push({region:a.region, text:arcEpilogueText(a, kind), day:GAME_TIME.totalDays});
 if(PC._arcEpilogues.length > 8) PC._arcEpilogues.shift();
 if(a.type === 'bodyguard') arcDOnFinish(a, kind);
 if(a.type === 'runaway') arcEOnFinish(a, kind);
 arcMakeSeed(a, kind);   // 連なり：続編の種
}
// 期限切れ：PCのいない間に別の結末で決着する
function arcLapse(a){
 if(a.type === 'runaway'){ arcELapse(a); return; }
 if(a.type === 'bodyguard'){ arcLapseD(a); return; }
 if(a.type === 'false_request'){ arcLapseB(a); return; }
 if(a.type === 'stolen_goods'){ arcLapseC(a); return; }
 // すでに現場で決着をつけていた（報告だけ遅れた）なら、その結果を採用する
 const kind = (a.stage === 'report' && a.deed) ? a.deed : 'lapsed';
 if(kind === 'lapsed') arcRegionShift(a.region, (ARC_REGION_FX[a.truth] || {}).lapsed);
 arcFinish(a, kind);
}
function checkArcTick(){
 const now = GAME_TIME.totalDays;
 arcSeedClean();
 arcActive().forEach(a=>{ if(now > a.by) arcLapse(a); });
}
// 酒場の客の話から、後日譚の噂を聞く（聞いたら true）
function arcShowEpilogue(townId){
 if(!Array.isArray(PC._arcEpilogues) || !PC._arcEpilogues.length) return false;
 const now = GAME_TIME.totalDays;
 PC._arcEpilogues = PC._arcEpilogues.filter(e=>now - e.day <= ARC_EPILOGUE_KEEP_DAYS);
 const region = getRegionKey(townId);
 const i = PC._arcEpilogues.findIndex(e=>e.region === region && (!e.from || now >= e.from));
 if(i < 0) return false;
 if(!PC._arcEpilogues[i].must && Math.random() >= 0.5) return false;
 const e = PC._arcEpilogues.splice(i, 1)[0];
 if(e.life) addLifeEvent('', e.life);
 const header = e.master
  ? `<div style="font-size:calc(var(--font-sm) + 1px);color:#f0ece0;margin-bottom:8px"> 酒場の主人</div>
  <div style="font-size:var(--font-sm);color:#c8b8a0;line-height:1.8;margin-bottom:10px">主人は、あなたの顔を見るなり、声を落とした。</div>`
  : `<div style="font-size:calc(var(--font-sm) + 1px);color:#f0ece0;margin-bottom:8px"> 酒場の客</div>
  <div style="font-size:var(--font-sm);color:#c8b8a0;line-height:1.8;margin-bottom:10px">近くの席の客が、あの件について話している。</div>`;
 const msgBox = `<div style="font-size:var(--font-sm);color:#e0d8cc;line-height:1.8;padding:8px;background:#0a0804;border-radius:3px;border-left:2px solid var(--border)">${e.text}</div>`;
 _showPatronPanel(header + msgBox, ()=>{ updateHUD(); });
 return true;
}

// ── ①発端：酒場の噂 ──
function arcCreateLostCaravan(townId, forcedTruth){
 const region = getRegionKey(townId);
 const others = (REGIONS[region] || []).filter(t=>t !== townId);
 if(!others.length) return null;
 const now = GAME_TIME.totalDays;
 const pool = NPC_NAMES.slice();
 const takeName = ()=>pool.splice(Math.floor(Math.random() * pool.length), 1)[0];
 const merchant = takeName(), master = takeName(), wname = takeName();
 const ready = now + arcRand(30, 90);
 const a = {
  id: 'arc' + now + '_' + arcRand(1000, 9999),
  type: 'lost_caravan', state: 'active',
  truth: forcedTruth || arcWeighted(ARC_TRUTH_WEIGHTS),
  region, home: townId, witnessTown: arcPick(others),
  merchant, master,
  witness: {name: wname, role: arcPick(ARC_WITNESS_ROLES)},
  cargo: arcPick(ARC_CARGO), wagons: arcRand(2, 5), missing: arcRand(4, 9),
  stage: 'witness', startDay: now, ready, by: ready + arcRand(60, 100),
  clue: 0, siteDays: arcRand(2, 4), deed: null,
 };
 arcList().push(a);
 PC._arcLastStart = now;
 return a;
}
function arcRumorEligible(townId){
 const region = getRegionKey(townId);
 if(!region) return false;
 if(arcActive().length >= ARC_MAX_ACTIVE) return false;
 if(arcActive().some(a=>a.region === region)) return false;
 if(PC._arcLastStart != null && GAME_TIME.totalDays - PC._arcLastStart < ARC_RUMOR_GAP_DAYS) return false;
 return (REGIONS[region] || []).length >= 2;
}
function arcRumorPanel(a){
 if(a.type === 'runaway'){ arcERumorPanel(a); return; }
 if(a.type === 'bodyguard'){ arcRumorPanelD(a); return; }
 if(a.type === 'false_request'){ arcRumorPanelB(a); return; }
 if(a.type === 'stolen_goods'){ arcRumorPanelC(a); return; }
 const T = arcTown(a.home), W = arcTown(a.witnessTown);
 const header = arcRumorHeaderHtml();
 const text = `「${arcLeadText(a)}${a.merchant}商会の隊商が、${a.cargo}を積んで出たきり戻らないそうだ。荷馬車が${a.wagons}台、人も${a.missing}人。`
  + `${a.witness.role}の${a.witness.name}だけが命からがら逃げ延びて、いまは${W}で療養しているらしい。`
  + `怪我が癒えて、まともに話せるようになるまで、ひと月かふた月はかかるそうだがな。`
  + `……商会は、腕の立つ者に礼を出すと言っている。気になるなら、${W}の酒場を覗いてみるといい」`;
 const msgBox = `<div style="font-size:var(--font-sm);color:#e0d8cc;line-height:1.8;padding:8px;background:#0a0804;border-radius:3px;border-left:2px solid #553300">${text}</div>`;
 _showPatronPanel(header + msgBox, ()=>{ updateHUD(); });
}
// 酒場で客に話しかけたときに呼ぶ。噂を語ったら true
function arcTryRumor(townId, force){
 if(!force){
  if(Math.random() >= (arcDueSeed(townId) ? ARC_SEED_RUMOR_CHANCE : ARC_RUMOR_CHANCE)) return false;
  if(!arcRumorEligible(townId)) return false;
 }
 const a = arcCreateRandom(townId);
 if(!a) return false;
 arcRumorPanel(a);
 return true;
}

// ── 酒場メニューに出る場面ボタン ──
function arcEntryA(a){
 if(a.stage === 'witness') return {town:a.witnessTown, label:` 隊商の生き残り「${a.witness.name}」に会う（${a.merchant}商会の件）`};
 if(a.stage === 'site')    return {town:a.witnessTown, label:` 隊商が消えた現場へ向かう（${a.merchant}商会の件）`};
 return {town:a.home, label:` ${a.merchant}商会の使いと話す（隊商の件）`};
}

// ── 救出した人物のその後（後日譚の噂＋酒場での再会） ──
// 救出（rescue）の目標で助けた人物。すり替えの場合は、依頼人の言った人物とは別人で、ここで名前を決める
function arcDRescuee(a){
 if(a.truth !== 'swapped') return a.other;
 if(!a.rescuee){
  const ex = [a.other, a.npc1.name, a.npc2.name, a.patron];
  const pool = (typeof NPC_NAMES !== 'undefined' ? NPC_NAMES : ['旅人']).filter(n=>!ex.includes(n));
  a.rescuee = pool.length ? arcPick(pool) : '名もなき人';
 }
 return a.rescuee;
}
// 依頼人が人物を追っていた理由（すり替えの真相。動機ごと）
const ARC_D_RESCUEE_WHY = {
 金:'「あの人の商いの帳尻を、わたしは知っていた。……口を封じたかったのでしょう」',
 復讐:'「昔、あの人の身内に、取り返しのつかないことをした。それは事実です。……ただ、命で償うほどのことではなかった」',
 名誉:'「あの人の一族の恥を、わたしは見てしまった。それだけのことです」',
 信仰:'「あの人の信じるものに、わたしは背いた。……背いたつもりは、なかったのですが」',
 保身:'「あの人の過去の悪事を、わたしは知っている。それが、追われた理由です」',
 愛情:'「あの人の大切な人を、わたしは守れなかった。その恨みを、わたしが負っているのです」',
};
// 結末 → 人物の行く末（handed：依頼人の手に渡った／freed：逃げ延びた／safe：依頼人が捕まり、追われなくなった）
const ARC_D_RESCUE_FATE = {cleared:'handed', tolerated:'handed', proxy_done:'handed', proxy_chase:'handed', stopped:'handed', stopped_rough:'handed', blocked:'freed', unmet:'freed', exposed:'safe'};
function arcDRescueAfter(a, kind){
 if(a.goal !== 'rescue' || a.truth === 'traveler' || !a.goalDone) return;
 const fate = ARC_D_RESCUE_FATE[kind]; if(!fate) return;
 const now = GAME_TIME.totalDays, R = arcDRescuee(a), N = a.npc1.name, nm = PC.name, T = arcTown(a.town2);
 const swapped = a.truth === 'swapped';
 // ①後日譚の噂
 const text = ({
  handed: swapped
   ? `「${R}という人が、${N}の宿から連れ出されたそうだ。それきり、姿を見た者はいないらしい。……深く訊かないほうがいいんだろうな」`
   : `「${N}が捜していた${R}が、無事に戻ったそうだ。助け出したのは${nm}とかいう冒険者だと聞く。久しぶりに、いい話を聞いた気がするよ」`,
  freed:`「${R}という人が、${T}で見かけられたかと思えば、いつの間にか町から消えていたそうだ。追っ手の話も、ぱったり聞かなくなった。どこかで、静かに暮らしているのかもしれん」`,
  safe:`「${N}が連れて行かれて以来、${R}という人は、もう誰にも追われていないそうだ。……${nm}とかいう冒険者のおかげだと、本人は言っているらしい」`,
 })[fate];
 if(!Array.isArray(PC._arcEpilogues)) PC._arcEpilogues = [];
 PC._arcEpilogues.push({region:a.region, text, day:now, from:now + arcRand(10, 30)});
 if(PC._arcEpilogues.length > 8) PC._arcEpilogues.shift();
 // ②酒場での再会（逃げ延びた・追われなくなった・無事に戻った場合。すり替えで渡した場合は起きない）
 if(fate === 'handed' && swapped) return;
 if(!Array.isArray(PC._arcReunions)) PC._arcReunions = [];
 const from = now + arcRand(30, 70);
 PC._arcReunions.push({id:'rn' + now + '_' + arcRand(1000, 9999), name:R, town:a.town2, region:a.region, npc1:N, motive:a.npc1.motive, fate, swapped, dung:a.dung.name, from, by:from + 150});
 if(PC._arcReunions.length > 6) PC._arcReunions.shift();
}
function arcReunionChoices(townId){
 const now = GAME_TIME.totalDays, out = [];
 if(!Array.isArray(PC._arcReunions)) return out;
 PC._arcReunions = PC._arcReunions.filter(r=>now <= r.by);
 PC._arcReunions.forEach(r=>{
  if(r.town !== townId || now < r.from) return;
  const id = r.id;
  out.push({label:` 隅の席の${r.name}に声をかける`, fn:()=>arcReunion(id, currentNodeId)});
 });
 return out;
}
function arcReunion(id, back){
 const i = (PC._arcReunions || []).findIndex(r=>r.id === id);
 if(i < 0){ go(back); return; }
 const r = PC._arcReunions.splice(i, 1)[0];
 const R = r.name, N = r.npc1, nm = PC.name;
 const gift = arcRand(60, 140);
 const why = ARC_D_RESCUEE_WHY[r.motive] || '';
 let body;
 if(r.swapped && r.fate === 'freed'){
  body = `<span style="color:#e8e4d8">隅の席から、見覚えのある顔が、そっと手を上げた。${r.dung}で助けた、あの人だ。${R}は、すっかり血色を取り戻していた。</span><br><br>`
   + `<span style="color:#e8e4d8">「……あのときの礼を、ずっと言いたかった」。${R}は、深く頭を下げた。「${N}が、なぜわたしを追っていたのか。お話ししておきます」</span><br><br>`
   + `<span style="color:#c8b8d8">${why}</span><br><br>`
   + `<span style="color:#e8e4d8">「あなたが${N}の言うままに、わたしを渡していたら……。いえ、もう言うまい」。${R}は、小さな袋をあなたの前に置いた。「少ないが、礼です。受け取ってください。わたしは、もうこの町を出ます」</span>`;
 } else if(r.swapped){
  body = `<span style="color:#e8e4d8">隅の席から、見覚えのある顔が、そっと手を上げた。${r.dung}で助けた、あの人だ。${N}が捕まったと聞き、ようやく姿を現せたという。</span><br><br>`
   + `<span style="color:#e8e4d8">「${N}が、なぜわたしを追っていたのか。お話ししておきます」</span><br><br>`
   + `<span style="color:#c8b8d8">${why}</span><br><br>`
   + `<span style="color:#e8e4d8">「あなたが衛兵に訴えてくださったおかげで、わたしはもう、隠れなくていい」。${R}は、小さな袋をあなたの前に置いた。「少ないが、礼です。受け取ってください」</span>`;
 } else if(r.fate === 'freed'){
  body = `<span style="color:#e8e4d8">隅の席から、見覚えのある顔が、そっと手を上げた。${r.dung}で助けた${R}だ。あのあと、町を離れて暮らしていたという。</span><br><br>`
   + `<span style="color:#e8e4d8">「あのとき、あなたが連れ出してくれなければ、いまごろは……」。${R}は、言葉を詰まらせた。「どうしても、もう一度お礼を言いたくて。……少ないですが、受け取ってください」。小さな袋が、あなたの前に置かれた。</span>`;
 } else {
  body = `<span style="color:#e8e4d8">隅の席から、見覚えのある顔が、そっと手を上げた。${r.dung}で助けた${R}だ。${N}のもとへ戻れて、元気にしているという。</span><br><br>`
   + `<span style="color:#e8e4d8">「あのとき、あなたが来てくれなければ、いまごろは……」。${R}は、言葉を詰まらせた。「どうしても、もう一度お礼を言いたくて。……少ないですが、受け取ってください」。小さな袋が、あなたの前に置かれた。</span>`;
 }
 gainGP(gift); updateHUD();
 addLifeEvent('', `${R}と再会し、礼を受け取った。`);
 arcStory(arcHeader(`${R}との再会`) + body + `<br><br><span style="color:#ffcc88">礼として${gift}GPを受け取った。</span>`, true);
 renderChoices([{label:'▶ OK', fn:()=>go(back)}]);
 scrollToTop();
}

// 聞き込みに失敗したアーク（型E・C）：地方内の酒場で足取りを尋ねる。
// 終点の町なら必ず手がかりが得られる。ほかの町は1回ずつ・50%で「終点の町」の話が聞ける
function arcVagueAsk(id, townId, back){
 const a = arcFindById(id); if(!a){ go(back); return; }
 const E = arcTown(a.endTown);
 const isE = a.type === 'runaway';
 const what = isE ? `${a.holder.name}という${a.holder.role}` : `盗まれた${a.item.short}`;
 const AK = arcAsker(), W = AK.who;
 const head = arcHeader(`${arcTown(townId)}の酒場`);
 a._vagueAsked = a._vagueAsked || {};
 const here = townId === a.endTown;
 if(here || (!a._vagueAsked[townId] && Math.random() < 0.5)){
  a.vague = false;
  const tip = here
   ? (isE ? `${W}は少し考えてから、頷いた。「その${a.holder.role}なら、この町で見かけたという話を聞いた。……詳しいことは、もう少し調べてやろう」`
          : `${W}は少し考えてから、頷いた。「その手の荷なら、この町に運び込まれたという噂がある。……詳しいことは、もう少し調べてやろう」`)
   : (isE ? `${W}は、少し考えてから、思い出したように言った。「その${a.holder.role}なら、${E}で見かけたと、旅の者が話していたぞ」`
          : `${W}は、少し考えてから、思い出したように言った。「その手の荷なら、${E}へ運ばれたという話を聞いたことがある」`);
  arcStory(head + `<span style="color:#c0b098">${what}の足取りを、酒場で尋ねた。</span><br><br><span style="color:#e8e4d8">${tip}</span>`
   + (here ? '' : `<br><br><span style="color:#c0b098">${E}の酒場で、あらためて居場所を確かめよう。</span>`), true);
  if(here) arcENext('先へ進む', ()=>arcRun(a.id, back)); else arcEOk(back);
  return;
 }
 a._vagueAsked[townId] = true;
 arcStory(head + `<span style="color:#c0b098">${what}の足取りを、酒場で尋ねた。</span><br><br><span style="color:#e8e4d8">${W}は首を振った。「さあな。この町では、そんな話は聞かないが……ほかの町の酒場なら、何か知っているかもしれん」</span>`, true);
 arcEOk(back);
}
// 酒場の噂を語る相手（毎回、主人とは限らない）
const ARC_TELLERS = [
 {who:'酒場の主人', acts:['主人は、周りを気にしながら、身を寄せてきた。','主人は皿を拭く手を止めて、ひそひそと話し始めた。','主人は声を落として、グラスを磨く手を止めた。','主人はカウンター越しに身を乗り出し、声を潜めた。']},
 {who:'常連の客', acts:['隣に座った常連の客が、杯を傾けながら声を落とした。','顔なじみらしい常連の客が、ふと思い出したように話しかけてきた。']},
 {who:'給仕の女', acts:['酒を運んできた給仕の女が、盆を抱えたまま、そっと耳打ちしてきた。','空いた皿を下げに来た給仕の女が、辺りをうかがってから話しかけてきた。']},
 {who:'旅商人', acts:['隣の席の旅商人が、身を乗り出して、小声で話しかけてきた。','酒をあおっていた旅商人が、ふとこちらを向いて口を開いた。']},
];
function arcRumorHeaderHtml(){
 const t = ARC_TELLERS[Math.floor(Math.random() * ARC_TELLERS.length)];
 const act = t.acts[Math.floor(Math.random() * t.acts.length)];
 return `<div style="font-size:calc(var(--font-sm) + 1px);color:#f0ece0;margin-bottom:8px"> ${t.who}</div>\n  <div style="font-size:var(--font-sm);color:#c8b8a0;line-height:1.8;margin-bottom:10px">${act}</div>`;
}
function arcTavernChoices(townId){
 checkArcTick();
 const now = GAME_TIME.totalDays, out = [];
 arcActive().forEach(a=>{
  if(a.vague && (a.type === 'runaway' || a.type === 'stolen_goods')){
   // 聞き込みに失敗した：居場所の町が分かっていない。地方内のどの町の酒場でも尋ねられる
   if(now >= a.ready && (REGIONS[a.region] || []).includes(townId) && !(a._vagueAsked && a._vagueAsked[townId] && townId !== a.endTown)){
    const _id = a.id;
    out.push({label: a.type === 'runaway' ? ` 酒場で、${a.holder.name}の足取りを尋ねる（${arcEShort(a)}の件）` : ` 酒場で、盗まれた${a.item.short}の行方を尋ねる`,
     fn:()=>arcVagueAsk(_id, townId, currentNodeId)});
   }
   return;
  }
  const e = (a.type === 'runaway') ? arcEEntry(a) : (a.type === 'bodyguard') ? arcEntryD(a) : (a.type === 'false_request') ? arcEntryB(a) : (a.type === 'stolen_goods') ? arcEntryC(a) : arcEntryA(a);
  if(!e || e.town !== townId || now < a.ready) return;
  const id = a.id;
  out.push({label:e.label, fn:()=>arcRun(id, currentNodeId)});
  if(a.type === 'bodyguard' && a.stage === 'night') out.push({label:` ${a.npc2.name}に話しかける（${a.npc2.skill}）`, fn:()=>arcDTalkP(id, currentNodeId)});
 });
 return out;
}
function arcRun(id, back){
 const a = arcFindById(id);
 if(!a || a.state !== 'active'){ go(back); return; }
 if(a.type === 'runaway'){ arcERun(a, back); return; }
 if(a.type === 'bodyguard'){ arcRunD(a, back); return; }
 if(a.type === 'false_request'){ arcRunB(a, back); return; }
 if(a.type === 'stolen_goods'){ arcRunC(a, back); return; }
 if(a.stage === 'witness') arcSceneWitness(a, back);
 else if(a.stage === 'site') arcSceneSite(a, back);
 else arcSceneReport(a, back);
}
function arcHeader(text){
 return `<span style="color:#e0d8c8">${text}</span><br><br>`;
}

// ── ②手がかり：生き残りに会う ──
function arcTestimony(a){
 const W = a.witness.name, M = a.master;
 const strong = {
  bandits:`「日暮れの街道で、覆面の男たちに囲まれたんだ。御者が弓で射られて、荷は全部持っていかれた。連中は街道から外れた岩場の野営地に潜んでいる。頭目らしい大男の声は、忘れられない」`,
  monster:`「あれは人間じゃない。闇の中で、巨大な影が荷馬車ごと引きずっていった。叫び声が、山裾の洞窟のほうへ遠ざかっていくのを聞いた。……あそこには近づかないほうがいい」`,
  staged: `「おかしいんだ。襲われたとき、隊商主の${M}さんだけは少しも慌てていなかった。荷の積み替えも、俺たちを先に行かせたのも、あの人だ。……あの人は、最初から知っていたんじゃないか。街道から外れた小屋に、馬車を隠せる場所がある」`,
 };
 const weak = `「ほとんど覚えていないんだ……夜だった。いきなり叫び声がして、気がついたら林の中で倒れていた。だが、荷馬車が街道から外れて消えた方角だけは覚えている」`;
 return a.clue >= 2 ? strong[a.truth] : weak;
}
