// 通常の旅と同じ旅画面（進捗バー・道中の遭遇・イベント・食料消費）で、現場や帰路を移動する
function arcTravelDays(a){
 let days = a.siteDays;
 const wp = checkWeightPenalty();
 if(wp && wp.over) days *= 2;    // 徒歩で重量オーバーなら2倍
 return days;
}
function arcTravel(destLabel, days, arriveLabel, onArrive){
 const from = TOWNS[PC.town] || {name:PC.town};
 drawScene('travel');
 showTravelImage('walk', PC.town, PC.town);   // 目的地は町ではないので、いまの町の地方の雰囲気を使う
 const storyEl = document.getElementById('story');
 if(storyEl) storyEl.innerHTML = '';
 const tpw = document.getElementById('travel-progress-wrap');
 if(tpw){
  tpw.style.display = '';
  document.getElementById('travel-progress-bar').style.width = '0%';
  document.getElementById('travel-progress-dot').style.left = '0%';
  document.getElementById('travel-latest').textContent = '';
  document.getElementById('travel-progress-label').innerHTML =
   ` 徒歩　<span style="color:#f0ece0">${from.name}</span> → <span style="color:#f0ece0">${destLabel}</span>　<span id="travel-day-count" style="color:#e0d8c8">0/${days}日</span>`;
 }
 renderChoices([]);
 advanceDaysAnimated(days, onArrive);
 if(travelState){
  travelState.method = 'walk'; travelState.crossRegion = false;
  travelState.destLabel = destLabel; travelState.arriveLabel = arriveLabel;
 }
 travelLog(`<span style="color:#b8a890">徒歩で <span style="color:#f0ece0">${from.name}</span> → <span style="color:#f0ece0">${destLabel}</span> へ出発。所要: ${days}日　費用: 0GP</span>`);
}
function arcSiteGo(id, back){
 const a = arcFindById(id);
 if(!a){ go(back); return; }
 arcTravel('隊商が消えた現場', arcTravelDays(a), ' 現場の様子を確かめる', ()=>arcSiteArrive(id, back));
}
// 現場の決着のあと、同じ旅画面で町へ帰る
