const FC_TAVERN_HEADER = '<span style="color:#e0d8c8">酒場の主人</span><br><br>';

function fcAskTavernMenu(townId, backNode){
 const story = document.getElementById('story');
 const targets = (PC._formerCompanions||[]).filter(fcSearchable);
 if(!targets.length){
  if(story) story.innerHTML = FC_TAVERN_HEADER + '<span style="color:#c0b098">尋ねるべき相手は、もういないようだ。</span>';
  renderChoices([{label:'← 戻る', fn:()=>go(backNode)}]);
  return;
 }
 if(story) story.innerHTML = FC_TAVERN_HEADER
  + `<span style="color:#c0b098">主人はグラスを磨く手を止め、こちらの顔を見た。</span><br><br>`
  + `<span style="color:#e0d8c8">「誰か探してるのか。情報料は${FC_SEARCH_FEE_GP}GPだ。聞いてやるだけで、見つかる保証はしないぞ」</span><br><br>`
  + `<span style="color:#a8a090;font-size:var(--font-sm)">所持金：${PC.gold||0}GP</span>`;
 const choices = targets.map(n=>{
  const hint = fcKnownRegionActive(n) ? `（${fcRegionName(n._knownRegion)}にいるらしい）` : '';
  return {label:` ${n.name}について尋ねる${hint}`, fn:()=>fcAskTavernExec(townId, n._npcId, backNode)};
 });
 choices.push({label:'← 戻る', fn:()=>go(backNode)});
 renderChoices(choices);
 scrollToTop();
}

function fcAskTavernExec(townId, npcId, backNode){
 const story = document.getElementById('story');
 const npc = (PC._formerCompanions||[]).find(n=>n._npcId===npcId);
 if(!npc || !fcSearchable(npc)){ fcAskTavernMenu(townId, backNode); return; }
 const now = GAME_TIME.totalDays;
 npc._searchedAt = npc._searchedAt || {};
 const last = npc._searchedAt[townId];
 if(last != null && now - last < FC_SEARCH_COOLDOWN_DAYS){
  if(story) story.innerHTML = FC_TAVERN_HEADER + `<span style="color:#e0d8c8">「さっき聞かれたばかりだろう。何か分かったら教えてやるから、また来てくれ」</span>`;
  renderChoices([{label:'← 戻る', fn:()=>fcAskTavernMenu(townId, backNode)}]);
  return;
 }
 if((PC.gold||0) < FC_SEARCH_FEE_GP){
  showSaveToast(`お金が足りない（情報料${FC_SEARCH_FEE_GP}GP必要）`);
  return;
 }
 PC.gold -= FC_SEARCH_FEE_GP;
 updateHUD();
 npc._searchedAt[townId] = now;
 fcEnsureWhereabouts(npc);
 catchUpFormerCompanion(npc);
 const actual = fcActualTown(npc);
 const dist = getRegionDistance(getRegionKey(townId), getRegionKey(actual));
 const level = 1 + Math.min(dist, 3);
 if(story) story.innerHTML = FC_TAVERN_HEADER
  + `<span style="color:#c0b098">${FC_SEARCH_FEE_GP}GPを渡して、${npc.name}の行方を尋ねた。主人は常連たちに声をかけ、顔の広い者を当たってくれている……</span>`;
 setupSavingRoll({
  attr:'lk', level, noAP:true, // 情報を買うだけなので経験値は入れない
  onSuccess:()=>fcAskTavernResult(townId, npc, actual, true, backNode),
  onFail:()=>fcAskTavernResult(townId, npc, actual, false, backNode),
 });
 renderChoices([]);
 scrollToTop();
}

function fcAskTavernResult(townId, npc, actual, ok, backNode){
 const story = document.getElementById('story');
 const back = [{label:'← 酒場に戻る', fn:()=>go(backNode)}];
 if(!ok){
  if(story) story.innerHTML = FC_TAVERN_HEADER + `<span style="color:#e0d8c8">「……すまんな、聞かない名だ」</span><br><br><span class="dim" style="font-size:var(--font-sm)">情報料は戻らない。</span>`;
  renderChoices(back);
  return;
 }
 const sameRegion = getRegionKey(townId) === getRegionKey(actual);
 if(sameRegion){
  if(npc._itinerant){
   npc._lastSeen = { town:actual, untilDay:npc._roamUntilDay, seenDay:GAME_TIME.totalDays };
  } else {
   npc.settledTown = actual;
  }
  npc._knownRegion = null; npc._knownRegionUntil = null;
  addLifeEvent('', `酒場で、${npc.name}は${fcTownName(actual)}にいるらしいと聞いた。`);
  if(story) story.innerHTML = FC_TAVERN_HEADER + `<span style="color:#e0d8c8">「ああ、その名なら覚えている。${fcTownName(actual)}にいると聞いたぞ」</span><br><br><span style="color:#f0ece0">${npc.name}の居場所が分かった：${fcTownName(actual)}</span>`;
 } else {
  const regionKey = getRegionKey(actual);
  npc._knownRegion = regionKey;
  npc._knownRegionUntil = npc._itinerant ? npc._roamUntilDay : null;
  addLifeEvent('', `酒場で、${npc.name}は${fcRegionName(regionKey)}にいるらしいと聞いた。`);
  if(story) story.innerHTML = FC_TAVERN_HEADER + `<span style="color:#e0d8c8">「この辺りでは見かけないが、${fcRegionName(regionKey)}でそれらしい人物を見たという話は聞いた」</span><br><br><span style="color:#f0ece0">${npc.name}は${fcRegionName(regionKey)}にいるらしい。その地方の酒場で尋ねれば、町まで分かるかもしれない。</span>`;
 }
 renderChoices(back);
}

// 放浪中の者に、居場所を聞いた町の酒場で会う
function visitRoamingCompanion(townId, npcId){
 const story = document.getElementById('story');
 const npc = (PC._formerCompanions||[]).find(n=>n._npcId===npcId);
 const townName = fcTownName(townId);
 const back = [{label:'← 戻る', fn:()=>goOtherActions(townId)}];
 if(!npc || npc._dead || !npc._lastSeen || npc._lastSeen.town !== townId){
  if(story) story.innerHTML = ` <span style="color:#e0d8c8">${townName}の酒場</span><br><br><span style="color:#c0b098">探してみたが、それらしい人物は見つからなかった。</span>`;
  renderChoices(back);
  return;
 }
 if(GAME_TIME.totalDays >= npc._lastSeen.untilDay){
  npc._lastSeen = null; npc._knownRegion = null; npc._knownRegionUntil = null;
  if(story) story.innerHTML = ` <span style="color:#e0d8c8">${townName}の酒場</span><br><br><span style="color:#c0b098">酒場の主人に${npc.name}のことを尋ねると、「ああ、あの人ならもう発ったよ。行き先までは分からんがね」と肩をすくめた。</span><br><br><span style="color:#a8a090;font-size:var(--font-sm)">間に合わなかったようだ。もう一度、酒場で消息を尋ねてみよう。</span>`;
  renderChoices(back);
  return;
 }
 ensureFormerChildReady(npc);
 catchUpFormerCompanion(npc);
 const roamHtml = ` <span style="color:#e0d8c8">${townName}の酒場</span><br><br>`
  + `<span style="color:#c0b098">酒場の片隅で、${npc.name}が一人で酒を飲んでいた。声をかけると、顔を上げて笑った。</span><br><br>`
  + `<span style="color:#c0b098">${formerCompanionVisitLine(npc, {noChild:true})}</span>`;
 const finish = (h, blocked)=>{
 if(story) story.innerHTML = h;
 const choices = [];
 if(!blocked && (PC.party||[]).length < 3){
  choices.push({label:` ${npc.name}を${npc.isChild?'':'再び'}仲間に加える`, fn:()=>{
   const idx = (PC._formerCompanions||[]).indexOf(npc);
   if(idx !== -1) PC._formerCompanions.splice(idx,1);
   const member = {...npc, trust:npc.trust||0, joinDay:GAME_TIME.totalDays};
   fcClearTracking(member);
   if(npc.isChild) outfitFormerChildLikeGeneralNPC(member);
   PC.party = PC.party||[];
   PC.party.push(member);
   addLifeEvent('', `${npc.name}が${npc.isChild?'':'再び'}パーティに加わった（${({warrior:'戦士',rogue:'盗賊',wizard:'魔法使い'})[npc.type]||npc.type}・${npc.race}）。`);
   updateHUD();
   const s2 = document.getElementById('story');
   if(s2) s2.innerHTML = ` <span style="color:#e0d8c8">${townName}の酒場</span><br><br><span style="color:#f0ece0">${npc.name}が${npc.isChild?'':'再び'}パーティに加わった！</span>`;
   renderChoices([{label:'← 戻る', fn:()=>goOtherActions(townId)}]);
  }});
 }
 choices.push({label:(PC.party||[]).length >= 3 ? 'パーティが満員なので見送る' : 'そのまま別れる', fn:()=>goOtherActions(townId)});
 renderChoices(choices);
 };
 // こちらから会いに行った場合も、相手が質問を投げかけてくる（同じ人とは30日に1回まで）
 const nowDay = GAME_TIME.totalDays;
 if(npc._talkedDay != null && nowDay - npc._talkedDay < FC_CALL_TALK_INTERVAL_DAYS){ finish(roamHtml, false); return; }
 npc._talkedDay = nowDay;
 fcRunQuestion(npc, fcCallKind(npc), roamHtml, true, (h, flag)=>{
  if(flag === 'e'){
   if(story) story.innerHTML = h;
   renderChoices([{label:'← 戻る', fn:()=>goOtherActions(townId)}]);
   return;
  }
  finish(h, flag === 'n');
 });
}

// ══════════════════════════════════════════
// 元仲間の来訪（別れた仲間が、プレイヤーを探して訪ねてくる）
// 仕様：claude/元仲間の来訪仕様案.md
// 保存データはすべて名簿エントリの中（_visit / _lastVisitDay / _letter）に持たせる。
// ══════════════════════════════════════════
const FC_VISIT_RATE_PER_DAY = 0.0015;   // 1人あたりの来訪決心の確率（日）
const FC_VISIT_MIN_PARTED_DAYS = 90;    // 別れてからこの日数が経つまでは訪ねない
const FC_VISIT_COOLDOWN_DAYS = 365;     // 同じ人が再び訪ねるまでの間隔
const FC_VISIT_WAIT_DAYS = 60;          // 到着後、この日数会えなければ手紙を残して去る
const FC_VISIT_GIFT_GP = 20;            // 祝儀の額
let _fcVisitLastDay = null;             // 来訪判定を最後に行った日（セーブしない。読み込み時に初期化）

function fcVisitKind(npc){
 if(npc.isChild) return 'child';
 switch(npc.leaveReason){
  case 'marriage_age': case 'party_marriage': return 'report';
  case 'independence': case 'apprenticeship': case 'ideal_partner': return Math.random() < 0.5 ? 'report' : 'offer';
  case 'dissatisfaction': case 'property_unpaid': return 'reconcile';
  default: return 'report';
 }
}

// 来訪の予約が入ってから到着するまでの日数（本人の居場所とプレイヤーの地方の距離で決まる）
function fcVisitDelay(npc){
 let dist = 1;
 try{
  const loc = npc.settledTown || (npc._lastSeen && npc._lastSeen.town) || npc._hiddenTown || null;
  if(loc && PC.town){
   const d = getRegionDistance(getRegionKey(PC.town), getRegionKey(loc));
   if(isFinite(d)) dist = Math.min(3, d);
  }
 }catch(e){}
 return dist * 3 + 1 + Math.floor(Math.random()*3);
}

function fcVisitEligible(npc, now){
 if(npc._dead || npc._visit || npc._letter) return false;
 if(!formerCompanionReunionEligible(npc)) return false;
 if(now - (npc._leftPartyDay ?? now) < FC_VISIT_MIN_PARTED_DAYS) return false;
 if(npc._lastVisitDay != null && now - npc._lastVisitDay < FC_VISIT_COOLDOWN_DAYS) return false;
 return true;
}

// 期限切れの予約は手紙に変える。故人の予約・手紙は消す
function fcVisitSweep(){
 const now = GAME_TIME.totalDays;
 (PC._formerCompanions||[]).forEach(n=>{
  if(n._dead){ delete n._visit; delete n._letter; return; }
  if(n._visit && now > n._visit.expireDay){
   n._letter = { kind:n._visit.kind, day:now };
   delete n._visit;
  }
 });
}

// 時間が進むたびに呼ぶ（checkAging経由）。経過日数ぶんをまとめて判定し、当たった1人だけ予約する
function fcVisitTick(){
 arcLetterTick();
 const now = GAME_TIME.totalDays;
 if(_fcVisitLastDay == null || now < _fcVisitLastDay){ _fcVisitLastDay = now; return; }
 const elapsed = Math.min(now - _fcVisitLastDay, 3650);
 _fcVisitLastDay = now;
 fcVisitSweep();
 if(elapsed <= 0) return;
 const list = PC._formerCompanions || [];
 if(!list.length || list.some(n=>n._visit && !n._dead)) return; // 同時の予約は1件まで
 const cands = list.filter(n=>fcVisitEligible(n, now));
 for(let i = cands.length - 1; i > 0; i--){ const j = Math.floor(Math.random()*(i+1)); [cands[i], cands[j]] = [cands[j], cands[i]]; }
 for(const npc of cands){
  const parted = now - (npc._leftPartyDay ?? now);
  const kind = fcVisitKind(npc);
  let pd = FC_VISIT_RATE_PER_DAY;
  if(kind === 'report' || kind === 'offer') pd *= 0.5 + Math.max(0, Math.min(100, npc.trust || 0)) / 100; // 信頼度が高いほど訪ねやすい
  if(parted > 5*365) pd *= 0.5;
  const p = 1 - Math.pow(1 - pd, elapsed);
  if(Math.random() < p){
   const ready = now + fcVisitDelay(npc);
   npc._visit = { kind, readyDay:ready, expireDay:ready + FC_VISIT_WAIT_DAYS };
   npc._lastVisitDay = now;
   return;
  }
 }
}

// 今、出会いの時を迎えている来訪者
function fcVisitFind(){
 const now = GAME_TIME.totalDays;
 return (PC._formerCompanions||[]).find(n=>!n._dead && n._visit && now >= n._visit.readyDay && now <= n._visit.expireDay) || null;
}
function fcLetterEntries(){ return (PC._formerCompanions||[]).filter(n=>!n._dead && n._letter); }

// 来訪をきっかけに、居場所が分かっていなければ分かるようにする。表示用のHTMLを返す
function fcVisitReveal(npc){
 if(npc.settledTown || fcLastSeenActive(npc)) return '';
 fcEnsureWhereabouts(npc);
 const actual = fcActualTown(npc);
 if(npc._itinerant) return `<br><br><span style="color:#a8a090;font-size:var(--font-sm)">${npc.name}には決まった住まいがなく、あちこちを回っているという。</span>`;
 npc.settledTown = actual;
 npc._knownRegion = null; npc._knownRegionUntil = null;
 addLifeEvent('', `${npc.name}は今、${fcTownName(actual)}で暮らしているという。`);
 return `<br><br><span style="color:#f0ece0">${npc.name}は今、${fcTownName(actual)}で暮らしているという。（居場所が分かった）</span>`;
}

function fcVisitBodyLines(npc, kind){
 const n = PC.name;
 const r = npc.leaveReason;
 if(kind === 'child'){
  return pick([
   `「……${n}。ずっと、会いたかったんだ」と、少し照れくさそうに言った。`,
   `「${n}、探したよ。立派になったでしょう？　今の暮らしぶりを、見てもらいたくて来たんだ」`,
   `「家を出てから、いろいろあってね。でも、どうしても顔を見ておきたかった」`,
  ]);
 }
 if(kind === 'reconcile'){
  return pick([
   `「${n}、あの時は言い過ぎた。ずっと気になっていたんだ。……詫びたくて来た」`,
   `「時間が経って、ようやく分かったことがある。あの頃のことを、直接謝りたくてな」`,
   `「あんたのことを、悪く言うつもりはもうないんだ。……もう一度、話をさせてくれないか」`,
  ]);
 }
 if(kind === 'offer'){
  const lead = r === 'independence' ? `「自分の隊を率いてみたが、人が足りなくてね。やはり、あんたと組んでいた頃が一番だった」`
   : r === 'apprenticeship' ? `「修行が一区切りついたんだ。師匠にも『外の世界を見てこい』と言われてね」`
   : r === 'ideal_partner' ? `「結局、理想の相手なんて見つからなかったよ。……笑ってくれ」`
   : `「いろいろ考えたんだが、あんたの隊が懐かしくなってね」`;
  return lead + `<br><span style="color:#c0b098">「${n}、もう一度、仲間に入れてくれないか」</span>`;
 }
 // report
 if(r === 'ideal_partner'){
  return pick([
   `「${n}、聞いてくれ！　ついに理想の相手を見つけたんだ。真っ先に知らせたくてね」`,
   `「${n}か！　長い旅だったが、探していた相手に出会えたよ。それを伝えに来た」`,
  ]);
 }
 return formerCompanionVisitLine(npc, {});
}

function fcVisitJoin(npc, kind){
 const list = PC._formerCompanions || [];
 const idx = list.indexOf(npc);
 if(idx !== -1) list.splice(idx, 1);
 const member = {...npc, trust:npc.trust||0, joinDay:GAME_TIME.totalDays};
 fcClearTracking(member);
 if(kind === 'reconcile') member.trust = Math.max(member.trust, 30); // 和解を経ての再加入
 if(npc.isChild) outfitFormerChildLikeGeneralNPC(member);
 PC.party = PC.party || [];
 PC.party.push(member);
 addLifeEvent('', `${npc.name}が${npc.isChild?'':'再び'}パーティに加わった（${({warrior:'戦士',rogue:'盗賊',wizard:'魔法使い'})[npc.type]||npc.type}・${npc.race}）。`);
 updateHUD();
}

