function applyInjury(injury){
 const effects = [];
 (injury.stats||[]).forEach(stat=>{
  const n = Nd6(2);
  const before = PC[stat];
  PC[stat] = Math.max(1, Math.floor(before / n));
  effects.push({stat, n, before, after:PC[stat]});
 });
 if(injury.noHeavyWeapon) PC._noHeavyWeapon = true;
 if(injury.deathKnellPanic) PC._deathKnellPanic = true;
 PC._injuries = PC._injuries || [];
 PC._injuries.push({id:injury.id, name:injury.name, flavor:injury.flavor, effects});
 return effects;
}

// 体力0到達時に呼ぶ。運11以上ならtrueを返し選択肢を表示する（呼び出し元は通常の死亡処理をせず、ここに処理を委ねる）。
// 運が0（あるいはそれ以下）なら発動しない。呼び出し元はこれまで通り死亡処理を行う。
function offerLuckSave(enemyName){
 if((PC.lk||0) <= 0) return false;
 const area = document.getElementById('cbt-ok-area');
 if(!area) return false;
 const luckCost = Math.max(1, (PC.level||1) * 2);
 // 戦闘中の行動選択パネル（戦う／様子を見る／逃走等）が出ていれば消しておく
 const actionPanel = document.getElementById('npc-action-panel');
 const actionTitle  = document.getElementById('npc-action-title');
 const actionBtns   = document.getElementById('npc-action-btns');
 if(actionTitle) actionTitle.innerHTML = '';
 if(actionBtns)  actionBtns.innerHTML = '';
 if(actionPanel) actionPanel.style.display = 'none';
 const cl = document.getElementById('clog');
 area.innerHTML = '';
 const msg = document.createElement('div');
 msg.style.cssText = 'color:#e0d0d0;font-size:var(--font-sm);margin-bottom:10px;text-align:center';
 msg.textContent = '死の淵で、何かが体を引き戻そうとしている……';
 area.appendChild(msg);
 const willSurvive = (PC.lk - luckCost) > 0;
 const saveBtn = document.createElement('button');
 saveBtn.className = 'choice-btn';
 saveBtn.style.cssText = willSurvive
  ? 'width:100%;margin-bottom:8px;background:#150f06;border-color:#b0a080;color:#f0ece0'
  : 'width:100%;margin-bottom:8px;background:#150f06;border-color:#663322;color:#cc8866';
 saveBtn.textContent = willSurvive
  ? `▶ 運を${luckCost}消費して生き延びる（運 ${PC.lk} → ${PC.lk-luckCost}）`
  : `▶ 残る運${PC.lk}を全て賭ける（届かなければ、それが最期になる）`;
 saveBtn.onclick = ()=>{
  area.innerHTML=''; area.style.display='none';
  startLuckSaveSequence(enemyName);
 };
 area.appendChild(saveBtn);

 const dieBtn = document.createElement('button');
 dieBtn.className = 'choice-btn';
 dieBtn.style.cssText = 'width:100%;background:#150f06;border-color:#663322;color:#cc8866';
 dieBtn.textContent = '▶ このまま力尽きる';
 dieBtn.onclick = ()=>{
  area.innerHTML=''; area.style.display='none';
  go((cbtState && cbtState.lose) || 'DEAD');
 };
 area.appendChild(dieBtn);

 area.style.display = 'block';
 if(cl) cl.scrollTop = 9999;
 return true;
}

function startLuckSaveSequence(enemyName){
 const luckCost = Math.max(1, (PC.level||1) * 2);
 PC.lk = (PC.lk||0) - luckCost;
 if(PC.lk <= 0){
  // 運を使い果たした——最後の運も尽き、その場で力尽きる
  PC.lk = 0;
  const _onLose = cbtState && cbtState.onLose;
  const loseNode = (cbtState && cbtState.lose) || 'DEAD';
  cbtState = null;
  const cbtArea = document.getElementById('cbt-area');
  if(cbtArea) cbtArea.classList.add('hidden');
  const scrollArea = document.getElementById('scroll-area');
  if(scrollArea) scrollArea.classList.remove('in-combat');
  const textWin = document.getElementById('text-win');
  if(textWin) textWin.style.display = '';
  hideTravelImage();
  hideTravelProgress();
  hideDungeonImage();
  travelState = null;
  PC._yeldunDungeon = null;
  _huntState = null;
  updateHUD();
  const story = document.getElementById('story');
  if(story){
   story.innerHTML = `<div style="color:#e0d0d0;font-size:var(--font-sm)">
    ${enemyName}との死闘の中、最後に残った運さえも使い果たした。<br><br>
    もう、体を引き戻してくれるものは何も残っていない。
   </div>`;
  }
  renderChoices([{label:'▶ ……力尽きる', fn:()=>{ if(_onLose){ _onLose(); } else { go(loseNode); } }}]);
  return;
 }
 cbtState = null;
 const cbtArea = document.getElementById('cbt-area');
 if(cbtArea) cbtArea.classList.add('hidden');
 const scrollArea = document.getElementById('scroll-area');
 if(scrollArea) scrollArea.classList.remove('in-combat');
 const textWin = document.getElementById('text-win');
 if(textWin) textWin.style.display = '';

 // 同行者募集ダンジョン内・同行配達中だったかを、状態をクリアする前に記録しておく
 const _companionQuestOnSave = _isCompanionHuntCombat()
  ? (PC._yeldunDungeon?.isHuntDungeon
     ? (PC.quests||[]).find(qq=>qq.id===PC._yeldunDungeon.huntQuestId)
     : _getActiveCompanionDeliveryQuest())
  : null;

 // 旅の途中・ダンジョン内どちらで倒れても、残った画像・状態を確実にクリアする
 hideTravelImage();
 hideTravelProgress();
 hideDungeonImage();
 travelState = null;
 PC._yeldunDungeon = null;
 _huntState = null;

 const hasAliveAlly = (PC.party||[]).some(n=>n.con>0);
 const rescueTxt = hasAliveAlly
  ? '意識が遠のく中、仲間が体を支え、庇いながら必死に町まで撤退してくれた。'
  : '敵はすでに事切れたものと見て、その場に打ち捨てていった。しばらくして、たまたま通りかかった旅人が虫の息のその体を見つけ、町まで担ぎ運んでくれた。';

 const story = document.getElementById('story');
 if(story){
  story.innerHTML = `<div style="color:#e0d0d0;font-size:var(--font-sm)">
   ${enemyName}との死闘の中、意識が完全に途切れた。<br><br>${rescueTxt}
  </div>`;
 }
 renderChoices([{label:'▶ ……目を覚ます', fn:()=>_finishLuckSave(enemyName, _companionQuestOnSave)}]);
}

function _finishLuckSave(enemyName, companionQuest){
 // 1〜3ヶ月経過（食料消費・混沌の巣判定・かつての仲間の生死判定はスキップ）
 const monthsOut = 1 + Math.floor(Math.random()*3);
 GAME_TIME.totalDays += monthsOut * 30;
 updateTimebar();
 checkAging(true); // 加齢・寿命チェックは実行、かつての仲間の死亡判定はスキップ
 checkQuestDeadlines(); // クエスト期限切れチェックは実行

 // 所持金のみ失う（装備・所持品・呪文・技能・拠点・不動産は残る）
 PC.gold = 0; PC.sp = 0; PC.cp = 0;

 PC.con = 1;

 const injury = AFTERMATH_INJURIES[Math.floor(Math.random()*AFTERMATH_INJURIES.length)];
 applyInjury(injury);

 addLifeEvent('', `${enemyName}との戦いで瀕死の重傷を負い、九死に一生を得た。<br>${injury.flavor}`);

 updateHUD();
 showSaveToast(` 九死に一生を得た……「${injury.name}」の後遺症が残った。`);
 // 同行者募集ダンジョン内・同行配達中で倒れた場合、生き延びても一時パーティは解散する
 if(companionQuest?.isCompanionHunt || companionQuest?.isCompanionDelivery){
  PC.party = [];
  PC.quests = (PC.quests||[]).filter(qq=>qq.id !== companionQuest.id);
  if(companionQuest.isCompanionHunt){
   if(!PC._huntCooldown) PC._huntCooldown = {};
   const _d = getCurrentDate();
   PC._huntCooldown[companionQuest.fromTownId] = _d.year * 12 + _d.month;
   delete _tavernBoard[companionQuest.fromTownId];
  }
 }
 const destTown = 'TOWN_' + (PC.town||'khazan').toUpperCase();
 go(destTown);
}

function checkAging(skipCompanionCheck){
 if(!skipCompanionCheck){ checkFormerCompanionDeaths(); fcVisitTick(); }
 const newAge = calcAge();
 const params = AGING_PARAMS[PC.race] || AGING_PARAMS.human;
 const lifespan = PC.lifespan || params.lifespan;

 // 寿命超過後：毎日死亡判定（年間確率を日割り）
 if(newAge >= lifespan){
  const overYears = newAge - lifespan + 1;
  const yearlyChance = 1 - Math.pow(0.8, overYears); // 毎年死亡確率が増加（上限なし）
  const dailyChance = 1 - Math.pow(1 - yearlyChance, 1/365);
  if(Math.random() < dailyChance){
   return { event:'death', age:newAge };
  }
 }

 // 以下は誕生日のみ処理
 if(newAge <= PC.age) return null;
 PC.age = newAge;
 if(newAge > params.declineStart){
  const yearsDeclined = newAge - params.declineStart;
  if(yearsDeclined % 5 === 0){
   PC.st = Math.max(1, PC.st - 1);
   PC.iq = Math.max(1, PC.iq - 1);
   PC.lk = Math.max(1, PC.lk - 1);
   PC.chr = Math.max(1, PC.chr - 1);
   PC.dex = Math.max(1, PC.dex - 1);
   PC.spd = Math.max(1, PC.spd - 1);
   if(PC.spdBase != null) PC.spdBase = Math.max(1, PC.spdBase - 1);
   PC.con = Math.max(1, PC.con - 1);
   PC.maxCon = Math.max(1, PC.maxCon - 1);
   updateHUD();
   return { event:'aging', age:newAge };
  }
 }
 return { event:'birthday', age:newAge };
}


