// ALIGNMENT SYSTEM
// ══════════════════════════════════════════
function getAlignmentLabel(ethics, order){
 const e = (ethics||0);
 const o = (order||0);
 const ethicsLabel = e >= 34 ? '善' : e <= -34 ? '悪' : '中立';
 const orderLabel  = o >= 34 ? '秩序' : o <= -34 ? '混沌' : '中庸';
 if(ethicsLabel==='中立' && orderLabel==='中庸') return '真の中立';
 if(ethicsLabel==='中立') return `${orderLabel}・中立`;
 if(orderLabel==='中庸')  return e >= 34 ? '善よりの中庸' : '悪よりの中庸';
 return `${orderLabel}にして${ethicsLabel}`;
}

function getAlignmentColor(ethics, order){
 const e = (ethics||0), o = (order||0);
 if(e>=34 && o>=34)  return 'var(--info2)'; // 秩序にして善：青白
 if(e>=34 && o<=-34) return 'var(--white)'; // 混沌にして善：緑
 if(e>=34)           return 'var(--info2)'; // 善良中立：薄青
 if(e<=-34 && o>=34) return '#cc6644'; // 秩序にして悪：赤橙
 if(e<=-34 && o<=-34)return '#aa44aa'; // 混沌にして悪：紫
 if(e<=-34)          return '#ff8866'; // 邪悪中立：赤
 if(o>=34)           return '#ccbbaa'; // 秩序中立：茶白
 if(o<=-34)          return 'var(--white)'; // 混沌中立：紫
 return '#c0b098888';                     // 真の中立：灰
}

function changeAlignment(ethicsDelta, orderDelta, pc=PC){
 if(ethicsDelta) pc.alignment_ethics = Math.max(-100, Math.min(100, (pc.alignment_ethics||0)+ethicsDelta));
 if(orderDelta)  pc.alignment_order  = Math.max(-100, Math.min(100, (pc.alignment_order||0)+orderDelta));
 // パーティNPCはPCの1/2の変化（PCへの直接呼び出し時のみ）
 if(pc === PC){
  (PC.party||[]).filter(n=>n.con>0).forEach(npc=>{
   const he = ethicsDelta ? Math.round(ethicsDelta / 2) : 0;
   const ho = orderDelta  ? Math.round(orderDelta  / 2) : 0;
   if(he) npc.alignment_ethics = Math.max(-100, Math.min(100, (npc.alignment_ethics||0)+he));
   if(ho) npc.alignment_order  = Math.max(-100, Math.min(100, (npc.alignment_order||0)+ho));
  });
 }
 updateHUD();
}

function renderAlignmentWidget(ethics, order){
 const e = ethics||0, o = order||0;
 const label = getAlignmentLabel(e, o);
 const col   = getAlignmentColor(e, o);
 const ethicsBar = `<div style="display:flex;align-items:center;gap:4px;margin-bottom:3px">
  <span style="font-size:calc(var(--font-sm) - 3px);color:#d0c8b8;width:20px">悪</span>
  <div style="flex:1;height:5px;background:#050505;border-radius:3px;position:relative">
   <div style="position:absolute;left:50%;width:1px;height:100%;background:#606060"></div>
   <div style="position:absolute;left:${Math.round((e+100)/2)}%;width:6px;height:6px;border-radius:50%;background:#f0ece0;top:-0.5px;transform:translateX(-50%)"></div>
  </div>
  <span style="font-size:calc(var(--font-sm) - 3px);color:#e0d8c8;width:20px;text-align:right">善</span>
 </div>`;
 const orderBar = `<div style="display:flex;align-items:center;gap:4px">
  <span style="font-size:calc(var(--font-sm) - 3px);color:#e0d8c8;width:20px">混</span>
  <div style="flex:1;height:5px;background:#050505;border-radius:3px;position:relative">
   <div style="position:absolute;left:50%;width:1px;height:100%;background:#606060"></div>
   <div style="position:absolute;left:${Math.round((o+100)/2)}%;width:6px;height:6px;border-radius:50%;background:#f0ece0;top:-0.5px;transform:translateX(-50%)"></div>
  </div>
  <span style="font-size:calc(var(--font-sm) - 3px);color:#e0d8c8;width:20px;text-align:right">秩</span>
 </div>`;
 return `<div style="background:var(--panel);border:1px solid var(--panel2);border-radius:3px;padding:8px;margin-bottom:12px">
  <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:6px">
   <span style="font-size:calc(var(--font-sm) - 1px);color:#d0c8b8"> 性格</span>
   <span style="font-size:calc(var(--font-sm) + 1px);color:#f0ece0;font-weight:bold">${label}</span>
  </div>
  ${ethicsBar}${orderBar}
 </div>`;
}

function checkNPCAging(){
 const _applyDecline = (npc)=>{
  if(npc.con <= 0) return;
  if(!npc.birthDay) npc.birthDay = -(400 - 380) * 365;
  const params = AGING_PARAMS[npc.race] || AGING_PARAMS.human;
  const lifespan = npc.lifespan || params.lifespan;
  const ageYears = (GAME_TIME.totalDays - npc.birthDay) / 365;
  if(ageYears >= lifespan){
   npc.con = 0;
   return `${npc.name}は天寿を全うした。享年${Math.floor(ageYears)}歳。`;
  }
  // 老衰による能力値低下（5年ごと）
  if(ageYears > params.declineStart){
   const yearsDeclined = Math.floor(ageYears - params.declineStart);
   const expectedDeclines = Math.floor(yearsDeclined / 5);
   const actualDeclines = npc._declineCount || 0;
   if(expectedDeclines > actualDeclines){
    const steps = expectedDeclines - actualDeclines;
    for(let i=0;i<steps;i++){
     npc.st  = Math.max(1, (npc.st||1)  - 1);
     npc.iq  = Math.max(1, (npc.iq||1)  - 1);
     npc.lk  = Math.max(1, (npc.lk||1)  - 1);
     npc.chr = Math.max(1, (npc.chr||1) - 1);
     npc.dex = Math.max(1, (npc.dex||1) - 1);
     npc.spd = Math.max(1, (npc.spd||1) - 1);
     npc.con = Math.max(1, (npc.con||1) - 1);
     npc.maxCon = Math.max(1, (npc.maxCon||1) - 1);
    }
    npc._declineCount = expectedDeclines;
    updateHUD();
   }
  }
  return null;
 };

 const party = PC.party || [];
 party.forEach(npc=>{
  const deathMsg = _applyDecline(npc);
  if(deathMsg){
   addLifeEvent('', deathMsg);
   Object.values(PC.properties||{}).forEach(prop=>{
    (prop.caretakers||[]).forEach(c=>{ if(c._npcId === npc._npcId) c.con = 0; });
   });
   PC._pendingMsg = (PC._pendingMsg||'') + `<div style="color:#e8e0d0;border:1px solid #554433;border-radius:3px;padding:8px;margin-bottom:8px"> ${deathMsg}</div>`;
  }
 });
 Object.values(PC.properties||{}).forEach(prop=>{
  (prop.caretakers||[]).forEach(npc=>{
   const deathMsg = _applyDecline(npc);
   if(deathMsg) addLifeEvent('', deathMsg);
  });
 });
}

