// ROUTESを無向グラフとして扱い、2町間の最短経路（徒歩・馬車のみ。冬季閉鎖区間・船区間は除外）を求める
function findTownRoute(fromTown, toTown){
 if(fromTown === toTown) return [fromTown];
 const allTowns = Object.keys(TOWNS);
 // ダイクストラ法（getRouteで隣接町を都度取得。船区間・冬季閉鎖区間は除外）
 const dist = {[fromTown]:0};
 const prev = {};
 const visited = new Set();
 const pq = [[0, fromTown]];
 while(pq.length){
  pq.sort((x,y)=>x[0]-y[0]);
  const [d, u] = pq.shift();
  if(visited.has(u)) continue;
  visited.add(u);
  if(u === toTown) break;
  allTowns.forEach(v=>{
   if(v === u || visited.has(v)) return;
   const r = getRoute(u, v);
   if(!r || r.hasShip || r.winterBlocked) return;
   const days = r.days.walk!=null ? r.days.walk : r.days.coach;
   if(days == null) return;
   const nd = d + days;
   if(dist[v]==null || nd < dist[v]){
    dist[v] = nd;
    prev[v] = u;
    pq.push([nd, v]);
   }
  });
 }
 if(dist[toTown] == null) return null; // 到達不能
 const path = [toTown];
 while(path[path.length-1] !== fromTown){
  path.push(prev[path[path.length-1]]);
 }
 return path.reverse();
}

