// 二つ名を生成（10%の確率でなし、種類はランダム）
function generateEpithet(){
 if(Math.random() < 0.1) return '';
 const categories = Object.keys(NPC_EPITHETS);
 // epicはやや低確率
 const weights = { funny:3, profession:3, appearance:3, personality:3, epic:1, origin:2 };
 const pool = [];
 for(const cat of categories){
  const w = weights[cat]||1;
  for(let i=0;i<w;i++) pool.push(cat);
 }
 const cat = pool[Math.floor(Math.random()*pool.length)];
 const list = NPC_EPITHETS[cat];
 return list[Math.floor(Math.random()*list.length)];
}

