// ── 地方定義 ──
const REGIONS = {
 khazan_region:   ['khazan','port_argon','stonehiem'],
 elmaria_region:  ['elsia','verda','rimholm','marakai'],
 zahara_region:   ['al_rashid','oasis_fort','saroon','duna'],
 draklim_region:  ['yeldun','frostpeak','ashveil'],
 valdheim_region: ['valdheim','nifurvik','iskald'],
 marea_region:    ['neria','dorua','sarpe','nebra','kalvo'],
};
// 地方キーを返す
function getRegionKey(townId){
 for(const [key, members] of Object.entries(REGIONS)){
 if(members.includes(townId)) return key;
 }
 return null;
}

// 地方間距離（BFS、将来の拡張に対応）
// 隣接地方ルートの定義（地方キー同士）
const REGION_ADJACENCY = {
 khazan_region:   ['elmaria_region','zahara_region','draklim_region','marea_region'],
 elmaria_region:  ['khazan_region','valdheim_region'],
 zahara_region:   ['khazan_region'],
 draklim_region:  ['khazan_region'],
 marea_region:    ['khazan_region'],
 valdheim_region: ['elmaria_region'],
};
function getRegionDistance(keyA, keyB){
 if(keyA === keyB) return 0;
 const visited = new Set([keyA]);
 const queue = [{key:keyA, dist:0}];
 while(queue.length){
 const {key, dist} = queue.shift();
 for(const next of (REGION_ADJACENCY[key]||[])){
 if(next === keyB) return dist+1;
 if(!visited.has(next)){ visited.add(next); queue.push({key:next, dist:dist+1}); }
 }
 }
 return 99; // 到達不能
}

// ══════════════════════════════════════════
// 地方状態システム（物流途絶度／治安悪化度／住民流出度）
// 対象は marea_region を除く5地方。各0〜100、0が最良・100が最悪。
// ══════════════════════════════════════════
const REGION_CONDITION_SCOPE = Object.keys(REGIONS).filter(k => k !== 'marea_region');

// 未初期化なら埋める（food系の PC._foodPriceMult と同じ遅延初期化パターン）。
// 2026年10月4日：ゲーム開始時点から「何もない静かな世界」ではなく既にある程度の
// くすぶりを抱えた状態にするため、各指標は0ではなく20〜30のランダム値から始める
// （3項目は互いに独立にランダム化）。
function ensureRegionCondition(){
 if(!PC._regionCondition) PC._regionCondition = {};
 REGION_CONDITION_SCOPE.forEach(regionKey=>{
  if(!PC._regionCondition[regionKey]){
   const randInit = () => 20 + Math.random() * 10;
   PC._regionCondition[regionKey] = { logi: randInit(), unrest: randInit(), exodus: randInit() };
  }
 });
}

// ── 地方ごとのアンビエント圧力 ──
// PCの行動や既存システム（根城・巣窟・大地震・手配度）が何も無くても、地方は小さな諍いや不運な事故などで
// わずかに悪化しうる、という「何もないところから始まるきっかけ」。周期性を持たせず、値が矩形に飛ばないよう
// 前月の値に引っ張られながら小さな乱数でゆっくり動く（平均回帰つきのランダムウォーク）。0〜3の小さな範囲に収め、
// 強さそのものにも毎月ランダムな大小がつくようにする。
function ensureRegionConditionAmbient(){
 if(!PC._regionConditionAmbient) PC._regionConditionAmbient = {};
 REGION_CONDITION_SCOPE.forEach(regionKey=>{
  if(PC._regionConditionAmbient[regionKey] == null){
   PC._regionConditionAmbient[regionKey] = Math.random() * 1.5; // 地方ごとに初期値もばらける
  }
 });
}
function stepRegionConditionAmbient(prev){
 // 一様乱数を3つ足して平均することで、極端な値が出にくい緩やかな分布にする（-1〜+1付近に集中、平均0の対称ノイズ）
 const noise = (Math.random() + Math.random() + Math.random() - 1.5) / 1.5;
 // 緩やかに引き戻される基準値（2026年10月2日：危機的到達率を上げるため1.2→1.4に調整／
 // 同日：NPC英雄介入導入に合わせ、「放置すれば平均的に不穏レベル、NPC介入があっても稀に危機的レベルに届く」水準まで1.4→2.6に再調整）
 const target = 2.6;
 // 2026年10月2日：振れ幅をさらに大きくして危機的到達率を上げるため、ノイズ係数0.6→1.0、上限3→5に調整
 // 2026年10月4日：巣窟の圧力係数引き下げ（後述）に合わせて「もう少し自然な年ごとの振れ幅」を出すため
 // ノイズ係数を1.0→1.6に再調整（このノイズ式は平均0の対称分布のため、係数を上げても長期平均は動かない）
 const next = prev + (target - prev) * 0.15 + noise * 1.6;
 return Math.max(0, Math.min(5, next));
}

// 指定地方・指定項目のスコアを返す（スコープ外の地方やmarea_regionは常に0）
function getRegionConditionScore(regionKey, metric){
 if(!regionKey || !REGION_CONDITION_SCOPE.includes(regionKey)) return 0;
 ensureRegionCondition();
 return PC._regionCondition[regionKey][metric] || 0;
}

// スコアの段階（0:安定 1:不穏 2:悪化 3:危機的）。しきい値は0-40/41-60/61-80/81-100
// （2026年10月2日：0-29/30-50/51-80/81-100 → 2026年10月20日：0-40/41-60/61-80/81-100 に変更）
function regionConditionStageIndex(score){
 if(score <= 40) return 0;
 if(score <= 60) return 1;
 if(score <= 80) return 2;
 return 3;
}
const REGION_CONDITION_STAGE_LABEL = ['安定','不穏','悪化','危機的'];

// 月次の相互作用式（係数の根拠・安定性検証はプロジェクトドキュメント参照）
function stepRegionCondition(c){
 const clamp = v => Math.max(0, Math.min(100, v));
 const logi = c.logi||0, unrest = c.unrest||0, exodus = c.exodus||0;
 return {
  logi:   clamp(logi  *(1-0.18) + unrest*0.12 + exodus*0.04),
  unrest: clamp(unrest*(1-0.18) + logi  *0.07 + exodus*0.04),
  exodus: clamp(exodus*(1-0.16) + logi  *0.10 + unrest*0.07),
 };
}

// 月次の外的要因（PCの依頼達成以外）：混沌の根城・巣窟ダンジョンの先住者・PCの手配度が
// 該当地方に継続的な圧力を与える。現在の「生」の状態を参照する簡易実装（過去に遡った履歴は見ない）。
const REGION_CONDITION_LAIR_TOWNS = [
 { key: '_lairDungeon',     townId: 'port_argon' },
 { key: '_lair6Dungeon',    townId: 'elsia' },
 { key: '_lair2Dungeon',    townId: 'verda' },
 { key: '_lair3Dungeon',    townId: 'ashveil' },
 { key: '_lair4Dungeon',    townId: 'saroon' },
 { key: '_lair5Dungeon',    townId: 'marakai' },
 { key: '_niflairDungeon',  townId: 'nifurvik' },
 { key: '_lair7Dungeon',    townId: 'duna' },
 { key: '_outpostDungeon',  townId: 'stonehiem' },
];
function getRegionConditionExternalDelta(regionKey){
 const d = { logi:0, unrest:0, exodus:0 };
 // 混沌の根城：活動中（未討伐・NPCにも未討伐）は治安・住民流出に継続的な圧力
 const nest = PC._chaosNest;
 if(nest && nest.nestTownId && !nest.defeatedByNPC && !nest.cleared && getRegionKey(nest.nestTownId) === regionKey){
  d.unrest += 3.5; // 2026年10月2日：危機的到達率を上げるため3→3.5に調整
  d.exodus += 1.2; // 同時に1→1.2に調整
 }
 // 巣窟ダンジョン：何かが巣食っている間（themeIdが設定されている間）、治安にわずかな圧力
 // 2026年10月4日：巣窟は一度テーマが付くと討伐されるまで半永久的に圧力を出し続ける
 // （酒場で話すだけでも再湧き判定が走るため実質放置しても埋まりやすい）ことを踏まえ、
 // 1箇所あたりの圧力を1.15→0.6に引き下げ（根城3→3.5、地震1発15のような単発ショックに比べ
 // 常時圧力が過大にならないようにするための調整）
 REGION_CONDITION_LAIR_TOWNS.forEach(({key, townId})=>{
  const dungeon = PC[key];
  if(dungeon && dungeon.themeId && getRegionKey(townId) === regionKey){
   d.unrest += 0.6;
  }
 });
 // PCの手配度：この地方のいずれかの町で手配度が高い（中）ほど、治安に圧力（PC自身が脅威になっている）
 const towns = REGIONS[regionKey] || [];
 let worstTier = 'low';
 towns.forEach(townId=>{
  const tier = wantedTier(townId);
  if(tier === 'high') worstTier = 'high';
  else if(tier === 'mid' && worstTier !== 'high') worstTier = 'mid';
 });
 if(worstTier === 'high') d.unrest += 2.3; // 2026年10月2日：危機的到達率を上げるため2→2.3に調整
 else if(worstTier === 'mid') d.unrest += 1.15; // 同時に1→1.15に調整
 return d;
}

// ══════════════════════════════════════════
// NPCによる英雄的介入（2026年10月2日追加）
// ある地方の状態が「悪化」(61+)以上のまま一定期間続くと、PCとは無関係にNPCが
// 事態の収拾に乗り出し、3項目をまとめて押し下げることがある。しばらく悪い状態が
// 続くほど・深刻なほど発生確率が上がる。発生後はクールダウンを挟み連発はしない。
// ══════════════════════════════════════════
const REGION_CONDITION_HERO = {
 minStreakMonths:  18,   // 悪化(61+)以上がこの月数続くと介入の対象になる
 baseProb:         0.03, // 対象になった月の基本発生確率
 probStepPerExtra: 0.03, // 対象期間が延びるごとの確率加算
 extraStepMonths:  6,    // 確率加算の刻み幅（ヶ月）
 probCap:          0.12, // 悪化(stage2)時点での発生確率の上限
 stage3Bonus:      0.05, // 危機的(81+)の場合に追加されるボーナス確率
 effectMult:       0.5,  // 発生時、logi/unrest/exodusをこの倍率まで縮小（半減）
 cooldownMonths:   24,   // 発生後、同じ地方が再び対象になりうるまでの月数
};
function ensureRegionConditionHero(){
 if(!PC._regionConditionHero) PC._regionConditionHero = {};
 REGION_CONDITION_SCOPE.forEach(regionKey=>{
  if(!PC._regionConditionHero[regionKey]){
   PC._regionConditionHero[regionKey] = { streak:0, cooldown:0, lastEvent:null, rumorShown:0 };
  }
 });
}
// 地方の最悪段階（0:安定〜3:危機的）を返す
function getRegionConditionWorstStage(regionKey){
 ensureRegionCondition();
 const c = PC._regionCondition[regionKey];
 return regionConditionStageIndex(Math.max(c.logi, c.unrest, c.exodus));
}
// 月次ティック1回分のNPC英雄介入判定。checkRegionConditionTick()からstepRegionConditionの直後に呼ぶ。
function stepRegionConditionHero(regionKey){
 ensureRegionConditionHero();
 const hero = PC._regionConditionHero[regionKey];
 const stage = getRegionConditionWorstStage(regionKey);
 if(stage >= 2){ hero.streak++; } else { hero.streak = 0; }
 if(hero.cooldown > 0) hero.cooldown--;
 if(hero.cooldown <= 0 && stage >= 2 && hero.streak >= REGION_CONDITION_HERO.minStreakMonths){
  const extra = Math.floor((hero.streak - REGION_CONDITION_HERO.minStreakMonths) / REGION_CONDITION_HERO.extraStepMonths);
  let prob = Math.min(REGION_CONDITION_HERO.probCap, REGION_CONDITION_HERO.baseProb + extra * REGION_CONDITION_HERO.probStepPerExtra);
  if(stage >= 3) prob += REGION_CONDITION_HERO.stage3Bonus;
  if(Math.random() < prob){
   const c = PC._regionCondition[regionKey];
   c.logi   *= REGION_CONDITION_HERO.effectMult;
   c.unrest *= REGION_CONDITION_HERO.effectMult;
   c.exodus *= REGION_CONDITION_HERO.effectMult;
   hero.streak = 0;
   hero.cooldown = REGION_CONDITION_HERO.cooldownMonths;
   hero.lastEvent = { npcName: NPC_NAMES[Math.floor(Math.random()*NPC_NAMES.length)], stageAtEvent: stage };
   hero.rumorShown = 0;
  }
 }
}
// 酒場の噂テキスト（NPC英雄介入）。他地方の噂なので、どの町でも聞ける。最大3回まで。
const REGION_CONDITION_HERO_RUMOR_POOL = [
 (name, npc)=>`「${name}の治安がここ最近、急に持ち直したらしい。${npc}とかいう冒険者が一肌脱いだという話だ」`,
 (name, npc)=>`「${npc}という人物が${name}の騒ぎを収めたらしい。おかげで向こうはだいぶ落ち着いたとか」`,
 (name, npc)=>`「${name}で荒れていた一件、${npc}の働きで片付いたと聞いた。大したものだ」`,
];
function getRegionConditionHeroRumor(townId){
 ensureRegionConditionHero();
 const candidates = REGION_CONDITION_SCOPE.filter(regionKey=>{
  const hero = PC._regionConditionHero[regionKey];
  return hero && hero.lastEvent && hero.rumorShown < 3;
 });
 if(!candidates.length) return null;
 const regionKey = candidates[Math.floor(Math.random()*candidates.length)];
 const hero = PC._regionConditionHero[regionKey];
 const regionName = (HERO_REGIONS[regionKey]||{}).name || regionKey;
 const npcName = hero.lastEvent.npcName;
 hero.rumorShown++;
 if(hero.rumorShown >= 3) hero.lastEvent = null;
 const line = REGION_CONDITION_HERO_RUMOR_POOL[Math.floor(Math.random()*REGION_CONDITION_HERO_RUMOR_POOL.length)];
 return line(regionName, npcName);
}

// ══════════════════════════════════════════
// 危機的状況からのPC主導の回復を世界の記録に残す（2026年10月2日追加）
// ある地方が一度でも「危機的」(81+)に達した後、PCの依頼達成（§6の点数表。
// NPC英雄介入やアンビエント圧力の自然減衰による回復は対象外）によって
// 最悪段階が「安定」(40-)まで戻った瞬間を記録する。ws.regionLegendsと同様、
// 地方ごとに最新の1件のみを保持する単発記録＋酒場の噂として実装。
// ══════════════════════════════════════════
function ensureRegionConditionCrisisRecord(){
 if(!PC._regionWasCrisis) PC._regionWasCrisis = {};
 if(!PC._regionCrisisRecord) PC._regionCrisisRecord = {};
 REGION_CONDITION_SCOPE.forEach(regionKey=>{
  if(PC._regionWasCrisis[regionKey] == null) PC._regionWasCrisis[regionKey] = false;
 });
}
// 月次ティックから呼ぶ：その地方が「危機的」に達したことを記録しておく（回復判定の前提条件）
function markRegionConditionCrisisIfNeeded(regionKey){
 ensureRegionConditionCrisisRecord();
 if(getRegionConditionWorstStage(regionKey) >= 3) PC._regionWasCrisis[regionKey] = true;
}
const REGION_CONDITION_CRISIS_RECOVERY_RUMOR_POOL = [
 (name, pcName)=>`「${name}はつい最近まで危機的な有様だったらしいが、${pcName}という冒険者の働きですっかり落ち着いたそうだ」`,
 (name, pcName)=>`「${pcName}が${name}を立て直したという話を聞いた。あそこまで荒れていた地方がよくぞ、と評判だ」`,
 (name, pcName)=>`「${name}の惨状を救ったのは${pcName}だという。もう危機的だった頃の面影はないらしい」`,
];
function getRegionConditionCrisisRecoveryRumor(townId){
 ensureRegionConditionCrisisRecord();
 const candidates = REGION_CONDITION_SCOPE.filter(regionKey=>{
  const rec = PC._regionCrisisRecord[regionKey];
  return rec && rec.rumorShown < 3;
 });
 if(!candidates.length) return null;
 const regionKey = candidates[Math.floor(Math.random()*candidates.length)];
 const rec = PC._regionCrisisRecord[regionKey];
 const regionName = (HERO_REGIONS[regionKey]||{}).name || regionKey;
 rec.rumorShown++;
 const line = REGION_CONDITION_CRISIS_RECOVERY_RUMOR_POOL[Math.floor(Math.random()*REGION_CONDITION_CRISIS_RECOVERY_RUMOR_POOL.length)];
 return line(regionName, rec.pcName);
}

// 月次ティック（遅延評価）：checkHarvestTick() と同じパターンで、呼ばれるたびに経過月数ぶん追いつかせる
function checkRegionConditionTick(){
 ensureRegionCondition();
 ensureRegionConditionAmbient();
 ensureRegionConditionHero();
 ensureRegionConditionCrisisRecord();
 const cur = getCurrentDate();
 const nowKey = cur.year * 12 + cur.month;
 if(PC._regionConditionLastKey == null){ PC._regionConditionLastKey = nowKey; return; }
 const elapsed = nowKey - PC._regionConditionLastKey;
 if(elapsed <= 0) return;
 const clamp = v => Math.max(0, Math.min(100, v));
 for(let i=0; i<elapsed; i++){
  REGION_CONDITION_SCOPE.forEach(regionKey=>{
   // アンビエント圧力をまず緩やかに動かし、治安悪化度への小さな圧力として加える
   const ambient = stepRegionConditionAmbient(PC._regionConditionAmbient[regionKey]);
   PC._regionConditionAmbient[regionKey] = ambient;
   const ext = getRegionConditionExternalDelta(regionKey);
   const c = PC._regionCondition[regionKey];
   c.logi   = clamp(c.logi   + ext.logi);
   c.unrest = clamp(c.unrest + ext.unrest + ambient);
   c.exodus = clamp(c.exodus + ext.exodus);
   PC._regionCondition[regionKey] = stepRegionCondition(c);
   // 「危機的」に達したことを記録しておく（PC主導の回復イベントの前提条件）
   markRegionConditionCrisisIfNeeded(regionKey);
   // NPCの英雄的介入判定（悪化が長引いた地方をPCとは無関係に収拾することがある）
   stepRegionConditionHero(regionKey);
  });
 }
 PC._regionConditionLastKey = nowKey;
}

// 依頼達成時の増減量（§6の点数表）。地方内配達=物流-2、護衛=物流-6、討伐=治安-3〜-4、賞金首=治安-5〜-8
function applyRegionConditionQuestDelta(townId, qtype){
 const regionKey = getRegionKey(townId);
 if(!regionKey || !REGION_CONDITION_SCOPE.includes(regionKey)) return;
 ensureRegionCondition();
 ensureRegionConditionCrisisRecord();
 const c = PC._regionCondition[regionKey];
 const clamp = v => Math.max(0, Math.min(100, v));
 // §6の点数表の半分 → さらに宅配・護衛を1/5に調整（2026年10月改訂）
 if(qtype === 'delivery_local'){
  c.logi = clamp(c.logi - 0.2); // 元-2の半分の1/5
 } else if(qtype === 'escort'){
  c.logi = clamp(c.logi - 0.6); // 元-6の半分の1/5
 } else if(qtype === 'hunt'){
  c.unrest = clamp(c.unrest - (3 + Math.floor(Math.random()*2))/2); // 元-3〜-4の半分（-1.5〜-2）
 } else if(qtype === 'bounty'){
  c.unrest = clamp(c.unrest - (5 + Math.floor(Math.random()*4))/2); // 元-5〜-8の半分（-2.5〜-4）
 }
 // 危機的状況からのPC主導の回復を記録する（2026年10月2日追加）。
 // この地方が一度でも「危機的」に達していて、今回の依頼達成によって
 // ちょうど「安定」まで戻った場合のみ発動（NPC英雄介入や自然減衰は対象外）。
 if(PC._regionWasCrisis[regionKey] && regionConditionStageIndex(Math.max(c.logi, c.unrest, c.exodus)) === 0){
  const regionName = (HERO_REGIONS[regionKey]||{}).name || regionKey;
  PC._regionCrisisRecord[regionKey] = { pcName: PC.name, year: getCurrentDate().year, rumorShown: 0 };
  PC._regionWasCrisis[regionKey] = false;
  showSaveToast(`★ ${regionName}の危機を救った！この功績は世界に記録される`);
 }
}

// 依頼報酬の段階的倍率（最大1.3倍）。安定1.0/不穏1.1/悪化1.2/危機的1.3
function regionConditionRewardMult(regionKey, metric){
 const score = getRegionConditionScore(regionKey, metric);
 return [1.0, 1.1, 1.2, 1.3][regionConditionStageIndex(score)];
}

// 道中エンカウント率の段階的倍率（最大2.0倍）。治安悪化度を参照
function regionConditionEncounterMult(regionKey){
 const score = getRegionConditionScore(regionKey, 'unrest');
 return [1.0, 1.3, 1.6, 2.0][regionConditionStageIndex(score)];
}

// 酒場の冒険者数（住民流出度を参照）。安定〜不穏=3人／悪化=2人／危機的=1人
function regionConditionTavernNPCCount(regionKey){
 const score = getRegionConditionScore(regionKey, 'exodus');
 return [3, 3, 2, 1][regionConditionStageIndex(score)];
}

